        .root-journey-sky {
            position: absolute;
            inset: 0;
            background:
                linear-gradient(108deg, transparent 0 18%, rgba(167, 239, 255, 0.04) 18.1% 18.3%, transparent 18.4% 74%, rgba(255, 229, 162, 0.06) 74.1% 74.3%, transparent 74.4%),
                radial-gradient(ellipse at 50% 39%, rgba(255, 235, 180, 0.16), transparent 23%);
        }

        .root-journey-sky::before,
        .root-journey-sky::after {
            content: "";
            position: absolute;
            width: min(42vw, 560px);
            height: 72px;
            border-radius: 50%;
            background: rgba(205, 243, 255, 0.055);
            filter: blur(18px);
            animation: root-journey-cloud-drift 18s ease-in-out infinite alternate;
        }

        .root-journey-sky::before {
            top: 15%;
            left: -10%;
        }

        .root-journey-sky::after {
            top: 22%;
            right: -8%;
            animation-delay: -9s;
            animation-direction: alternate-reverse;
        }

        .root-journey-sun {
            position: absolute;
            top: clamp(74px, 15vh, 150px);
            left: 50%;
            width: clamp(126px, 17vw, 238px);
            aspect-ratio: 1;
            border-radius: 50%;
            background:
                radial-gradient(circle at 42% 38%, #fffce6 0 8%, #ffe7a0 28%, #f8b75f 62%, rgba(240, 137, 63, 0.08) 72%);
            box-shadow:
                0 0 34px rgba(255, 222, 142, 0.75),
                0 0 100px rgba(255, 184, 93, 0.42),
                0 0 190px rgba(121, 233, 229, 0.16);
            opacity: 0;
            transform: translate(-50%, 95px) scale(0.72);
            animation: root-journey-sunrise 4.2s cubic-bezier(.18,.75,.24,1) 0.35s forwards;
        }

        .root-journey-sun::after {
            content: "";
            position: absolute;
            inset: -22%;
            border: 1px solid rgba(255, 232, 171, 0.28);
            border-radius: 50%;
            animation: root-journey-sun-ring 4.8s ease-in-out infinite;
        }

        .root-journey-horizon {
            position: absolute;
            top: clamp(250px, 38vh, 390px);
            left: -10%;
            width: 120%;
            height: 2px;
            background: linear-gradient(90deg, transparent, rgba(167, 239, 255, 0.34) 16%, rgba(255, 229, 162, 0.72) 50%, rgba(167, 239, 255, 0.34) 84%, transparent);
            box-shadow:
                0 -3px 18px rgba(255, 225, 144, 0.38),
                0 8px 34px rgba(88, 216, 221, 0.28);
            opacity: 0;
            animation: root-journey-horizon-in 2.8s ease 1.2s forwards;
        }

        .root-journey-horizon::after {
            content: "";
            position: absolute;
            top: 2px;
            left: 0;
            width: 100%;
            height: 34vh;
            background:
                repeating-linear-gradient(90deg, transparent 0 70px, rgba(153, 235, 239, 0.08) 71px 72px),
                repeating-linear-gradient(180deg, rgba(153, 235, 239, 0.09) 0 1px, transparent 1px 42px);
            transform-origin: top;
            transform: perspective(320px) rotateX(68deg);
            mask-image: linear-gradient(180deg, rgba(0,0,0,0.75), transparent 80%);
        }

        .root-journey-road {
            position: absolute;
            top: clamp(250px, 38vh, 390px);
            bottom: -8vh;
            left: 5%;
            width: 90%;
            clip-path: polygon(49.2% 0, 50.8% 0, 78% 100%, 22% 100%);
            background:
                linear-gradient(90deg, transparent 0 20%, rgba(132, 230, 232, 0.12) 20.2%, rgba(255, 226, 147, 0.12) 49%, rgba(132, 230, 232, 0.12) 79.8%, transparent 80%),
                linear-gradient(180deg, rgba(4, 22, 47, 0.32), rgba(2, 12, 28, 0.7));
            filter: drop-shadow(0 0 22px rgba(128, 232, 231, 0.18));
            opacity: 0;
            animation: root-journey-road-in 2.6s ease 1.65s forwards;
        }

        .root-journey-road::before,
        .root-journey-road::after {
            content: "";
            position: absolute;
            top: 0;
            bottom: 0;
        }

        .root-journey-road::before {
            left: 49.55%;
            width: 0.9%;
            min-width: 3px;
            background: repeating-linear-gradient(180deg, rgba(255, 229, 162, 0.86) 0 18px, transparent 18px 48px);
            background-position-y: 0;
            box-shadow: 0 0 12px rgba(255, 218, 122, 0.36);
            animation: root-journey-road-move 2.6s linear infinite;
        }

        .root-journey-road::after {
            left: 21%;
            right: 21%;
            border-right: 1px solid rgba(169, 240, 240, 0.34);
            border-left: 1px solid rgba(169, 240, 240, 0.34);
        }

        .root-journey-route-map {
            position: absolute;
            inset: 7% 4% 3%;
            width: 92%;
            height: 90%;
            overflow: visible;
            opacity: 0.74;
        }

        .root-journey-route-line {
            fill: none;
            stroke: rgba(255, 228, 151, 0.48);
            stroke-width: 2;
            stroke-linecap: round;
            stroke-dasharray: 5 15;
            filter: drop-shadow(0 0 6px rgba(255, 218, 124, 0.45));
            animation: root-journey-route-dash 2.2s linear infinite;
        }

        .root-journey-traveller {
            fill: #fff1b8;
            stroke: rgba(153, 240, 255, 0.9);
            stroke-width: 5;
            filter: drop-shadow(0 0 10px #ffe29a);
        }

        .root-journey-film-rail {
            position: absolute;
            top: 0;
            bottom: 0;
            width: clamp(18px, 2.6vw, 38px);
            border-right: 1px solid rgba(164, 235, 255, 0.18);
            border-left: 1px solid rgba(164, 235, 255, 0.18);
            background:
                repeating-linear-gradient(180deg, rgba(2, 14, 32, 0.82) 0 13px, transparent 13px 25px),
                linear-gradient(90deg, rgba(119, 224, 239, 0.08), rgba(255, 228, 151, 0.18), rgba(119, 224, 239, 0.08));
            box-shadow: 0 0 22px rgba(102, 223, 237, 0.12);
            opacity: 0.78;
        }

        .root-journey-film-rail.is-left {
            left: clamp(5px, 1.6vw, 26px);
        }

        .root-journey-film-rail.is-right {
            right: clamp(5px, 1.6vw, 26px);
        }

        .root-journey-film-rail::before {
            content: "";
            position: absolute;
            top: -12%;
            left: 4px;
            right: 4px;
            height: 44px;
            border-radius: 5px;
            background: linear-gradient(180deg, transparent, #dffaff 45%, #ffe4a0 55%, transparent);
            box-shadow: 0 0 18px rgba(164, 239, 255, 0.72);
            animation: root-journey-playhead 7s linear infinite;
        }

        .root-journey-film-rail::after {
            position: absolute;
            top: 50%;
            left: 50%;
            color: rgba(230, 249, 255, 0.46);
            font-size: 0.52rem;
            font-weight: 900;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            writing-mode: vertical-rl;
            transform: translate(-50%, -50%);
        }

        .root-journey-film-rail.is-left::after {
            content: "FRAME 01  \00B7  PLAY  \00B7  FRAME 02";
        }

        .root-journey-film-rail.is-right::after {
            content: "KEYFRAME  \00B7  MOTION  \00B7  24 FPS";
        }

        .root-journey-waypoint {
            position: absolute;
            display: grid;
            place-items: center;
            width: 86px;
            aspect-ratio: 1;
            border: 1px solid rgba(171, 238, 255, 0.3);
            border-radius: 50%;
            color: rgba(235, 250, 255, 0.76);
            background: radial-gradient(circle, rgba(10, 49, 77, 0.72), rgba(3, 20, 43, 0.12) 68%, transparent 70%);
            box-shadow: inset 0 0 20px rgba(126, 229, 234, 0.1), 0 0 24px rgba(81, 215, 225, 0.12);
            font-size: 0.56rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-align: center;
            text-transform: uppercase;
            animation: root-journey-waypoint-float 5.5s ease-in-out infinite;
        }

        .root-journey-waypoint::before {
            content: "";
            position: absolute;
            inset: 8px;
            border: 1px dashed rgba(255, 226, 148, 0.34);
            border-radius: 50%;
            animation: root-journey-waypoint-spin 12s linear infinite;
        }

        .root-journey-waypoint.is-explore {
            top: 22%;
            left: max(40px, calc((100vw - 1120px) / 4));
        }

        .root-journey-waypoint.is-discover {
            top: 53%;
            right: max(40px, calc((100vw - 1120px) / 4));
            animation-delay: -2.6s;
        }

        .root-journey-animation-badge {
            position: absolute;
            right: max(42px, calc((100vw - 1120px) / 4));
            bottom: 24px;
            display: grid;
            grid-template-columns: 36px auto;
            align-items: center;
            gap: 10px;
            padding: 10px 13px 10px 10px;
            border: 1px solid rgba(160, 235, 255, 0.26);
            border-radius: 16px;
            color: rgba(239, 251, 255, 0.82);
            background: rgba(3, 22, 48, 0.62);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 12px 28px rgba(0,0,0,0.18);
            backdrop-filter: blur(8px);
        }

        .root-journey-animation-badge > span:first-child {
            display: grid;
            place-items: center;
            width: 36px;
            height: 36px;
            border-radius: 50%;
            color: #092744;
            background: linear-gradient(145deg, #fff0b3, #86e5ef);
            box-shadow: 0 0 16px rgba(139, 232, 240, 0.42);
            font-size: 0.82rem;
            animation: root-journey-play-pulse 2.4s ease-in-out infinite;
        }

        .root-journey-animation-badge strong,
        .root-journey-animation-badge small {
            display: block;
            text-transform: uppercase;
        }

        .root-journey-animation-badge strong {
            color: #ffe4a0;
            font-size: 0.62rem;
            letter-spacing: 0.13em;
        }

        .root-journey-animation-badge small {
            margin-top: 3px;
            color: rgba(193, 235, 248, 0.62);
            font-size: 0.48rem;
            font-weight: 800;
            letter-spacing: 0.12em;
        }

        .root-journey-door {
            position: absolute;
            top: 0;
            bottom: 0;
            width: 50.2%;
            overflow: hidden;
            background:
                linear-gradient(90deg, transparent 0 12%, rgba(166, 235, 255, 0.08) 12.2% 12.6%, transparent 12.8% 86%, rgba(255, 226, 148, 0.09) 86.2% 86.6%, transparent 86.8%),
                radial-gradient(circle at 50% 48%, rgba(74, 196, 211, 0.14), transparent 32%),
                linear-gradient(145deg, #061831, #0a3359 56%, #041329);
            box-shadow: inset 0 0 70px rgba(0,0,0,0.42), 0 0 55px rgba(0,0,0,0.46);
            backface-visibility: hidden;
        }

        .root-journey-door::before {
            content: "";
            position: absolute;
            inset: 28px;
            border: 1px solid rgba(179, 237, 255, 0.16);
            border-radius: 18px;
            box-shadow: inset 0 0 0 8px rgba(0, 10, 27, 0.2);
        }

        .root-journey-door::after {
            content: "";
            position: absolute;
            top: 0;
            bottom: 0;
            width: 2px;
            background: linear-gradient(180deg, transparent, #ffdfa0 28%, #9beaf3 72%, transparent);
            box-shadow: 0 0 20px rgba(255, 224, 154, 0.68);
        }

        .root-journey-door.is-left {
            left: 0;
            transform-origin: left center;
            animation: root-journey-door-left 2.75s cubic-bezier(.58,.02,.23,1) 0.16s forwards;
        }

        .root-journey-door.is-left::after {
            right: 0;
        }

        .root-journey-door.is-right {
            right: 0;
            transform-origin: right center;
            animation: root-journey-door-right 2.75s cubic-bezier(.58,.02,.23,1) 0.16s forwards;
        }

        .root-journey-door.is-right::after {
            left: 0;
        }

        .root-journey-door-copy {
            position: absolute;
            top: 48%;
            color: #fff0bb;
            font-size: clamp(0.78rem, 1.5vw, 1.12rem);
            font-weight: 950;
            letter-spacing: 0.28em;
            text-shadow: 0 0 22px rgba(255, 224, 150, 0.4);
            white-space: nowrap;
        }

        .root-journey-door.is-left .root-journey-door-copy {
            right: clamp(22px, 5vw, 80px);
        }

        .root-journey-door.is-right .root-journey-door-copy {
            left: clamp(22px, 5vw, 80px);
        }

        @keyframes root-journey-gates-dismiss {
            0%, 94% { visibility: visible; }
            100% { visibility: hidden; }
        }

        @keyframes root-journey-door-left {
            0%, 16% { transform: translateX(0) rotateY(0); opacity: 1; }
            54% { transform: translateX(-22%) rotateY(-24deg); opacity: 1; }
            100% { transform: translateX(-108%) rotateY(-58deg); opacity: 0.12; }
        }

        @keyframes root-journey-door-right {
            0%, 16% { transform: translateX(0) rotateY(0); opacity: 1; }
            54% { transform: translateX(22%) rotateY(24deg); opacity: 1; }
            100% { transform: translateX(108%) rotateY(58deg); opacity: 0.12; }
        }

        @keyframes root-journey-sunrise {
            0% { opacity: 0; transform: translate(-50%, 95px) scale(0.72); filter: saturate(0.7); }
            55% { opacity: 0.9; }
            100% { opacity: 1; transform: translate(-50%, 0) scale(1); filter: saturate(1); }
        }

        @keyframes root-journey-sun-ring {
            0%, 100% { transform: scale(0.88); opacity: 0.22; }
            50% { transform: scale(1.08); opacity: 0.7; }
        }

        @keyframes root-journey-horizon-in {
            from { opacity: 0; transform: scaleX(0.18); }
            to { opacity: 1; transform: scaleX(1); }
        }

        @keyframes root-journey-road-in {
            from { opacity: 0; transform: translateY(90px); }
            to { opacity: 1; transform: translateY(0); }
        }

        @keyframes root-journey-road-move {
            to { background-position-y: 48px; }
        }

        @keyframes root-journey-route-dash {
            to { stroke-dashoffset: -40; }
        }

        @keyframes root-journey-cloud-drift {
            from { transform: translateX(-2vw) scaleX(0.9); opacity: 0.35; }
            to { transform: translateX(12vw) scaleX(1.1); opacity: 0.8; }
        }

        @keyframes root-journey-playhead {
            0% { transform: translateY(-10vh); opacity: 0; }
            8%, 88% { opacity: 1; }
            100% { transform: translateY(112vh); opacity: 0; }
        }

        @keyframes root-journey-waypoint-float {
            0%, 100% { transform: translateY(0); opacity: 0.54; }
            50% { transform: translateY(-13px); opacity: 0.9; }
        }

        @keyframes root-journey-waypoint-spin {
            to { transform: rotate(360deg); }
        }

        @keyframes root-journey-play-pulse {
            0%, 100% { transform: scale(0.94); filter: brightness(0.9); }
            50% { transform: scale(1.06); filter: brightness(1.15); }
        }

        @keyframes root-journey-welcome-pulse {
            0%, 100% { box-shadow: 0 0 0 rgba(255, 226, 148, 0); }
            50% { box-shadow: 0 0 18px rgba(255, 226, 148, 0.18); }
        }

        @media (max-width: 900px) {
            .root-journey-film-rail {
                width: 9px;
                border: 0;
                opacity: 0.5;
            }

            .root-journey-film-rail.is-left { left: 1px; }
            .root-journey-film-rail.is-right { right: 1px; }

            .root-journey-film-rail::after,
            .root-journey-waypoint,
            .root-journey-animation-badge {
                display: none;
            }

            .root-journey-sun {
                top: 80px;
                width: 146px;
            }

            .root-journey-horizon,
            .root-journey-road {
                top: 250px;
            }

            .root-journey-route-map {
                inset: 4% -28% 2%;
                width: 156%;
            }

            .root-journey-door::before {
                inset: 12px;
            }

            .root-journey-door-copy {
                top: 45%;
                max-width: 42vw;
                overflow: hidden;
                font-size: 0.66rem;
                letter-spacing: 0.18em;
            }

            .root-journey-door.is-left .root-journey-door-copy { right: 14px; }
            .root-journey-door.is-right .root-journey-door-copy { left: 14px; }

            body[data-overview-view="root"] .overview-kicker::after {
                display: flex;
                width: fit-content;
                margin: 7px 0 0;
            }
        }

        @media (min-width: 901px) and (max-width: 1300px) {
            .root-journey-waypoint {
                width: 46px;
                font-size: 0.38rem;
                letter-spacing: 0.05em;
            }

            .root-journey-waypoint::before {
                inset: 5px;
            }

            .root-journey-waypoint.is-explore {
                left: 8px;
            }

            .root-journey-waypoint.is-discover {
                right: 8px;
            }

            .root-journey-animation-badge {
                right: 14px;
                transform: scale(0.82);
                transform-origin: right bottom;
            }
        }

        @media (prefers-reduced-motion: reduce) {
            body[data-overview-view="root"] .root-journey-gates {
                display: none;
            }

            .root-journey-sun {
                opacity: 1;
                transform: translate(-50%, 0) scale(1);
            }

            .root-journey-horizon,
            .root-journey-road {
                opacity: 1;
            }

            .root-journey-scene *,
            body[data-overview-view="root"] .overview-kicker::after {
                animation: none !important;
            }
        }

        .page-shell {
            width: min(1120px, calc(100% - 28px));
            margin: 0 auto;
            padding: 28px 0 40px;
        }

        .overview-card {
            position: relative;
            overflow: hidden;
            border-radius: 36px;
            border: 1px solid var(--panel-border);
            background:
                linear-gradient(160deg, rgba(8, 37, 82, 0.96), rgba(3, 22, 52, 0.98)),
                linear-gradient(120deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow: var(--shadow-3d);
            padding: 28px 28px 30px;
        }

        .overview-card::before {
            content: "";
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 14% 12%, rgba(255,255,255,0.12), transparent 26%),
                radial-gradient(circle at 88% 8%, rgba(167, 239, 255, 0.12), transparent 20%);
            pointer-events: none;
        }

        .seo-ai-summary {
            position: relative;
            max-height: 2200px;
            margin-top: 28px;
            padding: clamp(22px, 4vw, 34px);
            border: 1px solid rgba(255, 255, 255, 0.18);
            border-radius: 30px;
            color: rgba(239, 248, 255, 0.94);
            background:
                radial-gradient(circle at top right, rgba(167, 239, 255, 0.16), transparent 28%),
                linear-gradient(155deg, rgba(7, 29, 65, 0.88), rgba(6, 45, 78, 0.76));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.09),
                0 20px 42px rgba(0,0,0,0.22);
            overflow: hidden;
            opacity: 1;
            transform: translateY(0);
            transition:
                opacity 0.7s ease,
                transform 0.7s ease,
                max-height 0.85s ease,
                margin-top 0.85s ease,
                padding-top 0.85s ease,
                padding-bottom 0.85s ease,
                border-width 0.85s ease;
        }

        .seo-ai-summary.is-faded {
            max-height: 0;
            margin-top: 0;
            padding-top: 0;
            padding-bottom: 0;
            border-width: 0;
            opacity: 0;
            transform: translateY(14px);
            pointer-events: none;
        }

        .seo-ai-summary::before {
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(90deg, rgba(255,255,255,0.07) 1px, transparent 1px),
                linear-gradient(0deg, rgba(255,255,255,0.055) 1px, transparent 1px);
            background-size: 42px 42px;
            mask-image: linear-gradient(180deg, rgba(0,0,0,0.8), transparent 85%);
            opacity: 0.55;
            pointer-events: none;
        }

        .seo-ai-summary > * {
            position: relative;
            z-index: 1;
        }

        .seo-ai-kicker {
            display: inline-flex;
            align-items: center;
            margin: 0 0 10px;
            padding: 6px 10px;
            border: 1px solid rgba(255,255,255,0.22);
            border-radius: 999px;
            color: var(--cyan-soft);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.13em;
            text-transform: uppercase;
        }

        .seo-ai-title {
            margin: 0 0 12px;
            color: #ffffff;
            font-size: clamp(1.7rem, 4vw, 3rem);
            letter-spacing: -0.04em;
            line-height: 1;
        }

        .seo-ai-copy {
            max-width: 920px;
            margin: 0;
            color: rgba(239, 248, 255, 0.9);
            font-size: 1.02rem;
            line-height: 1.7;
        }

        .seo-ai-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 14px;
            margin-top: 20px;
        }

        .seo-ai-card,
        .seo-ai-faq details {
            border: 1px solid rgba(255,255,255,0.16);
            border-radius: 20px;
            background: rgba(255,255,255,0.08);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.07);
            padding: 16px;
        }

        .seo-ai-card h3,
        .seo-ai-faq summary {
            margin: 0 0 8px;
            color: #ffffff;
            font-weight: 900;
        }

        .seo-ai-card p,
        .seo-ai-faq p {
            margin: 0;
            color: rgba(239, 248, 255, 0.86);
            line-height: 1.55;
        }

        .seo-ai-faq {
            display: grid;
            gap: 10px;
            margin-top: 18px;
        }

        .seo-ai-faq summary {
            cursor: pointer;
            list-style-position: inside;
        }

        .seo-ai-faq p {
            margin-top: 8px;
        }

        .page-rating-shell {
            --page-rating-color: rgba(167, 239, 255, 0.7);
            position: relative;
            width: min(430px, 100%);
            min-height: 176px;
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            gap: 16px;
            margin: 20px 0 24px auto;
            border: 1px solid rgba(184, 230, 255, 0.18);
            border-radius: 24px;
            background:
                radial-gradient(circle at 88% 4%, color-mix(in srgb, var(--page-rating-color) 16%, transparent), transparent 40%),
                linear-gradient(155deg, rgba(7, 35, 73, 0.92), rgba(3, 21, 48, 0.96));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.09),
                0 15px 30px rgba(0,0,0,0.2);
            padding: 16px 17px;
            overflow: hidden;
            transition:
                width 0.42s cubic-bezier(.2,.82,.28,1),
                min-height 0.42s cubic-bezier(.2,.82,.28,1),
                padding 0.42s cubic-bezier(.2,.82,.28,1),
                border-color 0.28s ease,
                box-shadow 0.28s ease,
                background 0.28s ease;
        }

        .page-rating-shell.is-collapsed {
            width: 58px;
            height: 58px;
            max-height: 58px;
            min-height: 58px;
            grid-template-columns: 1fr;
            gap: 0;
            border-radius: 18px;
            padding: 0;
        }

        .page-rating-launcher {
            position: absolute;
            z-index: 3;
            inset: 0;
            width: 100%;
            height: 100%;
            display: grid;
            place-items: center;
            border: 0;
            background: transparent;
            color: rgba(214, 235, 246, 0.82);
            cursor: pointer;
            padding: 16px;
            opacity: 0;
            pointer-events: none;
            transform: translateX(-18px) scale(0.55);
            transition: opacity 0.24s ease, transform 0.42s cubic-bezier(.2,.82,.28,1.18), color 0.2s ease;
        }

        .page-rating-launcher svg {
            width: 100%;
            height: 100%;
            filter: drop-shadow(0 5px 7px rgba(0,0,0,0.26));
        }

        .page-rating-shell.is-collapsed .page-rating-launcher {
            opacity: 1;
            pointer-events: auto;
            transform: translateX(0) scale(1);
        }

        .page-rating-shell.is-collapsed.is-up .page-rating-launcher,
        .page-rating-shell.is-collapsed.is-down .page-rating-launcher {
            color: var(--page-rating-color);
        }

        .page-rating-launcher:hover,
        .page-rating-launcher:focus-visible {
            color: #ffffff;
            outline: none;
            transform: translateX(0) translateY(-2px) rotate(-6deg) scale(1.04);
        }

        .page-rating-collapse {
            position: absolute;
            z-index: 4;
            top: 9px;
            right: 9px;
            width: 26px;
            height: 26px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(191, 225, 243, 0.14);
            border-radius: 9px;
            background: rgba(2, 16, 37, 0.48);
            color: rgba(219, 237, 247, 0.62);
            cursor: pointer;
            font: 900 1rem/1 "Segoe UI", sans-serif;
            transition: opacity 0.24s ease, transform 0.24s ease, color 0.18s ease, border-color 0.18s ease;
        }

        .page-rating-collapse:hover,
        .page-rating-collapse:focus-visible {
            border-color: rgba(219, 239, 250, 0.38);
            color: #ffffff;
            outline: none;
            transform: translateY(-1px);
        }

        .page-rating-copy,
        .page-rating-control {
            opacity: 1;
            visibility: visible;
            transform: translateX(0);
            transition: opacity 0.24s 0.13s ease, visibility 0s 0s, transform 0.34s 0.08s ease;
        }

        .page-rating-shell.is-collapsed .page-rating-copy,
        .page-rating-shell.is-collapsed .page-rating-control,
        .page-rating-shell.is-collapsed .page-rating-collapse {
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
            transform: translateX(22px);
            transition: opacity 0.12s ease, visibility 0s 0.42s, transform 0.25s ease;
        }

        .page-rating-shell.is-up,
        .page-rating-shell.is-down {
            border-color: color-mix(in srgb, var(--page-rating-color) 54%, rgba(255,255,255,0.16));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 16px 30px rgba(0,0,0,0.22),
                0 0 24px color-mix(in srgb, var(--page-rating-color) 16%, transparent);
        }

        .page-rating-copy {
            min-width: 0;
            display: grid;
            align-content: center;
            gap: 5px;
        }

        .page-rating-kicker {
            margin: 0;
            color: rgba(167, 239, 255, 0.62);
            font-size: 0.6rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .page-rating-title {
            margin: 0;
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            font-weight: 900;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }

        .page-rating-page-name {
            overflow: hidden;
            margin: 0;
            color: rgba(220, 240, 251, 0.58);
            font-size: 0.7rem;
            line-height: 1.35;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .page-rating-readout {
            margin: 7px 0 0;
            color: rgba(232, 247, 255, 0.76);
            font-size: 0.76rem;
            font-weight: 800;
            line-height: 1.35;
        }

        .page-rating-shell.is-up .page-rating-readout,
        .page-rating-shell.is-down .page-rating-readout {
            color: var(--page-rating-color);
        }

        .page-rating-submit {
            width: fit-content;
            min-width: 104px;
            min-height: 34px;
            margin-top: 8px;
            border: 1px solid rgba(190, 225, 243, 0.18);
            border-radius: 11px;
            background: rgba(167, 239, 255, 0.08);
            color: rgba(233, 247, 255, 0.82);
            cursor: pointer;
            font: 900 0.62rem "Segoe UI", sans-serif;
            letter-spacing: 0.09em;
            padding: 7px 11px;
            text-transform: uppercase;
            transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, opacity 0.18s ease;
        }

        .page-rating-submit:not(:disabled):hover,
        .page-rating-submit:not(:disabled):focus-visible {
            transform: translateY(-1px);
            border-color: var(--page-rating-color);
            background: color-mix(in srgb, var(--page-rating-color) 14%, rgba(3, 25, 53, 0.9));
            outline: none;
        }

        .page-rating-submit:disabled {
            cursor: default;
            opacity: 0.4;
        }

        .page-rating-status {
            min-height: 16px;
            margin: 2px 0 0;
            color: rgba(205, 229, 242, 0.55);
            font-size: 0.62rem;
            line-height: 1.35;
        }

        .page-rating-status.is-error {
            color: #ffb4bf;
        }

        .page-rating-control {
            display: grid;
            grid-template-columns: 42px 38px;
            grid-template-rows: 1fr 1fr;
            align-items: center;
            gap: 7px 6px;
        }

        .page-rating-thumb {
            width: 42px;
            height: 42px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(187, 224, 244, 0.17);
            border-radius: 13px;
            background:
                linear-gradient(180deg, rgba(44, 67, 91, 0.78), rgba(13, 25, 42, 0.92));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 7px 13px rgba(0,0,0,0.19);
            color: rgba(214, 231, 241, 0.65);
            cursor: pointer;
            padding: 10px;
            transition: transform 0.24s cubic-bezier(.2,.82,.28,1.12), border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
        }

        .page-rating-thumb svg {
            width: 100%;
            height: 100%;
        }

        .page-rating-thumb.is-down svg {
            transform: rotate(180deg);
        }

        .page-rating-thumb:hover,
        .page-rating-thumb:focus-visible {
            border-color: rgba(213, 239, 252, 0.42);
            color: #f0f9ff;
            outline: none;
        }

        .page-rating-thumb.is-selected {
            border-color: var(--page-rating-color);
            color: var(--page-rating-color);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 8px 16px rgba(0,0,0,0.22),
                0 0 18px color-mix(in srgb, var(--page-rating-color) 34%, transparent);
        }

        .page-rating-thumb.is-up.is-selected {
            transform: translateY(-4px) rotate(-4deg);
        }

        .page-rating-thumb.is-down.is-selected {
            transform: translateY(4px) rotate(-4deg);
        }

        .page-rating-rail {
            grid-column: 2;
            grid-row: 1 / span 2;
            display: grid;
            grid-template-rows: auto 1fr auto;
            justify-items: center;
            gap: 2px;
            min-height: 116px;
        }

        .page-rating-limit {
            color: rgba(221, 239, 249, 0.55);
            font: 900 0.58rem Consolas, "Courier New", monospace;
            line-height: 1;
        }

        .page-rating-range {
            width: 26px;
            height: 88px;
            margin: 0;
            accent-color: var(--page-rating-color);
            cursor: ns-resize;
            direction: rtl;
            writing-mode: vertical-lr;
            -webkit-appearance: slider-vertical;
        }

        .page-rating-shell.is-down .page-rating-range {
            direction: ltr;
        }

        .page-rating-range:disabled {
            cursor: default;
            filter: grayscale(1);
            opacity: 0.38;
        }

        .page-rating-range:focus-visible {
            outline: 2px solid color-mix(in srgb, var(--page-rating-color) 72%, white);
            outline-offset: 3px;
        }

        .page-rating-shell.is-saving {
            opacity: 0.78;
            pointer-events: none;
        }

        .page-rating-shell.is-saved {
            animation: page-rating-saved 0.52s ease;
        }

        @keyframes page-rating-saved {
            0%, 100% { transform: translateY(0); }
            45% { transform: translateY(-2px); filter: brightness(1.16); }
        }

        .overview-header {
            position: relative;
            z-index: 1;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            margin-bottom: 22px;
        }

        .overview-header-actions {
            display: flex;
            align-items: center;
            gap: 12px;
            flex: 0 0 auto;
        }

        .narration-control {
            display: inline-flex;
            flex-direction: row;
            align-items: center;
            gap: 8px;
            padding: 8px;
            border: 1px solid rgba(197, 206, 218, 0.2);
            border-radius: 22px;
            background:
                linear-gradient(180deg, rgba(64, 74, 88, 0.36), rgba(17, 22, 30, 0.74)),
                linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 12px 22px rgba(0,0,0,0.2);
        }

        .autoplay-toggle {
            display: inline-flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 4px;
            min-width: 78px;
            min-height: 54px;
            padding: 6px 9px 7px;
            border: 1px solid rgba(197, 206, 218, 0.24);
            border-radius: 18px;
            cursor: pointer;
            color: rgba(241, 244, 248, 0.94);
            background:
                linear-gradient(180deg, rgba(67, 76, 91, 0.92), rgba(21, 26, 35, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 7px 14px rgba(0,0,0,0.18);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .autoplay-toggle:hover,
        .autoplay-toggle:focus-visible {
            transform: translateY(-1px);
            border-color: rgba(222, 228, 236, 0.42);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 10px 18px rgba(0,0,0,0.22),
                0 0 14px rgba(199, 208, 220, 0.14);
            outline: none;
        }

        .autoplay-toggle:active {
            transform: translateY(2px);
        }

        .autoplay-toggle.is-active {
            border-color: rgba(223, 229, 236, 0.46);
            color: #ffffff;
            background:
                linear-gradient(180deg, rgba(101, 112, 127, 0.96), rgba(34, 41, 52, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
        }

        .autoplay-toggle-label {
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.52rem;
            font-weight: 900;
            letter-spacing: 0.1em;
            line-height: 1;
            text-transform: uppercase;
            white-space: nowrap;
        }

        .autoplay-toggle-track {
            position: relative;
            width: 30px;
            height: 16px;
            border: 1px solid rgba(226, 236, 248, 0.28);
            border-radius: 999px;
            background: linear-gradient(180deg, rgba(18, 23, 31, 0.98), rgba(57, 67, 82, 0.96));
            box-shadow:
                inset 0 1px 2px rgba(0,0,0,0.34),
                inset 0 1px 0 rgba(255,255,255,0.06);
            transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
        }

        .autoplay-toggle-knob {
            position: absolute;
            top: 2px;
            left: 2px;
            width: 12px;
            height: 12px;
            border-radius: 999px;
            background: linear-gradient(180deg, #f4f7fb, #aeb8c7);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.36),
                0 2px 5px rgba(0,0,0,0.22);
            transition: transform 0.18s ease, background 0.18s ease;
        }

        .autoplay-toggle.is-active .autoplay-toggle-knob {
            transform: translateX(14px);
            background: linear-gradient(180deg, #ffffff, #cfd7e3);
        }

        .autoplay-toggle.is-active .autoplay-toggle-track {
            border-color: rgba(151, 239, 255, 0.88);
            background: linear-gradient(180deg, #39bdd5, #176b88);
            box-shadow:
                inset 0 1px 2px rgba(4, 37, 51, 0.42),
                0 0 10px rgba(107, 226, 247, 0.42);
        }

        .overview-title-wrap {
            min-width: 0;
        }

        .overview-kicker {
            margin: 0 0 6px;
            color: rgba(188, 232, 255, 0.7);
            font-size: 0.76rem;
            font-weight: 900;
            letter-spacing: 0.2em;
            text-transform: uppercase;
        }

        .overview-title {
            margin: 0;
            color: var(--gold-soft);
            font-size: clamp(1.8rem, 3vw, 2.55rem);
            line-height: 1.02;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }

        .title-inline-button {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            margin: 0 10px 0 0;
            padding: 0.2em 0.58em 0.24em;
            border: 1px solid rgba(255, 231, 161, 0.42);
            border-radius: 16px;
            cursor: pointer;
            color: #fff5cc;
            font: inherit;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            background:
                radial-gradient(circle at 22% 18%, rgba(255,255,255,0.3), transparent 30%),
                linear-gradient(180deg, rgba(255, 220, 123, 0.34), rgba(154, 104, 18, 0.5)),
                linear-gradient(180deg, rgba(12, 56, 110, 0.98), rgba(4, 24, 53, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.24),
                inset 0 -8px 14px rgba(0,0,0,0.16),
                0 7px 0 rgba(47, 28, 4, 0.7),
                0 14px 24px rgba(0,0,0,0.22);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
            vertical-align: middle;
        }

        .title-inline-button:hover,
        .title-inline-button:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 239, 194, 0.62);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.28),
                inset 0 -8px 14px rgba(0,0,0,0.16),
                0 7px 0 rgba(47, 28, 4, 0.7),
                0 18px 28px rgba(0,0,0,0.26),
                0 0 16px rgba(255, 226, 145, 0.16);
            outline: none;
        }

        .title-inline-button:active {
            transform: translateY(3px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.22),
                inset 0 -6px 12px rgba(0,0,0,0.14),
                0 3px 0 rgba(47, 28, 4, 0.78),
                0 9px 16px rgba(0,0,0,0.2);
        }

        .overview-breadcrumb {
            margin: 10px 0 0;
            color: rgba(233, 246, 255, 0.78);
            font-size: 0.86rem;
            line-height: 1.45;
            letter-spacing: 0.04em;
        }

        .back-button {
            width: 54px;
            height: 54px;
            flex: 0 0 auto;
            position: relative;
            isolation: isolate;
            border: 0;
            border-radius: 18px;
            cursor: pointer;
            touch-action: manipulation;
            user-select: none;
            color: #f7fbff;
            background:
                radial-gradient(circle at 26% 20%, rgba(255,255,255,0.38), transparent 24%),
                linear-gradient(145deg, rgba(255, 210, 106, 0.28), rgba(13, 50, 95, 0.98) 48%, rgba(3, 19, 43, 0.98)),
                rgba(3, 25, 54, 0.92);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.3),
                inset 0 -8px 14px rgba(0,0,0,0.24),
                0 8px 0 rgba(2, 15, 36, 0.86),
                0 18px 30px rgba(0,0,0,0.28);
            transition: transform 0.18s ease, box-shadow 0.18s ease;
        }

        .back-button::before {
            content: "";
            position: absolute;
            z-index: 0;
            inset: 4px;
            border-radius: 14px;
            opacity: 0;
            transform: scaleY(0);
            transform-origin: 50% 100%;
            background:
                linear-gradient(180deg, rgba(134, 243, 255, 0.48), rgba(255, 211, 105, 0.92)),
                rgba(42, 168, 218, 0.54);
            box-shadow: inset 0 0 18px rgba(255,255,255,0.42);
            pointer-events: none;
        }

        .back-button::after {
            content: "";
            position: absolute;
            z-index: 1;
            inset: -8px;
            border: 2px solid rgba(145, 237, 255, 0);
            border-radius: 25px;
            opacity: 0;
            pointer-events: none;
        }

        .back-button:hover,
        .back-button:focus-visible {
            transform: translateY(-2px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.34),
                inset 0 -8px 14px rgba(0,0,0,0.24),
                0 8px 0 rgba(2, 15, 36, 0.86),
                0 22px 34px rgba(0,0,0,0.32),
                0 0 20px rgba(167, 239, 255, 0.14);
            outline: none;
        }

        .back-button:active {
            transform: translateY(4px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.26),
                inset 0 -6px 12px rgba(0,0,0,0.22),
                0 3px 0 rgba(2, 15, 36, 0.9),
                0 10px 18px rgba(0,0,0,0.24);
        }

        .back-button.is-home-holding::before {
            opacity: 0.82;
            animation: back-button-home-progress 2s linear forwards;
        }

        .back-button.is-home-holding svg {
            animation: back-button-home-pulse 0.72s ease-in-out infinite alternate;
        }

        .back-button.is-home-launching {
            pointer-events: none;
            animation: back-button-home-launch 1.05s cubic-bezier(0.18, 0.82, 0.22, 1) both;
        }

        .back-button.is-home-launching::before {
            opacity: 1;
            transform: scaleY(1);
            animation: back-button-home-core 1.05s ease-out both;
        }

        .back-button.is-home-launching::after {
            animation: back-button-home-ring 1.05s ease-out both;
        }

        .back-button.is-home-launching svg {
            animation: back-button-home-arrow 1.05s cubic-bezier(0.2, 0.8, 0.2, 1) both;
        }

        @keyframes back-button-home-progress {
            0% { transform: scaleY(0); opacity: 0.38; }
            72% { opacity: 0.82; }
            100% { transform: scaleY(1); opacity: 1; }
        }

        @keyframes back-button-home-pulse {
            from { transform: translateX(0) scale(1); filter: drop-shadow(0 0 0 rgba(255,255,255,0)); }
            to { transform: translateX(-2px) scale(1.08); filter: drop-shadow(0 0 6px rgba(255,255,255,0.9)); }
        }

        @keyframes back-button-home-launch {
            0% { transform: translateY(2px) rotateY(0deg) scale(1); }
            35% { transform: translateY(-5px) rotateY(210deg) scale(1.16); }
            72% { transform: translateY(-2px) rotateY(540deg) scale(1.08); }
            100% { transform: translateY(0) rotateY(720deg) scale(1); }
        }

        @keyframes back-button-home-core {
            0% { filter: brightness(1); }
            42% { filter: brightness(2.1) saturate(1.35); }
            100% { filter: brightness(1.15); }
        }

        @keyframes back-button-home-ring {
            0% { inset: -5px; opacity: 0; border-color: rgba(145, 237, 255, 0.9); }
            35% { opacity: 1; }
            100% { inset: -30px; opacity: 0; border-color: rgba(255, 211, 105, 0.25); }
        }

        @keyframes back-button-home-arrow {
            0% { transform: translateX(0) scale(1); }
            35% { transform: translateX(-5px) scale(1.18); }
            70% { transform: translateX(3px) scale(0.92); }
            100% { transform: translateX(0) scale(1); }
        }

        .back-button[hidden] {
            display: none;
        }

        .back-button svg {
            position: relative;
            z-index: 2;
            width: 22px;
            height: 22px;
        }

        .narration-button {
            width: 54px;
            height: 54px;
            flex: 0 0 auto;
            border: 1px solid rgba(197, 206, 218, 0.28);
            border-radius: 18px;
            cursor: pointer;
            color: #f1f4f8;
            background:
                radial-gradient(circle at 26% 20%, rgba(255,255,255,0.28), transparent 24%),
                linear-gradient(145deg, rgba(223, 228, 235, 0.26), rgba(86, 96, 112, 0.98) 48%, rgba(29, 34, 43, 0.99)),
                rgba(23, 28, 36, 0.96);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.24),
                inset 0 -8px 14px rgba(0,0,0,0.22),
                0 8px 0 rgba(2, 15, 36, 0.86),
                0 18px 30px rgba(0,0,0,0.24);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, opacity 0.18s ease;
        }

        .narration-button:hover,
        .narration-button:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(221, 227, 236, 0.46);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.28),
                inset 0 -8px 14px rgba(0,0,0,0.22),
                0 8px 0 rgba(2, 15, 36, 0.86),
                0 22px 34px rgba(0,0,0,0.28),
                0 0 18px rgba(200, 208, 220, 0.16);
            outline: none;
        }

        .narration-button:active,
        .narration-button.is-playing {
            transform: translateY(3px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.22),
                inset 0 -6px 12px rgba(0,0,0,0.18),
                0 3px 0 rgba(2, 15, 36, 0.9),
                0 10px 18px rgba(0,0,0,0.22);
        }

        .narration-button.is-playing {
            border-color: rgba(232, 237, 244, 0.58);
            color: #ffffff;
        }

        .narration-button.is-paused {
            border-color: rgba(255, 228, 176, 0.52);
            color: #fff6df;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.22),
                inset 0 -6px 12px rgba(0,0,0,0.18),
                0 5px 0 rgba(2, 15, 36, 0.88),
                0 14px 22px rgba(0,0,0,0.24);
        }

        .narration-button[disabled] {
            cursor: not-allowed;
            opacity: 0.42;
            filter: saturate(0.4);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 5px 0 rgba(2, 15, 36, 0.76),
                0 10px 16px rgba(0,0,0,0.16);
        }

        .narration-button svg {
            width: 22px;
            height: 22px;
        }

        .overview-content {
            position: relative;
            z-index: 1;
            display: grid;
            grid-template-columns: minmax(0, 1fr);
            gap: 18px;
        }

        .guide-launcher-row {
            position: relative;
            z-index: 4;
            display: flex;
            justify-content: flex-end;
            max-height: 110px;
            overflow: visible;
            opacity: 1;
            transform: translateY(0);
            margin: -4px 2px -4px;
            transition:
                max-height 0.58s ease,
                opacity 0.48s ease,
                transform 0.58s ease,
                margin 0.58s ease;
        }

        .guide-launcher-row.is-faded {
            max-height: 0;
            overflow: hidden;
            margin: 0 2px -18px;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-12px);
        }

        .guide-launcher {
            position: relative;
            isolation: isolate;
            overflow: hidden;
            touch-action: manipulation;
            user-select: none;
            -webkit-user-select: none;
            -webkit-touch-callout: none;
            display: inline-grid;
            grid-template-columns: 46px auto;
            align-items: center;
            gap: 12px;
            min-height: 64px;
            padding: 8px 18px 8px 10px;
            border: 1px solid rgba(193, 186, 125, 0.58);
            border-radius: 18px;
            cursor: pointer;
            color: #f4f0ce;
            background:
                radial-gradient(ellipse at 12% 18%, rgba(193, 186, 125, 0.2) 0 18%, transparent 19%),
                radial-gradient(ellipse at 84% 72%, rgba(8, 16, 8, 0.56) 0 25%, transparent 26%),
                linear-gradient(145deg, #59633d, #28351f 48%, #121b11 100%);
            box-shadow:
                inset 0 1px 0 rgba(243, 239, 201, 0.16),
                inset 0 -12px 20px rgba(5, 11, 5, 0.2),
                0 6px 0 #0a1109,
                0 14px 24px rgba(0,0,0,0.28);
            font: inherit;
            text-align: left;
            transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
        }

        .guide-launcher::after {
            content: "";
            position: absolute;
            z-index: 0;
            left: 12px;
            right: 12px;
            bottom: 8px;
            height: 6px;
            border-radius: 999px;
            opacity: 0;
            transform: scaleX(0);
            transform-origin: left center;
            background: linear-gradient(90deg, rgba(113, 220, 210, 0.94), rgba(244, 207, 120, 0.98), rgba(143, 246, 255, 0.94));
            box-shadow:
                0 0 16px rgba(126, 232, 221, 0.48),
                0 0 30px rgba(244, 207, 120, 0.22);
            pointer-events: none;
        }

        .guide-launcher::before {
            content: "";
            position: absolute;
            z-index: 0;
            inset: 2px;
            border: 0 solid rgba(236, 231, 184, 0);
            border-radius: 15px;
            opacity: 0;
            box-shadow: none;
            pointer-events: none;
        }

        .guide-launcher > * {
            position: relative;
            z-index: 1;
        }

        .guide-launcher.is-command-centre-holding::after {
            animation: analytics-dashboard-hold-progress 4s linear forwards;
        }

        .guide-launcher.is-command-centre-holding {
            border-color: rgba(244, 224, 151, 0.92);
            animation: analytics-dashboard-hold-charge 0.68s ease-in-out infinite alternate;
        }

        .guide-launcher:hover,
        .guide-launcher:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(232, 224, 161, 0.82);
            box-shadow:
                inset 0 1px 0 rgba(243, 239, 201, 0.22),
                inset 0 -12px 20px rgba(5, 11, 5, 0.18),
                0 6px 0 #0a1109,
                0 18px 28px rgba(0,0,0,0.3),
                0 0 18px rgba(166, 177, 100, 0.18);
            outline: none;
        }

        .guide-launcher:active {
            transform: translateY(3px);
            box-shadow:
                inset 0 1px 0 rgba(243, 239, 201, 0.14),
                0 2px 0 #0a1109,
                0 8px 14px rgba(0,0,0,0.25);
        }

        .guide-launcher.is-command-centre-launching {
            z-index: 8;
            overflow: visible;
            pointer-events: none;
            transform-origin: center center;
            backface-visibility: visible;
            transform-style: preserve-3d;
            will-change: transform, filter, box-shadow;
            animation: guide-command-centre-launch-spin 2.4s cubic-bezier(.18,.72,.16,1) both;
        }

        .guide-launcher.is-command-centre-launching::before {
            inset: -4px;
            border-width: 4px;
            border-color: rgba(232, 226, 174, 0.94);
            border-radius: 22px;
            opacity: 1;
            box-shadow:
                2px 2px 0 #79815a,
                5px 5px 0 #475035,
                8px 8px 0 #252e20,
                11px 11px 0 #0a1109,
                14px 16px 24px rgba(0,0,0,0.44);
            animation: guide-command-centre-launch-depth 2.4s ease-in-out both;
        }

        .guide-launcher.is-command-centre-launching::after {
            inset: 0;
            height: auto;
            border-radius: inherit;
            opacity: 1;
            transform: none;
            background:
                radial-gradient(circle at 24% 30%, rgba(143, 246, 255, 0.45), transparent 20%),
                linear-gradient(110deg, rgba(94, 224, 172, 0.18), rgba(244, 207, 120, 0.42), rgba(143, 246, 255, 0.2));
            animation: guide-command-centre-launch-wash 2.4s cubic-bezier(.2,.72,.18,1) both;
        }

        .guide-document-icon {
            position: relative;
            width: 34px;
            height: 42px;
            justify-self: center;
            border: 2px solid rgba(244, 239, 203, 0.92);
            border-radius: 5px 10px 5px 5px;
            background: linear-gradient(155deg, #f0eccb, #aeb58a);
            box-shadow: 3px 4px 0 rgba(6, 14, 6, 0.62);
        }

        .guide-document-icon::before {
            content: "";
            position: absolute;
            top: -2px;
            right: -2px;
            width: 12px;
            height: 12px;
            border-left: 2px solid rgba(55, 68, 37, 0.58);
            border-bottom: 2px solid rgba(55, 68, 37, 0.58);
            border-radius: 0 8px 0 3px;
            background: #7c8959;
        }

        .guide-document-icon::after {
            content: "";
            position: absolute;
            left: 7px;
            bottom: 9px;
            width: 18px;
            height: 10px;
            border-top: 2px solid rgba(47, 61, 34, 0.66);
            border-bottom: 2px solid rgba(47, 61, 34, 0.66);
        }

        .guide-launcher-copy {
            display: grid;
            gap: 3px;
        }

        .guide-launcher-kicker {
            color: rgba(214, 208, 145, 0.84);
            font-size: 0.64rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            line-height: 1;
            text-transform: uppercase;
        }

        .guide-launcher-title {
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.06rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.05;
            text-transform: uppercase;
        }

        .guide-modal {
            position: fixed;
            z-index: 1000;
            inset: 0;
            display: grid;
            place-items: center;
            overflow: auto;
            padding: max(22px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(22px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
            background: rgba(1, 12, 30, 0.76);
            backdrop-filter: blur(12px);
            animation: guide-backdrop-in 0.22s ease both;
        }

        .guide-modal[hidden] {
            display: none;
        }

        .guide-window {
            isolation: isolate;
            width: min(760px, calc(100vw - 44px));
            max-height: min(calc(100dvh - 44px), 780px);
            min-height: 0;
            overflow: hidden;
            display: grid;
            grid-template-rows: auto minmax(0, 1fr);
            border: 1px solid rgba(180, 232, 255, 0.3);
            border-radius: 28px;
            outline: 1px solid rgba(221, 248, 255, 0.08);
            outline-offset: -2px;
            background-clip: padding-box;
            background:
                radial-gradient(circle at 9% 0%, rgba(167, 239, 255, 0.13), transparent 34%),
                linear-gradient(155deg, #0b376b, #041a3d 70%);
            background-color: #041a3d;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 32px 80px rgba(0,0,0,0.5),
                0 0 44px rgba(75, 185, 237, 0.13);
            animation: guide-window-in 0.3s cubic-bezier(.2,.85,.28,1) both;
        }

        .guide-window-head {
            display: grid;
            grid-template-columns: 48px minmax(0, 1fr) 42px;
            align-items: center;
            gap: 13px;
            padding: 18px 18px 16px 22px;
            border-bottom: 1px solid rgba(184, 230, 255, 0.14);
            background: rgba(3, 23, 54, 0.48);
        }

        .guide-window-head .guide-document-icon {
            width: 32px;
            height: 40px;
        }

        .guide-window-kicker {
            margin: 0 0 4px;
            color: rgba(167, 239, 255, 0.7);
            font-size: 0.62rem;
            font-weight: 900;
            letter-spacing: 0.17em;
            text-transform: uppercase;
        }

        .guide-window-title {
            margin: 0;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.25rem, 3vw, 1.8rem);
            letter-spacing: 0.055em;
            line-height: 1.05;
            text-transform: uppercase;
        }

        .guide-close {
            width: 42px;
            height: 42px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border: 1px solid rgba(205, 221, 236, 0.24);
            border-radius: 14px;
            cursor: pointer;
            color: rgba(241, 248, 255, 0.88);
            background: linear-gradient(180deg, rgba(81, 93, 109, 0.9), rgba(23, 29, 39, 0.96));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 6px 12px rgba(0,0,0,0.2);
            font: 900 1.3rem/1 "Segoe UI", sans-serif;
        }

        .guide-close:hover,
        .guide-close:focus-visible {
            color: #ffffff;
            border-color: rgba(255, 229, 162, 0.5);
            outline: none;
        }

        .guide-window-body {
            min-height: 0;
            overflow-y: auto;
            overscroll-behavior: contain;
            scrollbar-color: rgba(167, 239, 255, 0.5) rgba(3, 21, 49, 0.7);
            padding: 24px 28px 30px;
        }

        .guide-lead {
            margin: 0 0 22px;
            color: rgba(244, 250, 255, 0.96);
            font-size: clamp(1rem, 2vw, 1.12rem);
            font-weight: 700;
            line-height: 1.62;
        }

        .guide-section {
            margin-top: 25px;
            padding-top: 22px;
            border-top: 1px solid rgba(184, 230, 255, 0.12);
        }

        .guide-section-title {
            margin: 0 0 10px;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            letter-spacing: 0.09em;
            text-transform: uppercase;
        }

        .guide-copy,
        .guide-list {
            margin: 0;
            color: rgba(224, 241, 252, 0.83);
            font-size: 0.92rem;
            line-height: 1.66;
        }

        .guide-list {
            display: grid;
            gap: 8px;
            padding-left: 20px;
        }

        .guide-link-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 12px;
            margin-top: 15px;
        }

        .guide-link-card {
            min-width: 0;
            display: grid;
            gap: 5px;
            padding: 15px 16px;
            border: 1px solid rgba(167, 239, 255, 0.18);
            border-radius: 17px;
            color: rgba(241, 250, 255, 0.96);
            background: rgba(13, 62, 111, 0.52);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.07);
            text-decoration: none;
            transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
        }

        .guide-link-card:hover,
        .guide-link-card:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 229, 162, 0.48);
            background: rgba(21, 82, 137, 0.68);
            outline: none;
        }

        .guide-link-label {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.86rem;
            font-weight: 900;
            letter-spacing: 0.07em;
            text-transform: uppercase;
        }

        .guide-link-copy {
            color: rgba(211, 236, 251, 0.74);
            font-size: 0.76rem;
            line-height: 1.45;
        }

        @keyframes guide-backdrop-in {
            from { opacity: 0; }
            to { opacity: 1; }
        }

        @keyframes guide-window-in {
            from { opacity: 1; transform: translateY(14px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .analytics-dashboard-overlay {
            --holo-pointer-x: 50%;
            --holo-pointer-y: 14%;
            position: fixed;
            z-index: 1200;
            inset: 0;
            overflow: hidden;
            display: grid;
            place-items: center;
            padding: 14px;
            background:
                radial-gradient(circle at var(--holo-pointer-x) var(--holo-pointer-y), rgba(105, 239, 255, 0.16), transparent 24%),
                radial-gradient(circle at 50% 0%, rgba(65, 203, 216, 0.16), transparent 42%),
                rgba(1, 9, 23, 0.88);
            backdrop-filter: blur(16px) saturate(0.85);
            perspective: 1600px;
            animation: analytics-dashboard-backdrop 0.25s ease both;
        }

        .analytics-dashboard-overlay::before,
        .analytics-dashboard-overlay::after {
            content: "";
            position: absolute;
            pointer-events: none;
        }

        .analytics-dashboard-overlay::before {
            inset: -20%;
            background:
                repeating-linear-gradient(0deg, transparent 0 5px, rgba(111, 239, 255, 0.018) 6px),
                linear-gradient(90deg, transparent 48%, rgba(118, 240, 255, 0.08) 50%, transparent 52%);
            mix-blend-mode: screen;
            animation: analytics-dashboard-field-drift 16s linear infinite;
        }

        .analytics-dashboard-overlay::after {
            top: -14vh;
            left: calc(var(--holo-pointer-x) - 34vw);
            width: 68vw;
            height: 118vh;
            opacity: 0.24;
            background: linear-gradient(90deg, transparent, rgba(98, 229, 255, 0.08), transparent);
            clip-path: polygon(47% 0, 53% 0, 78% 100%, 22% 100%);
            filter: blur(14px);
            transition: left 0.45s cubic-bezier(.2,.8,.2,1);
        }

        .analytics-dashboard-window {
            --holo-pointer-x: 50%;
            --holo-pointer-y: 14%;
            position: relative;
            isolation: isolate;
            width: min(1500px, 100%);
            height: calc(100dvh - 28px);
            min-height: 560px;
            overflow: hidden;
            display: grid;
            grid-template-rows: auto minmax(0, 1fr) auto;
            border: 1px solid rgba(137, 234, 237, 0.3);
            border-radius: 30px;
            background:
                radial-gradient(circle at var(--holo-pointer-x) var(--holo-pointer-y), rgba(107, 236, 255, 0.11), transparent 26%),
                linear-gradient(rgba(114, 225, 229, 0.025) 1px, transparent 1px),
                linear-gradient(90deg, rgba(114, 225, 229, 0.025) 1px, transparent 1px),
                radial-gradient(circle at 4% 4%, rgba(53, 193, 201, 0.16), transparent 28%),
                linear-gradient(145deg, #071e35, #031224 62%, #071827);
            background-size: auto, 34px 34px, 34px 34px, auto, auto;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                inset 0 0 70px rgba(68, 221, 235, 0.055),
                0 38px 100px rgba(0,0,0,0.62),
                0 0 80px rgba(47, 202, 208, 0.2),
                0 0 2px rgba(164, 249, 255, 0.9);
            animation: analytics-dashboard-window-in 0.36s cubic-bezier(.2,.8,.24,1) both;
        }

        .analytics-dashboard-window::before,
        .analytics-dashboard-window::after {
            content: "";
            position: absolute;
            z-index: 4;
            inset: 0;
            border-radius: inherit;
            pointer-events: none;
        }

        .analytics-dashboard-window::before {
            opacity: 0.46;
            background:
                linear-gradient(#8ff6ff, #8ff6ff) 18px 14px / 72px 1px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) 14px 18px / 1px 72px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) calc(100% - 18px) 14px / 72px 1px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) calc(100% - 14px) 18px / 1px 72px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) 18px calc(100% - 14px) / 72px 1px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) 14px calc(100% - 18px) / 1px 72px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) calc(100% - 18px) calc(100% - 14px) / 72px 1px no-repeat,
                linear-gradient(#8ff6ff, #8ff6ff) calc(100% - 14px) calc(100% - 18px) / 1px 72px no-repeat,
                repeating-linear-gradient(0deg, transparent 0 7px, rgba(131, 243, 255, 0.024) 8px);
            box-shadow: inset 0 0 18px rgba(116, 240, 255, 0.08);
        }

        .analytics-dashboard-window::after {
            left: -36%;
            width: 28%;
            border-radius: 0;
            opacity: 0.34;
            background: linear-gradient(90deg, transparent, rgba(130, 244, 255, 0.2), rgba(255,255,255,0.08), transparent);
            filter: blur(8px);
            transform: skewX(-12deg);
            animation: analytics-dashboard-scan-sweep 9s ease-in-out infinite 1s;
        }

        .analytics-dashboard-holo-rail {
            position: absolute;
            z-index: 5;
            top: 104px;
            bottom: 26px;
            width: 1px;
            opacity: 0.62;
            background: linear-gradient(transparent, #7ff2ff 15%, rgba(127, 242, 255, 0.18) 78%, transparent);
            box-shadow: 0 0 13px rgba(127, 242, 255, 0.5);
            pointer-events: none;
        }

        .analytics-dashboard-holo-rail::before,
        .analytics-dashboard-holo-rail::after {
            position: absolute;
            color: rgba(145, 242, 255, 0.62);
            font: 700 0.48rem/1 Consolas, "Courier New", monospace;
            letter-spacing: 0.16em;
            writing-mode: vertical-rl;
        }

        .analytics-dashboard-holo-rail::before { content: "TLM // 01"; top: 18px; }
        .analytics-dashboard-holo-rail::after { content: "SYNC // LIVE"; bottom: 18px; }
        .analytics-dashboard-holo-rail.is-left { left: 8px; }
        .analytics-dashboard-holo-rail.is-right { right: 8px; transform: rotate(180deg); }

        .analytics-dashboard-head {
            position: relative;
            z-index: 2;
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto auto auto;
            align-items: center;
            gap: 20px;
            padding: 17px 20px 16px 24px;
            border-bottom: 1px solid rgba(137, 234, 237, 0.14);
            background: linear-gradient(90deg, rgba(2, 19, 38, 0.88), rgba(7, 51, 67, 0.48), rgba(2, 15, 31, 0.88));
            box-shadow: 0 12px 28px rgba(0,0,0,0.18), 0 1px 18px rgba(80, 227, 240, 0.08);
            backdrop-filter: blur(18px) saturate(1.25);
        }

        .analytics-dashboard-head::after {
            content: "TELEMETRY / ACTIVE / SECURE CHANNEL";
            position: absolute;
            right: 92px;
            bottom: -5px;
            color: rgba(115, 233, 244, 0.5);
            background: #061a2d;
            font: 700 0.47rem/1 Consolas, "Courier New", monospace;
            letter-spacing: 0.15em;
            padding: 0 8px;
        }

        .analytics-dashboard-brand {
            min-width: 0;
            display: flex;
            align-items: center;
            gap: 14px;
        }

        .analytics-dashboard-orbit {
            position: relative;
            width: 46px;
            height: 46px;
            flex: 0 0 auto;
            appearance: none;
            padding: 0;
            border: 1px solid rgba(121, 234, 237, 0.42);
            border-radius: 50%;
            cursor: pointer;
            color: inherit;
            background: rgba(6, 42, 59, 0.28);
            box-shadow: inset 0 0 18px rgba(75, 224, 224, 0.14), 0 0 18px rgba(75, 224, 224, 0.12);
        }

        .analytics-dashboard-orbit:hover,
        .analytics-dashboard-orbit:focus-visible {
            border-color: rgba(244, 207, 120, 0.72);
            outline: none;
            box-shadow: inset 0 0 20px rgba(75, 224, 224, 0.2), 0 0 24px rgba(121, 234, 237, 0.24);
        }

        .analytics-dashboard-orbit.is-ip-holding {
            animation: analytics-dashboard-ip-charge 5s linear forwards;
        }

        .analytics-dashboard-orbit.is-ip-visible {
            border-color: rgba(94, 224, 172, 0.78);
            box-shadow: inset 0 0 22px rgba(94, 224, 172, 0.2), 0 0 26px rgba(94, 224, 172, 0.3);
        }

        .analytics-dashboard-orbit::before,
        .analytics-dashboard-orbit::after {
            content: "";
            position: absolute;
            inset: 8px;
            border: 2px solid transparent;
            border-top-color: #79eaed;
            border-bottom-color: #f4cf78;
            border-radius: 50%;
            animation: analytics-dashboard-orbit 4s linear infinite;
        }

        .analytics-dashboard-orbit::after {
            inset: 16px;
            border: 0;
            background: #f4cf78;
            box-shadow: 0 0 16px rgba(244, 207, 120, 0.72);
            animation: none;
        }

        .analytics-dashboard-kicker {
            margin: 0 0 4px;
            color: rgba(121, 234, 237, 0.7);
            font-size: 0.62rem;
            font-weight: 900;
            letter-spacing: 0.2em;
            text-transform: uppercase;
        }

        .analytics-dashboard-title {
            overflow: hidden;
            margin: 0;
            color: #f7e7b0;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.25rem, 2.5vw, 2rem);
            letter-spacing: 0.08em;
            line-height: 1;
            text-overflow: ellipsis;
            text-transform: uppercase;
            white-space: nowrap;
            text-shadow: 0 0 16px rgba(125, 240, 250, 0.22), 0 0 38px rgba(125, 240, 250, 0.08);
        }

        .analytics-dashboard-title-mobile {
            display: none;
        }

        .analytics-dashboard-live {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            color: rgba(204, 249, 242, 0.78);
            font-size: 0.65rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .analytics-dashboard-live::before {
            content: "";
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: #5ee0ac;
            box-shadow: 0 0 13px rgba(94, 224, 172, 0.8);
            animation: analytics-dashboard-live-pulse 1.8s ease-in-out infinite;
        }

        .analytics-dashboard-close {
            width: 44px;
            height: 44px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border: 1px solid rgba(188, 222, 230, 0.22);
            border-radius: 15px;
            cursor: pointer;
            color: rgba(239, 250, 252, 0.9);
            background: linear-gradient(180deg, rgba(40, 109, 121, 0.68), rgba(6, 29, 43, 0.92));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.18), 0 7px 14px rgba(0,0,0,0.24), 0 0 18px rgba(106, 233, 244, 0.1);
            font: 900 1.35rem/1 "Segoe UI", sans-serif;
        }

        .analytics-dashboard-close:hover,
        .analytics-dashboard-close:focus-visible,
        .analytics-dashboard-logout:hover,
        .analytics-dashboard-logout:focus-visible {
            border-color: rgba(244, 207, 120, 0.58);
            color: #ffffff;
            outline: none;
        }

        .analytics-dashboard-logout {
            min-height: 38px;
            padding: 0 13px;
            border: 1px solid rgba(188, 222, 230, 0.18);
            border-radius: 12px;
            cursor: pointer;
            color: rgba(218, 239, 242, 0.78);
            background: linear-gradient(180deg, rgba(23, 66, 79, 0.72), rgba(6, 29, 43, 0.9));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.1), 0 6px 12px rgba(0,0,0,0.18);
            font: 900 0.6rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            letter-spacing: 0.11em;
            text-transform: uppercase;
        }

        .analytics-dashboard-ga4-link {
            position: static;
            z-index: 8;
            justify-self: end;
            display: inline-flex;
            align-items: center;
            gap: 10px;
            margin: 0 24px 18px;
            padding: 11px 14px 10px 12px;
            border: 1px solid rgba(244, 207, 120, 0.34);
            border-radius: 999px;
            color: rgba(247, 231, 176, 0.96);
            background:
                radial-gradient(circle at 20% 20%, rgba(244, 207, 120, 0.18), transparent 42%),
                linear-gradient(145deg, rgba(10, 39, 62, 0.88), rgba(4, 18, 32, 0.94));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 11px 24px rgba(0,0,0,0.34), 0 0 24px rgba(244, 207, 120, 0.12);
            font: 900 0.62rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            letter-spacing: 0.13em;
            text-decoration: none;
            text-transform: uppercase;
            opacity: 0;
            pointer-events: none;
            transition:
                opacity 0.38s ease,
                visibility 0s linear 0.38s;
            visibility: hidden;
        }

        .analytics-dashboard-window.is-command-centre-intro-complete .analytics-dashboard-ga4-link {
            opacity: 1;
            pointer-events: auto;
            transition-delay: 0s;
            visibility: visible;
        }

        .analytics-dashboard-ga4-link::before {
            content: "GA4";
            display: grid;
            place-items: center;
            width: 36px;
            height: 36px;
            border-radius: 50%;
            color: #061827;
            background: conic-gradient(from 210deg, #f4cf78, #5ee0ac, #79eaed, #f4cf78);
            box-shadow: 0 0 20px rgba(121, 234, 237, 0.22);
            letter-spacing: 0.02em;
        }

        .analytics-dashboard-ga4-link:hover,
        .analytics-dashboard-ga4-link:focus-visible {
            color: #ffffff;
            border-color: rgba(121, 234, 237, 0.64);
            outline: none;
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.16), 0 13px 28px rgba(0,0,0,0.38), 0 0 32px rgba(121, 234, 237, 0.2);
        }

        .analytics-dashboard-stage {
            position: relative;
            z-index: 1;
            min-height: 0;
            overflow-y: auto;
            overscroll-behavior: contain;
            scrollbar-color: rgba(121, 234, 237, 0.42) rgba(2, 15, 31, 0.7);
            padding: clamp(16px, 2.2vw, 30px);
            background:
                radial-gradient(circle at var(--holo-pointer-x) var(--holo-pointer-y), rgba(94, 226, 239, 0.055), transparent 24%),
                linear-gradient(105deg, transparent 0 46%, rgba(106, 235, 246, 0.022) 50%, transparent 54%);
        }

        .analytics-dashboard-access {
            min-height: 100%;
            display: grid;
            place-items: center;
        }

        .analytics-dashboard-access-card {
            width: min(520px, 100%);
            padding: clamp(24px, 4vw, 42px);
            border: 1px solid rgba(121, 234, 237, 0.22);
            border-radius: 26px;
            background:
                radial-gradient(circle at 50% 0%, rgba(121, 234, 237, 0.12), transparent 40%),
                rgba(5, 29, 51, 0.88);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 24px 50px rgba(0,0,0,0.28);
            text-align: center;
        }

        .analytics-dashboard-access-icon {
            width: 68px;
            height: 68px;
            display: grid;
            place-items: center;
            margin: 0 auto 18px;
            border: 1px solid rgba(244, 207, 120, 0.42);
            border-radius: 22px;
            color: #f4cf78;
            background: rgba(244, 207, 120, 0.08);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 0 26px rgba(244, 207, 120, 0.08);
            font-size: 1.6rem;
        }

        .analytics-dashboard-access-title {
            margin: 0 0 8px;
            color: #f7e7b0;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.35rem;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .analytics-dashboard-access-copy,
        .analytics-dashboard-access-status {
            margin: 0;
            color: rgba(218, 240, 244, 0.72);
            font-size: 0.84rem;
            line-height: 1.55;
        }

        .analytics-dashboard-access-form {
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            gap: 10px;
            margin-top: 22px;
        }

        .analytics-dashboard-access-input {
            min-width: 0;
            height: 48px;
            border: 1px solid rgba(121, 234, 237, 0.24);
            border-radius: 14px;
            outline: none;
            color: #eefbfb;
            background: rgba(1, 13, 27, 0.72);
            font: 700 0.9rem/1 Consolas, "Courier New", monospace;
            padding: 0 14px;
        }

        .analytics-dashboard-access-input:focus {
            border-color: rgba(121, 234, 237, 0.72);
            box-shadow: 0 0 0 4px rgba(121, 234, 237, 0.08);
        }

        .analytics-dashboard-access-submit,
        .analytics-dashboard-period {
            border: 1px solid rgba(121, 234, 237, 0.28);
            border-radius: 13px;
            cursor: pointer;
            color: rgba(235, 250, 250, 0.88);
            background: linear-gradient(180deg, rgba(34, 99, 111, 0.95), rgba(10, 46, 59, 0.98));
            font: 900 0.68rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            letter-spacing: 0.11em;
            padding: 0 17px;
            text-transform: uppercase;
        }

        .analytics-dashboard-access-submit:hover,
        .analytics-dashboard-access-submit:focus-visible,
        .analytics-dashboard-period:hover,
        .analytics-dashboard-period:focus-visible,
        .analytics-dashboard-period.is-active {
            border-color: rgba(244, 207, 120, 0.58);
            color: #fff2c8;
            background: linear-gradient(180deg, rgba(111, 92, 45, 0.96), rgba(51, 40, 18, 0.98));
            outline: none;
        }

        .analytics-dashboard-access-status {
            min-height: 1.4em;
            margin-top: 13px;
            color: #f1ab91;
        }

        .analytics-dashboard-content {
            display: grid;
            gap: 18px;
        }

        .analytics-dashboard-toolbar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 14px;
        }

        .analytics-dashboard-periods {
            display: inline-flex;
            gap: 6px;
            padding: 5px;
            border: 1px solid rgba(121, 234, 237, 0.14);
            border-radius: 16px;
            background: rgba(1, 14, 29, 0.58);
        }

        .analytics-dashboard-period {
            min-height: 36px;
            padding: 0 14px;
        }

        .analytics-dashboard-updated {
            color: rgba(187, 223, 229, 0.56);
            font-size: 0.66rem;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .analytics-dashboard-session-grid,
        .analytics-dashboard-metric-grid {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 12px;
        }

        .analytics-dashboard-metric-grid {
            grid-template-columns: repeat(4, minmax(0, 1fr));
        }

        .analytics-dashboard-session-card,
        .analytics-dashboard-metric,
        .analytics-dashboard-panel {
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(121, 234, 237, 0.2);
            border-radius: 22px;
            background:
                radial-gradient(circle at 100% 0%, rgba(121, 234, 237, 0.09), transparent 34%),
                linear-gradient(145deg, rgba(9, 55, 78, 0.7), rgba(3, 22, 40, 0.86));
            box-shadow: inset 0 1px 0 rgba(211, 251, 255, 0.09), inset 0 0 24px rgba(79, 221, 234, 0.03), 0 14px 25px rgba(0,0,0,0.16), 0 0 18px rgba(74, 219, 231, 0.04);
            backdrop-filter: blur(13px) saturate(1.15);
            transform: translateZ(0);
            transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
        }

        .analytics-dashboard-session-card::after,
        .analytics-dashboard-metric::after,
        .analytics-dashboard-panel::after,
        .analytics-dashboard-audio::before {
            content: "";
            position: absolute;
            z-index: 0;
            top: -30%;
            left: -70%;
            width: 34%;
            height: 160%;
            opacity: 0;
            background: linear-gradient(90deg, transparent, rgba(155, 248, 255, 0.14), transparent);
            transform: skewX(-16deg);
            pointer-events: none;
        }

        @media (hover: hover) and (pointer: fine) {
            .analytics-dashboard-session-card:hover,
            .analytics-dashboard-metric:hover,
            .analytics-dashboard-panel:hover,
            .analytics-dashboard-audio:hover {
                border-color: rgba(137, 241, 249, 0.42);
                box-shadow: inset 0 1px 0 rgba(225, 253, 255, 0.14), inset 0 0 30px rgba(79, 221, 234, 0.055), 0 18px 32px rgba(0,0,0,0.22), 0 0 24px rgba(74, 219, 231, 0.1);
                transform: translateY(-2px) translateZ(0);
            }

            .analytics-dashboard-session-card:hover::after,
            .analytics-dashboard-metric:hover::after,
            .analytics-dashboard-panel:hover::after,
            .analytics-dashboard-audio:hover::before {
                animation: analytics-dashboard-card-glint 0.9s ease both;
            }
        }

        .analytics-dashboard-session-card {
            min-height: 116px;
            display: grid;
            align-content: end;
            padding: 18px 20px;
        }

        .analytics-dashboard-session-card::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 5px;
            height: 100%;
            background: linear-gradient(#79eaed, #2c7180);
            box-shadow: 0 0 18px rgba(121, 234, 237, 0.35);
        }

        .analytics-dashboard-session-card:nth-child(2)::before { background: linear-gradient(#f4cf78, #8d6a2d); }
        .analytics-dashboard-session-card:nth-child(3)::before { background: linear-gradient(#72dda8, #2f7454); }

        .analytics-dashboard-value {
            color: #ffffff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(2rem, 4vw, 3.35rem);
            font-weight: 900;
            letter-spacing: -0.03em;
            line-height: 0.9;
            text-shadow: 0 0 16px rgba(117, 238, 248, 0.2);
        }

        .analytics-dashboard-label {
            margin-top: 9px;
            color: rgba(181, 224, 229, 0.68);
            font-size: 0.64rem;
            font-weight: 900;
            letter-spacing: 0.15em;
            text-transform: uppercase;
        }

        .analytics-dashboard-metric {
            min-height: 106px;
            display: grid;
            align-content: center;
            padding: 16px 18px;
        }

        .analytics-dashboard-metric-value {
            color: #f7e7b0;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.42rem, 2.7vw, 2.1rem);
            font-weight: 900;
            line-height: 1;
        }

        .analytics-dashboard-columns {
            display: grid;
            grid-template-columns: minmax(0, 1.15fr) minmax(330px, 0.85fr);
            gap: 14px;
        }

        .analytics-dashboard-panel {
            padding: 18px;
        }

        .analytics-dashboard-panel-title {
            margin: 0 0 15px;
            color: rgba(236, 248, 247, 0.9);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.78rem;
            letter-spacing: 0.13em;
            text-transform: uppercase;
        }

        .analytics-dashboard-device-layout {
            display: grid;
            grid-template-columns: 150px minmax(0, 1fr);
            align-items: center;
            gap: 20px;
        }

        .analytics-dashboard-device-ring {
            --mobile-angle: 0deg;
            --tablet-angle: 0deg;
            width: 142px;
            aspect-ratio: 1;
            display: grid;
            place-items: center;
            border-radius: 50%;
            background: conic-gradient(
                #79eaed 0 var(--mobile-angle),
                #f4cf78 var(--mobile-angle) var(--tablet-angle),
                #4d7897 var(--tablet-angle) 360deg
            );
            box-shadow: 0 0 28px rgba(67, 207, 211, 0.22), 0 0 0 1px rgba(135, 244, 252, 0.08), 0 0 0 9px rgba(72, 216, 229, 0.025);
            animation: analytics-dashboard-ring-breathe 4.5s ease-in-out infinite;
        }

        .analytics-dashboard-device-ring::before {
            content: attr(data-total);
            width: 94px;
            aspect-ratio: 1;
            display: grid;
            place-items: center;
            border-radius: 50%;
            color: #ffffff;
            background: #061a2d;
            box-shadow: inset 0 0 20px rgba(121, 234, 237, 0.09);
            font: 900 1.55rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
        }

        .analytics-dashboard-device-list,
        .analytics-dashboard-ranking,
        .analytics-dashboard-transitions {
            display: grid;
            gap: 9px;
        }

        .analytics-dashboard-device-item,
        .analytics-dashboard-rank,
        .analytics-dashboard-transition {
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            align-items: center;
            gap: 12px;
            color: rgba(215, 238, 241, 0.76);
            font-size: 0.76rem;
        }

        .analytics-dashboard-device-name::before {
            content: "";
            display: inline-block;
            width: 8px;
            height: 8px;
            margin-right: 8px;
            border-radius: 50%;
            background: #79eaed;
        }

        .analytics-dashboard-device-item:nth-child(2) .analytics-dashboard-device-name::before { background: #f4cf78; }
        .analytics-dashboard-device-item:nth-child(3) .analytics-dashboard-device-name::before { background: #4d7897; }

        .analytics-dashboard-device-count,
        .analytics-dashboard-rank-count,
        .analytics-dashboard-transition-count {
            color: #f7e7b0;
            font-family: Consolas, "Courier New", monospace;
            font-weight: 800;
        }

        .analytics-dashboard-timeline {
            height: 178px;
            display: grid;
            grid-template-columns: repeat(30, minmax(3px, 1fr));
            align-items: end;
            gap: 3px;
            padding-top: 15px;
            border-bottom: 1px solid rgba(121, 234, 237, 0.18);
        }

        .analytics-dashboard-timeline-day {
            position: relative;
            height: 100%;
            display: flex;
            align-items: end;
            gap: 1px;
        }

        .analytics-dashboard-timeline-bar {
            width: 50%;
            min-height: 2px;
            border-radius: 4px 4px 0 0;
            background: linear-gradient(#79eaed, #245f71);
            box-shadow: 0 0 10px rgba(121, 234, 237, 0.3);
        }

        .analytics-dashboard-timeline-bar.is-clicks {
            background: linear-gradient(#f4cf78, #806027);
            box-shadow: 0 0 7px rgba(244, 207, 120, 0.12);
        }

        .analytics-dashboard-timeline-day:hover::after {
            content: attr(data-tooltip);
            position: absolute;
            z-index: 2;
            left: 50%;
            bottom: calc(100% + 7px);
            width: max-content;
            max-width: 180px;
            transform: translateX(-50%);
            border: 1px solid rgba(121, 234, 237, 0.24);
            border-radius: 8px;
            color: #eaf8f8;
            background: #031426;
            box-shadow: 0 8px 18px rgba(0,0,0,0.28);
            font: 700 0.62rem/1.3 Consolas, "Courier New", monospace;
            padding: 7px 8px;
            pointer-events: none;
        }

        .analytics-dashboard-legend {
            display: flex;
            gap: 15px;
            margin-top: 10px;
            color: rgba(187, 223, 229, 0.58);
            font-size: 0.64rem;
            text-transform: uppercase;
        }

        .analytics-dashboard-legend span::before {
            content: "";
            display: inline-block;
            width: 9px;
            height: 9px;
            margin-right: 6px;
            border-radius: 2px;
            background: #79eaed;
        }

        .analytics-dashboard-legend span:last-child::before { background: #f4cf78; }

        .analytics-dashboard-rank,
        .analytics-dashboard-transition {
            min-height: 43px;
            padding: 9px 11px;
            border: 1px solid rgba(121, 234, 237, 0.09);
            border-radius: 12px;
            background: rgba(2, 18, 34, 0.52);
        }

        .analytics-dashboard-rank-copy,
        .analytics-dashboard-transition-copy {
            min-width: 0;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .analytics-dashboard-empty {
            margin: 0;
            color: rgba(187, 223, 229, 0.52);
            font-size: 0.76rem;
            line-height: 1.5;
        }

        .analytics-dashboard-audio {
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(244, 207, 120, 0.22);
            border-radius: 22px;
            background:
                radial-gradient(circle at 0% 0%, rgba(244, 207, 120, 0.09), transparent 30%),
                linear-gradient(145deg, rgba(10, 43, 67, 0.9), rgba(3, 21, 38, 0.96));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), inset 0 0 34px rgba(93, 227, 238, 0.025), 0 14px 25px rgba(0,0,0,0.16), 0 0 22px rgba(93, 227, 238, 0.05);
            backdrop-filter: blur(13px) saturate(1.15);
            transition: transform 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
        }

        .analytics-dashboard-audio > * { position: relative; z-index: 1; }

        .analytics-dashboard-audio-summary {
            list-style: none;
            display: grid;
            grid-template-columns: auto minmax(0, 1fr) auto auto;
            align-items: center;
            gap: 14px;
            min-height: 82px;
            padding: 14px 18px;
            cursor: pointer;
            user-select: none;
        }

        .analytics-dashboard-audio-summary::-webkit-details-marker {
            display: none;
        }

        .analytics-dashboard-audio-wave {
            width: 46px;
            height: 46px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 3px;
            border: 1px solid rgba(244, 207, 120, 0.28);
            border-radius: 15px;
            background: rgba(244, 207, 120, 0.06);
        }

        .analytics-dashboard-audio-wave i {
            width: 3px;
            border-radius: 999px;
            background: linear-gradient(#f4cf78, #79eaed);
            box-shadow: 0 0 7px rgba(244, 207, 120, 0.2);
            animation: analytics-dashboard-wave 1.8s ease-in-out infinite;
        }

        .analytics-dashboard-audio-wave i:nth-child(1),
        .analytics-dashboard-audio-wave i:nth-child(5) { height: 12px; }
        .analytics-dashboard-audio-wave i:nth-child(2),
        .analytics-dashboard-audio-wave i:nth-child(4) { height: 23px; }
        .analytics-dashboard-audio-wave i:nth-child(3) { height: 32px; }
        .analytics-dashboard-audio-wave i:nth-child(2) { animation-delay: -0.25s; }
        .analytics-dashboard-audio-wave i:nth-child(3) { animation-delay: -0.5s; }
        .analytics-dashboard-audio-wave i:nth-child(4) { animation-delay: -0.75s; }
        .analytics-dashboard-audio-wave i:nth-child(5) { animation-delay: -1s; }

        .analytics-dashboard-audio-title {
            display: block;
            color: #f7e7b0;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            font-weight: 900;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .analytics-dashboard-audio-copy {
            display: block;
            margin-top: 4px;
            color: rgba(196, 228, 232, 0.58);
            font-size: 0.68rem;
            line-height: 1.35;
        }

        .analytics-dashboard-audio-preview {
            color: rgba(228, 242, 239, 0.72);
            font-size: 0.7rem;
            font-weight: 800;
            white-space: nowrap;
        }

        .analytics-dashboard-audio-chevron {
            width: 32px;
            height: 32px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(121, 234, 237, 0.16);
            border-radius: 50%;
            color: #79eaed;
            transition: transform 0.22s ease, color 0.22s ease;
        }

        .analytics-dashboard-audio[open] .analytics-dashboard-audio-chevron {
            transform: rotate(180deg);
            color: #f4cf78;
        }

        .analytics-dashboard-audio-body {
            display: grid;
            gap: 16px;
            border-top: 1px solid rgba(244, 207, 120, 0.12);
            padding: 18px;
        }

        .analytics-dashboard-audio-grid {
            display: grid;
            grid-template-columns: repeat(6, minmax(0, 1fr));
            gap: 8px;
        }

        .analytics-dashboard-audio-metric {
            min-height: 94px;
            display: grid;
            align-content: center;
            padding: 13px;
            border: 1px solid rgba(121, 234, 237, 0.1);
            border-radius: 15px;
            background: rgba(2, 18, 34, 0.52);
        }

        .analytics-dashboard-audio-value {
            color: #f7e7b0;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.5rem;
            font-weight: 900;
            line-height: 1;
        }

        .analytics-dashboard-audio-label {
            margin-top: 8px;
            color: rgba(168, 211, 217, 0.62);
            font-size: 0.55rem;
            font-weight: 900;
            letter-spacing: 0.1em;
            line-height: 1.25;
            text-transform: uppercase;
        }

        .analytics-dashboard-audio-columns {
            display: grid;
            grid-template-columns: minmax(280px, 0.7fr) minmax(0, 1.3fr);
            gap: 12px;
            min-width: 0;
        }

        .analytics-dashboard-audio-card {
            min-width: 0;
            border: 1px solid rgba(121, 234, 237, 0.09);
            border-radius: 16px;
            background: rgba(2, 18, 34, 0.4);
            padding: 15px;
        }

        .analytics-dashboard-audio-card-title {
            margin: 0 0 12px;
            color: rgba(231, 245, 245, 0.82);
            font-size: 0.66rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .analytics-dashboard-audio-state {
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            gap: 10px;
            align-items: center;
            margin-top: 9px;
            color: rgba(206, 232, 235, 0.7);
            font-size: 0.72rem;
        }

        .analytics-dashboard-audio-state strong {
            color: #f7e7b0;
            font-family: Consolas, "Courier New", monospace;
        }

        .analytics-dashboard-audio-table-scroll {
            width: 100%;
            max-width: 100%;
            overflow-x: auto;
            overscroll-behavior-inline: contain;
            -webkit-overflow-scrolling: touch;
        }

        .analytics-dashboard-audio-table {
            width: 100%;
            min-width: 650px;
            border-collapse: collapse;
            color: rgba(211, 236, 239, 0.7);
            font-size: 0.68rem;
        }

        .analytics-dashboard-audio-table th,
        .analytics-dashboard-audio-table td {
            border-bottom: 1px solid rgba(121, 234, 237, 0.07);
            padding: 9px 8px;
            text-align: left;
        }

        .analytics-dashboard-audio-table th {
            color: rgba(121, 234, 237, 0.66);
            font-size: 0.56rem;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .analytics-dashboard-ratings {
            border-color: rgba(115, 232, 169, 0.22);
            background:
                radial-gradient(circle at 10% 0%, rgba(75, 224, 145, 0.1), transparent 42%),
                radial-gradient(circle at 94% 100%, rgba(255, 84, 112, 0.08), transparent 38%),
                rgba(2, 18, 34, 0.72);
        }

        .analytics-dashboard-rating-icon {
            position: relative;
            width: 46px;
            height: 46px;
            display: grid;
            place-items: center;
            overflow: hidden;
            border: 1px solid rgba(141, 238, 187, 0.17);
            border-radius: 15px;
            background: rgba(12, 57, 50, 0.34);
            color: #68dfa2;
        }

        .analytics-dashboard-rating-icon svg {
            width: 22px;
            height: 22px;
            filter: drop-shadow(0 0 8px rgba(80, 227, 151, 0.34));
        }

        .analytics-dashboard-rating-balance {
            display: grid;
            grid-template-columns: var(--rating-up, 50%) minmax(0, 1fr);
            min-height: 12px;
            overflow: hidden;
            border: 1px solid rgba(211, 238, 239, 0.1);
            border-radius: 999px;
            background: rgba(255, 74, 103, 0.42);
        }

        .analytics-dashboard-rating-balance span {
            background: linear-gradient(90deg, rgba(56, 207, 128, 0.56), #58e29b);
            box-shadow: 0 0 16px rgba(73, 223, 146, 0.28);
        }

        .analytics-dashboard-rating-balance-labels {
            display: flex;
            justify-content: space-between;
            gap: 10px;
            margin-top: 8px;
            color: rgba(208, 235, 237, 0.62);
            font-size: 0.65rem;
            font-weight: 800;
        }

        .analytics-dashboard-rating-distribution {
            display: grid;
            gap: 8px;
        }

        .analytics-dashboard-rating-distribution-row {
            display: grid;
            grid-template-columns: 55px minmax(0, 1fr) 55px;
            align-items: center;
            gap: 9px;
            color: rgba(211, 236, 239, 0.66);
            font: 800 0.64rem Consolas, "Courier New", monospace;
        }

        .analytics-dashboard-rating-distribution-row > span:last-child {
            text-align: right;
        }

        .analytics-dashboard-rating-distribution-track {
            height: 7px;
            display: grid;
            grid-template-columns: minmax(0, var(--down-width, 0%)) minmax(0, var(--up-width, 0%));
            justify-content: center;
            overflow: hidden;
            border-radius: 999px;
            background: rgba(192, 227, 234, 0.06);
        }

        .analytics-dashboard-rating-distribution-track i:first-child {
            background: linear-gradient(90deg, rgba(255, 70, 99, 0.42), #ff5872);
        }

        .analytics-dashboard-rating-distribution-track i:last-child {
            background: linear-gradient(90deg, #4bd68f, rgba(75, 214, 143, 0.38));
        }

        .analytics-dashboard-rating-score {
            display: inline-flex;
            min-width: 44px;
            justify-content: center;
            border: 1px solid color-mix(in srgb, var(--rating-score-color, #79eaed) 36%, transparent);
            border-radius: 999px;
            background: color-mix(in srgb, var(--rating-score-color, #79eaed) 10%, transparent);
            color: var(--rating-score-color, #79eaed);
            font: 900 0.68rem Consolas, "Courier New", monospace;
            padding: 4px 7px;
        }

        .analytics-dashboard-rating-unavailable {
            margin: 0;
            border: 1px dashed rgba(244, 207, 120, 0.28);
            border-radius: 15px;
            color: rgba(232, 237, 220, 0.72);
            font-size: 0.74rem;
            line-height: 1.55;
            padding: 15px;
        }

        .analytics-dashboard-table-scroll {
            overflow-x: auto;
            scrollbar-color: rgba(121, 234, 237, 0.34) rgba(2, 15, 31, 0.6);
        }

        .analytics-dashboard-table {
            width: 100%;
            min-width: 820px;
            border-collapse: collapse;
            color: rgba(218, 240, 243, 0.72);
            font-size: 0.7rem;
        }

        .analytics-dashboard-table.is-ip-visible {
            min-width: 980px;
        }

        .analytics-dashboard-table.is-journeys {
            min-width: 1000px;
        }

        .analytics-dashboard-table.is-journeys.is-ip-visible {
            min-width: 1160px;
        }

        .analytics-dashboard-table th,
        .analytics-dashboard-table td {
            border-bottom: 1px solid rgba(121, 234, 237, 0.08);
            padding: 10px 9px;
            text-align: left;
        }

        .analytics-dashboard-table th {
            color: rgba(121, 234, 237, 0.68);
            font-size: 0.6rem;
            letter-spacing: 0.11em;
            text-transform: uppercase;
        }

        .analytics-dashboard-journey-when {
            min-width: 172px;
            white-space: nowrap;
        }

        .analytics-dashboard-journey-when strong,
        .analytics-dashboard-journey-when span {
            display: block;
        }

        .analytics-dashboard-journey-when strong {
            color: rgba(231, 250, 252, 0.92);
            font-size: 0.7rem;
            font-weight: 800;
        }

        .analytics-dashboard-journey-when span {
            margin-top: 4px;
            color: rgba(121, 234, 237, 0.58);
            font-size: 0.56rem;
            letter-spacing: 0.04em;
        }

        .analytics-dashboard-external-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 10px;
            margin-bottom: 14px;
        }

        .analytics-dashboard-external-card {
            position: relative;
            overflow: hidden;
            min-height: 92px;
            padding: 15px;
            border: 1px solid rgba(244, 207, 120, 0.18);
            border-radius: 18px;
            background:
                radial-gradient(circle at 12% 0%, rgba(244, 207, 120, 0.12), transparent 46%),
                rgba(4, 29, 48, 0.64);
        }

        .analytics-dashboard-external-card::after {
            content: "";
            position: absolute;
            inset: auto 14px 12px;
            height: 1px;
            background: linear-gradient(90deg, rgba(244, 207, 120, 0.6), transparent);
        }

        .analytics-dashboard-external-label {
            display: block;
            color: rgba(121, 234, 237, 0.72);
            font-size: 0.6rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .analytics-dashboard-external-value {
            display: block;
            margin-top: 9px;
            color: #f7e7b0;
            font-family: Consolas, "Courier New", monospace;
            font-size: clamp(1.35rem, 2.5vw, 2rem);
            font-weight: 900;
        }

        .analytics-dashboard-external-meta {
            display: block;
            margin-top: 8px;
            color: rgba(211, 236, 239, 0.58);
            font-size: 0.64rem;
        }

        .analytics-dashboard-outbound-link {
            color: rgba(247, 231, 176, 0.9);
            font-weight: 800;
            text-decoration: none;
        }

        .analytics-dashboard-outbound-link:hover,
        .analytics-dashboard-outbound-link:focus-visible {
            color: #ffffff;
            outline: none;
            text-decoration: underline;
        }

        .analytics-dashboard-table tbody tr,
        .analytics-dashboard-audio-table tbody tr {
            transition: background 0.18s ease, color 0.18s ease;
        }

        .analytics-dashboard-table tbody tr:hover,
        .analytics-dashboard-audio-table tbody tr:hover {
            color: rgba(238, 254, 255, 0.94);
            background: linear-gradient(90deg, rgba(99, 229, 240, 0.09), transparent);
        }

        .analytics-dashboard-loading {
            min-height: 360px;
            display: grid;
            place-items: center;
            color: rgba(121, 234, 237, 0.74);
            font: 900 0.72rem/1.4 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            letter-spacing: 0.18em;
            text-transform: uppercase;
        }

        .analytics-dashboard-loading::before {
            content: "";
            width: 48px;
            height: 48px;
            margin: 0 auto 15px;
            border: 3px solid rgba(121, 234, 237, 0.12);
            border-top-color: #79eaed;
            border-radius: 50%;
            animation: analytics-dashboard-orbit 0.8s linear infinite;
        }

        .analytics-dashboard-command-boot {
            position: absolute;
            z-index: 8;
            inset: 0;
            overflow: hidden;
            display: grid;
            place-content: center;
            justify-items: center;
            opacity: 0;
            color: #d9fcff;
            background:
                repeating-linear-gradient(0deg, transparent 0 5px, rgba(140, 246, 255, 0.035) 6px),
                radial-gradient(circle, #0a3341 0%, #02101f 48%, #01060d 100%);
            text-align: center;
            pointer-events: none;
        }

        .analytics-dashboard-command-boot::before,
        .analytics-dashboard-command-boot::after {
            content: "";
            position: absolute;
            pointer-events: none;
        }

        .analytics-dashboard-command-boot::before {
            inset: 12%;
            border: 1px solid rgba(131, 243, 255, 0.32);
            clip-path: polygon(0 0, 18% 0, 18% 1px, 82% 1px, 82% 0, 100% 0, 100% 18%, calc(100% - 1px) 18%, calc(100% - 1px) 82%, 100% 82%, 100% 100%, 82% 100%, 82% calc(100% - 1px), 18% calc(100% - 1px), 18% 100%, 0 100%, 0 82%, 1px 82%, 1px 18%, 0 18%);
            box-shadow: inset 0 0 34px rgba(96, 231, 243, 0.08);
        }

        .analytics-dashboard-command-boot::after {
            left: 10%;
            right: 10%;
            top: 50%;
            height: 1px;
            background: linear-gradient(90deg, transparent, #8ef6ff, transparent);
            box-shadow: 0 0 18px rgba(142, 246, 255, 0.7);
            transform: scaleX(0);
        }

        .analytics-dashboard-command-boot strong {
            position: relative;
            z-index: 2;
            color: #f7e7b0;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.65rem, 5vw, 4.6rem);
            letter-spacing: 0.18em;
            line-height: 1;
            text-shadow: 0 0 22px rgba(128, 242, 251, 0.35);
        }

        .analytics-dashboard-command-status {
            position: relative;
            z-index: 2;
            margin-top: 14px;
            color: rgba(168, 241, 247, 0.78);
            font: 800 clamp(0.58rem, 1.2vw, 0.88rem)/1.3 Consolas, "Courier New", monospace;
            letter-spacing: 0.24em;
            text-transform: uppercase;
        }

        .analytics-dashboard-command-release {
            position: absolute;
            z-index: 3;
            left: 50%;
            top: calc(50% + 96px);
            opacity: 0;
            color: #8ff6ff;
            font: 900 clamp(0.62rem, 1.4vw, 0.9rem)/1 Consolas, "Courier New", monospace;
            letter-spacing: 0.24em;
            text-transform: uppercase;
            text-shadow: 0 0 16px rgba(143, 246, 255, 0.65);
            transform: translateX(-50%);
            white-space: nowrap;
        }

        .analytics-dashboard-kaleidoscope {
            position: absolute;
            z-index: 1;
            left: 50%;
            top: 50%;
            width: min(78vmin, 680px);
            aspect-ratio: 1;
            border: 1px solid rgba(122, 239, 250, 0.14);
            border-radius: 50%;
            opacity: 0.72;
            filter: drop-shadow(0 0 22px rgba(74, 220, 235, 0.22));
            transform: translate(-50%, -50%);
        }

        .analytics-dashboard-kaleidoscope::before,
        .analytics-dashboard-kaleidoscope::after {
            content: "";
            position: absolute;
            border-radius: 50%;
            mix-blend-mode: screen;
        }

        .analytics-dashboard-kaleidoscope::before {
            inset: 4%;
            background:
                repeating-conic-gradient(from 12deg, rgba(112, 239, 250, 0.28) 0 7deg, transparent 7deg 23deg, rgba(244, 207, 120, 0.2) 23deg 29deg, transparent 29deg 45deg),
                radial-gradient(circle, transparent 0 25%, rgba(57, 188, 218, 0.16) 26% 27%, transparent 28% 48%, rgba(244, 207, 120, 0.13) 49% 50%, transparent 51%);
            mask: radial-gradient(circle, transparent 0 18%, #000 19% 82%, transparent 83%);
        }

        .analytics-dashboard-kaleidoscope::after {
            inset: 22%;
            border: 1px solid rgba(244, 207, 120, 0.24);
            background: conic-gradient(from 45deg, rgba(244, 207, 120, 0.2), transparent 12%, rgba(89, 224, 238, 0.22) 24%, transparent 38%, rgba(244, 207, 120, 0.16) 52%, transparent 68%, rgba(89, 224, 238, 0.22) 84%, transparent);
            box-shadow: inset 0 0 34px rgba(99, 229, 240, 0.08), 0 0 28px rgba(99, 229, 240, 0.12);
        }

        .analytics-dashboard-kaleidoscope i {
            --slice: 0deg;
            position: absolute;
            inset: 13%;
            opacity: 0.7;
            clip-path: polygon(50% 50%, 100% 37%, 100% 63%);
            background: linear-gradient(90deg, transparent 35%, rgba(130, 244, 255, 0.27), rgba(244, 207, 120, 0.17));
            transform: rotate(var(--slice));
            transform-origin: center;
            mix-blend-mode: screen;
        }

        .analytics-dashboard-kaleidoscope i:nth-child(2) { --slice: 60deg; }
        .analytics-dashboard-kaleidoscope i:nth-child(3) { --slice: 120deg; }
        .analytics-dashboard-kaleidoscope i:nth-child(4) { --slice: 180deg; }
        .analytics-dashboard-kaleidoscope i:nth-child(5) { --slice: 240deg; }
        .analytics-dashboard-kaleidoscope i:nth-child(6) { --slice: 300deg; }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-command-boot {
            animation: analytics-dashboard-command-boot 10.8s ease both;
        }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-command-boot::after {
            animation: analytics-dashboard-command-line 3.2s cubic-bezier(.2,.8,.2,1) both 0.25s;
        }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-kaleidoscope {
            animation: analytics-dashboard-kaleidoscope-spin 8.6s cubic-bezier(.3,.05,.2,1) both;
        }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-kaleidoscope::after {
            animation: analytics-dashboard-kaleidoscope-counterspin 3.8s linear infinite;
        }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-kaleidoscope i {
            animation: analytics-dashboard-kaleidoscope-pulse 1.15s ease-in-out infinite alternate;
        }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-command-boot strong,
        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-command-status {
            animation: analytics-dashboard-command-copy 9.1s ease both;
        }

        .analytics-dashboard-window.is-command-centre-booting .analytics-dashboard-command-release {
            animation: analytics-dashboard-command-release 10.7s ease both;
        }

        .analytics-dashboard-window.is-command-centre-booting > .analytics-dashboard-head,
        .analytics-dashboard-window.is-command-centre-booting > .analytics-dashboard-stage,
        .analytics-dashboard-window.is-command-centre-booting > .analytics-dashboard-ga4-link,
        .analytics-dashboard-window.is-command-centre-booting > .analytics-dashboard-holo-rail {
            opacity: 0;
            visibility: hidden;
        }

        .analytics-dashboard-window.is-command-centre-booting::before,
        .analytics-dashboard-window.is-command-centre-booting::after {
            visibility: hidden;
        }

        .analytics-dashboard-window.is-command-centre-ready > .analytics-dashboard-head {
            animation: analytics-dashboard-ready-head 0.65s cubic-bezier(.2,.9,.25,1) both;
        }

        .analytics-dashboard-window.is-command-centre-ready > .analytics-dashboard-stage {
            animation: analytics-dashboard-ready-stage 0.85s cubic-bezier(.2,.85,.25,1) both 0.08s;
        }

        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > * {
            animation: analytics-dashboard-ready-panel 0.7s cubic-bezier(.2,.9,.25,1) both;
        }

        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > *:nth-child(2) { animation-delay: 0.12s; }
        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > *:nth-child(3) { animation-delay: 0.2s; }
        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > *:nth-child(4) { animation-delay: 0.28s; }
        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > *:nth-child(5) { animation-delay: 0.36s; }
        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > *:nth-child(n+6) { animation-delay: 0.44s; }

        .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-period {
            animation: analytics-dashboard-ready-control 0.9s ease both 0.72s;
        }

        .edit-mode-toggle-label,
        .edit-mode-toggle-track {
            position: relative;
            z-index: 1;
        }

        @keyframes analytics-dashboard-backdrop {
            from { opacity: 0; }
            to { opacity: 1; }
        }

        @keyframes analytics-dashboard-window-in {
            from { opacity: 0; transform: translateY(18px) scale(0.985); }
            to { opacity: 1; transform: translateY(0) scale(1); }
        }

        @keyframes analytics-dashboard-orbit {
            to { transform: rotate(360deg); }
        }

        @keyframes analytics-dashboard-live-pulse {
            0%, 100% { opacity: 0.55; transform: scale(0.86); }
            50% { opacity: 1; transform: scale(1.12); }
        }

        @keyframes analytics-dashboard-field-drift {
            from { transform: translate3d(0, -18px, 0); }
            to { transform: translate3d(0, 18px, 0); }
        }

        @keyframes analytics-dashboard-scan-sweep {
            0%, 12% { left: -36%; opacity: 0; }
            22% { opacity: 0.32; }
            62% { opacity: 0.18; }
            78%, 100% { left: 112%; opacity: 0; }
        }

        @keyframes analytics-dashboard-card-glint {
            from { left: -70%; opacity: 0; }
            35% { opacity: 1; }
            to { left: 138%; opacity: 0; }
        }

        @keyframes analytics-dashboard-ring-breathe {
            0%, 100% { filter: brightness(0.92); transform: scale(0.985); }
            50% { filter: brightness(1.12); transform: scale(1.015); }
        }

        @keyframes analytics-dashboard-wave {
            0%, 100% { transform: scaleY(0.68); opacity: 0.68; }
            50% { transform: scaleY(1); opacity: 1; }
        }

        @keyframes analytics-dashboard-command-boot {
            0% { opacity: 0; filter: brightness(1.8); }
            4%, 7% { opacity: 1; }
            9% { opacity: 0.58; }
            11%, 84% { opacity: 1; filter: brightness(1); }
            93% { opacity: 1; }
            100% { opacity: 0; filter: brightness(1.25); }
        }

        @keyframes analytics-dashboard-command-line {
            0% { transform: translateY(-24vh) scaleX(0); opacity: 0; }
            18% { transform: translateY(-24vh) scaleX(1); opacity: 1; }
            82% { transform: translateY(24vh) scaleX(1); opacity: 0.8; }
            100% { transform: translateY(24vh) scaleX(0); opacity: 0; }
        }

        @keyframes analytics-dashboard-kaleidoscope-spin {
            0% { opacity: 0; transform: translate(-50%, -50%) rotate(-28deg) scale(0.28); }
            13% { opacity: 0.58; }
            55% { opacity: 0.88; transform: translate(-50%, -50%) rotate(185deg) scale(1.08); }
            82% { opacity: 0.7; transform: translate(-50%, -50%) rotate(310deg) scale(0.92); }
            100% { opacity: 0; transform: translate(-50%, -50%) rotate(410deg) scale(1.42); }
        }

        @keyframes analytics-dashboard-kaleidoscope-counterspin {
            to { transform: rotate(-360deg); }
        }

        @keyframes analytics-dashboard-kaleidoscope-pulse {
            from { opacity: 0.28; filter: hue-rotate(0deg) brightness(0.8); }
            to { opacity: 0.88; filter: hue-rotate(34deg) brightness(1.35); }
        }

        @keyframes analytics-dashboard-command-copy {
            0% { opacity: 0; letter-spacing: 0.34em; filter: blur(8px); transform: scale(0.94); }
            8%, 68% { opacity: 1; filter: blur(0); transform: scale(1); }
            78%, 100% { opacity: 0; letter-spacing: 0.24em; filter: blur(5px); transform: scale(1.04); }
        }

        @keyframes analytics-dashboard-command-release {
            0%, 72% { opacity: 0; transform: translate(-50%, 10px); }
            78%, 91% { opacity: 1; transform: translate(-50%, 0); }
            100% { opacity: 0; transform: translate(-50%, -8px); }
        }

        @keyframes analytics-dashboard-ready-head {
            from { opacity: 0; transform: translateY(-22px); filter: blur(8px); }
            to { opacity: 1; transform: translateY(0); filter: blur(0); }
        }

        @keyframes analytics-dashboard-ready-stage {
            from { opacity: 0; transform: perspective(900px) translateY(24px) rotateX(4deg); filter: blur(8px); }
            to { opacity: 1; transform: perspective(900px) translateY(0) rotateX(0); filter: blur(0); }
        }

        @keyframes analytics-dashboard-ready-panel {
            from { opacity: 0; transform: translateY(18px) scale(0.975); filter: blur(5px); }
            to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
        }

        @keyframes analytics-dashboard-ready-control {
            0% { box-shadow: 0 0 0 rgba(121, 234, 237, 0); }
            42% { box-shadow: 0 0 0 5px rgba(121, 234, 237, 0.14), 0 0 25px rgba(121, 234, 237, 0.28); }
            100% { box-shadow: 0 0 0 rgba(121, 234, 237, 0); }
        }

        @keyframes analytics-dashboard-hold-progress {
            0% { opacity: 0; transform: scaleX(0); filter: brightness(1); }
            8% { opacity: 1; transform: scaleX(0.04); }
            58% { opacity: 1; transform: scaleX(0.64); filter: brightness(1.08); }
            100% { opacity: 1; transform: scaleX(1); filter: brightness(1.35); }
        }

        @keyframes analytics-dashboard-hold-charge {
            from {
                filter: brightness(1);
                box-shadow: inset 0 1px 0 rgba(255,255,255,0.2), 0 4px 0 rgba(2, 16, 38, 0.76), 0 0 16px rgba(121, 234, 237, 0.18);
            }
            to {
                filter: brightness(1.22);
                box-shadow: inset 0 1px 0 rgba(255,255,255,0.3), 0 4px 0 rgba(2, 16, 38, 0.76), 0 0 34px rgba(121, 234, 237, 0.5), 0 0 62px rgba(244, 207, 120, 0.18);
            }
        }

        @keyframes guide-command-centre-launch-spin {
            0% {
                transform: perspective(1100px) rotateX(0deg) rotateY(0deg) rotateZ(0deg) scale(1);
                filter: brightness(1);
                box-shadow:
                    inset 0 1px 0 rgba(243, 239, 201, 0.2),
                    2px 2px 0 #79815a,
                    5px 5px 0 #475035,
                    9px 9px 0 #0a1109,
                    0 14px 24px rgba(0,0,0,0.28);
            }
            18% {
                transform: perspective(1100px) rotateX(-8deg) rotateY(12deg) rotateZ(64deg) scale(0.92);
                filter: brightness(1.2) saturate(1.1);
            }
            38% {
                transform: perspective(1100px) rotateX(7deg) rotateY(-13deg) rotateZ(142deg) scale(0.86);
                filter: brightness(1.52) saturate(1.26);
                box-shadow:
                    inset 0 1px 0 rgba(255,255,255,0.34),
                    2px 2px 0 #96a26a,
                    6px 6px 0 #4b5736,
                    11px 11px 0 #0a1109,
                    0 0 34px rgba(143, 246, 255, 0.72),
                    0 0 72px rgba(94, 224, 172, 0.38);
            }
            58% {
                transform: perspective(1100px) rotateX(-7deg) rotateY(12deg) rotateZ(222deg) scale(0.88);
                filter: brightness(1.7) saturate(1.34);
            }
            78% {
                transform: perspective(1100px) rotateX(6deg) rotateY(-10deg) rotateZ(300deg) scale(0.93);
                filter: brightness(1.4) saturate(1.22);
                box-shadow:
                    inset 0 1px 0 rgba(255,255,255,0.38),
                    2px 2px 0 #8e9966,
                    6px 6px 0 #465133,
                    10px 10px 0 #0a1109,
                    0 0 42px rgba(244, 207, 120, 0.62),
                    0 0 92px rgba(143, 246, 255, 0.34);
            }
            91% {
                transform: perspective(1100px) rotateX(-3deg) rotateY(5deg) rotateZ(340deg) scale(0.97);
                filter: brightness(1.22) saturate(1.12);
            }
            100% {
                transform: perspective(1100px) rotateX(0deg) rotateY(0deg) rotateZ(360deg) scale(1);
                filter: brightness(1.08);
                box-shadow:
                    inset 0 1px 0 rgba(243, 239, 201, 0.22),
                    2px 2px 0 #79815a,
                    5px 5px 0 #475035,
                    9px 9px 0 #0a1109,
                    0 18px 34px rgba(0,0,0,0.3),
                    0 0 34px rgba(94, 224, 172, 0.36);
            }
        }

        @keyframes guide-command-centre-launch-depth {
            0%, 100% {
                border-color: rgba(232, 226, 174, 0.92);
                box-shadow:
                    2px 2px 0 #79815a,
                    5px 5px 0 #475035,
                    8px 8px 0 #252e20,
                    11px 11px 0 #0a1109,
                    14px 16px 24px rgba(0,0,0,0.44);
            }
            38%, 78% {
                border-color: rgba(156, 241, 248, 0.96);
                box-shadow:
                    3px 3px 0 #98a76e,
                    7px 7px 0 #54613d,
                    11px 11px 0 #283321,
                    15px 15px 0 #0a1109,
                    19px 22px 34px rgba(0,0,0,0.5),
                    0 0 34px rgba(107, 226, 247, 0.36);
            }
        }

        @keyframes guide-command-centre-launch-wash {
            0% { opacity: 0; filter: blur(16px) hue-rotate(0deg); transform: scale(0.72); }
            20% { opacity: 0.55; filter: blur(5px) hue-rotate(18deg); transform: scale(0.94); }
            48% { opacity: 1; filter: blur(0) hue-rotate(42deg); transform: scale(1); }
            72% { opacity: 0.72; filter: blur(2px) hue-rotate(15deg); transform: scale(1.04); }
            100% { opacity: 0; filter: blur(12px) hue-rotate(0deg); transform: scale(1.08); }
        }

        @keyframes analytics-dashboard-ip-charge {
            0% { filter: brightness(1); transform: scale(1); }
            20% { box-shadow: inset 0 0 20px rgba(121, 234, 237, 0.28), 0 0 18px rgba(121, 234, 237, 0.2); }
            65% { border-color: rgba(244, 207, 120, 0.76); box-shadow: inset 0 0 24px rgba(244, 207, 120, 0.18), 0 0 30px rgba(121, 234, 237, 0.36); }
            100% { filter: brightness(1.35); transform: scale(1.08); border-color: #5ee0ac; box-shadow: inset 0 0 28px rgba(94, 224, 172, 0.3), 0 0 40px rgba(94, 224, 172, 0.5); }
        }

        @media (prefers-reduced-motion: reduce) {
            .analytics-dashboard-overlay::before,
            .analytics-dashboard-window::after,
            .analytics-dashboard-orbit::before,
            .analytics-dashboard-live::before,
            .analytics-dashboard-device-ring,
            .analytics-dashboard-audio-wave i,
            .guide-launcher.is-command-centre-holding,
            .guide-launcher.is-command-centre-launching,
            .analytics-dashboard-orbit.is-ip-holding,
            .analytics-dashboard-kaleidoscope,
            .analytics-dashboard-kaleidoscope::after,
            .analytics-dashboard-kaleidoscope i,
            .analytics-dashboard-command-boot strong,
            .analytics-dashboard-command-status,
            .analytics-dashboard-command-release,
            .analytics-dashboard-window.is-command-centre-ready > .analytics-dashboard-head,
            .analytics-dashboard-window.is-command-centre-ready > .analytics-dashboard-stage,
            .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-content > *,
            .analytics-dashboard-window.is-command-centre-ready .analytics-dashboard-period {
                animation: none !important;
            }

            .analytics-dashboard-session-card,
            .analytics-dashboard-metric,
            .analytics-dashboard-panel,
            .analytics-dashboard-audio {
                transition: none;
            }
        }

        .edit-mode-toggle {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            max-width: 230px;
            min-height: 54px;
            overflow: hidden;
            padding: 10px 14px 10px 16px;
            border: 1px solid rgba(182, 229, 255, 0.18);
            border-radius: 20px;
            cursor: pointer;
            color: #eef8ff;
            background:
                linear-gradient(180deg, rgba(16, 68, 128, 0.94), rgba(6, 30, 64, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 10px 20px rgba(0,0,0,0.2),
                0 4px 0 rgba(2, 16, 38, 0.76);
            opacity: 1;
            transform-origin: right center;
            transition:
                transform 0.18s ease,
                box-shadow 0.18s ease,
                border-color 0.18s ease,
                opacity 0.48s ease,
                max-width 0.48s ease,
                padding 0.48s ease;
        }

        .is-edit-mode-control-hidden .edit-mode-toggle {
            max-width: 0;
            min-width: 0;
            padding-left: 0;
            padding-right: 0;
            border-color: transparent;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-8px) scale(0.95);
            box-shadow: none;
        }

        .is-edit-mode-control-hidden .edit-mode-toggle-label,
        .is-edit-mode-control-hidden .edit-mode-toggle-track {
            opacity: 0;
        }

        .edit-mode-toggle:hover,
        .edit-mode-toggle:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 225, 146, 0.38);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.2),
                0 16px 26px rgba(0,0,0,0.24),
                0 4px 0 rgba(2, 16, 38, 0.76),
                0 0 18px rgba(140, 232, 255, 0.14);
            outline: none;
        }

        .edit-mode-toggle:active {
            transform: translateY(3px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 5px 12px rgba(0,0,0,0.2),
                0 2px 0 rgba(2, 16, 38, 0.82);
        }

        .edit-mode-toggle.is-active {
            border-color: rgba(255, 225, 146, 0.42);
            background:
                radial-gradient(circle at 20% 20%, rgba(255,255,255,0.24), transparent 24%),
                linear-gradient(180deg, rgba(255, 214, 112, 0.34), rgba(148, 103, 18, 0.5)),
                linear-gradient(180deg, rgba(12, 56, 110, 0.98), rgba(5, 26, 56, 0.98));
        }

        .edit-mode-toggle-label {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            white-space: nowrap;
        }

        .edit-mode-toggle-track {
            position: relative;
            width: 56px;
            height: 26px;
            flex: 0 0 auto;
            border-radius: 999px;
            background:
                linear-gradient(180deg, rgba(3, 19, 40, 0.94), rgba(16, 62, 116, 0.88));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                inset 0 -6px 12px rgba(0,0,0,0.18);
        }

        .edit-mode-toggle-knob {
            position: absolute;
            top: 3px;
            left: 3px;
            width: 20px;
            height: 20px;
            border-radius: 50%;
            background:
                radial-gradient(circle at 30% 28%, rgba(255,255,255,0.7), rgba(255,255,255,0.06) 54%),
                linear-gradient(180deg, rgba(191, 237, 255, 0.96), rgba(84, 180, 255, 0.92));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.34),
                0 4px 8px rgba(0,0,0,0.22);
            transition: transform 0.22s ease, background 0.22s ease, box-shadow 0.22s ease;
        }

        .edit-mode-toggle.is-active .edit-mode-toggle-knob {
            transform: translateX(30px);
            background:
                radial-gradient(circle at 30% 28%, rgba(255,255,255,0.74), rgba(255,255,255,0.08) 54%),
                linear-gradient(180deg, rgba(255, 232, 155, 0.98), rgba(255, 178, 64, 0.94));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.36),
                0 4px 10px rgba(62, 40, 8, 0.3);
        }

        .edit-panel {
            border-radius: 28px;
            border: 1px solid rgba(255, 225, 146, 0.22);
            background:
                linear-gradient(180deg, rgba(10, 43, 88, 0.94), rgba(5, 25, 54, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 18px 30px rgba(0,0,0,0.22);
            padding: 22px 22px 20px;
        }

        .edit-panel-head {
            display: flex;
            align-items: flex-start;
            justify-content: space-between;
            gap: 14px;
            margin-bottom: 14px;
        }

        .edit-panel-title {
            margin: 0;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .edit-panel-copy {
            margin: 7px 0 0;
            color: rgba(230, 244, 255, 0.8);
            font-size: 0.9rem;
            line-height: 1.6;
            max-width: 58ch;
        }

        .edit-panel-chip {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-height: 34px;
            padding: 0 12px;
            border-radius: 999px;
            color: #fff7d6;
            font-size: 0.76rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
            background:
                linear-gradient(180deg, rgba(255, 222, 134, 0.3), rgba(90, 56, 8, 0.34)),
                rgba(8, 28, 58, 0.88);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 8px 14px rgba(0,0,0,0.18);
        }

        .edit-builder {
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            gap: 12px;
            margin-top: 14px;
            align-items: center;
        }

        .edit-builder-input {
            width: 100%;
            min-height: 56px;
            border: 1px solid rgba(180, 228, 255, 0.2);
            border-radius: 18px;
            padding: 0 18px;
            color: #f3faff;
            font-size: 0.98rem;
            background:
                linear-gradient(180deg, rgba(6, 28, 58, 0.98), rgba(10, 44, 86, 0.92));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 10px 18px rgba(0,0,0,0.16);
        }

        .edit-builder-input::placeholder {
            color: rgba(208, 232, 248, 0.5);
        }

        .edit-builder-input:focus {
            outline: none;
            border-color: rgba(255, 225, 146, 0.42);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 12px 20px rgba(0,0,0,0.18),
                0 0 0 2px rgba(255, 225, 146, 0.14);
        }

        .edit-builder-submit {
            min-height: 56px;
            padding: 0 20px;
            border: 1px solid rgba(255, 225, 146, 0.26);
            border-radius: 18px;
            cursor: pointer;
            color: #fff7dc;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.88rem;
            font-weight: 900;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            background:
                linear-gradient(180deg, rgba(255, 214, 111, 0.3), rgba(139, 91, 14, 0.46)),
                linear-gradient(180deg, rgba(9, 40, 84, 0.98), rgba(4, 22, 48, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 10px 18px rgba(0,0,0,0.2),
                0 4px 0 rgba(52, 34, 7, 0.74);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .edit-builder-submit:hover,
        .edit-builder-submit:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 233, 170, 0.42);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 16px 24px rgba(0,0,0,0.22),
                0 4px 0 rgba(52, 34, 7, 0.74),
                0 0 16px rgba(255, 226, 145, 0.14);
            outline: none;
        }

        .edit-builder-submit:active {
            transform: translateY(3px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 6px 12px rgba(0,0,0,0.18),
                0 2px 0 rgba(52, 34, 7, 0.8);
        }

        .edit-custom-list {
            margin-top: 16px;
        }

        .edit-custom-heading {
            margin: 0 0 12px;
            color: rgba(224, 241, 255, 0.72);
            font-size: 0.8rem;
            font-weight: 800;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .edit-empty {
            margin: 0;
            color: rgba(213, 234, 248, 0.66);
            font-size: 0.9rem;
            line-height: 1.55;
        }

        .choice-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 18px;
        }

        .choice-grid.is-single {
            grid-template-columns: 1fr;
        }

        .choice-grid.is-decision {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .choice-grid.is-triple {
            grid-template-columns: repeat(3, minmax(0, 1fr));
        }

        .choice-button {
            min-height: 210px;
            width: 100%;
            border: 1px solid rgba(182, 229, 255, 0.18);
            border-radius: 28px;
            cursor: pointer;
            padding: 28px 24px;
            text-align: left;
            color: #f5fbff;
            background:
                linear-gradient(180deg, rgba(17, 74, 138, 0.95), rgba(7, 34, 72, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 16px 28px rgba(0,0,0,0.22),
                0 4px 0 rgba(2, 16, 38, 0.78);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .choice-button:hover,
        .choice-button:focus-visible {
            transform: translateY(-3px);
            border-color: rgba(255, 225, 146, 0.36);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.22),
                0 22px 34px rgba(0,0,0,0.26),
                0 4px 0 rgba(2, 16, 38, 0.78),
                0 0 20px rgba(140, 232, 255, 0.14);
            outline: none;
        }

        .choice-button:active {
            transform: translateY(4px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 8px 16px rgba(0,0,0,0.22),
                0 2px 0 rgba(2, 16, 38, 0.82);
        }
        .choice-button.is-tone-blue {
            background:
                linear-gradient(180deg, rgba(17, 74, 138, 0.95), rgba(7, 34, 72, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
        }
        .choice-button.is-tone-green {
            background:
                linear-gradient(180deg, rgba(33, 135, 84, 0.96), rgba(13, 74, 48, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.16), rgba(255,255,255,0));
            border-color: rgba(171, 255, 211, 0.22);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.2),
                0 16px 28px rgba(0,0,0,0.22),
                0 4px 0 rgba(5, 40, 24, 0.72);
        }
        .choice-button.is-tone-green .choice-label {
            color: #ecfff3;
        }
        .choice-button.is-tone-red {
            background:
                linear-gradient(180deg, rgba(164, 36, 56, 0.96), rgba(88, 14, 30, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            border-color: rgba(255, 186, 196, 0.26);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 16px 28px rgba(0,0,0,0.22),
                0 4px 0 rgba(64, 8, 18, 0.78);
        }
        .choice-button.is-tone-red .choice-label {
            color: #fff0f3;
        }
        .choice-button.is-tone-slate {
            background:
                linear-gradient(180deg, rgba(96, 107, 122, 0.92), rgba(29, 35, 45, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            border-color: rgba(212, 220, 230, 0.22);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 14px 24px rgba(0,0,0,0.2),
                0 4px 0 rgba(16, 21, 28, 0.82);
        }
        .choice-button.is-tone-slate .choice-label {
            color: #f6f9fd;
        }
        .choice-button.is-compact {
            min-height: 118px;
            padding: 20px 18px;
        }
        .choice-button.is-small {
            min-height: 76px;
            padding: 14px 16px;
            border-radius: 20px;
        }
        .choice-button.is-span-full {
            grid-column: 1 / -1;
        }
        .choice-button.is-centered {
            text-align: center;
        }
        .choice-button.is-centered .choice-label {
            width: 100%;
            text-align: center;
        }
        .choice-button.is-compact .choice-label {
            font-size: clamp(1rem, 1.45vw, 1.2rem);
            line-height: 1.12;
        }
        .choice-button.is-small .choice-label {
            font-size: clamp(0.88rem, 1.15vw, 1rem);
            line-height: 1.2;
            letter-spacing: 0.05em;
        }

        .choice-label {
            display: block;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.32rem, 2vw, 1.9rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            line-height: 1.08;
        }

        .choice-copy {
            display: block;
            margin-top: 14px;
            color: rgba(226, 243, 255, 0.78);
            font-size: 0.92rem;
            line-height: 1.55;
            max-width: 30ch;
        }

        .decision-layout {
            display: grid;
            gap: 18px;
            transition: gap 0.42s ease;
        }

        .decision-layout.is-status-faded {
            gap: 0;
        }

        .decision-status-row {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 16px;
            max-height: 180px;
            overflow: hidden;
            opacity: 1;
            transform: translateY(0);
            transition:
                max-height 0.5s ease,
                opacity 0.5s ease,
                transform 0.5s ease,
                margin 0.5s ease;
        }

        .decision-status-row.is-faded {
            max-height: 0;
            margin-bottom: -16px;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-12px);
        }

        .decision-intent-shell {
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                linear-gradient(180deg, rgba(8, 38, 79, 0.94), rgba(4, 22, 48, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 18px 30px rgba(0,0,0,0.22);
            padding: 18px;
        }

        .decision-intent-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 16px;
        }

        .decision-intent-column {
            display: grid;
            gap: 14px;
        }

        .testcase-bridge-stage {
            display: grid;
            gap: 24px;
        }

        .testcase-bridge-frame {
            position: relative;
            overflow: hidden;
            border-radius: 32px;
            border: 1px solid rgba(184, 230, 255, 0.2);
            background:
                radial-gradient(circle at 18% 18%, rgba(167, 239, 255, 0.18), transparent 34%),
                radial-gradient(circle at 86% 74%, rgba(255, 229, 162, 0.16), transparent 30%),
                linear-gradient(145deg, rgba(9, 45, 92, 0.96), rgba(4, 21, 48, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.11),
                0 22px 46px rgba(0,0,0,0.26);
            padding: clamp(24px, 5vw, 46px);
        }

        .testcase-bridge-frame::before {
            content: "";
            position: absolute;
            inset: 18px;
            border-radius: 24px;
            border: 1px solid rgba(255,255,255,0.07);
            pointer-events: none;
        }

        .testcase-bridge-diagram {
            position: relative;
            z-index: 1;
            display: grid;
            grid-template-columns: minmax(120px, 0.8fr) minmax(220px, 1.6fr) minmax(120px, 0.8fr);
            align-items: center;
            gap: clamp(14px, 3vw, 32px);
            min-height: clamp(230px, 32vw, 330px);
        }

        .testcase-bridge-point {
            display: grid;
            justify-items: center;
            gap: 14px;
            text-align: center;
        }

        .testcase-bridge-dot {
            position: relative;
            width: clamp(58px, 7.4vw, 88px);
            height: clamp(58px, 7.4vw, 88px);
            border-radius: 999px;
            border: 3px solid rgba(167, 239, 255, 0.9);
            background:
                radial-gradient(circle at 36% 30%, rgba(255,255,255,0.38), transparent 28%),
                linear-gradient(145deg, rgba(57, 193, 224, 0.96), rgba(18, 88, 166, 0.98));
            box-shadow:
                0 0 0 8px rgba(167, 239, 255, 0.08),
                0 18px 34px rgba(0,0,0,0.26),
                inset 0 1px 0 rgba(255,255,255,0.32);
        }

        .testcase-bridge-dot.is-finish {
            border-color: rgba(255, 229, 162, 0.9);
            background:
                radial-gradient(circle at 50% 50%, rgba(255, 229, 162, 0.98) 0 20%, transparent 22%),
                radial-gradient(circle at 50% 50%, transparent 0 46%, rgba(255, 229, 162, 0.95) 47% 54%, transparent 55%),
                linear-gradient(145deg, rgba(37, 125, 180, 0.96), rgba(11, 45, 90, 0.98));
            box-shadow:
                0 0 0 8px rgba(255, 229, 162, 0.08),
                0 18px 34px rgba(0,0,0,0.26),
                inset 0 1px 0 rgba(255,255,255,0.28);
        }

        .testcase-bridge-label {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1rem, 2vw, 1.45rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.08;
            text-transform: uppercase;
        }

        .testcase-bridge-arrow {
            position: relative;
            display: flex;
            align-items: center;
            min-height: 112px;
            overflow: visible;
        }

        .testcase-bridge-arrow-track {
            position: relative;
            width: 100%;
            height: 30px;
            border-radius: 999px;
            background: rgba(167, 239, 255, 0.12);
            box-shadow: inset 0 0 0 1px rgba(167, 239, 255, 0.2);
        }

        .testcase-bridge-arrow-track::before {
            content: "";
            position: absolute;
            inset: 0 auto 0 0;
            width: 0;
            border-radius: 999px;
            background:
                linear-gradient(90deg, rgba(167, 239, 255, 0.94), rgba(255, 229, 162, 0.96));
            box-shadow: 0 0 26px rgba(167, 239, 255, 0.34);
            animation:
                testcase-bridge-arrow-grow 1.35s cubic-bezier(.16,.82,.25,1) 0.22s forwards,
                testcase-bridge-main-arrow-fade 0.24s ease 4.9s forwards;
        }

        .testcase-bridge-arrow-track::after {
            content: "";
            position: absolute;
            top: 50%;
            right: -30px;
            width: 0;
            height: 0;
            border-top: 26px solid transparent;
            border-bottom: 26px solid transparent;
            border-left: 34px solid var(--gold-soft);
            filter: drop-shadow(0 0 18px rgba(255, 229, 162, 0.34));
            opacity: 0;
            transform: translateY(-50%) translateX(-18px) scale(0.72);
            animation:
                testcase-bridge-arrow-head 1.35s cubic-bezier(.16,.82,.25,1) 0.22s forwards,
                testcase-bridge-main-arrow-fade 0.24s ease 4.9s forwards;
        }

        .testcase-bridge-arrow-label {
            position: absolute;
            left: 50%;
            top: 50%;
            z-index: 2;
            transform: translate(-50%, -50%) scale(0.88);
            border-radius: 999px;
            border: 1px solid rgba(255,255,255,0.22);
            background:
                linear-gradient(145deg, rgba(10, 45, 92, 0.96), rgba(13, 85, 142, 0.96));
            color: var(--cyan-soft);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 12px 28px rgba(0,0,0,0.24);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.02rem, 2.1vw, 1.5rem);
            font-weight: 900;
            letter-spacing: 0.1em;
            line-height: 1;
            opacity: 0;
            padding: 12px 18px;
            text-transform: uppercase;
            animation: testcase-bridge-label-pop 0.54s cubic-bezier(.2,.9,.22,1.2) 0.88s forwards;
        }

        .testcase-bridge-bug-route {
            position: absolute;
            left: 2%;
            right: 2%;
            top: 50%;
            height: 138px;
            transform: translateY(-112px);
            pointer-events: none;
        }

        .testcase-bridge-bug-svg {
            position: absolute;
            inset: 0;
            overflow: visible;
        }

        .testcase-bridge-bug-path {
            fill: none;
            stroke-width: 18;
            stroke-linecap: round;
            stroke-linejoin: round;
            filter: drop-shadow(0 0 14px rgba(255, 75, 87, 0.38));
        }

        .testcase-bridge-bug-path {
            stroke: #ff4b57;
            stroke-dasharray: 420;
            stroke-dashoffset: 420;
            animation: testcase-bridge-bug-path 1.15s cubic-bezier(.18,.82,.2,1) 5s forwards;
        }

        .testcase-bridge-bug-arrowhead {
            position: absolute;
            top: 18px;
            right: 34px;
            width: 0;
            height: 0;
            border-top: 26px solid transparent;
            border-bottom: 26px solid transparent;
            border-left: 34px solid #ff4b57;
            filter: drop-shadow(0 0 18px rgba(255, 75, 87, 0.42));
            opacity: 0;
            transform: translateX(-14px) scale(0.72);
            animation: testcase-bridge-bug-arrowhead 0.36s cubic-bezier(.2,.9,.22,1.18) 5.98s forwards;
        }

        .testcase-bridge-bug-marker {
            position: absolute;
            right: -6px;
            top: 0;
            display: inline-flex;
            align-items: center;
            gap: 9px;
            border-radius: 999px;
            border: 1px solid rgba(255, 75, 87, 0.5);
            background:
                linear-gradient(145deg, rgba(80, 16, 27, 0.95), rgba(29, 8, 22, 0.96));
            color: #ff4b57;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 14px 28px rgba(0,0,0,0.28),
                0 0 24px rgba(255, 75, 87, 0.2);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(0.96rem, 1.8vw, 1.22rem);
            font-weight: 900;
            letter-spacing: 0.14em;
            line-height: 1;
            opacity: 0;
            padding: 9px 13px 9px 10px;
            text-transform: uppercase;
            transform: translateY(10px) scale(0.82);
            animation: testcase-bridge-bug-marker 0.44s cubic-bezier(.2,.9,.22,1.22) 6.12s forwards;
        }

        .testcase-bridge-bug-icon {
            position: relative;
            width: 24px;
            height: 25px;
            flex: 0 0 auto;
            border-radius: 48% 48% 42% 42%;
            background:
                radial-gradient(circle at 37% 36%, #2a0812 0 2px, transparent 3px),
                radial-gradient(circle at 63% 36%, #2a0812 0 2px, transparent 3px),
                linear-gradient(180deg, #ff7b83, #ff2f42);
            box-shadow:
                inset 0 2px 0 rgba(255,255,255,0.22),
                0 0 0 2px rgba(255, 75, 87, 0.24);
        }

        .testcase-bridge-bug-icon::before,
        .testcase-bridge-bug-icon::after {
            content: "";
            position: absolute;
            left: 50%;
            width: 34px;
            height: 2px;
            border-radius: 999px;
            background: #ff4b57;
            transform-origin: center;
        }

        .testcase-bridge-bug-icon::before {
            top: 8px;
            transform: translateX(-50%) rotate(22deg);
        }

        .testcase-bridge-bug-icon::after {
            bottom: 8px;
            transform: translateX(-50%) rotate(-22deg);
        }

        .testcase-bridge-actions {
            display: flex;
            justify-content: center;
            margin-top: 4px;
        }

        .testcase-bridge-actions .choice-button {
            width: min(280px, 100%);
        }

        @keyframes testcase-bridge-arrow-grow {
            to {
                width: 100%;
            }
        }

        @keyframes testcase-bridge-arrow-head {
            0% {
                opacity: 0;
                transform: translateY(-50%) translateX(-18px) scale(0.72);
            }
            78% {
                opacity: 1;
                transform: translateY(-50%) translateX(-6px) scale(0.92);
            }
            100% {
                opacity: 1;
                transform: translateY(-50%) translateX(0) scale(1);
            }
        }

        @keyframes testcase-bridge-label-pop {
            to {
                opacity: 1;
                transform: translate(-50%, -50%) scale(1);
            }
        }

        @keyframes testcase-bridge-main-arrow-fade {
            to {
                opacity: 0;
            }
        }

        @keyframes testcase-bridge-bug-path {
            to {
                stroke-dashoffset: 0;
            }
        }

        @keyframes testcase-bridge-bug-arrowhead {
            to {
                opacity: 1;
                transform: translateX(0) scale(1);
            }
        }

        @keyframes testcase-bridge-bug-marker {
            to {
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }

        .technique-link-stage {
            display: grid;
            gap: 24px;
        }

        .technique-link-legend {
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 14px;
        }

        .technique-link-card {
            position: relative;
            overflow: hidden;
            min-height: 154px;
            border-radius: 24px;
            border: 1px solid rgba(167, 239, 255, 0.18);
            background:
                radial-gradient(circle at 18% 12%, rgba(167, 239, 255, 0.15), transparent 35%),
                linear-gradient(145deg, rgba(10, 48, 95, 0.95), rgba(4, 24, 54, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 16px 30px rgba(0,0,0,0.22);
            color: inherit;
            cursor: pointer;
            font: inherit;
            appearance: none;
            padding: 0;
            perspective: 1100px;
            text-align: left;
            transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
        }

        .technique-link-card:hover,
        .technique-link-card:focus-visible {
            border-color: rgba(255, 229, 162, 0.42);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 20px 34px rgba(0,0,0,0.26),
                0 0 0 4px rgba(167, 239, 255, 0.06);
            outline: none;
            transform: translateY(-2px);
        }

        .technique-link-card.is-flipped {
            border-color: rgba(255, 229, 162, 0.4);
        }

        .technique-link-card-inner {
            position: relative;
            display: block;
            min-height: 154px;
            transform-style: preserve-3d;
            transition: transform 0.72s cubic-bezier(.2,.82,.24,1.04);
        }

        .technique-link-card.is-flipped .technique-link-card-inner {
            transform: rotateY(180deg);
        }

        .technique-link-card.is-demo-spinning .technique-link-card-inner {
            animation: technique-link-demo-spin 1.18s cubic-bezier(.25,.86,.28,1.04);
        }

        .technique-link-card-face {
            position: absolute;
            inset: 0;
            display: block;
            overflow: hidden;
            border-radius: 23px;
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
            padding: 18px;
        }

        .technique-link-card-face.is-back {
            background:
                radial-gradient(circle at 82% 14%, rgba(255, 229, 162, 0.18), transparent 36%),
                linear-gradient(145deg, rgba(27, 70, 112, 0.98), rgba(7, 30, 61, 0.99));
            transform: rotateY(180deg);
        }

        .technique-link-card-face::after {
            content: "";
            position: absolute;
            right: -36px;
            bottom: -42px;
            width: 110px;
            height: 110px;
            border-radius: 999px;
            border: 1px solid rgba(255, 229, 162, 0.14);
            box-shadow: 0 0 0 18px rgba(255, 229, 162, 0.025);
            pointer-events: none;
        }

        .technique-link-code {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 42px;
            min-height: 30px;
            border-radius: 999px;
            background: rgba(167, 239, 255, 0.12);
            color: var(--cyan-soft);
            font-size: 0.76rem;
            font-weight: 900;
            letter-spacing: 0.14em;
            text-transform: uppercase;
        }

        .technique-link-card-title {
            position: relative;
            z-index: 1;
            display: block;
            margin: 13px 0 8px;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1rem, 1.8vw, 1.28rem);
            font-weight: 900;
            letter-spacing: 0.05em;
            line-height: 1.12;
            text-transform: uppercase;
        }

        .technique-link-card-copy {
            position: relative;
            z-index: 1;
            display: block;
            margin: 0;
            color: rgba(226, 243, 255, 0.74);
            font-size: 0.82rem;
            line-height: 1.48;
        }

        .technique-link-card-hint {
            position: absolute;
            left: 18px;
            bottom: 13px;
            z-index: 1;
            color: rgba(167, 239, 255, 0.56);
            font-size: 0.62rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .technique-link-example-title {
            position: relative;
            z-index: 1;
            display: block;
            margin: 12px 0 7px;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.98rem;
            font-weight: 900;
            letter-spacing: 0.05em;
            line-height: 1.12;
            text-transform: uppercase;
        }

        .technique-link-example-copy {
            position: relative;
            z-index: 1;
            display: block;
            color: rgba(239, 248, 255, 0.82);
            font-size: 0.76rem;
            line-height: 1.42;
        }

        .technique-link-frame {
            border-radius: 32px;
            border: 1px solid rgba(184, 230, 255, 0.2);
            background:
                radial-gradient(circle at 50% 0%, rgba(255, 229, 162, 0.12), transparent 34%),
                linear-gradient(155deg, rgba(8, 41, 84, 0.97), rgba(3, 19, 44, 0.99));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 22px 42px rgba(0,0,0,0.26);
            padding: clamp(20px, 4vw, 36px);
        }

        .technique-link-frame-title {
            margin: 0;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.2rem, 2.5vw, 1.8rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            text-align: center;
            text-transform: uppercase;
        }

        .technique-link-frame-copy {
            max-width: 66ch;
            margin: 9px auto 20px;
            color: rgba(226, 243, 255, 0.76);
            font-size: 0.92rem;
            line-height: 1.55;
            text-align: center;
        }

        .technique-link-table-wrap {
            width: min(560px, 100%);
            margin: 0 auto;
            overflow-x: auto;
        }

        .technique-link-table {
            width: 100%;
            border-collapse: separate;
            border-spacing: 8px 7px;
            table-layout: fixed;
        }

        .technique-link-table th,
        .technique-link-table td {
            height: 48px;
            border-radius: 14px;
            text-align: center;
            vertical-align: middle;
        }

        .technique-link-table th {
            border: 1px solid rgba(255, 229, 162, 0.25);
            background: rgba(255, 229, 162, 0.08);
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.92rem;
            font-weight: 900;
            letter-spacing: 0.12em;
        }

        .technique-link-table td {
            border: 1px solid rgba(167, 239, 255, 0.09);
            background: rgba(2, 15, 35, 0.44);
        }

        .technique-link-table tbody tr {
            opacity: 0;
            transform: translateY(8px);
            animation: technique-link-row-in 0.34s ease forwards;
        }

        .technique-link-table tbody tr:nth-child(1) { animation-delay: 0.12s; }
        .technique-link-table tbody tr:nth-child(2) { animation-delay: 0.18s; }
        .technique-link-table tbody tr:nth-child(3) { animation-delay: 0.24s; }
        .technique-link-table tbody tr:nth-child(4) { animation-delay: 0.3s; }
        .technique-link-table tbody tr:nth-child(5) { animation-delay: 0.36s; }
        .technique-link-table tbody tr:nth-child(6) { animation-delay: 0.42s; }
        .technique-link-table tbody tr:nth-child(7) { animation-delay: 0.48s; }
        .technique-link-table tbody tr:nth-child(8) { animation-delay: 0.54s; }

        .technique-link-head {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .technique-light {
            position: relative;
            display: inline-block;
            width: 22px;
            height: 22px;
            border-radius: 999px;
            vertical-align: middle;
        }

        .technique-light.is-off {
            border: 1px solid rgba(167, 239, 255, 0.16);
            background: #050b16;
            box-shadow:
                inset 0 2px 5px rgba(0,0,0,0.74),
                0 0 0 3px rgba(167, 239, 255, 0.025);
        }

        .technique-light.is-on {
            border: 2px solid rgba(255, 229, 162, 0.92);
            background:
                radial-gradient(circle at 36% 28%, #fffceb 0 15%, #ffe58c 34%, #f5ae32 72%, #ca7420 100%);
            box-shadow:
                0 0 10px rgba(255, 223, 113, 0.8),
                0 0 24px rgba(255, 190, 54, 0.38),
                inset 0 1px 0 rgba(255,255,255,0.72);
        }

        .technique-light.is-on::before {
            content: "";
            position: absolute;
            left: 6px;
            right: 6px;
            bottom: -6px;
            height: 6px;
            border-radius: 0 0 3px 3px;
            background: #b9772d;
            box-shadow: inset 0 -2px 0 rgba(52, 27, 8, 0.28);
        }

        .technique-light.is-on::after {
            content: "";
            position: absolute;
            left: 8px;
            right: 8px;
            bottom: -9px;
            height: 3px;
            border-radius: 0 0 3px 3px;
            background: #e3a14d;
        }

        .technique-light.is-table-header.is-blinking {
            animation: technique-light-blink 0.38s ease-in-out 3;
        }

        .technique-link-equation {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            justify-content: center;
            gap: 9px;
            margin-top: 22px;
            color: rgba(226, 243, 255, 0.7);
            font-size: 0.78rem;
            font-weight: 800;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .technique-link-equation-part,
        .technique-link-equation-result {
            border-radius: 999px;
            border: 1px solid rgba(167, 239, 255, 0.15);
            background: rgba(167, 239, 255, 0.06);
            padding: 8px 11px;
        }

        .technique-link-equation-result {
            border-color: rgba(255, 229, 162, 0.3);
            background: rgba(255, 229, 162, 0.09);
            color: var(--gold-soft);
        }

        .technique-link-actions {
            display: flex;
            justify-content: center;
        }

        .technique-link-actions .choice-button {
            width: min(280px, 100%);
        }

        @keyframes technique-link-row-in {
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes technique-light-blink {
            0%, 100% {
                opacity: 1;
                filter: brightness(1);
                transform: scale(1);
            }
            50% {
                opacity: 0.14;
                filter: brightness(0.35) saturate(0.2);
                transform: scale(0.78);
            }
        }

        @keyframes technique-link-demo-spin {
            0%, 100% {
                transform: rotateY(0deg);
            }
            48%, 58% {
                transform: rotateY(180deg);
            }
        }

        .integration-testing-stage {
            display: grid;
            gap: 22px;
        }

        .integration-testing-intro {
            width: min(780px, 100%);
            margin: 0 auto;
            color: rgba(231, 246, 255, 0.86);
            font-size: clamp(0.94rem, 1.7vw, 1.08rem);
            line-height: 1.62;
            text-align: center;
        }

        .integration-release {
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(167, 239, 255, 0.28);
            border-radius: 32px;
            background:
                radial-gradient(circle at 50% -10%, rgba(91, 225, 217, 0.16), transparent 38%),
                linear-gradient(155deg, rgba(7, 39, 80, 0.98), rgba(3, 18, 42, 0.995));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 24px 46px rgba(0,0,0,0.28),
                0 0 36px rgba(95, 221, 225, 0.08);
            padding: clamp(20px, 3.5vw, 34px);
        }

        .integration-release::before {
            content: "";
            position: absolute;
            inset: 10px;
            border: 1px solid rgba(167, 239, 255, 0.06);
            border-radius: 24px;
            pointer-events: none;
        }

        .integration-release-head {
            position: relative;
            z-index: 1;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
            margin-bottom: 24px;
        }

        .integration-release-identity {
            display: grid;
            gap: 4px;
        }

        .integration-release-kicker {
            margin: 0;
            color: rgba(167, 239, 255, 0.64);
            font-size: 0.66rem;
            font-weight: 900;
            letter-spacing: 0.17em;
            text-transform: uppercase;
        }

        .integration-release-title {
            margin: 0;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.15rem, 2.2vw, 1.55rem);
            font-weight: 900;
            letter-spacing: 0.07em;
            text-transform: uppercase;
        }

        .integration-version {
            display: grid;
            min-width: 82px;
            min-height: 62px;
            place-items: center;
            border: 1px solid rgba(255, 229, 162, 0.34);
            border-radius: 18px;
            background:
                linear-gradient(180deg, rgba(255, 229, 162, 0.15), rgba(255, 229, 162, 0.05)),
                rgba(3, 24, 52, 0.82);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.15), 0 10px 20px rgba(0,0,0,0.22);
        }

        .integration-version small {
            align-self: end;
            color: rgba(255, 229, 162, 0.62);
            font-size: 0.52rem;
            font-weight: 900;
            letter-spacing: 0.14em;
            line-height: 1;
            text-transform: uppercase;
        }

        .integration-version strong {
            align-self: start;
            color: #fff0bd;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.45rem;
            letter-spacing: 0.06em;
            line-height: 1.1;
        }

        .integration-feature-grid {
            position: relative;
            z-index: 1;
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 16px;
        }

        .integration-feature {
            position: relative;
            min-width: 0;
            overflow: hidden;
            border: 1px solid rgba(167, 239, 255, 0.15);
            border-radius: 24px;
            background:
                linear-gradient(155deg, rgba(13, 57, 108, 0.94), rgba(4, 25, 57, 0.98));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 15px 28px rgba(0,0,0,0.2);
            padding: 17px;
            transition: border-color 0.28s ease, box-shadow 0.28s ease, filter 0.28s ease;
        }

        .integration-feature::after {
            content: "";
            position: absolute;
            inset: auto -34px -52px auto;
            width: 130px;
            height: 130px;
            border: 1px solid rgba(167, 239, 255, 0.08);
            border-radius: 999px;
            box-shadow: 0 0 0 18px rgba(167, 239, 255, 0.025);
            pointer-events: none;
        }

        .integration-feature.is-active {
            border-color: rgba(111, 238, 199, 0.54);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 17px 30px rgba(0,0,0,0.24),
                0 0 24px rgba(86, 225, 188, 0.15);
        }

        .integration-feature-head {
            position: relative;
            z-index: 1;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
            margin-bottom: 15px;
        }

        .integration-feature-name {
            margin: 0;
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .integration-feature-purpose {
            display: block;
            margin-top: 4px;
            color: rgba(167, 239, 255, 0.56);
            font-size: 0.6rem;
            font-weight: 800;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .integration-toggle {
            display: inline-grid;
            grid-template-columns: auto auto;
            align-items: center;
            gap: 7px;
            flex: 0 0 auto;
            border: 0;
            background: transparent;
            color: rgba(224, 242, 252, 0.68);
            cursor: pointer;
            font: inherit;
            padding: 2px;
        }

        .integration-toggle-track {
            position: relative;
            width: 42px;
            height: 23px;
            border: 1px solid rgba(188, 225, 244, 0.2);
            border-radius: 999px;
            background: rgba(2, 15, 35, 0.72);
            box-shadow: inset 0 2px 5px rgba(0,0,0,0.48);
            transition: background 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
        }

        .integration-toggle-track::after {
            content: "";
            position: absolute;
            top: 3px;
            left: 3px;
            width: 15px;
            height: 15px;
            border-radius: 999px;
            background: #8ca2b4;
            box-shadow: 0 3px 7px rgba(0,0,0,0.38);
            transition: transform 0.25s cubic-bezier(.2,.84,.3,1.16), background 0.25s ease;
        }

        .integration-toggle[aria-checked="true"] .integration-toggle-track {
            border-color: rgba(129, 255, 213, 0.5);
            background: rgba(36, 154, 117, 0.72);
            box-shadow: inset 0 1px 4px rgba(1, 46, 36, 0.44), 0 0 15px rgba(90, 237, 194, 0.24);
        }

        .integration-toggle[aria-checked="true"] .integration-toggle-track::after {
            transform: translateX(19px);
            background: #eafff7;
        }

        .integration-toggle:focus-visible {
            border-radius: 8px;
            outline: 2px solid rgba(255, 229, 162, 0.72);
            outline-offset: 3px;
        }

        .integration-toggle-state {
            min-width: 21px;
            color: inherit;
            font-size: 0.58rem;
            font-weight: 900;
            letter-spacing: 0.09em;
            text-transform: uppercase;
        }

        .integration-toggle[aria-checked="true"] .integration-toggle-state {
            color: #abf5dc;
        }

        .integration-feature-body {
            position: relative;
            z-index: 1;
            display: grid;
            align-content: start;
            gap: 13px;
            min-height: 240px;
        }

        .integration-decision-ghost {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 4px;
            opacity: 0.34;
        }

        .integration-decision-ghost span {
            display: grid;
            min-height: 22px;
            place-items: center;
            border: 1px solid rgba(255, 229, 162, 0.25);
            border-radius: 7px;
            background: rgba(2, 14, 32, 0.55);
            color: rgba(255, 233, 164, 0.88);
            font-size: 0.56rem;
            font-weight: 900;
        }

        .integration-decision-ghost span:nth-child(n+4) {
            color: rgba(167, 239, 255, 0.86);
        }

        .integration-input-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 7px;
        }

        .integration-input-grid label {
            display: grid;
            gap: 4px;
            color: rgba(214, 235, 248, 0.56);
            font-size: 0.55rem;
            font-weight: 800;
            letter-spacing: 0.07em;
            text-transform: uppercase;
        }

        .integration-input-grid input {
            width: 100%;
            min-width: 0;
            height: 31px;
            border: 1px solid rgba(167, 239, 255, 0.15);
            border-radius: 9px;
            outline: none;
            background: rgba(1, 14, 34, 0.68);
            color: #eefaff;
            font: 700 0.72rem Consolas, "Courier New", monospace;
            padding: 0 8px;
        }

        .integration-input-grid input:focus {
            border-color: rgba(167, 239, 255, 0.62);
            box-shadow: 0 0 0 3px rgba(167, 239, 255, 0.08);
        }

        .integration-pipeline {
            display: grid;
            gap: 10px;
            padding-top: 8px;
        }

        .integration-pipeline-step {
            position: relative;
            min-height: 44px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 10px;
            border: 1px solid rgba(167, 239, 255, 0.13);
            border-radius: 13px;
            background: rgba(2, 17, 39, 0.48);
            color: rgba(233, 247, 255, 0.78);
            font-size: 0.7rem;
            font-weight: 800;
            padding: 9px 11px;
        }

        .integration-pipeline-step:not(:last-child)::after {
            content: "";
            position: absolute;
            left: 50%;
            top: calc(100% + 1px);
            width: 1px;
            height: 9px;
            background: rgba(167, 239, 255, 0.3);
        }

        .integration-pipeline-step code {
            color: var(--gold-soft);
            font: 700 0.62rem Consolas, "Courier New", monospace;
        }

        .integration-output-preview {
            display: grid;
            gap: 11px;
            padding-top: 8px;
        }

        .integration-output-screen {
            min-height: 90px;
            display: grid;
            align-content: center;
            gap: 7px;
            border: 1px solid rgba(167, 239, 255, 0.14);
            border-radius: 16px;
            background:
                radial-gradient(circle at 50% 0%, rgba(167, 239, 255, 0.1), transparent 50%),
                rgba(1, 13, 31, 0.7);
            padding: 13px;
            text-align: center;
        }

        .integration-output-screen strong {
            color: #effaff;
            font-size: 0.82rem;
        }

        .integration-output-screen span {
            color: rgba(216, 238, 250, 0.58);
            font-size: 0.66rem;
            line-height: 1.4;
        }

        .integration-event-row {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 6px;
        }

        .integration-event-row span {
            border: 1px solid rgba(255, 229, 162, 0.16);
            border-radius: 999px;
            background: rgba(255, 229, 162, 0.06);
            color: rgba(255, 235, 177, 0.72);
            font: 700 0.57rem Consolas, "Courier New", monospace;
            padding: 6px 8px;
        }

        .integration-branch {
            position: relative;
            z-index: 1;
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 16px;
            margin: 5px 0 0;
            padding-top: 28px;
        }

        .integration-branch::before {
            content: "";
            position: absolute;
            left: calc(16.666% - 1px);
            right: calc(16.666% - 1px);
            top: 15px;
            height: 3px;
            border-radius: 999px;
            background: linear-gradient(90deg, rgba(167, 239, 255, 0.28), rgba(255, 229, 162, 0.48), rgba(167, 239, 255, 0.28));
            box-shadow: 0 0 12px rgba(167, 239, 255, 0.12);
        }

        .integration-branch-node {
            position: relative;
            display: grid;
            place-items: center;
        }

        .integration-branch-node::before {
            content: "";
            position: absolute;
            bottom: 100%;
            width: 2px;
            height: 28px;
            background: rgba(167, 239, 255, 0.22);
        }

        .integration-branch-node::after {
            content: "";
            position: absolute;
            bottom: calc(100% + 8px);
            width: 10px;
            height: 10px;
            border: 2px solid rgba(167, 239, 255, 0.34);
            border-radius: 999px;
            background: #061b39;
            transition: background 0.24s ease, border-color 0.24s ease, box-shadow 0.24s ease;
        }

        .integration-branch-node.is-active::before {
            background: rgba(104, 240, 196, 0.78);
            box-shadow: 0 0 10px rgba(104, 240, 196, 0.34);
        }

        .integration-branch-node.is-active::after {
            border-color: #b8ffe8;
            background: #4bd5a7;
            box-shadow: 0 0 15px rgba(75, 213, 167, 0.76);
        }

        .integration-branch-label {
            border: 1px solid rgba(167, 239, 255, 0.14);
            border-radius: 999px;
            background: rgba(2, 17, 39, 0.72);
            color: rgba(210, 235, 248, 0.65);
            font: 700 0.61rem Consolas, "Courier New", monospace;
            padding: 7px 10px;
        }

        .integration-branch-core {
            position: relative;
            z-index: 1;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 9px;
            margin: 13px auto 0;
            width: fit-content;
            border: 1px solid rgba(255, 229, 162, 0.24);
            border-radius: 999px;
            background: rgba(255, 229, 162, 0.07);
            color: var(--gold-soft);
            font: 800 0.68rem Consolas, "Courier New", monospace;
            padding: 9px 13px;
        }

        .integration-branch-core::before {
            content: "";
            width: 8px;
            height: 8px;
            border-radius: 999px;
            background: #65d8ff;
            box-shadow: 0 0 12px rgba(101, 216, 255, 0.7);
        }

        .integration-outcome {
            position: relative;
            z-index: 1;
            display: grid;
            grid-template-columns: auto minmax(0, 1fr);
            gap: 14px;
            margin-top: 22px;
            border: 1px solid rgba(167, 239, 255, 0.16);
            border-radius: 22px;
            background: rgba(2, 17, 39, 0.66);
            padding: 17px 18px;
            transition: border-color 0.3s ease, background 0.3s ease, box-shadow 0.3s ease;
        }

        .integration-outcome.is-pulsing {
            animation: integration-outcome-pulse 0.46s ease;
        }

        .integration-outcome.is-success {
            border-color: rgba(112, 244, 199, 0.42);
            background: rgba(13, 76, 58, 0.44);
            box-shadow: 0 0 25px rgba(92, 229, 184, 0.1);
        }

        .integration-outcome.is-warning {
            border-color: rgba(255, 205, 105, 0.52);
            background: rgba(92, 59, 13, 0.42);
            box-shadow: 0 0 28px rgba(255, 190, 71, 0.11);
        }

        .integration-outcome.is-failure {
            border-color: rgba(255, 130, 142, 0.52);
            background: rgba(91, 20, 36, 0.46);
            box-shadow: 0 0 30px rgba(255, 89, 117, 0.12);
        }

        .integration-outcome-icon {
            width: 42px;
            height: 42px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(167, 239, 255, 0.2);
            border-radius: 14px;
            background: rgba(167, 239, 255, 0.08);
            color: var(--cyan-soft);
            font-size: 1.05rem;
            font-weight: 900;
        }

        .integration-outcome.is-success .integration-outcome-icon {
            border-color: rgba(112, 244, 199, 0.48);
            background: rgba(112, 244, 199, 0.12);
            color: #baffea;
        }

        .integration-outcome.is-warning .integration-outcome-icon {
            border-color: rgba(255, 215, 132, 0.5);
            background: rgba(255, 205, 105, 0.12);
            color: #ffe7a8;
        }

        .integration-outcome.is-failure .integration-outcome-icon {
            border-color: rgba(255, 145, 158, 0.5);
            background: rgba(255, 105, 128, 0.12);
            color: #ffc2ca;
        }

        .integration-outcome-copy {
            min-width: 0;
        }

        .integration-outcome-title {
            margin: 0;
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            font-weight: 900;
            letter-spacing: 0.04em;
        }

        .integration-outcome-text {
            margin: 5px 0 0;
            color: rgba(226, 242, 251, 0.72);
            font-size: 0.78rem;
            line-height: 1.5;
        }

        .integration-outcome-issues {
            display: flex;
            flex-wrap: wrap;
            gap: 7px;
            margin-top: 10px;
        }

        .integration-outcome-issues span {
            border: 1px solid rgba(255,255,255,0.12);
            border-radius: 999px;
            background: rgba(0,0,0,0.16);
            color: rgba(245, 250, 255, 0.78);
            font-size: 0.64rem;
            font-weight: 800;
            padding: 6px 9px;
        }

        .integration-testing-actions {
            display: flex;
            justify-content: center;
        }

        .integration-testing-actions .choice-button {
            width: min(280px, 100%);
        }

        @keyframes integration-outcome-pulse {
            0% { transform: scale(1); filter: brightness(1); }
            48% { transform: scale(1.012); filter: brightness(1.22); }
            100% { transform: scale(1); filter: brightness(1); }
        }

        .knowledge-exchange-stage {
            display: grid;
            gap: 22px;
        }

        .knowledge-exchange-intro {
            width: min(820px, 100%);
            margin: 0 auto;
            color: rgba(229, 245, 255, 0.84);
            font-size: clamp(0.96rem, 1.8vw, 1.1rem);
            line-height: 1.65;
            text-align: center;
        }

        .knowledge-exchange-intro strong {
            color: var(--gold-soft);
        }

        .knowledge-exchange-lab {
            --exchange-developer: #75d8ff;
            --exchange-shared: #ffe59a;
            --exchange-tester: #7eebbd;
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(167, 239, 255, 0.25);
            border-radius: 34px;
            background:
                radial-gradient(circle at 50% -8%, rgba(255, 226, 139, 0.16), transparent 34%),
                radial-gradient(circle at 2% 50%, rgba(85, 198, 255, 0.13), transparent 31%),
                radial-gradient(circle at 98% 50%, rgba(91, 230, 171, 0.12), transparent 31%),
                linear-gradient(150deg, rgba(6, 37, 77, 0.99), rgba(2, 17, 39, 0.995));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 24px 48px rgba(0,0,0,0.28),
                0 0 38px rgba(97, 218, 226, 0.08);
            padding: clamp(20px, 3.7vw, 38px);
        }

        .knowledge-exchange-lab::before {
            content: "";
            position: absolute;
            inset: 0;
            opacity: 0.2;
            background-image:
                linear-gradient(rgba(167, 239, 255, 0.08) 1px, transparent 1px),
                linear-gradient(90deg, rgba(167, 239, 255, 0.08) 1px, transparent 1px);
            background-size: 32px 32px;
            mask-image: linear-gradient(to bottom, black, transparent 72%);
            pointer-events: none;
        }

        .knowledge-exchange-lab::after {
            content: "";
            position: absolute;
            z-index: 5;
            inset: -28%;
            opacity: 0;
            background:
                conic-gradient(from 0deg, transparent 0 9%, rgba(255, 229, 154, 0.2) 11%, transparent 14% 27%, rgba(117, 216, 255, 0.18) 30%, transparent 34% 51%, rgba(126, 235, 189, 0.18) 54%, transparent 58% 76%, rgba(255, 145, 173, 0.16) 79%, transparent 83%);
            filter: blur(10px);
            pointer-events: none;
            transform: scale(0.45) rotate(0deg);
        }

        .knowledge-exchange-lab.is-celebrating::after {
            animation: knowledge-kickoff-flash 3.6s ease-out forwards;
        }

        .knowledge-exchange-lab-head {
            position: relative;
            z-index: 2;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            margin-bottom: 27px;
        }

        .knowledge-exchange-kicker {
            margin: 0;
            color: rgba(167, 239, 255, 0.62);
            font-size: 0.62rem;
            font-weight: 900;
            letter-spacing: 0.17em;
            text-transform: uppercase;
        }

        .knowledge-exchange-lab-title {
            margin: 4px 0 0;
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.15rem, 2.4vw, 1.65rem);
            font-weight: 900;
            letter-spacing: 0.05em;
            text-transform: uppercase;
        }

        .knowledge-exchange-duration {
            display: grid;
            min-width: 76px;
            min-height: 59px;
            place-items: center;
            border: 1px solid rgba(255, 229, 154, 0.33);
            border-radius: 17px;
            background: rgba(255, 229, 154, 0.07);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.1), 0 10px 20px rgba(0,0,0,0.18);
            color: #fff0bd;
            font: 900 1.08rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
        }

        .knowledge-exchange-duration small {
            align-self: end;
            color: rgba(255, 234, 175, 0.6);
            font-size: 0.48rem;
            letter-spacing: 0.13em;
            text-transform: uppercase;
        }

        .knowledge-exchange-duration strong {
            align-self: start;
            letter-spacing: 0.04em;
        }

        .knowledge-exchange-handoff {
            position: relative;
            z-index: 2;
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 7px;
            margin: -8px 0 24px;
            border: 1px solid rgba(167, 239, 255, 0.12);
            border-radius: 18px;
            background: rgba(2, 18, 42, 0.48);
            padding: 8px;
        }

        .knowledge-exchange-handoff-step {
            position: relative;
            min-height: 43px;
            display: grid;
            align-content: center;
            justify-items: center;
            border: 1px solid rgba(167, 239, 255, 0.11);
            border-radius: 12px;
            background: rgba(7, 41, 78, 0.62);
            color: rgba(218, 239, 250, 0.65);
            font-size: 0.57rem;
            font-weight: 900;
            letter-spacing: 0.07em;
            line-height: 1.25;
            padding: 7px 9px;
            text-align: center;
            text-transform: uppercase;
        }

        .knowledge-exchange-handoff-step:not(:last-child)::after {
            content: "";
            position: absolute;
            z-index: 2;
            left: calc(100% + 1px);
            top: 50%;
            width: 12px;
            height: 2px;
            background: linear-gradient(90deg, rgba(167, 239, 255, 0.5), transparent);
            transform: translateY(-50%);
        }

        .knowledge-exchange-handoff-step.is-complete {
            border-color: rgba(107, 232, 184, 0.27);
            color: #baf5dc;
        }

        .knowledge-exchange-handoff-step.is-current {
            border-color: rgba(255, 229, 154, 0.48);
            background: rgba(255, 229, 154, 0.1);
            box-shadow: 0 0 18px rgba(255, 224, 139, 0.1);
            color: #fff0bd;
        }

        .knowledge-exchange-handoff-step small {
            display: block;
            margin-top: 3px;
            color: rgba(211, 235, 247, 0.45);
            font-size: 0.47rem;
            letter-spacing: 0.05em;
        }

        .knowledge-exchange-nodes {
            position: relative;
            z-index: 2;
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            align-items: center;
            gap: clamp(12px, 2.4vw, 28px);
        }

        .knowledge-exchange-nodes::before {
            content: "";
            position: absolute;
            z-index: -1;
            top: 50%;
            left: 14%;
            right: 14%;
            height: 3px;
            border-radius: 999px;
            background: linear-gradient(90deg, rgba(117, 216, 255, 0.24), rgba(255, 229, 154, 0.56), rgba(126, 235, 189, 0.24));
            box-shadow: 0 0 16px rgba(167, 239, 255, 0.16);
        }

        .knowledge-exchange-node {
            --node-color: var(--exchange-developer);
            position: relative;
            min-width: 0;
            min-height: 144px;
            display: grid;
            align-content: center;
            justify-items: center;
            gap: 9px;
            overflow: hidden;
            border: 1px solid color-mix(in srgb, var(--node-color) 28%, transparent);
            border-radius: 27px;
            background:
                radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--node-color) 13%, transparent), transparent 50%),
                linear-gradient(155deg, rgba(10, 49, 93, 0.96), rgba(3, 23, 52, 0.99));
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.1), 0 15px 28px rgba(0,0,0,0.23);
            color: #f4fbff;
            cursor: pointer;
            padding: 18px 13px;
            isolation: isolate;
            transition: transform 0.3s cubic-bezier(.2,.84,.3,1.12), border-color 0.25s ease, box-shadow 0.25s ease, filter 0.25s ease;
        }

        .knowledge-exchange-node.is-shared { --node-color: var(--exchange-shared); }
        .knowledge-exchange-node.is-tester { --node-color: var(--exchange-tester); }

        .knowledge-exchange-node::after {
            content: "";
            position: absolute;
            z-index: -1;
            inset: 100% 8% auto;
            height: 70%;
            border-radius: 999px 999px 0 0;
            background: color-mix(in srgb, var(--node-color) 18%, transparent);
            filter: blur(18px);
            transition: inset 0.4s ease;
        }

        .knowledge-exchange-node:hover,
        .knowledge-exchange-node:focus-visible {
            border-color: color-mix(in srgb, var(--node-color) 68%, white 8%);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.15), 0 18px 32px rgba(0,0,0,0.27), 0 0 24px color-mix(in srgb, var(--node-color) 18%, transparent);
            filter: brightness(1.08);
            outline: none;
            transform: translateY(-4px);
        }

        .knowledge-exchange-node.is-active {
            border-color: var(--node-color);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.18), 0 18px 32px rgba(0,0,0,0.25), 0 0 30px color-mix(in srgb, var(--node-color) 30%, transparent);
            transform: translateY(-3px);
        }

        .knowledge-exchange-node.is-active::after {
            inset: 47% 8% -20%;
        }

        .knowledge-exchange-node.is-activated-now {
            animation: knowledge-node-activate 0.58s cubic-bezier(.2,.84,.3,1.2);
        }

        .knowledge-exchange-node-icon {
            width: 47px;
            height: 47px;
            display: grid;
            place-items: center;
            border: 1px solid color-mix(in srgb, var(--node-color) 40%, transparent);
            border-radius: 16px;
            background: color-mix(in srgb, var(--node-color) 10%, rgba(3, 24, 52, 0.7));
            color: var(--node-color);
            font-size: 1.25rem;
            font-weight: 900;
            box-shadow: 0 0 18px color-mix(in srgb, var(--node-color) 12%, transparent);
        }

        .knowledge-exchange-node-title {
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(0.8rem, 1.55vw, 1rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.15;
            text-align: center;
            text-transform: uppercase;
        }

        .knowledge-exchange-node-hint {
            color: color-mix(in srgb, var(--node-color) 68%, rgba(220, 239, 250, 0.6));
            font-size: 0.57rem;
            font-weight: 800;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .knowledge-exchange-sequence {
            position: relative;
            z-index: 2;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 9px;
            margin: 22px auto 0;
        }

        .knowledge-exchange-sequence-slot {
            min-width: 98px;
            min-height: 32px;
            display: grid;
            place-items: center;
            border: 1px dashed rgba(167, 239, 255, 0.18);
            border-radius: 999px;
            color: rgba(206, 231, 245, 0.42);
            font-size: 0.55rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            padding: 6px 10px;
            text-transform: uppercase;
            transition: border-color 0.25s ease, color 0.25s ease, background 0.25s ease, transform 0.25s ease;
        }

        .knowledge-exchange-sequence-slot.is-filled {
            border-style: solid;
            border-color: color-mix(in srgb, var(--slot-color) 45%, transparent);
            background: color-mix(in srgb, var(--slot-color) 8%, transparent);
            color: var(--slot-color);
            transform: translateY(-2px);
        }

        .knowledge-exchange-sequence-arrow {
            color: rgba(167, 239, 255, 0.34);
            font-size: 0.76rem;
        }

        .knowledge-exchange-insights {
            position: relative;
            z-index: 2;
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 12px;
            margin-top: 20px;
        }

        .knowledge-exchange-insight {
            --insight-color: var(--exchange-developer);
            min-width: 0;
            min-height: 0;
            max-height: 0;
            overflow: hidden;
            border: 1px solid transparent;
            border-radius: 20px;
            background: rgba(2, 18, 42, 0.62);
            opacity: 0;
            padding: 0 16px;
            transform: translateY(14px) scale(0.98);
            transition: max-height 0.52s ease, min-height 0.52s ease, opacity 0.34s ease, transform 0.42s ease, padding 0.42s ease, border-color 0.32s ease;
        }

        .knowledge-exchange-insight.is-shared { --insight-color: var(--exchange-shared); }
        .knowledge-exchange-insight.is-tester { --insight-color: var(--exchange-tester); }

        .knowledge-exchange-insight.is-visible {
            min-height: 192px;
            max-height: 340px;
            border-color: color-mix(in srgb, var(--insight-color) 23%, transparent);
            opacity: 1;
            padding: 16px;
            transform: translateY(0) scale(1);
        }

        .knowledge-exchange-insight h3 {
            margin: 0;
            color: var(--insight-color);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .knowledge-exchange-insight p {
            margin: 8px 0 11px;
            color: rgba(226, 242, 251, 0.7);
            font-size: 0.69rem;
            line-height: 1.5;
        }

        .knowledge-exchange-chip-list {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
        }

        .knowledge-exchange-chip-list span {
            border: 1px solid color-mix(in srgb, var(--insight-color) 24%, transparent);
            border-radius: 999px;
            background: color-mix(in srgb, var(--insight-color) 7%, transparent);
            color: color-mix(in srgb, var(--insight-color) 76%, white 8%);
            font-size: 0.58rem;
            font-weight: 800;
            padding: 6px 8px;
        }

        .knowledge-exchange-calendar {
            position: relative;
            z-index: 2;
            display: grid;
            grid-template-columns: auto minmax(0, 1fr) auto;
            align-items: center;
            gap: 15px;
            margin-top: 18px;
            border: 1px solid rgba(255, 229, 154, 0.2);
            border-radius: 22px;
            background: linear-gradient(135deg, rgba(255, 229, 154, 0.08), rgba(4, 29, 60, 0.68));
            padding: 15px 17px;
            transition: border-color 0.3s ease, background 0.3s ease, box-shadow 0.3s ease;
        }

        .knowledge-exchange-calendar.is-protected {
            border-color: rgba(115, 238, 185, 0.48);
            background: linear-gradient(135deg, rgba(93, 226, 169, 0.13), rgba(4, 43, 55, 0.78));
            box-shadow: 0 0 24px rgba(93, 226, 169, 0.11);
        }

        .knowledge-exchange-calendar-icon {
            width: 48px;
            height: 48px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(255, 229, 154, 0.3);
            border-radius: 15px;
            background: rgba(255, 229, 154, 0.08);
            color: #ffe9a8;
            font-size: 1.15rem;
            font-weight: 900;
        }

        .knowledge-exchange-calendar-copy strong,
        .knowledge-exchange-calendar-copy span {
            display: block;
        }

        .knowledge-exchange-calendar-copy strong {
            color: #f7fbff;
            font-size: 0.82rem;
        }

        .knowledge-exchange-calendar-copy span {
            margin-top: 4px;
            color: rgba(218, 238, 249, 0.6);
            font-size: 0.65rem;
            line-height: 1.4;
        }

        .knowledge-exchange-calendar-button,
        .knowledge-exchange-replay {
            border: 1px solid rgba(255, 230, 165, 0.28);
            border-radius: 12px;
            background: rgba(255, 229, 154, 0.08);
            color: #fff0bd;
            cursor: pointer;
            font: 900 0.59rem "Segoe UI", sans-serif;
            letter-spacing: 0.08em;
            padding: 10px 12px;
            text-transform: uppercase;
            transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease;
        }

        .knowledge-exchange-calendar-button:hover,
        .knowledge-exchange-calendar-button:focus-visible,
        .knowledge-exchange-replay:hover,
        .knowledge-exchange-replay:focus-visible {
            border-color: rgba(255, 238, 191, 0.62);
            background: rgba(255, 229, 154, 0.15);
            outline: none;
            transform: translateY(-2px);
        }

        .knowledge-exchange-calendar.is-protected .knowledge-exchange-calendar-button {
            border-color: rgba(132, 245, 196, 0.46);
            background: rgba(105, 233, 178, 0.12);
            color: #baffdf;
        }

        .knowledge-exchange-finale {
            position: relative;
            z-index: 2;
            min-height: 94px;
            display: grid;
            grid-template-columns: auto minmax(0, 1fr) auto;
            align-items: center;
            gap: 15px;
            overflow: hidden;
            margin-top: 18px;
            border: 1px solid rgba(167, 239, 255, 0.16);
            border-radius: 24px;
            background: rgba(2, 17, 39, 0.68);
            padding: 16px 18px;
            transition: border-color 0.35s ease, background 0.35s ease, box-shadow 0.35s ease;
        }

        .knowledge-exchange-finale.is-connected {
            border-color: rgba(120, 220, 255, 0.42);
            background: rgba(16, 64, 91, 0.58);
        }

        .knowledge-exchange-finale.is-synergy {
            border-color: rgba(255, 229, 154, 0.58);
            background:
                radial-gradient(circle at 50% 0%, rgba(255, 229, 154, 0.2), transparent 52%),
                rgba(18, 69, 62, 0.72);
            box-shadow: 0 0 34px rgba(255, 224, 132, 0.13), inset 0 1px 0 rgba(255,255,255,0.12);
            animation: knowledge-finale-celebrate 1.1s cubic-bezier(.2,.84,.3,1.12) both;
        }

        .knowledge-exchange-finale-icon {
            width: 50px;
            height: 50px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(167, 239, 255, 0.23);
            border-radius: 17px;
            background: rgba(167, 239, 255, 0.08);
            color: var(--cyan-soft);
            font-size: 1.15rem;
            font-weight: 900;
            transition: transform 0.35s ease, color 0.35s ease, border-color 0.35s ease;
        }

        .knowledge-exchange-finale.is-synergy .knowledge-exchange-finale-icon {
            border-color: rgba(255, 233, 171, 0.54);
            color: #fff0bd;
            transform: rotate(360deg) scale(1.08);
        }

        .knowledge-exchange-finale-copy h3 {
            margin: 0;
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            font-weight: 900;
            letter-spacing: 0.04em;
        }

        .knowledge-exchange-finale-copy p {
            margin: 5px 0 0;
            color: rgba(225, 242, 251, 0.68);
            font-size: 0.72rem;
            line-height: 1.5;
        }

        .knowledge-exchange-replay {
            opacity: 0;
            pointer-events: none;
            transform: translateY(7px);
        }

        .knowledge-exchange-finale.is-complete .knowledge-exchange-replay {
            opacity: 1;
            pointer-events: auto;
            transform: translateY(0);
        }

        .knowledge-fireworks {
            position: absolute;
            z-index: 6;
            inset: 0;
            overflow: hidden;
            pointer-events: none;
        }

        .knowledge-firework-particle {
            --firework-color: #ffe59a;
            position: absolute;
            left: var(--firework-x);
            top: var(--firework-y);
            width: 9px;
            height: 9px;
            border-radius: 999px;
            background: var(--firework-color);
            box-shadow: 0 0 7px var(--firework-color), 0 0 17px var(--firework-color);
            opacity: 0;
            animation: knowledge-firework-burst 2.65s var(--firework-delay) cubic-bezier(.12,.72,.24,1) forwards;
        }

        .knowledge-firework-ring {
            position: absolute;
            left: var(--firework-x);
            top: var(--firework-y);
            width: 30px;
            height: 30px;
            border: 3px solid var(--firework-color);
            border-radius: 999px;
            box-shadow: 0 0 18px var(--firework-color), inset 0 0 12px var(--firework-color);
            opacity: 0;
            animation: knowledge-firework-ring 2.3s var(--firework-delay) ease-out forwards;
        }

        .knowledge-exchange-actions {
            display: flex;
            justify-content: center;
        }

        .knowledge-exchange-actions .choice-button {
            width: min(280px, 100%);
        }

        @keyframes knowledge-node-activate {
            0% { transform: translateY(0) scale(1); }
            40% { transform: translateY(-9px) scale(1.045); filter: brightness(1.24); }
            100% { transform: translateY(-3px) scale(1); }
        }

        @keyframes knowledge-firework-burst {
            0% { opacity: 0; transform: translate(-50%, -50%) scale(0.3); }
            8% { opacity: 1; }
            65% { opacity: 1; }
            100% { opacity: 0; transform: translate(calc(-50% + var(--firework-dx)), calc(-50% + var(--firework-dy) + 28px)) scale(0.55); }
        }

        @keyframes knowledge-firework-ring {
            0% { opacity: 0; transform: translate(-50%, -50%) scale(0.15); }
            12% { opacity: 0.9; }
            100% { opacity: 0; transform: translate(-50%, -50%) scale(7.5); }
        }

        @keyframes knowledge-kickoff-flash {
            0% { opacity: 0; transform: scale(0.42) rotate(0deg); }
            16% { opacity: 0.78; }
            52% { opacity: 0.32; }
            100% { opacity: 0; transform: scale(1.2) rotate(135deg); }
        }

        @keyframes knowledge-finale-celebrate {
            0% { transform: scale(0.96); filter: brightness(1); }
            45% { transform: scale(1.015); filter: brightness(1.28); }
            100% { transform: scale(1); filter: brightness(1); }
        }

        @media (prefers-reduced-motion: reduce) {
            .knowledge-exchange-node,
            .knowledge-exchange-insight,
            .knowledge-exchange-finale-icon,
            .knowledge-firework-particle,
            .knowledge-firework-ring,
            .knowledge-exchange-lab::after {
                animation: none !important;
                transition-duration: 0.01ms !important;
            }

            .knowledge-firework-particle {
                display: none;
            }

            .knowledge-firework-ring {
                display: none;
            }
        }

        .retest-investigation-stage {
            display: grid;
            gap: 22px;
        }

        .retest-investigation-intro {
            width: min(860px, 100%);
            margin: 0 auto;
            color: rgba(229, 245, 255, 0.86);
            font-size: clamp(0.96rem, 1.75vw, 1.08rem);
            line-height: 1.65;
            text-align: center;
        }

        .retest-investigation-intro strong {
            color: var(--gold-soft);
        }

        .retest-investigation-workbench {
            --retest-cyan: #78d9ff;
            --retest-gold: #ffe29a;
            --retest-green: #78e2b4;
            --retest-coral: #ff9a9f;
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(167, 239, 255, 0.24);
            border-radius: 30px;
            background:
                radial-gradient(circle at 8% 0%, rgba(120, 217, 255, 0.13), transparent 29%),
                radial-gradient(circle at 92% 8%, rgba(255, 226, 154, 0.1), transparent 25%),
                linear-gradient(155deg, rgba(5, 31, 67, 0.98), rgba(2, 18, 42, 0.995));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.11),
                0 24px 48px rgba(0,0,0,0.28),
                0 0 40px rgba(95, 215, 229, 0.07);
            padding: clamp(18px, 3.2vw, 34px);
        }

        .retest-investigation-workbench::before {
            content: "";
            position: absolute;
            inset: 0;
            opacity: 0.18;
            background-image:
                linear-gradient(rgba(167, 239, 255, 0.08) 1px, transparent 1px),
                linear-gradient(90deg, rgba(167, 239, 255, 0.08) 1px, transparent 1px);
            background-size: 30px 30px;
            pointer-events: none;
        }

        .retest-investigation-workbench > * {
            position: relative;
            z-index: 1;
        }

        .retest-request {
            display: grid;
            grid-template-columns: auto minmax(0, 1fr) auto;
            align-items: center;
            gap: 16px;
            border: 1px solid rgba(120, 217, 255, 0.2);
            border-radius: 22px;
            background: rgba(5, 27, 57, 0.72);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.07), 0 14px 26px rgba(0,0,0,0.16);
            padding: 16px 18px;
            animation: retest-request-arrive 0.72s cubic-bezier(.2,.82,.25,1) both;
        }

        .retest-request-avatar {
            width: 48px;
            height: 48px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(120, 217, 255, 0.34);
            border-radius: 16px;
            color: var(--retest-cyan);
            background: rgba(120, 217, 255, 0.08);
            box-shadow: 0 0 22px rgba(120, 217, 255, 0.1);
            font: 900 0.82rem/1 Consolas, "Courier New", monospace;
        }

        .retest-request-copy {
            min-width: 0;
        }

        .retest-request-kicker,
        .retest-section-kicker,
        .retest-learning-kicker {
            margin: 0;
            color: rgba(120, 217, 255, 0.66);
            font-size: 0.59rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .retest-request blockquote {
            margin: 6px 0 0;
            color: #f4fbff;
            font-size: clamp(0.87rem, 1.55vw, 1rem);
            font-weight: 700;
            line-height: 1.45;
        }

        .retest-request-status {
            display: grid;
            gap: 4px;
            justify-items: center;
            min-width: 90px;
            border: 1px solid rgba(255, 226, 154, 0.28);
            border-radius: 15px;
            background: rgba(255, 226, 154, 0.07);
            color: #fff0bd;
            padding: 10px 12px;
            text-align: center;
        }

        .retest-request-status strong {
            font: 900 0.78rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .retest-request-status small {
            color: rgba(255, 235, 181, 0.56);
            font-size: 0.48rem;
            font-weight: 800;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .retest-section {
            margin-top: 24px;
        }

        .retest-section-head {
            display: flex;
            align-items: end;
            justify-content: space-between;
            gap: 18px;
            margin-bottom: 13px;
        }

        .retest-section-title {
            margin: 4px 0 0;
            color: #f4fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.02rem, 2.2vw, 1.34rem);
            font-weight: 900;
            letter-spacing: 0.05em;
            line-height: 1.1;
            text-transform: uppercase;
        }

        .retest-section-note {
            max-width: 430px;
            margin: 0;
            color: rgba(214, 237, 249, 0.62);
            font-size: 0.7rem;
            line-height: 1.45;
            text-align: right;
        }

        .retest-hat-grid {
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 10px;
        }

        .retest-hat-card {
            --hat-color: var(--retest-cyan);
            position: relative;
            min-width: 0;
            min-height: 210px;
            display: grid;
            align-content: start;
            justify-items: center;
            gap: 7px;
            overflow: hidden;
            border: 1px solid color-mix(in srgb, var(--hat-color) 23%, transparent);
            border-radius: 20px;
            cursor: pointer;
            color: #f4fbff;
            background:
                radial-gradient(circle at 50% 4%, color-mix(in srgb, var(--hat-color) 13%, transparent), transparent 43%),
                rgba(4, 25, 54, 0.72);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.07), 0 12px 22px rgba(0,0,0,0.16);
            padding: 15px 12px 14px;
            transition: transform 0.28s cubic-bezier(.2,.82,.25,1.08), border-color 0.24s ease, box-shadow 0.24s ease, background 0.24s ease;
            animation: retest-hat-arrive 0.65s cubic-bezier(.2,.82,.25,1) both;
        }

        .retest-hat-card:nth-child(2) { --hat-color: var(--retest-coral); animation-delay: 0.08s; }
        .retest-hat-card:nth-child(3) { --hat-color: var(--retest-gold); animation-delay: 0.16s; }
        .retest-hat-card:nth-child(4) { --hat-color: var(--retest-green); animation-delay: 0.24s; }

        .retest-hat-card::after {
            content: "";
            position: absolute;
            inset: auto 12% -34px;
            height: 48px;
            border-radius: 50%;
            background: color-mix(in srgb, var(--hat-color) 24%, transparent);
            filter: blur(20px);
            opacity: 0;
            transition: opacity 0.25s ease, transform 0.25s ease;
        }

        .retest-hat-card:hover,
        .retest-hat-card:focus-visible {
            border-color: color-mix(in srgb, var(--hat-color) 64%, white 8%);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 17px 29px rgba(0,0,0,0.23), 0 0 24px color-mix(in srgb, var(--hat-color) 13%, transparent);
            outline: none;
            transform: translateY(-4px);
        }

        .retest-hat-card.is-selected {
            border-color: var(--hat-color);
            background:
                radial-gradient(circle at 50% 4%, color-mix(in srgb, var(--hat-color) 24%, transparent), transparent 48%),
                rgba(6, 36, 69, 0.9);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.14), 0 17px 29px rgba(0,0,0,0.23), 0 0 28px color-mix(in srgb, var(--hat-color) 22%, transparent);
            transform: translateY(-4px);
        }

        .retest-hat-card.is-selected::after {
            opacity: 1;
            transform: translateY(-18px);
        }

        .retest-hat-card.is-selected .retest-hat-visual {
            animation: retest-hat-selected 0.74s cubic-bezier(.2,.82,.25,1.16);
        }

        .retest-hat-visual {
            width: 78px;
            height: 68px;
            color: var(--hat-color);
            filter: drop-shadow(0 0 9px color-mix(in srgb, var(--hat-color) 26%, transparent));
            transform-origin: center bottom;
        }

        .retest-hat-visual .is-head {
            fill: rgba(229, 245, 255, 0.09);
            stroke: rgba(222, 245, 255, 0.24);
            stroke-width: 1.5;
        }

        .retest-hat-visual .is-main {
            fill: color-mix(in srgb, currentColor 28%, rgba(5, 29, 59, 0.9));
            stroke: currentColor;
            stroke-width: 2;
            stroke-linejoin: round;
        }

        .retest-hat-visual .is-accent {
            fill: none;
            stroke: #fff1bd;
            stroke-width: 2.5;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .retest-hat-role {
            color: var(--hat-color);
            font-size: 0.58rem;
            font-weight: 900;
            letter-spacing: 0.14em;
            text-transform: uppercase;
        }

        .retest-hat-title {
            color: #f5fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.87rem;
            font-weight: 900;
            letter-spacing: 0.04em;
            line-height: 1.18;
            text-align: center;
            text-transform: uppercase;
        }

        .retest-hat-copy {
            margin: 1px 0 0;
            color: rgba(213, 236, 248, 0.62);
            font-size: 0.62rem;
            line-height: 1.4;
            text-align: center;
        }

        .retest-knowledge-grid {
            position: relative;
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 10px;
        }

        .retest-knowledge-grid::before {
            content: "";
            position: absolute;
            top: 50%;
            left: 15%;
            right: 15%;
            height: 2px;
            background: linear-gradient(90deg, rgba(120, 217, 255, 0.18), rgba(255, 226, 154, 0.58), rgba(120, 226, 180, 0.18));
            box-shadow: 0 0 15px rgba(255, 226, 154, 0.15);
        }

        .retest-knowledge-card {
            --knowledge-color: var(--retest-cyan);
            position: relative;
            z-index: 1;
            min-height: 116px;
            display: grid;
            align-content: center;
            gap: 6px;
            border: 1px solid color-mix(in srgb, var(--knowledge-color) 22%, transparent);
            border-radius: 18px;
            cursor: pointer;
            color: #f4fbff;
            background: rgba(4, 24, 52, 0.91);
            padding: 15px;
            text-align: left;
            transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;
        }

        .retest-knowledge-card:nth-child(2) { --knowledge-color: var(--retest-green); }
        .retest-knowledge-card:nth-child(3) { --knowledge-color: var(--retest-gold); }

        .retest-knowledge-card:hover,
        .retest-knowledge-card:focus-visible,
        .retest-knowledge-card.is-selected {
            border-color: var(--knowledge-color);
            outline: none;
            box-shadow: 0 0 23px color-mix(in srgb, var(--knowledge-color) 16%, transparent);
            transform: translateY(-3px);
        }

        .retest-knowledge-card.is-selected {
            background: color-mix(in srgb, var(--knowledge-color) 10%, rgba(4, 24, 52, 0.94));
        }

        .retest-knowledge-label {
            color: var(--knowledge-color);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.07em;
            text-transform: uppercase;
        }

        .retest-knowledge-copy {
            color: rgba(215, 237, 249, 0.66);
            font-size: 0.64rem;
            line-height: 1.4;
        }

        .retest-technique-list {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        .retest-technique-chip {
            min-height: 40px;
            border: 1px solid rgba(167, 239, 255, 0.18);
            border-radius: 999px;
            cursor: pointer;
            color: rgba(225, 243, 252, 0.76);
            background: rgba(4, 25, 54, 0.72);
            font: 800 0.65rem/1.2 "Segoe UI", Arial, sans-serif;
            padding: 9px 13px;
            transition: color 0.2s ease, border-color 0.2s ease, background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
        }

        .retest-technique-chip:hover,
        .retest-technique-chip:focus-visible {
            border-color: rgba(255, 226, 154, 0.52);
            color: #fff0bd;
            outline: none;
            transform: translateY(-2px);
        }

        .retest-technique-chip.is-selected {
            border-color: rgba(255, 226, 154, 0.72);
            color: #fff0bd;
            background: rgba(255, 226, 154, 0.1);
            box-shadow: 0 0 18px rgba(255, 226, 154, 0.12);
        }

        .retest-toolkit-summary {
            display: grid;
            grid-template-columns: auto minmax(0, 1fr) auto;
            align-items: center;
            gap: 12px;
            margin-top: 17px;
            border: 1px solid rgba(167, 239, 255, 0.14);
            border-radius: 18px;
            background: rgba(2, 16, 37, 0.62);
            padding: 12px 13px;
        }

        .retest-toolkit-number {
            width: 34px;
            height: 34px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(120, 217, 255, 0.26);
            border-radius: 11px;
            color: var(--retest-cyan);
            background: rgba(120, 217, 255, 0.07);
            font: 900 0.7rem/1 Consolas, "Courier New", monospace;
        }

        .retest-toolkit-copy {
            min-width: 0;
            color: rgba(218, 239, 250, 0.66);
            font-size: 0.68rem;
            line-height: 1.45;
        }

        .retest-toolkit-copy strong {
            color: #f4fbff;
        }

        .retest-start-button {
            min-height: 42px;
            border: 1px solid rgba(255, 226, 154, 0.48);
            border-radius: 14px;
            cursor: pointer;
            color: #092744;
            background: linear-gradient(145deg, #fff1b8, #8ce5ef);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.5), 0 10px 19px rgba(0,0,0,0.18), 0 0 19px rgba(137, 230, 239, 0.13);
            font: 900 0.63rem/1 "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            letter-spacing: 0.09em;
            padding: 0 15px;
            text-transform: uppercase;
            transition: transform 0.2s ease, filter 0.2s ease, opacity 0.2s ease;
        }

        .retest-start-button:hover:not(:disabled),
        .retest-start-button:focus-visible:not(:disabled) {
            filter: brightness(1.08);
            outline: none;
            transform: translateY(-2px);
        }

        .retest-start-button:disabled {
            cursor: not-allowed;
            filter: grayscale(0.72);
            opacity: 0.38;
        }

        .retest-run-board {
            margin-top: 20px;
            border: 1px solid rgba(167, 239, 255, 0.18);
            border-radius: 22px;
            background:
                radial-gradient(circle at 100% 0%, rgba(120, 226, 180, 0.08), transparent 34%),
                rgba(2, 16, 38, 0.72);
            padding: 17px;
        }

        .retest-run-grid {
            display: grid;
            grid-template-columns: minmax(0, 1fr) minmax(170px, 0.28fr);
            align-items: stretch;
            gap: 14px;
        }

        .retest-route {
            position: relative;
            display: grid;
            grid-template-columns: repeat(5, minmax(0, 1fr));
            align-items: start;
            gap: 7px;
            padding: 13px 4px 4px;
        }

        .retest-route::before,
        .retest-route::after {
            content: "";
            position: absolute;
            top: 34px;
            left: 9%;
            right: 9%;
            height: 2px;
            border-radius: 999px;
        }

        .retest-route::before {
            background: rgba(167, 239, 255, 0.14);
        }

        .retest-route::after {
            right: 91%;
            background: linear-gradient(90deg, var(--retest-cyan), var(--retest-gold), var(--retest-green));
            box-shadow: 0 0 12px rgba(120, 217, 255, 0.45);
            transition: right 0.5s ease;
        }

        .retest-run-board[data-progress="1"] .retest-route::after { right: 70%; }
        .retest-run-board[data-progress="2"] .retest-route::after { right: 50%; }
        .retest-run-board[data-progress="3"] .retest-route::after { right: 30%; }
        .retest-run-board[data-progress="4"] .retest-route::after,
        .retest-run-board[data-progress="5"] .retest-route::after { right: 9%; }

        .retest-route-step {
            position: relative;
            z-index: 1;
            display: grid;
            justify-items: center;
            gap: 8px;
            color: rgba(205, 231, 244, 0.46);
            font-size: 0.53rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.25;
            text-align: center;
            text-transform: uppercase;
            transition: color 0.3s ease, transform 0.3s ease;
        }

        .retest-route-step span {
            width: 42px;
            height: 42px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(167, 239, 255, 0.18);
            border-radius: 50%;
            color: rgba(210, 237, 249, 0.5);
            background: #061d3d;
            box-shadow: 0 0 0 5px rgba(4, 28, 59, 0.92);
            font: 900 0.67rem/1 Consolas, "Courier New", monospace;
            transition: border-color 0.3s ease, color 0.3s ease, background 0.3s ease, box-shadow 0.3s ease;
        }

        .retest-route-step.is-active {
            color: #eafaff;
            transform: translateY(-3px);
        }

        .retest-route-step.is-active span {
            border-color: var(--retest-cyan);
            color: #061d3d;
            background: linear-gradient(145deg, #e8fcff, #7edff0);
            box-shadow: 0 0 0 5px rgba(4, 28, 59, 0.92), 0 0 20px rgba(120, 217, 255, 0.48);
            animation: retest-route-node 0.55s cubic-bezier(.2,.82,.25,1.12);
        }

        .retest-scanner {
            position: relative;
            overflow: hidden;
            display: grid;
            align-content: center;
            justify-items: center;
            gap: 6px;
            min-height: 126px;
            border: 1px solid rgba(120, 226, 180, 0.22);
            border-radius: 18px;
            background: rgba(5, 35, 57, 0.72);
            text-align: center;
            padding: 13px;
        }

        .retest-scanner::before {
            content: "";
            position: absolute;
            top: -40%;
            bottom: -40%;
            width: 30%;
            background: linear-gradient(90deg, transparent, rgba(120, 226, 180, 0.16), transparent);
            opacity: 0;
            transform: rotate(18deg) translateX(-420%);
        }

        .retest-run-board.is-running .retest-scanner::before {
            opacity: 1;
            animation: retest-scanner-sweep 1.05s linear infinite;
        }

        .retest-scanner-kicker {
            color: rgba(120, 226, 180, 0.58);
            font-size: 0.5rem;
            font-weight: 900;
            letter-spacing: 0.15em;
            text-transform: uppercase;
        }

        .retest-scanner-value {
            min-height: 32px;
            display: grid;
            place-items: center;
            color: var(--retest-green);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(0.82rem, 1.6vw, 1.02rem);
            font-weight: 900;
            letter-spacing: 0.04em;
            line-height: 1.15;
            text-transform: uppercase;
        }

        .retest-scanner-value.is-changing {
            animation: retest-scanner-value 0.2s ease;
        }

        .retest-scanner-state {
            color: rgba(213, 238, 246, 0.5);
            font-size: 0.55rem;
            font-weight: 800;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .retest-result {
            max-height: 0;
            overflow: hidden;
            opacity: 0;
            transform: translateY(12px);
            transition: max-height 0.68s ease, opacity 0.4s ease, transform 0.5s ease, margin-top 0.5s ease;
        }

        .retest-result.is-visible {
            max-height: 480px;
            margin-top: 14px;
            opacity: 1;
            transform: translateY(0);
        }

        .retest-result-card {
            display: grid;
            grid-template-columns: auto minmax(0, 1fr);
            gap: 14px;
            border: 1px solid rgba(255, 226, 154, 0.38);
            border-radius: 19px;
            background:
                radial-gradient(circle at 0 0, rgba(255, 226, 154, 0.13), transparent 35%),
                rgba(7, 37, 58, 0.9);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.09), 0 0 28px rgba(255, 226, 154, 0.08);
            padding: 16px;
        }

        .retest-result-icon {
            width: 48px;
            height: 48px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(255, 226, 154, 0.48);
            border-radius: 50%;
            color: #092744;
            background: linear-gradient(145deg, #fff2bd, #79dfd1);
            box-shadow: 0 0 23px rgba(255, 226, 154, 0.26);
            font-size: 1.14rem;
            font-weight: 950;
        }

        .retest-result-kicker {
            margin: 0;
            color: rgba(255, 232, 170, 0.66);
            font-size: 0.55rem;
            font-weight: 900;
            letter-spacing: 0.15em;
            text-transform: uppercase;
        }

        .retest-result-title {
            margin: 4px 0 5px;
            color: #fff0bd;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(0.95rem, 2vw, 1.2rem);
            font-weight: 900;
            letter-spacing: 0.04em;
            line-height: 1.15;
            text-transform: uppercase;
        }

        .retest-result-copy,
        .retest-result-principle {
            margin: 0;
            color: rgba(222, 241, 250, 0.72);
            font-size: 0.7rem;
            line-height: 1.5;
        }

        .retest-result-principle {
            margin-top: 7px;
            color: rgba(120, 226, 180, 0.82);
            font-weight: 700;
        }

        .retest-learning {
            margin-top: 24px;
            overflow: hidden;
            border: 1px solid rgba(255, 226, 154, 0.2);
            border-radius: 24px;
            background:
                radial-gradient(circle at 100% 0%, rgba(255, 226, 154, 0.09), transparent 30%),
                linear-gradient(145deg, rgba(7, 38, 70, 0.88), rgba(3, 20, 44, 0.94));
            padding: clamp(18px, 3vw, 26px);
        }

        .retest-learning-title {
            margin: 5px 0 8px;
            color: #fff0bd;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1rem, 2.2vw, 1.32rem);
            font-weight: 900;
            letter-spacing: 0.05em;
            text-transform: uppercase;
        }

        .retest-learning-copy {
            max-width: 860px;
            margin: 0;
            color: rgba(222, 240, 250, 0.76);
            font-size: 0.76rem;
            line-height: 1.58;
        }

        .retest-learning-steps {
            position: relative;
            display: grid;
            grid-template-columns: repeat(5, minmax(0, 1fr));
            align-items: end;
            gap: 7px;
            margin-top: 18px;
            padding-top: 28px;
        }

        .retest-learning-step {
            min-height: 72px;
            display: grid;
            align-content: center;
            gap: 5px;
            border: 1px solid rgba(167, 239, 255, 0.14);
            border-radius: 14px 14px 5px 5px;
            background: rgba(4, 25, 53, 0.74);
            color: rgba(222, 241, 250, 0.72);
            padding: 10px;
            transform: translateY(var(--learning-offset));
            opacity: 0;
            animation: retest-learning-step-in 0.52s cubic-bezier(.2,.82,.25,1) forwards;
            animation-delay: var(--learning-delay);
        }

        .retest-learning-step:nth-child(1) { --learning-offset: 26px; --learning-delay: 0.25s; }
        .retest-learning-step:nth-child(2) { --learning-offset: 19px; --learning-delay: 0.37s; }
        .retest-learning-step:nth-child(3) { --learning-offset: 12px; --learning-delay: 0.49s; }
        .retest-learning-step:nth-child(4) { --learning-offset: 5px; --learning-delay: 0.61s; }
        .retest-learning-step:nth-child(5) {
            --learning-offset: -2px;
            --learning-delay: 0.73s;
            border-color: rgba(255, 226, 154, 0.34);
            color: #fff0bd;
            background: rgba(255, 226, 154, 0.07);
        }

        .retest-learning-step small {
            color: rgba(120, 217, 255, 0.5);
            font-size: 0.46rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .retest-learning-step strong {
            font-size: 0.59rem;
            letter-spacing: 0.04em;
            line-height: 1.3;
            text-transform: uppercase;
        }

        .retest-investigation-actions {
            display: flex;
            justify-content: center;
        }

        .retest-investigation-actions .choice-button {
            width: min(280px, 100%);
        }

        .retest-investigation-actions .choice-button:disabled {
            cursor: not-allowed;
            filter: grayscale(0.72);
            opacity: 0.4;
            transform: none;
        }

        @keyframes retest-request-arrive {
            from { opacity: 0; transform: translateX(-22px); }
            to { opacity: 1; transform: translateX(0); }
        }

        @keyframes retest-hat-arrive {
            from { opacity: 0; transform: translateY(18px) rotateX(-10deg); }
            to { opacity: 1; transform: translateY(0) rotateX(0); }
        }

        @keyframes retest-hat-selected {
            0% { transform: rotate(-5deg) scale(0.94); }
            45% { transform: rotate(7deg) scale(1.08); }
            100% { transform: rotate(0) scale(1); }
        }

        @keyframes retest-route-node {
            0% { transform: scale(0.72); filter: brightness(0.8); }
            55% { transform: scale(1.16); filter: brightness(1.22); }
            100% { transform: scale(1); filter: brightness(1); }
        }

        @keyframes retest-scanner-sweep {
            from { transform: rotate(18deg) translateX(-420%); }
            to { transform: rotate(18deg) translateX(420%); }
        }

        @keyframes retest-scanner-value {
            0% { opacity: 0.2; transform: translateY(5px); filter: blur(2px); }
            100% { opacity: 1; transform: translateY(0); filter: blur(0); }
        }

        @keyframes retest-learning-step-in {
            from { opacity: 0; transform: translateY(calc(var(--learning-offset) + 15px)); }
            to { opacity: 1; transform: translateY(var(--learning-offset)); }
        }

        @media (max-width: 900px) {
            .retest-request {
                grid-template-columns: auto minmax(0, 1fr);
            }

            .retest-request-status {
                grid-column: 1 / -1;
                grid-template-columns: auto auto;
                justify-content: center;
                width: 100%;
            }

            .retest-section-head {
                display: grid;
                gap: 7px;
            }

            .retest-section-note {
                max-width: none;
                text-align: left;
            }

            .retest-hat-grid {
                grid-template-columns: repeat(2, minmax(0, 1fr));
            }

            .retest-hat-card {
                min-height: 202px;
            }

            .retest-knowledge-grid,
            .retest-run-grid {
                grid-template-columns: 1fr;
            }

            .retest-knowledge-grid::before {
                display: none;
            }

            .retest-toolkit-summary {
                grid-template-columns: auto minmax(0, 1fr);
            }

            .retest-start-button {
                grid-column: 1 / -1;
                width: 100%;
            }

            .retest-learning-steps {
                grid-template-columns: 1fr;
                gap: 7px;
                padding: 0 0 0 18px;
            }

            .retest-learning-step,
            .retest-learning-step:nth-child(n) {
                min-height: 58px;
                border-radius: 12px;
                transform: none;
                animation-name: retest-learning-step-mobile-in;
            }

            .retest-learning-steps::before {
                content: "";
                position: absolute;
                top: 6px;
                bottom: 6px;
                left: 5px;
                width: 2px;
                background: linear-gradient(var(--retest-cyan), var(--retest-gold));
            }
        }

        @media (max-width: 560px) {
            .retest-investigation-workbench {
                border-radius: 22px;
                padding: 15px;
            }

            .retest-hat-grid {
                grid-template-columns: 1fr;
            }

            .retest-hat-card {
                min-height: 0;
                grid-template-columns: 68px minmax(0, 1fr);
                grid-template-rows: auto auto 1fr;
                align-items: center;
                justify-items: start;
                column-gap: 12px;
                text-align: left;
            }

            .retest-hat-visual {
                grid-row: 1 / 4;
                width: 66px;
                height: 60px;
            }

            .retest-hat-title,
            .retest-hat-copy {
                text-align: left;
            }

            .retest-route {
                grid-template-columns: 1fr;
                gap: 8px;
                padding: 0;
            }

            .retest-route::before,
            .retest-route::after {
                display: none;
            }

            .retest-route-step {
                grid-template-columns: 38px minmax(0, 1fr);
                justify-items: start;
                align-items: center;
                text-align: left;
            }

            .retest-route-step span {
                width: 36px;
                height: 36px;
                box-shadow: none;
            }

            .retest-result-card {
                grid-template-columns: 1fr;
            }
        }

        @keyframes retest-learning-step-mobile-in {
            from { opacity: 0; transform: translateX(-12px); }
            to { opacity: 1; transform: translateX(0); }
        }

        @media (prefers-reduced-motion: reduce) {
            .retest-request,
            .retest-hat-card,
            .retest-hat-card.is-selected .retest-hat-visual,
            .retest-route-step.is-active span,
            .retest-scanner::before,
            .retest-scanner-value,
            .retest-learning-step {
                animation: none !important;
                transition-duration: 0.01ms !important;
            }

            .retest-learning-step {
                opacity: 1;
            }
        }

        .deep-link-shell {
            margin-top: clamp(46px, 8vw, 82px);
            max-height: 3600px;
            overflow: hidden;
            opacity: 1;
            transform: translateY(0);
            transition:
                opacity 0.56s ease,
                transform 0.56s ease,
                max-height 0.56s ease,
                margin-top 0.56s ease;
        }

        .deep-link-shell.is-faded {
            margin-top: 0;
            max-height: 0;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-12px);
        }

        .deep-link-panel {
            overflow: hidden;
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.2);
            background:
                radial-gradient(circle at 10% 0%, rgba(167, 239, 255, 0.12), transparent 32%),
                linear-gradient(155deg, rgba(8, 40, 82, 0.97), rgba(3, 20, 46, 0.99));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 20px 38px rgba(0,0,0,0.24);
        }

        .deep-link-summary {
            list-style: none;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
            min-height: 74px;
            padding: 18px 22px;
            cursor: pointer;
            user-select: none;
        }

        .deep-link-summary::-webkit-details-marker {
            display: none;
        }

        .deep-link-summary-copy {
            display: grid;
            gap: 5px;
        }

        .deep-link-summary-kicker {
            color: rgba(167, 239, 255, 0.7);
            font-size: 0.68rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .deep-link-summary-title {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1rem, 2vw, 1.24rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.1;
            text-transform: uppercase;
        }

        .deep-link-summary-icon {
            width: 38px;
            height: 38px;
            flex: 0 0 auto;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 999px;
            border: 1px solid rgba(167, 239, 255, 0.24);
            background: rgba(167, 239, 255, 0.08);
            color: var(--cyan-soft);
            font-size: 1.25rem;
            font-weight: 900;
            transition: transform 0.2s ease, background 0.2s ease;
        }

        .deep-link-panel[open] .deep-link-summary-icon {
            transform: rotate(45deg);
            background: rgba(255, 229, 162, 0.1);
            color: var(--gold-soft);
        }

        .deep-link-body {
            display: grid;
            gap: 20px;
            border-top: 1px solid rgba(184, 230, 255, 0.12);
            padding: 20px;
        }

        .deep-link-explainer {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            gap: 9px;
            margin: 0;
            color: rgba(226, 243, 255, 0.78);
            font-size: 0.84rem;
            line-height: 1.5;
        }

        .deep-link-example {
            border-radius: 999px;
            border: 1px solid rgba(255, 229, 162, 0.24);
            background: rgba(255, 229, 162, 0.08);
            color: var(--gold-soft);
            font-family: Consolas, "Courier New", monospace;
            font-size: 0.76rem;
            padding: 7px 10px;
        }

        .deep-link-toolbar {
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            align-items: center;
            gap: 12px;
        }

        .deep-link-search {
            width: 100%;
            min-height: 46px;
            border-radius: 15px;
            border: 1px solid rgba(167, 239, 255, 0.2);
            outline: none;
            background: rgba(2, 16, 38, 0.66);
            color: #f0f9ff;
            font: inherit;
            padding: 0 14px;
            transition: border-color 0.18s ease, box-shadow 0.18s ease;
        }

        .deep-link-search::placeholder {
            color: rgba(226, 243, 255, 0.46);
        }

        .deep-link-search:focus {
            border-color: rgba(167, 239, 255, 0.66);
            box-shadow: 0 0 0 4px rgba(167, 239, 255, 0.08);
        }

        .deep-link-count {
            color: rgba(167, 239, 255, 0.72);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            white-space: nowrap;
            text-transform: uppercase;
        }

        .deep-link-groups {
            display: grid;
            gap: 22px;
        }

        .deep-link-group[hidden],
        .deep-link-item[hidden] {
            display: none;
        }

        .deep-link-group-title {
            margin: 0 0 10px;
            color: rgba(167, 239, 255, 0.78);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .deep-link-grid {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 9px;
        }

        .deep-link-item {
            display: grid;
            grid-template-columns: minmax(0, 1fr) auto;
            border-radius: 16px;
            border: 1px solid rgba(167, 239, 255, 0.12);
            background: rgba(3, 20, 45, 0.54);
            transition: border-color 0.18s ease, transform 0.18s ease, background 0.18s ease;
        }

        .deep-link-item:hover {
            border-color: rgba(167, 239, 255, 0.3);
            background: rgba(9, 48, 91, 0.68);
            transform: translateY(-1px);
        }

        .deep-link-jump,
        .deep-link-copy {
            border: 0;
            cursor: pointer;
            font: inherit;
        }

        .deep-link-jump {
            min-width: 0;
            display: grid;
            gap: 5px;
            padding: 12px 13px;
            background: transparent;
            text-align: left;
        }

        .deep-link-jump-title {
            overflow: hidden;
            color: rgba(241, 249, 255, 0.94);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.86rem;
            font-weight: 800;
            line-height: 1.18;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .deep-link-jump-value {
            overflow: hidden;
            color: rgba(167, 239, 255, 0.58);
            font-family: Consolas, "Courier New", monospace;
            font-size: 0.66rem;
            line-height: 1.15;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        .deep-link-copy {
            align-self: stretch;
            min-width: 54px;
            border-left: 1px solid rgba(167, 239, 255, 0.1);
            border-radius: 0 15px 15px 0;
            background: rgba(167, 239, 255, 0.045);
            color: rgba(167, 239, 255, 0.7);
            font-size: 0.62rem;
            font-weight: 900;
            letter-spacing: 0.1em;
            text-transform: uppercase;
        }

        .deep-link-copy:hover,
        .deep-link-copy:focus-visible {
            background: rgba(255, 229, 162, 0.1);
            color: var(--gold-soft);
        }

        .deep-link-status {
            min-height: 1.2em;
            margin: 0;
            color: rgba(167, 239, 255, 0.76);
            font-size: 0.72rem;
            text-align: right;
        }

        .knowledge-overlap-shell {
            margin-top: clamp(52px, 9vw, 96px);
            max-height: 1200px;
            overflow: hidden;
            opacity: 1;
            transform: translateY(0);
            transition:
                max-height 0.6s ease,
                opacity 0.6s ease,
                transform 0.6s ease,
                margin-top 0.6s ease;
        }

        .knowledge-overlap-shell.is-faded {
            margin-top: 0;
            max-height: 0;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-12px);
        }

        .knowledge-overlap-panel {
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                linear-gradient(180deg, rgba(8, 38, 79, 0.94), rgba(4, 22, 48, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 18px 30px rgba(0,0,0,0.22);
            overflow: hidden;
        }

        .knowledge-overlap-summary {
            list-style: none;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
            min-height: 68px;
            padding: 18px 22px;
            cursor: pointer;
            user-select: none;
        }

        .knowledge-overlap-summary::-webkit-details-marker {
            display: none;
        }

        .knowledge-overlap-summary-text {
            display: grid;
            gap: 5px;
        }

        .knowledge-overlap-summary-kicker {
            color: rgba(167, 239, 255, 0.72);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            line-height: 1;
            text-transform: uppercase;
        }

        .knowledge-overlap-summary-title {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.02rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.08;
            text-transform: uppercase;
        }

        .knowledge-overlap-summary-icon {
            width: 32px;
            height: 32px;
            flex: 0 0 auto;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 999px;
            color: #f5fbff;
            font-size: 1.18rem;
            font-weight: 900;
            background:
                radial-gradient(circle at 30% 24%, rgba(255,255,255,0.2), transparent 28%),
                linear-gradient(180deg, rgba(255, 221, 138, 0.9), rgba(137, 95, 24, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 8px 14px rgba(0,0,0,0.2);
            transition: transform 0.18s ease;
        }

        .knowledge-overlap-panel[open] .knowledge-overlap-summary-icon {
            transform: rotate(45deg);
        }

        .knowledge-overlap-body {
            display: grid;
            grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
            gap: 24px;
            padding: 6px 22px 22px;
            border-top: 1px solid rgba(184, 230, 255, 0.12);
            background:
                linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0));
        }

        .knowledge-overlap-visual {
            display: grid;
            align-content: start;
        }

        .knowledge-overlap-diagram {
            position: relative;
            width: min(100%, 520px);
            min-height: 320px;
            aspect-ratio: 1.38 / 1;
            margin: 0 auto;
        }

        .knowledge-overlap-ring {
            position: absolute;
            width: 44%;
            aspect-ratio: 1 / 1;
            border-radius: 999px;
            border: 4px solid rgba(184, 230, 255, 0.48);
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 20px;
            text-align: center;
            background:
                radial-gradient(circle at 28% 24%, rgba(255,255,255,0.12), rgba(255,255,255,0.02) 42%, rgba(255,255,255,0) 70%);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 16px 24px rgba(0,0,0,0.16);
        }

        .knowledge-overlap-ring.is-domain {
            top: 2%;
            left: 7%;
            border-color: rgba(255, 222, 145, 0.9);
            color: #fff3cb;
        }

        .knowledge-overlap-ring.is-professional {
            top: 2%;
            right: 7%;
            border-color: rgba(167, 239, 255, 0.9);
            color: #e5faff;
        }

        .knowledge-overlap-ring.is-organizational {
            left: 50%;
            top: 37%;
            transform: translateX(-50%);
            border-color: rgba(162, 247, 222, 0.9);
            color: #ebfff7;
        }

        .knowledge-overlap-ring-label {
            display: grid;
            gap: 3px;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(0.78rem, 1.35vw, 0.98rem);
            font-weight: 900;
            letter-spacing: 0.04em;
            line-height: 1.08;
            text-transform: none;
            text-shadow: 0 1px 0 rgba(0,0,0,0.22);
        }

        .knowledge-overlap-copy {
            display: grid;
            gap: 12px;
            align-content: start;
        }

        .knowledge-overlap-note {
            margin: 0;
            padding: 16px 18px;
            border-radius: 20px;
            border: 1px solid rgba(184, 230, 255, 0.14);
            color: rgba(236, 246, 255, 0.9);
            font-size: 0.94rem;
            line-height: 1.62;
            background:
                linear-gradient(180deg, rgba(11, 50, 101, 0.72), rgba(5, 25, 50, 0.9)),
                linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 12px 20px rgba(0,0,0,0.16);
        }

        .knowledge-overlap-note-term {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1rem;
            letter-spacing: 0.04em;
        }

        .expandable-action-shell {
            margin-top: clamp(52px, 9vw, 96px);
        }

        .expandable-action-panel {
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                linear-gradient(180deg, rgba(8, 38, 79, 0.94), rgba(4, 22, 48, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 18px 30px rgba(0,0,0,0.22);
            overflow: hidden;
        }

        .expandable-action-summary {
            list-style: none;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
            min-height: 68px;
            padding: 18px 22px;
            cursor: pointer;
            user-select: none;
        }

        .expandable-action-summary::-webkit-details-marker {
            display: none;
        }

        .expandable-action-summary-text {
            display: grid;
            gap: 5px;
        }

        .expandable-action-summary-kicker {
            color: rgba(167, 239, 255, 0.72);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            line-height: 1;
            text-transform: uppercase;
        }

        .expandable-action-summary-title {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.02rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.08;
            text-transform: uppercase;
        }

        .expandable-action-summary-icon {
            width: 32px;
            height: 32px;
            flex: 0 0 auto;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 999px;
            color: #f5fbff;
            font-size: 1.18rem;
            font-weight: 900;
            background:
                radial-gradient(circle at 30% 24%, rgba(255,255,255,0.2), transparent 28%),
                linear-gradient(180deg, rgba(174, 184, 198, 0.94), rgba(67, 75, 88, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 8px 14px rgba(0,0,0,0.2);
            transition: transform 0.18s ease;
        }

        .expandable-action-panel[open] .expandable-action-summary-icon {
            transform: rotate(45deg);
        }

        .expandable-action-body {
            display: grid;
            gap: 18px;
            padding: 6px 22px 22px;
            border-top: 1px solid rgba(184, 230, 255, 0.12);
            background:
                linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0));
        }

        .expandable-action-group {
            display: grid;
            gap: 10px;
        }

        .reason-map-stage {
            display: grid;
            gap: 18px;
        }

        .reason-map-frame {
            position: relative;
            border-radius: 30px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                radial-gradient(circle at 16% 12%, rgba(255, 229, 162, 0.08), transparent 24%),
                radial-gradient(circle at 84% 10%, rgba(167, 239, 255, 0.08), transparent 24%),
                linear-gradient(180deg, rgba(9, 41, 84, 0.96), rgba(5, 24, 50, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 18px 30px rgba(0,0,0,0.24);
            padding: 24px 22px 22px;
        }

        .reason-map-plan {
            width: min(420px, 100%);
            margin: 0 auto 20px;
            padding: 16px 22px;
            border-radius: 24px;
            border: 1px solid rgba(184, 230, 255, 0.16);
            text-align: center;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.5rem, 2.5vw, 2rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            background:
                linear-gradient(180deg, rgba(13, 58, 115, 0.88), rgba(6, 30, 63, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 14px 24px rgba(0,0,0,0.2);
        }

        .reason-map-script-wrap {
            position: relative;
            display: flex;
            justify-content: center;
            margin-bottom: 28px;
        }

        .reason-map-script-wrap::after {
            content: "";
            position: absolute;
            top: calc(100% + 2px);
            left: 50%;
            width: 2px;
            height: 26px;
            transform: translateX(-50%);
            background: linear-gradient(180deg, rgba(184, 230, 255, 0.54), rgba(184, 230, 255, 0));
        }

        .reason-map-requirement {
            appearance: none;
            position: relative;
            display: block;
            width: min(340px, 100%);
            margin: 0 auto 34px;
            padding: 13px 20px;
            border-radius: 20px;
            border: 1px solid rgba(255, 226, 145, 0.22);
            cursor: pointer;
            color: #fff6d4;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.08rem, 1.65vw, 1.3rem);
            font-weight: 900;
            letter-spacing: 0.08em;
            text-align: center;
            text-transform: uppercase;
            background:
                linear-gradient(180deg, rgba(52, 76, 105, 0.92), rgba(23, 36, 56, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 12px 20px rgba(0,0,0,0.18);
            transform-style: preserve-3d;
            transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
        }

        .reason-map-requirement::after {
            content: "";
            position: absolute;
            top: calc(100% + 2px);
            left: 50%;
            width: 2px;
            height: 28px;
            transform: translateX(-50%);
            background: linear-gradient(180deg, rgba(184, 230, 255, 0.54), rgba(184, 230, 255, 0));
        }

        .reason-map-requirement:hover,
        .reason-map-requirement:focus-visible {
            border-color: rgba(255, 226, 145, 0.38);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 16px 24px rgba(0,0,0,0.2),
                0 0 18px rgba(255, 226, 145, 0.12);
            outline: none;
            transform: translateY(-1px);
        }

        .reason-map-requirement.is-code {
            font-size: clamp(0.72rem, 1.08vw, 0.92rem);
            letter-spacing: 0.05em;
            line-height: 1.2;
            text-transform: none;
        }

        .reason-map-requirement.is-flipping {
            animation: reason-map-requirement-flip 0.62s cubic-bezier(.28,.88,.26,1.05);
        }

        @keyframes reason-map-requirement-flip {
            0% {
                transform: rotateY(0deg) translateY(-1px);
            }
            48% {
                transform: rotateY(92deg) translateY(-2px);
            }
            100% {
                transform: rotateY(360deg) translateY(-1px);
            }
        }

        .reason-map-node {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            border-radius: 999px;
            border: 1px solid rgba(184, 230, 255, 0.16);
            color: #f4fbff;
            background:
                linear-gradient(180deg, rgba(13, 59, 114, 0.9), rgba(6, 30, 61, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 12px 20px rgba(0,0,0,0.18);
        }

        .reason-map-node.is-script {
            width: 160px;
            height: 160px;
            padding: 20px;
            color: #fff4cc;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.08rem, 1.55vw, 1.28rem);
            font-weight: 900;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }

        .reason-map-branches {
            position: relative;
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 18px;
        }

        .reason-map-branches::before {
            content: "";
            position: absolute;
            top: 0;
            left: 12.5%;
            width: 75%;
            height: 2px;
            background: linear-gradient(90deg, rgba(184, 230, 255, 0), rgba(184, 230, 255, 0.6) 18%, rgba(184, 230, 255, 0.6) 82%, rgba(184, 230, 255, 0));
        }

        .reason-map-branch {
            position: relative;
            display: grid;
            justify-items: center;
            gap: 14px;
            padding-top: 24px;
        }

        .reason-map-branch::before {
            content: "";
            position: absolute;
            top: 0;
            left: 50%;
            width: 2px;
            height: 24px;
            transform: translateX(-50%);
            background: linear-gradient(180deg, rgba(184, 230, 255, 0.64), rgba(184, 230, 255, 0));
        }

        .reason-map-node.is-case {
            width: min(100%, 176px);
            height: 176px;
            padding: 20px;
            cursor: pointer;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(0.84rem, 1.05vw, 0.96rem);
            font-weight: 900;
            letter-spacing: 0.05em;
            line-height: 1.14;
            text-transform: uppercase;
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .reason-map-node.is-case span {
            max-width: 13ch;
            overflow-wrap: anywhere;
        }

        .reason-map-node.is-case:hover,
        .reason-map-node.is-case:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 226, 145, 0.34);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 16px 24px rgba(0,0,0,0.2),
                0 0 18px rgba(140, 232, 255, 0.14);
            outline: none;
        }

        .reason-map-node.is-case.is-selected {
            border-color: rgba(255, 226, 145, 0.42);
            color: #fff8dd;
        }

        .reason-map-node.is-case.is-explicit {
            background:
                linear-gradient(180deg, rgba(15, 87, 141, 0.95), rgba(8, 42, 78, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
        }

        .reason-map-node.is-mindmap {
            width: 120px;
            height: 120px;
            padding: 18px;
            color: rgba(236, 246, 255, 0.9);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            line-height: 1.08;
            text-transform: uppercase;
        }

        .reason-map-branch-tail {
            display: grid;
            justify-items: center;
            gap: 12px;
            width: 100%;
        }

        .reason-map-layer-prompt {
            margin: 0;
            color: rgba(167, 239, 255, 0.78);
            font-size: 0.68rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            line-height: 1.25;
            text-align: center;
            text-transform: uppercase;
        }

        .reason-map-layer-prompt[hidden],
        .reason-map-layer-roller[hidden],
        .reason-map-preview[hidden] {
            display: none !important;
        }

        .reason-map-layer-roller {
            position: relative;
            display: grid;
            place-items: center;
            width: min(100%, 180px);
            min-height: 58px;
            padding: 7px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            border-radius: 18px;
            background:
                linear-gradient(180deg, rgba(11, 19, 33, 0.94), rgba(4, 10, 20, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                inset 0 -10px 18px rgba(0,0,0,0.22),
                0 10px 18px rgba(0,0,0,0.2);
            overflow: hidden;
        }

        .reason-map-layer-roller::before,
        .reason-map-layer-roller::after {
            content: "";
            position: absolute;
            left: 10px;
            right: 10px;
            height: 1px;
            background: rgba(255,255,255,0.14);
            z-index: 1;
        }

        .reason-map-layer-roller::before {
            top: 12px;
        }

        .reason-map-layer-roller::after {
            bottom: 12px;
        }

        .reason-map-layer-value {
            position: relative;
            z-index: 2;
            display: grid;
            place-items: center;
            width: 100%;
            min-height: 44px;
            border: 1px solid rgba(212, 220, 230, 0.22);
            border-radius: 14px;
            color: #f6f9fd;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-align: center;
            text-transform: uppercase;
            background:
                linear-gradient(180deg, rgba(96, 107, 122, 0.92), rgba(29, 35, 45, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 4px 0 rgba(16, 21, 28, 0.82);
            transition: transform 0.16s ease, opacity 0.16s ease, border-color 0.16s ease;
        }

        .reason-map-layer-roller.is-rolling .reason-map-layer-value {
            animation: reason-map-slot-flash 0.22s steps(2, end) infinite;
            border-color: rgba(167, 239, 255, 0.38);
        }

        .reason-map-layer-roller.is-settled .reason-map-layer-value {
            border-color: rgba(255, 226, 145, 0.38);
            color: #fff8df;
            transform: translateY(-1px);
        }

        .reason-map-layer-roller.is-nothing {
            border-color: rgba(171, 255, 211, 0.32);
            background:
                radial-gradient(circle at 50% 12%, rgba(171, 255, 211, 0.2), transparent 42%),
                linear-gradient(180deg, rgba(20, 84, 55, 0.88), rgba(6, 45, 29, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 0 22px rgba(86, 255, 173, 0.22),
                0 10px 18px rgba(0,0,0,0.18);
        }

        .reason-map-layer-roller.is-nothing::before,
        .reason-map-layer-roller.is-nothing::after {
            opacity: 0.28;
        }

        .reason-map-layer-roller.is-nothing .reason-map-layer-value {
            display: flex;
            align-items: center;
            justify-content: center;
            border-color: rgba(171, 255, 211, 0.34);
            color: #ecfff3;
            font-family: "Trebuchet MS", sans-serif;
            font-size: 0.96rem;
            font-weight: 900;
            letter-spacing: 0.03em;
            text-transform: none;
            background:
                linear-gradient(180deg, rgba(33, 135, 84, 0.96), rgba(13, 74, 48, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.16), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.2),
                0 4px 0 rgba(5, 40, 24, 0.72);
            transform: none;
        }

        .reason-map-layer-roller.is-nothing .reason-map-layer-value::before {
            content: "✓";
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 18px;
            height: 18px;
            margin-right: 7px;
            border-radius: 999px;
            color: #0b3e28;
            font-size: 0.72rem;
            font-weight: 900;
            background: #ecfff3;
            box-shadow: 0 0 12px rgba(236, 255, 243, 0.42);
        }

        .reason-map-layer-roller.is-nothing .reason-map-layer-value::before {
            content: "\2713";
        }

        @keyframes reason-map-slot-flash {
            0% {
                opacity: 0.52;
                transform: translateY(-2px);
            }
            100% {
                opacity: 1;
                transform: translateY(2px);
            }
        }

        .reason-map-preview {
            width: min(100%, 300px);
            padding: 14px 16px 15px;
            border-radius: 20px;
            border: 1px solid rgba(184, 230, 255, 0.16);
            background:
                linear-gradient(180deg, rgba(11, 50, 101, 0.74), rgba(5, 25, 50, 0.92)),
                linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 12px 20px rgba(0,0,0,0.16);
            text-align: center;
        }

        .reason-map-preview-label {
            margin: 0;
            color: rgba(167, 239, 255, 0.8);
            font-size: 0.68rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .reason-map-preview-title {
            margin: 0;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.02rem;
            font-weight: 900;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }

        .reason-map-preview-mode {
            margin: 8px 0 0;
            color: #f5fbff;
            font-size: 0.9rem;
            font-weight: 700;
            letter-spacing: 0.03em;
        }

        .reason-map-preview-reason {
            display: flex;
            align-items: center;
            min-height: 76px;
            margin: 12px 0 0;
            padding: 14px 16px;
            border: 1px solid rgba(212, 220, 230, 0.22);
            border-radius: 20px;
            color: #f6f9fd;
            font-size: clamp(0.88rem, 1.15vw, 1rem);
            font-weight: 800;
            letter-spacing: 0.05em;
            line-height: 1.2;
            background:
                linear-gradient(180deg, rgba(96, 107, 122, 0.92), rgba(29, 35, 45, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 14px 24px rgba(0,0,0,0.2),
                0 4px 0 rgba(16, 21, 28, 0.82);
            text-align: left;
            text-transform: none;
        }

        .reason-map-robot-panel {
            width: min(720px, 100%);
            margin: 28px auto 0;
            padding: 18px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            border-radius: 26px;
            background:
                radial-gradient(circle at 18% 18%, rgba(171, 255, 211, 0.12), transparent 30%),
                radial-gradient(circle at 82% 10%, rgba(167, 239, 255, 0.12), transparent 30%),
                linear-gradient(180deg, rgba(11, 50, 101, 0.76), rgba(5, 25, 50, 0.94));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 16px 26px rgba(0,0,0,0.2);
            animation: reason-map-robot-reveal 0.42s ease both;
        }

        .reason-map-robot-panel[hidden] {
            display: none !important;
        }

        .reason-map-robot-head {
            display: grid;
            grid-template-columns: auto minmax(0, 1fr);
            gap: 14px;
            align-items: center;
            margin-bottom: 16px;
        }

        .reason-map-robot-icon {
            position: relative;
            width: 68px;
            height: 58px;
            border: 2px solid rgba(171, 255, 211, 0.34);
            border-radius: 22px 22px 18px 18px;
            background:
                linear-gradient(180deg, rgba(33, 135, 84, 0.82), rgba(13, 74, 48, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.16), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 0 18px rgba(86, 255, 173, 0.2);
        }

        .reason-map-robot-icon::before {
            content: "";
            position: absolute;
            top: -16px;
            left: 50%;
            width: 2px;
            height: 14px;
            transform: translateX(-50%);
            background: rgba(171, 255, 211, 0.72);
            box-shadow: 0 -4px 0 2px rgba(171, 255, 211, 0.52);
        }

        .reason-map-robot-eye {
            position: absolute;
            top: 20px;
            width: 11px;
            height: 11px;
            border-radius: 999px;
            background: #ecfff3;
            box-shadow: 0 0 10px rgba(236, 255, 243, 0.6);
        }

        .reason-map-robot-eye.is-left {
            left: 18px;
        }

        .reason-map-robot-eye.is-right {
            right: 18px;
        }

        .reason-map-robot-mouth {
            position: absolute;
            left: 22px;
            right: 22px;
            bottom: 14px;
            height: 3px;
            border-radius: 999px;
            background: rgba(236, 255, 243, 0.72);
        }

        .reason-map-robot-kicker {
            margin: 0;
            color: rgba(167, 239, 255, 0.78);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.16em;
            text-transform: uppercase;
        }

        .reason-map-robot-title {
            margin: 3px 0 0;
            color: #f6f9fd;
            font-size: clamp(1rem, 1.6vw, 1.24rem);
            font-weight: 900;
            letter-spacing: 0.04em;
        }

        .reason-map-robot-sliders {
            display: grid;
            gap: 12px;
        }

        .reason-map-robot-slider {
            display: grid;
            grid-template-columns: minmax(92px, 0.45fr) minmax(0, 1fr) 54px;
            gap: 12px;
            align-items: center;
            padding: 12px 14px;
            border: 1px solid rgba(184, 230, 255, 0.14);
            border-radius: 18px;
            background: rgba(255,255,255,0.045);
        }

        .reason-map-robot-slider.is-disabled {
            opacity: 0.54;
            filter: blur(1.4px);
            pointer-events: none;
            user-select: none;
        }

        .reason-map-robot-slider-label,
        .reason-map-robot-value {
            color: #f6f9fd;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }

        .reason-map-robot-value {
            color: var(--gold-soft);
            text-align: right;
        }

        .reason-map-robot-range {
            width: 100%;
            accent-color: #8cffc0;
        }

        @keyframes reason-map-robot-reveal {
            from {
                opacity: 0;
                transform: translateY(16px) scale(0.98);
            }
            to {
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }

        .reason-map-actions {
            display: flex;
            justify-content: center;
            margin-top: 6px;
        }

        .reason-map-actions .choice-button {
            width: min(260px, 100%);
            min-height: auto;
            padding: 18px 22px;
            text-align: center;
        }

        .info-frame {
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                linear-gradient(180deg, rgba(9, 40, 86, 0.94), rgba(5, 24, 50, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 16px 28px rgba(0,0,0,0.22);
            padding: 24px 24px 22px;
        }

        .info-title {
            margin: 0 0 12px;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.14rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .info-copy {
            margin: 0;
            color: rgba(232, 245, 255, 0.86);
            font-size: 0.95rem;
            line-height: 1.65;
        }

        .structured-chaos-stage {
            position: relative;
            overflow: hidden;
            border-radius: 30px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                radial-gradient(circle at 16% 12%, rgba(255, 229, 162, 0.14), transparent 24%),
                radial-gradient(circle at 84% 10%, rgba(167, 239, 255, 0.12), transparent 24%),
                linear-gradient(180deg, rgba(9, 43, 88, 0.96), rgba(5, 24, 52, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 18px 30px rgba(0,0,0,0.24);
            padding: 24px 20px 24px;
        }

        .structured-chaos-team {
            display: flex;
            justify-content: center;
            gap: 14px;
            margin-bottom: 18px;
        }

        .structured-chaos-tester {
            display: inline-flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 8px;
            width: 88px;
            min-height: 100px;
            border: 1px solid rgba(184, 230, 255, 0.16);
            border-radius: 22px;
            cursor: pointer;
            color: rgba(230, 244, 255, 0.72);
            background:
                linear-gradient(180deg, rgba(20, 78, 146, 0.86), rgba(8, 36, 74, 0.94));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 12px 20px rgba(0,0,0,0.18),
                0 3px 0 rgba(3, 21, 46, 0.7);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease, color 0.18s ease;
        }

        .structured-chaos-tester:hover,
        .structured-chaos-tester:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 229, 162, 0.4);
            color: #f7fbff;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 16px 24px rgba(0,0,0,0.22),
                0 3px 0 rgba(3, 21, 46, 0.72),
                0 0 18px rgba(167, 239, 255, 0.16);
            outline: none;
        }

        .structured-chaos-tester.is-active {
            color: #fff3c8;
            border-color: rgba(255, 229, 162, 0.48);
            background:
                linear-gradient(180deg, rgba(38, 116, 198, 0.9), rgba(11, 48, 96, 0.96));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.2),
                0 16px 24px rgba(0,0,0,0.22),
                0 3px 0 rgba(3, 21, 46, 0.72),
                0 0 18px rgba(255, 229, 162, 0.16);
        }

        .structured-chaos-tester.is-secondary.is-active {
            color: #e3f8ff;
            border-color: rgba(167, 239, 255, 0.48);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.2),
                0 16px 24px rgba(0,0,0,0.22),
                0 3px 0 rgba(3, 21, 46, 0.72),
                0 0 18px rgba(167, 239, 255, 0.18);
        }

        .structured-chaos-tester-icon {
            width: 34px;
            height: 46px;
        }

        .structured-chaos-tester-icon svg {
            display: block;
            width: 100%;
            height: 100%;
            stroke: currentColor;
            stroke-width: 3.5;
            fill: none;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .structured-chaos-tester-count {
            font-size: 0.78rem;
            font-weight: 900;
            letter-spacing: 0.14em;
            text-transform: uppercase;
        }

        .structured-chaos-figure {
            position: relative;
            width: 100%;
            min-height: 620px;
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.16);
            background:
                radial-gradient(circle at 50% 16%, rgba(255, 229, 162, 0.14), transparent 22%),
                radial-gradient(circle at 82% 12%, rgba(167, 239, 255, 0.08), transparent 24%),
                linear-gradient(180deg, rgba(7, 34, 72, 0.94), rgba(3, 20, 44, 0.96));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                inset 0 -18px 24px rgba(0, 0, 0, 0.16);
        }

        .structured-chaos-svg {
            display: block;
            width: 100%;
            height: auto;
        }

        .structured-chaos-axis,
        .structured-chaos-curve {
            fill: none;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .structured-chaos-axis {
            stroke: rgba(255, 229, 162, 0.32);
            stroke-width: 4;
        }

        .structured-chaos-axis.is-dashed {
            stroke-width: 4;
            stroke-dasharray: 12 12;
        }

        .structured-chaos-axis.is-primary {
            stroke: #ffd36c;
        }

        .structured-chaos-axis.is-secondary {
            stroke: #8ed8ff;
        }

        .structured-chaos-axis.is-hidden,
        .structured-chaos-indicator-cap.is-hidden {
            opacity: 0;
        }

        .structured-chaos-curve {
            stroke: rgba(167, 239, 255, 0.34);
            stroke-width: 6;
        }

        .structured-chaos-indicator-cap {
            stroke-width: 2;
            filter: drop-shadow(0 8px 14px rgba(0, 0, 0, 0.22));
        }

        .structured-chaos-indicator-cap.is-primary {
            fill: #ffd36c;
            stroke: rgba(255, 247, 220, 0.7);
        }

        .structured-chaos-indicator-cap.is-secondary {
            fill: #8ed8ff;
            stroke: rgba(235, 250, 255, 0.7);
        }

        .structured-chaos-label {
            position: absolute;
            color: rgba(255, 229, 162, 0.7);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-weight: 900;
            letter-spacing: 0.03em;
            text-transform: none;
            pointer-events: none;
        }

        .structured-chaos-label.is-y {
            top: 10%;
            left: 1.8%;
            font-size: clamp(1.8rem, 2.7vw, 2.95rem);
            writing-mode: vertical-rl;
            transform: rotate(180deg);
        }

        .structured-chaos-label.is-left {
            bottom: 11%;
            left: 5%;
            font-size: clamp(1.8rem, 3vw, 3rem);
        }

        .structured-chaos-label.is-right {
            right: 4%;
            bottom: 11%;
            font-size: clamp(1.8rem, 3vw, 3rem);
            text-align: right;
        }

        .structured-chaos-message {
            width: min(860px, calc(100% - 84px));
            min-height: 3.8em;
            margin: 6px auto 12px;
            color: #8ec8ff;
            font-size: clamp(0.98rem, 1.6vw, 1.16rem);
            font-weight: 700;
            line-height: 1.55;
            text-align: center;
            text-wrap: balance;
        }

        .structured-chaos-message-line {
            display: block;
        }

        .structured-chaos-message-line + .structured-chaos-message-line {
            margin-top: 4px;
        }

        .structured-chaos-slider-stack {
            display: grid;
            gap: 14px;
        }

        .structured-chaos-fader-shell {
            width: min(780px, calc(100% - 96px));
            margin: 0 auto;
            padding: 12px 18px 18px;
            border-radius: 20px;
            border: 1px solid rgba(184, 230, 255, 0.14);
            background:
                linear-gradient(180deg, rgba(15, 64, 118, 0.9), rgba(6, 30, 61, 0.96));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 16px 24px rgba(0,0,0,0.18);
        }

        .structured-chaos-fader-shell.is-secondary {
            border-color: rgba(167, 239, 255, 0.24);
        }

        .structured-chaos-fader-label {
            margin: 0 0 10px;
            color: rgba(255, 229, 162, 0.82);
            font-size: 0.76rem;
            font-weight: 900;
            letter-spacing: 0.14em;
            text-transform: uppercase;
        }

        .structured-chaos-slider {
            width: 100%;
            height: 54px;
            margin: 0;
            appearance: none;
            background: transparent;
            cursor: ew-resize;
            --slider-thumb-top: #fff0ba;
            --slider-thumb-mid: #ffd36c;
            --slider-thumb-bottom: #9f7928;
            --slider-thumb-border: rgba(255, 245, 215, 0.6);
            --slider-thumb-glow: rgba(255, 211, 108, 0.16);
        }

        .structured-chaos-slider.is-secondary {
            --slider-thumb-top: #dff8ff;
            --slider-thumb-mid: #8ed8ff;
            --slider-thumb-bottom: #2f7daa;
            --slider-thumb-border: rgba(235, 250, 255, 0.68);
            --slider-thumb-glow: rgba(142, 216, 255, 0.16);
        }

        .structured-chaos-slider:focus-visible {
            outline: none;
        }

        .structured-chaos-slider::-webkit-slider-runnable-track {
            height: 10px;
            border-radius: 999px;
            border: 1px solid rgba(184, 230, 255, 0.14);
            background: linear-gradient(90deg, rgba(22, 74, 131, 0.96), rgba(77, 150, 208, 0.96), rgba(22, 74, 131, 0.96));
            box-shadow:
                inset 0 2px 5px rgba(0,0,0,0.2),
                0 1px 0 rgba(255,255,255,0.06);
        }

        .structured-chaos-slider::-webkit-slider-thumb {
            width: 34px;
            height: 54px;
            margin-top: -23px;
            border: 1px solid var(--slider-thumb-border);
            border-radius: 11px;
            appearance: none;
            background:
                linear-gradient(180deg, var(--slider-thumb-top), var(--slider-thumb-mid) 50%, var(--slider-thumb-bottom) 100%);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.28),
                0 10px 18px rgba(0,0,0,0.22),
                0 0 0 4px var(--slider-thumb-glow);
        }

        .structured-chaos-slider::-moz-range-track {
            height: 10px;
            border-radius: 999px;
            border: 1px solid rgba(184, 230, 255, 0.14);
            background: linear-gradient(90deg, rgba(22, 74, 131, 0.96), rgba(77, 150, 208, 0.96), rgba(22, 74, 131, 0.96));
            box-shadow:
                inset 0 2px 5px rgba(0,0,0,0.2),
                0 1px 0 rgba(255,255,255,0.06);
        }

        .structured-chaos-slider::-moz-range-thumb {
            width: 34px;
            height: 54px;
            border: 1px solid var(--slider-thumb-border);
            border-radius: 11px;
            background:
                linear-gradient(180deg, var(--slider-thumb-top), var(--slider-thumb-mid) 50%, var(--slider-thumb-bottom) 100%);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.28),
                0 10px 18px rgba(0,0,0,0.22),
                0 0 0 4px var(--slider-thumb-glow);
        }

        .structured-chaos-actions {
            display: flex;
            justify-content: center;
            margin-top: 22px;
        }

        .structured-chaos-actions .choice-button {
            min-height: auto;
            width: min(280px, 100%);
            padding: 18px 24px;
            border-radius: 22px;
            text-align: center;
        }

        .structured-chaos-actions .choice-copy {
            display: none;
        }

        .info-list {
            margin: 0;
            padding-left: 18px;
            color: rgba(240, 248, 255, 0.88);
            line-height: 1.75;
        }

        .info-list li + li {
            margin-top: 4px;
        }

        .info-table-wrap {
            width: 100%;
            max-width: 100%;
            overflow-x: auto;
            padding-bottom: 4px;
        }

        .info-table-wrap::-webkit-scrollbar {
            height: 11px;
        }

        .info-table-wrap::-webkit-scrollbar-track {
            border-radius: 999px;
            background: rgba(4, 22, 46, 0.76);
        }

        .info-table-wrap::-webkit-scrollbar-thumb {
            border-radius: 999px;
            background: linear-gradient(90deg, rgba(255, 226, 145, 0.94), rgba(141, 231, 255, 0.94));
            border: 2px solid rgba(4, 22, 46, 0.92);
        }

        .info-table {
            width: 100%;
            min-width: 720px;
            border-collapse: separate;
            border-spacing: 0 10px;
        }

        .info-table th,
        .info-table td {
            padding: 12px 14px;
            text-align: left;
            vertical-align: top;
        }

        .info-table thead th {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .info-table tbody td {
            color: rgba(236, 246, 255, 0.9);
            font-size: 0.92rem;
            line-height: 1.55;
            background:
                linear-gradient(180deg, rgba(12, 56, 110, 0.72), rgba(6, 28, 58, 0.9)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            border-top: 1px solid rgba(180, 228, 255, 0.14);
            border-bottom: 1px solid rgba(12, 20, 34, 0.34);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 10px 18px rgba(0,0,0,0.14);
        }

        .info-table tbody td:first-child {
            border-top-left-radius: 16px;
            border-bottom-left-radius: 16px;
            color: #fef5cb;
            font-weight: 800;
            letter-spacing: 0.03em;
        }

        .info-table tbody td:last-child {
            border-top-right-radius: 16px;
            border-bottom-right-radius: 16px;
        }

        .info-table tbody tr.is-clickable {
            cursor: pointer;
            touch-action: manipulation;
        }

        .info-table tbody tr.is-clickable td {
            transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease, border-color 0.18s ease;
        }

        .info-table tbody tr.is-clickable:hover td,
        .info-table tbody tr.is-clickable:focus-visible td {
            filter: brightness(1.08);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 14px 22px rgba(0,0,0,0.18),
                0 0 18px rgba(255, 226, 145, 0.12);
        }

        .info-table tbody tr.is-clickable:hover td:first-child,
        .info-table tbody tr.is-clickable:focus-visible td:first-child {
            color: #fff8dd;
        }

        .info-table tbody tr.is-clickable:focus-visible {
            outline: none;
        }

        .matrix-frame {
            width: 100%;
            max-width: 100%;
            min-width: 0;
            border-radius: 28px;
            border: 1px solid rgba(184, 230, 255, 0.18);
            background:
                linear-gradient(180deg, rgba(8, 36, 74, 0.94), rgba(5, 22, 48, 0.97)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.12),
                0 16px 28px rgba(0,0,0,0.22);
            padding: 20px 20px 18px;
        }

        .matrix-note {
            margin: 0 0 14px;
            color: rgba(230, 244, 255, 0.82);
            font-size: 0.9rem;
            line-height: 1.55;
        }

        .matrix-mobile-hint {
            display: none;
            margin: -4px 0 12px;
            color: rgba(167, 239, 255, 0.82);
            font-size: 0.78rem;
            line-height: 1.45;
            letter-spacing: 0.03em;
        }

        .matrix-scroll {
            width: 100%;
            max-width: 100%;
            position: relative;
            overflow-x: auto;
            overflow-y: hidden;
            padding-bottom: 4px;
            -webkit-overflow-scrolling: touch;
            overscroll-behavior-x: contain;
            scrollbar-gutter: stable both-edges;
            touch-action: pan-x pan-y;
        }

        .matrix-scroll::-webkit-scrollbar {
            height: 12px;
        }

        .matrix-scroll::-webkit-scrollbar-track {
            border-radius: 999px;
            background: rgba(3, 20, 44, 0.74);
        }

        .matrix-scroll::-webkit-scrollbar-thumb {
            border-radius: 999px;
            background: linear-gradient(90deg, rgba(255, 229, 148, 0.92), rgba(140, 232, 255, 0.92));
            border: 2px solid rgba(3, 20, 44, 0.9);
        }

        .matrix-table {
            width: 100%;
            min-width: 920px;
            border-collapse: separate;
            border-spacing: 8px;
        }

        .matrix-table th,
        .matrix-table td {
            vertical-align: middle;
        }

        .matrix-corner,
        .matrix-axis {
            padding: 12px 10px;
            border-radius: 18px;
            background:
                linear-gradient(180deg, rgba(255,255,255,0.1), rgba(255,255,255,0.04)),
                rgba(255,255,255,0.04);
            border: 1px solid rgba(255,255,255,0.12);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 10px 16px rgba(0,0,0,0.14);
            text-align: center;
        }

        .matrix-corner {
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.82rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .matrix-axis-title {
            display: block;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.8rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .matrix-axis-subtitle {
            display: block;
            margin-top: 6px;
            color: rgba(228, 242, 255, 0.74);
            font-size: 0.72rem;
            line-height: 1.4;
        }

        .matrix-row-label {
            min-width: 128px;
            padding: 14px 10px;
            border-radius: 18px;
            background:
                linear-gradient(180deg, rgba(8, 48, 95, 0.92), rgba(5, 25, 52, 0.96)),
                linear-gradient(135deg, rgba(255,255,255,0.12), rgba(255,255,255,0));
            border: 1px solid rgba(180, 228, 255, 0.16);
            box-shadow: inset 0 1px 0 rgba(255,255,255,0.1), 0 10px 16px rgba(0,0,0,0.16);
            text-align: center;
        }

        .matrix-row-score {
            display: block;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 1.08rem;
            font-weight: 900;
            line-height: 1;
        }

        .matrix-row-text {
            display: block;
            margin-top: 6px;
            color: rgba(231, 245, 255, 0.84);
            font-size: 0.76rem;
            line-height: 1.32;
            text-transform: uppercase;
            letter-spacing: 0.06em;
        }

        .matrix-cell-button {
            width: 100%;
            min-height: 98px;
            border: 1px solid rgba(182, 229, 255, 0.18);
            border-radius: 22px;
            cursor: pointer;
            padding: 14px 10px;
            color: #f6fbff;
            background:
                linear-gradient(180deg, rgba(17, 74, 138, 0.95), rgba(7, 34, 72, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 14px 24px rgba(0,0,0,0.2),
                0 4px 0 rgba(2, 16, 38, 0.78);
            transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
        }

        .matrix-cell-button:hover,
        .matrix-cell-button:focus-visible {
            transform: translateY(-2px);
            border-color: rgba(255, 225, 146, 0.36);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.22),
                0 18px 28px rgba(0,0,0,0.24),
                0 4px 0 rgba(2, 16, 38, 0.78),
                0 0 18px rgba(140, 232, 255, 0.12);
            outline: none;
        }

        .matrix-cell-button:active {
            transform: translateY(4px);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.16),
                0 8px 14px rgba(0,0,0,0.2),
                0 2px 0 rgba(2, 16, 38, 0.82);
        }

        @media (hover: hover) and (pointer: fine) {
            body[data-overview-view="root"] .choice-button {
                transition:
                    transform 0.22s ease,
                    box-shadow 0.22s ease,
                    border-color 0.22s ease,
                    filter 0.22s ease;
            }

            body[data-overview-view="root"] .choice-button:hover {
                transform: translateY(-2px) scale(1.003);
                border-color: rgba(255, 232, 164, 0.88);
                background:
                    radial-gradient(circle at 18% 10%, rgba(255, 240, 184, 0.32), transparent 34%),
                    linear-gradient(145deg, rgba(31, 164, 146, 0.98), rgba(7, 69, 99, 0.99) 62%, rgba(4, 35, 72, 0.99));
                box-shadow:
                    inset 0 1px 0 rgba(255,255,255,0.34),
                    0 24px 38px rgba(0,0,0,0.3),
                    0 5px 0 rgba(3, 39, 55, 0.9),
                    0 0 28px rgba(93, 231, 208, 0.34),
                    0 0 48px rgba(255, 226, 145, 0.15);
            }

            body[data-overview-view="root"] .choice-button:hover .choice-label {
                color: #fff4c7;
                text-shadow: 0 2px 12px rgba(0, 20, 35, 0.48);
            }

            body[data-overview-view^="requirement-"] .matrix-cell-button:hover {
                transform: translateY(-2px);
                border-color: rgba(255, 246, 205, 0.94);
                color: #08284b;
                background:
                    radial-gradient(circle at 24% 14%, rgba(255,255,255,0.62), transparent 31%),
                    linear-gradient(155deg, #ffe89b, #e9aa37 58%, #b96d17);
                box-shadow:
                    inset 0 1px 0 rgba(255,255,255,0.68),
                    0 20px 32px rgba(0,0,0,0.3),
                    0 5px 0 rgba(91, 48, 7, 0.82),
                    0 0 28px rgba(255, 211, 100, 0.4);
            }

            body[data-overview-view^="requirement-"] .matrix-cell-button:hover .matrix-cell-tone,
            body[data-overview-view^="requirement-"] .matrix-cell-button:hover .matrix-cell-score {
                color: #08284b;
                text-shadow: 0 1px 0 rgba(255,255,255,0.34);
            }
        }

        .matrix-cell-tone {
            display: block;
            color: var(--gold-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.9rem;
            font-weight: 900;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            line-height: 1.1;
        }

        .matrix-cell-score {
            display: block;
            margin-top: 7px;
            color: rgba(240, 248, 255, 0.92);
            font-size: 1.08rem;
            font-weight: 900;
            line-height: 1;
        }

        .ai-types-stage {
            position: relative;
            overflow: hidden;
            border-radius: 30px;
            border: 1px solid rgba(186, 232, 255, 0.18);
            background:
                linear-gradient(180deg, rgba(236, 246, 255, 0.95), rgba(217, 235, 249, 0.9)),
                linear-gradient(135deg, rgba(255,255,255,0.28), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.5),
                0 18px 32px rgba(0,0,0,0.22);
            padding: 22px 20px 18px;
            color: #11264a;
        }

        .ai-types-stage::before {
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(rgba(104, 168, 214, 0.12) 1px, transparent 1px),
                linear-gradient(90deg, rgba(104, 168, 214, 0.12) 1px, transparent 1px);
            background-size: 34px 34px;
            opacity: 0.6;
            pointer-events: none;
        }

        .ai-types-stage > * {
            position: relative;
            z-index: 1;
        }

        .ai-types-head {
            margin-bottom: 14px;
        }

        .ai-types-kicker {
            margin: 0 0 8px;
            color: rgba(26, 55, 100, 0.76);
            font-size: 0.76rem;
            font-weight: 900;
            letter-spacing: 0.18em;
            text-transform: uppercase;
        }

        .ai-types-title {
            margin: 0;
            color: #08182f;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.55rem, 2.5vw, 2.45rem);
            font-weight: 900;
            line-height: 1.04;
            letter-spacing: 0.02em;
            text-transform: uppercase;
        }

        .ai-types-copy {
            max-width: 70ch;
            margin: 10px 0 0;
            color: rgba(22, 44, 82, 0.84);
            font-size: 0.9rem;
            line-height: 1.5;
        }

        .ai-types-stack {
            display: grid;
            gap: 12px;
        }

        .ai-type-cluster {
            display: grid;
            grid-template-columns: minmax(148px, 164px) minmax(0, 1fr);
            align-items: center;
            gap: 20px;
        }

        .ai-type-core {
            position: relative;
            width: min(100%, 158px);
            aspect-ratio: 1 / 1;
            display: grid;
            place-items: center;
            margin: 0 auto;
            padding: 14px;
            border-radius: 999px;
            text-align: center;
            color: #ffffff;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.24),
                inset 0 -16px 24px rgba(0,0,0,0.12),
                0 18px 28px rgba(0,0,0,0.18);
        }

        .ai-type-core::after {
            content: "";
            position: absolute;
            inset: 9px;
            border-radius: inherit;
            border: 1px solid rgba(255,255,255,0.18);
            pointer-events: none;
        }

        .ai-type-core.is-traditional {
            background:
                radial-gradient(circle at 28% 20%, rgba(255,255,255,0.18), transparent 28%),
                linear-gradient(180deg, #6c67d7, #4d459f);
        }

        .ai-type-core.is-generative {
            background:
                radial-gradient(circle at 28% 20%, rgba(255,255,255,0.18), transparent 28%),
                linear-gradient(180deg, #48c38f, #29996f);
        }

        .ai-type-core.is-agentic {
            background:
                radial-gradient(circle at 28% 20%, rgba(255,255,255,0.18), transparent 28%),
                linear-gradient(180deg, #cf5cad, #a83c88);
        }

        .ai-type-core-small {
            display: block;
            font-size: 0.72rem;
            font-weight: 800;
            letter-spacing: 0.06em;
            line-height: 1.2;
            text-transform: uppercase;
        }

        .ai-type-core-big {
            display: block;
            margin-top: 5px;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: clamp(1.72rem, 2.35vw, 2.6rem);
            font-weight: 900;
            line-height: 1.02;
            letter-spacing: 0.01em;
            text-transform: uppercase;
        }

        .ai-type-items {
            display: grid;
            gap: 10px;
        }

        .ai-type-item {
            position: relative;
            display: grid;
            grid-template-columns: 52px minmax(0, 1fr);
            gap: 12px;
            align-items: center;
        }

        .ai-type-item::before {
            content: "";
            position: absolute;
            top: 50%;
            left: -32px;
            width: 40px;
            height: 2px;
            border-radius: 999px;
            background: linear-gradient(90deg, rgba(10, 30, 63, 0.88), rgba(10, 30, 63, 0.22));
            transform: translateY(-50%);
        }

        .ai-type-item::after {
            content: "";
            position: absolute;
            top: calc(50% - 4px);
            left: -10px;
            width: 8px;
            height: 8px;
            border-radius: 999px;
            background: currentColor;
            box-shadow: 0 0 0 4px rgba(255,255,255,0.62);
        }

        .ai-type-cluster.is-traditional {
            color: #7067da;
        }

        .ai-type-cluster.is-generative {
            color: #33b784;
        }

        .ai-type-cluster.is-agentic {
            color: #d05fb0;
        }

        .ai-type-icon {
            position: relative;
            z-index: 1;
            width: 52px;
            height: 52px;
            display: grid;
            place-items: center;
            border-radius: 16px;
            color: #ffffff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.76rem;
            font-weight: 900;
            letter-spacing: 0.06em;
            text-transform: uppercase;
            background:
                radial-gradient(circle at 28% 20%, rgba(255,255,255,0.24), transparent 28%),
                linear-gradient(180deg, currentColor, color-mix(in srgb, currentColor 74%, #2d245d 26%));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.24),
                0 12px 20px rgba(0,0,0,0.16);
        }

        .ai-type-item-body {
            padding: 10px 12px 10px 14px;
            border-radius: 18px;
            border: 1px solid rgba(18, 47, 90, 0.1);
            background: rgba(255,255,255,0.76);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.44),
                0 12px 18px rgba(24, 52, 95, 0.08);
        }

        .ai-type-item-head {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 4px;
        }

        .ai-type-number {
            flex: 0 0 auto;
            width: 24px;
            height: 24px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 7px;
            background: rgba(14, 33, 66, 0.92);
            color: #f7fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.76rem;
            font-weight: 900;
            line-height: 1;
        }

        .ai-type-item-title {
            margin: 0;
            color: #122548;
            font-size: 0.94rem;
            font-weight: 900;
            line-height: 1.28;
        }

        .ai-type-item-copy {
            position: relative;
            margin: 0;
            padding-left: 12px;
            color: rgba(24, 47, 85, 0.86);
            font-size: 0.84rem;
            line-height: 1.42;
        }

        .ai-type-item-copy::before {
            content: "•";
            position: absolute;
            left: 0;
            top: 0;
            color: rgba(17, 37, 72, 0.82);
            font-size: 1rem;
            line-height: 1.35;
        }

        .dtap-grid {
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 16px;
        }

        .dtap-stack {
            display: grid;
            gap: 16px;
        }

        .dtap-topbar {
            display: flex;
            justify-content: flex-start;
            align-items: center;
        }

        .dtap-aspects-shell {
            display: grid;
            gap: 16px;
            max-height: 1200px;
            overflow: hidden;
            opacity: 1;
            transform: translateY(0);
            transition:
                max-height 0.62s ease,
                opacity 0.62s ease,
                transform 0.62s ease,
                margin 0.62s ease;
        }

        .dtap-aspects-shell.is-faded {
            max-height: 0;
            margin-top: -16px;
            opacity: 0;
            pointer-events: none;
            transform: translateY(-12px);
        }

        .dtap-aspects-content {
            display: grid;
            gap: 12px;
        }

        .dtap-stage-shell {
            width: min(420px, 100%);
            padding: 14px 16px 15px;
            border: 1px solid rgba(167, 239, 255, 0.22);
            border-radius: 20px;
            background:
                radial-gradient(circle at 12% 0%, rgba(167, 239, 255, 0.12), transparent 34%),
                linear-gradient(155deg, rgba(13, 66, 124, 0.88), rgba(4, 26, 61, 0.94));
            color: var(--text-soft);
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.1),
                0 14px 24px rgba(0,0,0,0.2),
                0 0 18px rgba(115, 220, 255, 0.06);
            --dtap-stage-progress: 0%;
        }

        .dtap-stage-label {
            margin: 0 0 8px;
            color: var(--gold-soft);
            font-size: 0.72rem;
            font-weight: 900;
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .dtap-stage-range {
            width: 100%;
            height: 30px;
            appearance: none;
            -webkit-appearance: none;
            background: transparent;
            cursor: ew-resize;
        }

        .dtap-stage-range::-webkit-slider-runnable-track {
            height: 10px;
            border: 1px solid rgba(167, 239, 255, 0.26);
            border-radius: 999px;
            background:
                linear-gradient(90deg, #76ddeb 0 var(--dtap-stage-progress), rgba(2, 17, 43, 0.84) var(--dtap-stage-progress) 100%);
            box-shadow: inset 0 2px 5px rgba(0,0,0,0.35), 0 0 10px rgba(118, 221, 235, 0.08);
        }

        .dtap-stage-range::-webkit-slider-thumb {
            -webkit-appearance: none;
            width: 24px;
            height: 24px;
            margin-top: -8px;
            border: 2px solid #fff0ba;
            border-radius: 50%;
            background: linear-gradient(145deg, #ffe6a0, #5dcbdc);
            box-shadow: 0 4px 10px rgba(0,0,0,0.3), 0 0 14px rgba(167, 239, 255, 0.25);
        }

        .dtap-stage-range::-moz-range-track {
            height: 10px;
            border: 1px solid rgba(167, 239, 255, 0.26);
            border-radius: 999px;
            background:
                linear-gradient(90deg, #76ddeb 0 var(--dtap-stage-progress), rgba(2, 17, 43, 0.84) var(--dtap-stage-progress) 100%);
            box-shadow: inset 0 2px 5px rgba(0,0,0,0.35), 0 0 10px rgba(118, 221, 235, 0.08);
        }

        .dtap-stage-range::-moz-range-thumb {
            width: 24px;
            height: 24px;
            border: 2px solid #fff0ba;
            border-radius: 50%;
            background: linear-gradient(145deg, #ffe6a0, #5dcbdc);
            box-shadow: 0 4px 10px rgba(0,0,0,0.3), 0 0 14px rgba(167, 239, 255, 0.25);
        }

        .dtap-stage-ticks {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            align-items: center;
            margin-top: 2px;
            color: rgba(220, 241, 252, 0.66);
            font-size: 0.6rem;
            font-weight: 800;
            letter-spacing: 0.04em;
        }

        .dtap-stage-ticks span {
            text-align: center;
        }

        .dtap-stage-panel {
            display: grid;
            gap: 12px;
            padding: 16px 18px;
            border: 1px solid rgba(167, 239, 255, 0.18);
            border-radius: 22px;
            background:
                radial-gradient(circle at 8% 0%, rgba(167, 239, 255, 0.1), transparent 32%),
                linear-gradient(155deg, rgba(10, 54, 105, 0.88), rgba(4, 25, 58, 0.94));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 14px 24px rgba(0,0,0,0.18);
        }

        .dtap-stage-copy {
            margin: 0;
            color: rgba(232, 246, 255, 0.84);
            font-size: 0.9rem;
            line-height: 1.5;
        }

        .dtap-stage-emphasis {
            color: var(--gold-soft);
            font-weight: 900;
        }

        .dtap-expansion-grid {
            display: grid;
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 16px;
        }

        .dtap-expansion-card,
        .dtap-expansion-spacer {
            min-height: 92px;
            border-radius: 22px;
        }

        .dtap-expansion-card {
            padding: 14px 14px 12px;
            border: 1px solid rgba(167, 239, 255, 0.16);
            border-radius: 18px;
            background: linear-gradient(150deg, rgba(18, 74, 132, 0.7), rgba(4, 27, 63, 0.9));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.07),
                0 10px 18px rgba(0,0,0,0.14);
        }

        .dtap-expansion-title {
            margin: 0 0 8px;
            color: var(--cyan-soft);
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.8rem;
            font-weight: 700;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            line-height: 1.1;
        }

        .dtap-expansion-copy {
            margin: 0;
            color: rgba(224, 242, 253, 0.78);
            font-size: 0.8rem;
            line-height: 1.45;
        }

        .dtap-expansion-spacer {
            visibility: hidden;
            pointer-events: none;
        }

        .dtap-column {
            display: grid;
            gap: 14px;
            grid-template-rows: auto 1fr;
            gap: 0;
            padding: 3px;
            border-radius: 0;
            border-top: 2px solid #ffffff;
            border-left: 2px solid #ffffff;
            border-right: 2px solid #404040;
            border-bottom: 2px solid #404040;
            background: #c0c0c0;
            box-shadow:
                inset -1px -1px 0 #808080,
                inset 1px 1px 0 #dfdfdf,
                0 16px 28px rgba(0,0,0,0.2);
            font-family: "MS Sans Serif", Tahoma, Verdana, sans-serif;
        }

        .dtap-head {
            position: relative;
            display: grid;
            align-content: start;
            gap: 1px;
            min-height: 48px;
            padding: 5px 54px 5px 8px;
            background: linear-gradient(90deg, #000080, #1084d0);
        }

        .dtap-head::before,
        .dtap-head::after {
            content: "";
            position: absolute;
            top: 7px;
            width: 15px;
            height: 14px;
            background: #c0c0c0;
            border-top: 2px solid #ffffff;
            border-left: 2px solid #ffffff;
            border-right: 2px solid #404040;
            border-bottom: 2px solid #404040;
            box-shadow: inset -1px -1px 0 #808080;
        }

        .dtap-head::before {
            right: 25px;
        }

        .dtap-head::after {
            right: 6px;
        }

        .dtap-version {
            margin: 0;
            color: #ffffff;
            font-family: "MS Sans Serif", Tahoma, Verdana, sans-serif;
            font-size: 0.88rem;
            font-weight: 700;
            letter-spacing: 0;
            text-transform: none;
            line-height: 1.04;
        }

        .dtap-environment {
            margin: 0;
            color: #ffffff;
            font-size: 0.72rem;
            line-height: 1.24;
            letter-spacing: 0;
        }

        .dtap-form {
            display: grid;
            align-content: start;
            gap: 8px;
            padding: 12px 10px 10px;
        }

        .dtap-input {
            width: 100%;
            height: 36px;
            padding: 7px 8px;
            border-top: 2px solid #808080;
            border-left: 2px solid #808080;
            border-right: 2px solid #ffffff;
            border-bottom: 2px solid #ffffff;
            border-radius: 0;
            color: #000000;
            font-family: "MS Sans Serif", Tahoma, Verdana, sans-serif;
            font-size: 0.86rem;
            background: #ffffff;
            box-shadow: inset 1px 1px 0 #404040;
        }

        .dtap-input.is-seeded {
            color: #808080;
        }

        .dtap-input:focus {
            outline: none;
            border-color: inherit;
            box-shadow:
                inset 1px 1px 0 #404040,
                0 0 0 2px #000080;
        }

        .dtap-input-spacer {
            width: 100%;
            height: 36px;
            border-radius: 0;
            visibility: hidden;
            pointer-events: none;
        }

        .dtap-submit {
            width: 100%;
            height: 36px;
            border-top: 2px solid #ffffff;
            border-left: 2px solid #ffffff;
            border-right: 2px solid #404040;
            border-bottom: 2px solid #404040;
            border-radius: 0;
            cursor: pointer;
            color: #000000;
            font-family: "MS Sans Serif", Tahoma, Verdana, sans-serif;
            font-size: 0.86rem;
            font-weight: 700;
            letter-spacing: 0;
            text-transform: none;
            background: #c0c0c0;
            box-shadow:
                inset -1px -1px 0 #808080,
                inset 1px 1px 0 #dfdfdf;
            transition: transform 0.08s ease, box-shadow 0.08s ease;
        }

        .dtap-submit:hover,
        .dtap-submit:focus-visible {
            transform: none;
            box-shadow:
                inset -1px -1px 0 #808080,
                inset 1px 1px 0 #dfdfdf,
                0 0 0 1px #000000;
            outline: none;
        }

        .dtap-submit:active {
            transform: translate(1px, 1px);
            border-top-color: #404040;
            border-left-color: #404040;
            border-right-color: #ffffff;
            border-bottom-color: #ffffff;
            box-shadow:
                inset 1px 1px 0 #808080,
                inset -1px -1px 0 #dfdfdf;
        }

        .dive-deeper-shell {
            justify-self: end;
            width: auto;
            max-width: min(250px, 100%);
            margin-top: 8px;
        }

        .dive-deeper-panel {
            border-radius: 18px;
            border: 1px solid rgba(231, 196, 151, 0.18);
            background:
                linear-gradient(180deg, rgba(42, 36, 33, 0.96), rgba(19, 16, 15, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.08),
                0 12px 20px rgba(0,0,0,0.24);
            overflow: hidden;
        }

        .dive-deeper-summary {
            list-style: none;
            position: relative;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-height: 38px;
            min-width: 38px;
            padding: 7px;
            cursor: pointer;
            color: #dfc7a3;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.68rem;
            font-weight: 900;
            letter-spacing: 0.14em;
            text-transform: uppercase;
            user-select: none;
        }

        .dive-deeper-summary::-webkit-details-marker {
            display: none;
        }

        .dive-deeper-summary-text {
            position: absolute;
            top: calc(100% + 6px);
            right: 0;
            padding: 5px 8px 6px;
            border-radius: 999px;
            border: 1px solid rgba(239, 221, 190, 0.34);
            background:
                linear-gradient(180deg, rgba(75, 66, 58, 0.98), rgba(35, 30, 27, 0.99)),
                linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0));
            color: #fff4dc;
            white-space: nowrap;
            font-size: 0.62rem;
            line-height: 1;
            letter-spacing: 0.16em;
            opacity: 0;
            transform: translateY(-4px);
            pointer-events: none;
            transition: opacity 0.18s ease, transform 0.18s ease;
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.06),
                0 8px 14px rgba(0,0,0,0.2);
        }

        .dive-deeper-summary:hover .dive-deeper-summary-text,
        .dive-deeper-summary:focus-visible .dive-deeper-summary-text {
            opacity: 1;
            transform: translateY(0);
        }

        .dive-deeper-summary-icon {
            width: 22px;
            height: 22px;
            flex: 0 0 auto;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 999px;
            color: #f6efe4;
            background:
                radial-gradient(circle at 28% 22%, rgba(255,255,255,0.2), transparent 28%),
                linear-gradient(180deg, rgba(207, 160, 93, 0.94), rgba(95, 62, 28, 0.98));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.18),
                0 6px 10px rgba(0,0,0,0.22);
            transition: transform 0.18s ease;
        }

        .dive-deeper-panel[open] .dive-deeper-summary-icon {
            transform: rotate(90deg);
        }

        .dive-deeper-body {
            min-width: 214px;
            padding: 0 10px 10px;
            display: grid;
            gap: 6px;
            background:
                linear-gradient(180deg, rgba(58, 49, 43, 0.28), rgba(19, 16, 15, 0));
        }

        .dive-deeper-list {
            display: grid;
            gap: 6px;
        }

        .dive-deeper-link {
            display: grid;
            grid-template-columns: 24px minmax(0, 1fr);
            align-items: start;
            gap: 7px;
            color: rgba(249, 240, 226, 0.98);
            text-decoration: none;
            font-size: 0.76rem;
            line-height: 1.4;
        }

        .dive-deeper-link:hover,
        .dive-deeper-link:focus-visible {
            color: #fff0cb;
            outline: none;
        }

        .dive-deeper-link-index {
            width: 24px;
            height: 24px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            border-radius: 999px;
            color: #f6fbff;
            font-family: "Bahnschrift SemiCondensed", "Trebuchet MS", sans-serif;
            font-size: 0.74rem;
            font-weight: 900;
            letter-spacing: 0.04em;
            background:
                linear-gradient(180deg, rgba(149, 110, 66, 0.96), rgba(65, 45, 24, 0.98)),
                linear-gradient(135deg, rgba(255,255,255,0.14), rgba(255,255,255,0));
            box-shadow:
                inset 0 1px 0 rgba(255,255,255,0.14),
                0 6px 10px rgba(0,0,0,0.14);
        }

        .dive-deeper-link-text {
            min-width: 0;
            color: inherit;
            text-shadow: 0 1px 0 rgba(0,0,0,0.24);
        }

        .dive-deeper-empty {
            margin: 0;
            color: rgba(245, 236, 222, 0.8);
            font-size: 0.72rem;
            line-height: 1.5;
        }

        @media (max-width: 900px) {
            .seo-ai-grid {
                grid-template-columns: 1fr;
            }

            .seo-ai-summary {
                border-radius: 24px;
                padding: 20px 16px;
            }

            .page-rating-shell {
                width: 100%;
                min-height: 168px;
                grid-template-columns: minmax(0, 1fr) auto;
                gap: 12px;
                margin-top: 14px;
                border-radius: 20px;
                padding: 14px;
            }

            .page-rating-shell.is-collapsed {
                width: 54px;
                height: 54px;
                max-height: 54px;
                min-height: 54px;
                grid-template-columns: 1fr;
                gap: 0;
                margin-left: auto;
                border-radius: 17px;
                padding: 0;
            }

            .page-rating-launcher {
                padding: 15px;
            }

            .page-rating-control {
                grid-template-columns: 39px 34px;
                gap: 6px 4px;
            }

            .page-rating-thumb {
                width: 39px;
                height: 39px;
                border-radius: 12px;
