            .guide-window {
                width: 100%;
                max-height: calc(100dvh - 18px);
                border-radius: 22px;
            }

            .guide-window-head {
                grid-template-columns: 38px minmax(0, 1fr) 40px;
                gap: 9px;
                padding: 14px 12px 13px 15px;
            }

            .guide-window-head .guide-document-icon {
