                height: 38px;
            }

            .analytics-dashboard-title {
                overflow: visible;
                font-size: clamp(1rem, 4.8vw, 1.28rem);
                letter-spacing: 0.07em;
                line-height: 1.02;
                text-overflow: clip;
                white-space: normal;
            }

            .analytics-dashboard-title-desktop {
                display: none;
            }

            .analytics-dashboard-title-mobile {
                display: inline;
            }

            .analytics-dashboard-live {
                display: none;
            }

            .analytics-dashboard-logout {
                min-height: 36px;
                padding: 0 9px;
                font-size: 0.52rem;
            }

            .analytics-dashboard-ga4-link {
