                border-width: 2px;
                box-shadow:
                    0 0 0 5px rgba(167, 239, 255, 0.08),
                    0 12px 22px rgba(0,0,0,0.22),
                    inset 0 1px 0 rgba(255,255,255,0.28);
            }

            .testcase-bridge-dot.is-finish {
                box-shadow:
                    0 0 0 5px rgba(255, 229, 162, 0.08),
                    0 12px 22px rgba(0,0,0,0.22),
