            .testcase-bridge-arrow-track {
                height: 22px;
            }

            .testcase-bridge-arrow-track::after {
                right: -20px;
                border-top-width: 19px;
                border-bottom-width: 19px;
                border-left-width: 24px;
            }

            .testcase-bridge-arrow-label {
                font-size: 0.8rem;
                letter-spacing: 0.07em;
                padding: 9px 11px;
            }

            .testcase-bridge-bug-route {
