                font-size: clamp(1.15rem, 4vw, 1.65rem);
            }

            .structured-chaos-label.is-left,
            .structured-chaos-label.is-right {
                bottom: 12%;
                font-size: clamp(1.15rem, 4.7vw, 1.8rem);
            }

            .structured-chaos-label.is-right {
                right: 1%;
            }

            .structured-chaos-message {
                width: min(100%, calc(100% - 20px));
                min-height: 4.3em;
                margin: 4px auto 10px;
                font-size: 0.98rem;
                line-height: 1.5;
            }

            .structured-chaos-slider-stack {
                gap: 10px;
            }

            .structured-chaos-fader-shell {
                width: min(100%, calc(100% - 16px));
                padding: 10px 12px 14px;
            }

            .structured-chaos-slider {
                height: 48px;
            }

            .structured-chaos-slider::-webkit-slider-thumb {
                width: 28px;
                height: 48px;
                margin-top: -20px;
            }

            .structured-chaos-slider::-moz-range-thumb {
                width: 28px;
                height: 48px;
            }

            .dtap-grid {
                grid-template-columns: 1fr;
                gap: 12px;
            }

            .dtap-topbar {
                justify-content: stretch;
            }

            .dtap-stage-shell {
                width: 100%;
                padding: 13px 14px 14px;
            }

            .dtap-stage-panel {
                padding: 14px 14px 12px;
                border-radius: 18px;
            }

            .dtap-stage-copy {
                font-size: 0.88rem;
            }

            .dtap-expansion-grid {
                grid-template-columns: 1fr;
                gap: 10px;
            }

            .dtap-expansion-card,
            .dtap-expansion-spacer {
                min-height: 0;
            }

            .dtap-expansion-spacer {
                display: none;
            }

            .dtap-column {
                padding: 3px;
                border-radius: 0;
            }

            .dtap-head {
                min-height: 0;
            }

            .dtap-input {
                width: 100%;
                height: 36px;
            }

            .dtap-input-spacer {
                height: 36px;
            }

            .dtap-submit {
                width: 100%;
                height: 36px;
            }

            .dive-deeper-shell {
                width: auto;
                max-width: min(220px, 100%);
            }

            .dive-deeper-summary {
                min-height: 34px;
                min-width: 34px;
                padding: 6px;
                font-size: 0.62rem;
            }

            .dive-deeper-body {
                min-width: 188px;
                padding: 0 9px 9px;
            }

            .dive-deeper-link {
                font-size: 0.72rem;
            }

            .matrix-frame {
                padding: 16px 14px 14px;
                border-radius: 22px;
            }

            .matrix-note {
                font-size: 0.82rem;
            }

            .matrix-mobile-hint {
                display: block;
            }

            .matrix-scroll {
                margin: 0 -4px;
                padding: 0 4px 10px;
            }

            .matrix-table {
                min-width: 640px;
                border-spacing: 4px;
            }

            .info-table {
                min-width: 620px;
            }

            .matrix-corner,
            .matrix-axis {
                padding: 8px 6px;
                border-radius: 14px;
            }

            .matrix-corner,
            .matrix-axis-title {
                font-size: 0.68rem;
                letter-spacing: 0.05em;
            }

            .matrix-axis-subtitle {
                margin-top: 4px;
                font-size: 0.62rem;
            }

            .matrix-row-label {
                min-width: 86px;
                padding: 10px 6px;
                border-radius: 14px;
            }

            .matrix-row-score {
                font-size: 0.92rem;
            }

            .matrix-row-text {
                margin-top: 4px;
                font-size: 0.62rem;
                letter-spacing: 0.04em;
            }

            .matrix-cell-button {
                min-height: 72px;
                padding: 10px 6px;
                border-radius: 16px;
            }

            .matrix-cell-tone {
                font-size: 0.66rem;
                letter-spacing: 0.05em;
            }

            .matrix-cell-score {
                margin-top: 5px;
                font-size: 0.88rem;
            }

            .edit-builder {
                grid-template-columns: 1fr;
            }

            .edit-builder-submit {
                width: 100%;
            }

            .edit-panel-head {
                flex-direction: column;
            }

            .ai-types-stage {
                padding: 18px 14px 16px;
                border-radius: 24px;
            }

            .ai-types-stage::before {
                background-size: 24px 24px;
            }

            .ai-types-head {
                margin-bottom: 12px;
            }

            .ai-types-title {
                font-size: clamp(1.38rem, 6vw, 2.05rem);
                line-height: 1.06;
            }

            .ai-types-copy {
                font-size: 0.84rem;
            }

            .ai-type-cluster {
                grid-template-columns: 1fr;
                gap: 12px;
            }

            .ai-type-core {
                width: min(100%, 136px);
            }

            .ai-type-items {
                gap: 8px;
            }

            .ai-type-item {
                grid-template-columns: 44px minmax(0, 1fr);
                gap: 8px;
            }

            .ai-type-item::before {
                left: -10px;
                width: 22px;
            }

            .ai-type-item::after {
                left: 8px;
            }

            .ai-type-icon {
                width: 44px;
                height: 44px;
                border-radius: 16px;
                font-size: 0.68rem;
            }

            .ai-type-item-body {
                padding: 10px 10px 10px 12px;
                border-radius: 18px;
            }

            .ai-type-item-head {
                gap: 8px;
                margin-bottom: 5px;
            }

            .ai-type-number {
                width: 22px;
                height: 22px;
                border-radius: 7px;
                font-size: 0.72rem;
            }

            .ai-type-item-title {
                font-size: 0.88rem;
            }

            .ai-type-item-copy {
                font-size: 0.78rem;
            }
        }
    </style>
</head>
<body>
    <div class="root-journey-scene" aria-hidden="true">
        <div class="root-journey-sky"></div>
        <span class="root-journey-sun"></span>
        <span class="root-journey-horizon"></span>
        <span class="root-journey-road"></span>
        <svg class="root-journey-route-map" viewBox="0 0 1000 720" preserveAspectRatio="none" focusable="false">
            <path id="rootJourneyRoute" class="root-journey-route-line" d="M 40 650 C 150 600, 100 470, 260 430 S 420 535, 505 354 S 645 190, 740 255 S 860 190, 965 68"></path>
            <circle class="root-journey-traveller" r="5">
                <animateMotion dur="10s" repeatCount="indefinite" rotate="auto">
                    <mpath href="#rootJourneyRoute"></mpath>
                </animateMotion>
            </circle>
        </svg>
        <span class="root-journey-film-rail is-left"></span>
        <span class="root-journey-film-rail is-right"></span>
        <span class="root-journey-waypoint is-explore">Explore</span>
        <span class="root-journey-waypoint is-discover">Discover</span>
        <span class="root-journey-animation-badge">
            <span>&#9654;</span>
            <span><strong>Animated tour</strong><small>Keyframes in motion</small></span>
        </span>
    </div>
    <div class="root-journey-gates" aria-hidden="true">
        <span class="root-journey-door is-left"><span class="root-journey-door-copy">Welcome</span></span>
        <span class="root-journey-door is-right"><span class="root-journey-door-copy">Explorer</span></span>
    </div>
    <main class="page-shell">
        <section class="overview-card" aria-live="polite">
            <div class="overview-header">
                <div class="overview-title-wrap">
                    <p class="overview-kicker">Knowledge map</p>
                    <h1 id="viewTitle" class="overview-title">Test overview</h1>
                    <p id="viewBreadcrumb" class="overview-breadcrumb">Choose a direction to continue.</p>
                </div>
                <div class="overview-header-actions">
                    <button id="editModeToggle" class="edit-mode-toggle" type="button" aria-pressed="false" aria-label="Toggle edit mode">
                        <span id="editModeToggleLabel" class="edit-mode-toggle-label">View modus</span>
                        <span class="edit-mode-toggle-track" aria-hidden="true">
                            <span class="edit-mode-toggle-knob"></span>
                        </span>
                    </button>
                    <div class="narration-control">
                        <button id="autoplayToggle" class="autoplay-toggle" type="button" aria-pressed="false" aria-label="Autoplay narration off">
                            <span class="autoplay-toggle-label">Autoplay</span>
                            <span class="autoplay-toggle-track" aria-hidden="true">
                                <span class="autoplay-toggle-knob"></span>
                            </span>
                        </button>
                        <button id="narrationButton" class="narration-button" type="button" aria-pressed="false" aria-label="Page narration unavailable" disabled>
                            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                                <path fill="currentColor" d="M4.5 9.3h3.2l4-3.1c.55-.42 1.33-.03 1.33.66v10.24c0 .69-.78 1.08-1.33.66l-4-3.08H4.5c-.47 0-.85-.38-.85-.85v-3.7c0-.47.38-.85.85-.85Z"/>
                                <path fill="currentColor" d="M16.2 9.2c0-.66.73-1.06 1.3-.7l4.1 2.64a.83.83 0 0 1 0 1.4l-4.1 2.64a.83.83 0 0 1-1.3-.7V9.2Z"/>
                            </svg>
                        </button>
                    </div>
                    <button id="backButton" class="back-button" type="button" hidden aria-label="Go back one level. Hold for two seconds to return to the first page.">
                        <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                            <path fill="currentColor" d="M14.72 5.47a.85.85 0 0 1 0 1.2L10.25 11.1h8.11a.85.85 0 1 1 0 1.7h-8.1l4.46 4.43a.85.85 0 1 1-1.2 1.2l-5.9-5.88a.85.85 0 0 1 0-1.2l5.9-5.88a.85.85 0 0 1 1.2 0Z"/>
                        </svg>
                    </button>
                </div>
            </div>
            <div id="overviewContent" class="overview-content"></div>
        </section>
        <section id="pageRatingShell" class="page-rating-shell is-collapsed" aria-labelledby="pageRatingTitle">
            <button id="pageRatingLauncher" class="page-rating-launcher" type="button" aria-expanded="false" aria-controls="pageRatingPanel" aria-label="Open page rating">
                <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                    <path fill="currentColor" d="M2 21h4V9H2v12Zm20-10.8c0-1.1-.9-2-2-2h-6.3l.9-4.4.03-.3c0-.4-.17-.8-.44-1.1L13.1 1.3 6.5 7.9C6.2 8.2 6 8.7 6 9.2V19c0 1.1.9 2 2 2h9c.8 0 1.5-.5 1.8-1.2l3-7c.1-.2.2-.5.2-.8v-1.8Z"/>
                </svg>
            </button>
            <button id="pageRatingCollapse" class="page-rating-collapse" type="button" aria-label="Collapse page rating">&times;</button>
            <div class="page-rating-copy">
                <p class="page-rating-kicker">Your signal</p>
                <h2 id="pageRatingTitle" class="page-rating-title">Rate this page</h2>
                <p id="pageRatingPageName" class="page-rating-page-name">Test overview</p>
                <p id="pageRatingReadout" class="page-rating-readout">Choose a thumb</p>
                <button id="pageRatingSubmit" class="page-rating-submit" type="button" disabled>Save rating</button>
                <p id="pageRatingStatus" class="page-rating-status" aria-live="polite"></p>
            </div>
            <div id="pageRatingPanel" class="page-rating-control">
                <button id="pageRatingUp" class="page-rating-thumb is-up" type="button" aria-pressed="false" aria-label="Rate this page thumbs up">
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                        <path fill="currentColor" d="M2 21h4V9H2v12Zm20-10.8c0-1.1-.9-2-2-2h-6.3l.9-4.4.03-.3c0-.4-.17-.8-.44-1.1L13.1 1.3 6.5 7.9C6.2 8.2 6 8.7 6 9.2V19c0 1.1.9 2 2 2h9c.8 0 1.5-.5 1.8-1.2l3-7c.1-.2.2-.5.2-.8v-1.8Z"/>
                    </svg>
                </button>
                <div class="page-rating-rail">
                    <span id="pageRatingTopLimit" class="page-rating-limit">5</span>
                    <input id="pageRatingRange" class="page-rating-range" type="range" min="1" max="5" step="1" value="3" orient="vertical" disabled aria-label="Rating strength from 1 to 5">
                    <span id="pageRatingBottomLimit" class="page-rating-limit">1</span>
                </div>
                <button id="pageRatingDown" class="page-rating-thumb is-down" type="button" aria-pressed="false" aria-label="Rate this page thumbs down">
                    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                        <path fill="currentColor" d="M2 21h4V9H2v12Zm20-10.8c0-1.1-.9-2-2-2h-6.3l.9-4.4.03-.3c0-.4-.17-.8-.44-1.1L13.1 1.3 6.5 7.9C6.2 8.2 6 8.7 6 9.2V19c0 1.1.9 2 2 2h9c.8 0 1.5-.5 1.8-1.2l3-7c.1-.2.2-.5.2-.8v-1.8Z"/>
                    </svg>
                </button>
            </div>
        </section>
        <section id="about-test-overview" class="seo-ai-summary" data-ai-readable="true" aria-labelledby="aboutTestOverviewTitle">
            <p class="seo-ai-kicker">AI readable field note</p>
            <h2 id="aboutTestOverviewTitle" class="seo-ai-title">About this interactive software testing overview</h2>
            <p class="seo-ai-copy">
                Test Overview is an interactive Codex experiment and software testing knowledge map. It helps testers, QA professionals, test managers, business analysts and software teams explore how requirements, test environments, testing mindsets, tacit and explicit knowledge, test techniques, automation and complexity influence each other.
            </p>
            <div class="seo-ai-grid" aria-label="What this test overview explains">
                <article class="seo-ai-card">
                    <h3>Purpose</h3>
                    <p>Make the hidden relationships in software testing visible, instead of treating test cases, requirements and automation as isolated topics.</p>
                </article>
                <article class="seo-ai-card">
                    <h3>Core topics</h3>
                    <p>Requirement categories, DTAP, priority, tacit versus explicit knowledge, structured chaos, connected test techniques and re-testing complexity.</p>
                </article>
                <article class="seo-ai-card">
                    <h3>How to share</h3>
                    <p>Use direct URLs with a value parameter, for example <strong>?value=requirement</strong>, <strong>?value=dtap</strong> or <strong>?value=connectedtesttechniques</strong>.</p>
                </article>
            </div>
            <div id="faq" class="seo-ai-faq" aria-label="Frequently asked questions">
                <details open>
                    <summary>What is Test Overview?</summary>
                    <p>Test Overview is an interactive software testing knowledge map that shows how requirements, environments, testing mindsets, tacit and explicit knowledge, test techniques, automation choices and complexity connect.</p>
                </details>
                <details>
                    <summary>Who is it for?</summary>
                    <p>It is designed for software testers, QA professionals, test managers, business analysts and software teams who want to discuss testing as a connected professional discipline.</p>
                </details>
                <details>
                    <summary>Which techniques are included?</summary>
                    <p>The page references techniques and perspectives such as decision table testing, boundary value analysis, equivalence partitioning, functional testing, software testing versus automation, and knowledge-based testing.</p>
                </details>
                <details>
                    <summary>Why does the page include audio and sliders?</summary>
                    <p>The narration, sliders and animations make abstract testing concepts more concrete, so visitors can explore how a change in mindset, environment, requirement or test technique changes the testing conversation.</p>
                </details>
            </div>
        </section>
    </main>

    <script>
        const backButton = document.getElementById('backButton');
        const editModeToggle = document.getElementById('editModeToggle');
        const editModeToggleLabel = document.getElementById('editModeToggleLabel');
        const autoplayToggle = document.getElementById('autoplayToggle');
        const narrationButton = document.getElementById('narrationButton');
        const viewTitle = document.getElementById('viewTitle');
        const viewBreadcrumb = document.getElementById('viewBreadcrumb');
        const overviewContent = document.getElementById('overviewContent');
        const pageRatingShell = document.getElementById('pageRatingShell');
        const pageRatingLauncher = document.getElementById('pageRatingLauncher');
        const pageRatingCollapse = document.getElementById('pageRatingCollapse');
        const pageRatingPageName = document.getElementById('pageRatingPageName');
        const pageRatingReadout = document.getElementById('pageRatingReadout');
        const pageRatingStatus = document.getElementById('pageRatingStatus');
        const pageRatingUp = document.getElementById('pageRatingUp');
        const pageRatingDown = document.getElementById('pageRatingDown');
        const pageRatingRange = document.getElementById('pageRatingRange');
        const pageRatingTopLimit = document.getElementById('pageRatingTopLimit');
        const pageRatingBottomLimit = document.getElementById('pageRatingBottomLimit');
        const pageRatingSubmit = document.getElementById('pageRatingSubmit');
        const seoAiSummary = document.getElementById('about-test-overview');
        const EDIT_MODE_STORAGE_KEY = 'testoverview-edit-mode-v1';
        const CUSTOM_OVERVIEW_STORAGE_KEY = 'testoverview-custom-overview-v1';
        const DTAP_THEME_STORAGE_KEY = 'testoverview-dtap-theme-v1';
        const DTAP_STAGE_STORAGE_KEY = 'testoverview-dtap-stage-v1';
        const NARRATION_AUTOPLAY_STORAGE_KEY = 'testoverview-narration-autoplay-v1';
        const ANALYTICS_VISITOR_STORAGE_KEY = 'testoverview-analytics-visitor-v1';
        const ANALYTICS_SESSION_STORAGE_KEY = 'testoverview-analytics-session-v1';
        const ANALYTICS_SESSION_STARTED_STORAGE_KEY = 'testoverview-analytics-started-v1';
        const ANALYTICS_SEQUENCE_STORAGE_KEY = 'testoverview-analytics-sequence-v1';
        const ANALYTICS_ENDPOINT = 'testoverview-track.php';
        const PAGE_RATING_ENDPOINT = 'testoverview-rate.php';
        const PAGE_RATING_STORAGE_KEY = 'testoverview-page-ratings-v1';
        const ANALYTICS_APPLICATION_KEY = 'test_overview';
        const ANALYTICS_BATCH_SIZE = 25;
        const ANALYTICS_FLUSH_DELAY_MS = 800;
        const ANALYTICS_HEARTBEAT_INTERVAL_MS = 30000;
        const ANALYTICS_HEARTBEAT_MAX_DELTA_SECONDS = 45;
        const ANALYTICS_DASHBOARD_TOKEN_STORAGE_KEY = 'testoverview-dashboard-token-v1';
        const ANALYTICS_DASHBOARD_HOLD_MS = 5000;
        const ANALYTICS_DASHBOARD_HOLD_REVEAL_MS = 1000;
        const ANALYTICS_DASHBOARD_LAUNCH_SPIN_MS = 2400;
        const BACK_TO_START_HOLD_MS = 2000;
        const BACK_TO_START_LAUNCH_MS = 1050;
        const supportsSpeechSynthesis = typeof window !== 'undefined'
            && 'speechSynthesis' in window
            && typeof window.SpeechSynthesisUtterance === 'function';
        const INTRO_GUIDE_FADE_DELAY_MS = 15000;
        const AI_FIELD_NOTE_FADE_DELAY_MS = 5000;
        const DEEP_LINK_NAVIGATOR_FADE_DELAY_MS = 5000;
        const EDIT_MODE_INTRO_FADE_DELAY_MS = 10000;
        const GA4_MEASUREMENT_ID = window.testOverviewGa4MeasurementId || 'G-NQ7JFWBNXP';
        const GA4_TRACKING_ENABLED = Boolean(window.testOverviewGa4Enabled && typeof window.gtag === 'function');
        const GA4_EVENT_NAME_MAP = Object.freeze({
            click: 'testoverview_click',
            control_change: 'testoverview_control_change',
            audio_start: 'testoverview_audio_start',
            audio_pause: 'testoverview_audio_pause',
            audio_resume: 'testoverview_audio_resume',
            audio_stop: 'testoverview_audio_stop',
            audio_complete: 'testoverview_audio_complete',
            audio_error: 'testoverview_audio_error',
            audio_autoplay_toggle: 'testoverview_autoplay_toggle'
        });

        let activeNarrationText = '';
        let narrationVoicesPromise = null;
        let cachedNarrationVoice = null;
        let narrationLastVoiceName = '';
        let narrationPlaybackToken = 0;
        let narrationState = 'idle';
        let continueNarrationPlayback = null;
        let narrationAnalyticsPlayback = null;

        const analyticsCanSend = window.location.protocol !== 'file:'
            && !window.location.pathname.toLowerCase().endsWith('.html');
        let analyticsRuntimeEnabled = analyticsCanSend;
        let analyticsQueue = [];
        let analyticsFlushTimer = null;
        let analyticsRequestInFlight = false;
        let analyticsRetryDelayMs = 0;
        let analyticsLastError = '';
        let analyticsLastRenderedViewKey = null;
        let analyticsHeartbeatTimer = null;
        let analyticsActivePeriodStartedAt = document.visibilityState === 'visible' ? Date.now() : null;
        let ga4LastPageLocation = GA4_TRACKING_ENABLED ? window.location.href : '';

        function createAnalyticsId() {
            if (window.crypto && typeof window.crypto.randomUUID === 'function') {
                return window.crypto.randomUUID();
            }
            return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
                const randomValue = Math.floor(Math.random() * 16);
                const value = character === 'x' ? randomValue : ((randomValue & 0x3) | 0x8);
                return value.toString(16);
            });
        }

        function getStoredAnalyticsValue(storage, key, fallbackFactory) {
            try {
                const storedValue = storage.getItem(key);
                if (storedValue) {
                    return storedValue;
                }
                const newValue = fallbackFactory();
                storage.setItem(key, newValue);
                return newValue;
            } catch (error) {
                return fallbackFactory();
            }
        }

        const analyticsVisitorId = getStoredAnalyticsValue(
            window.localStorage,
            ANALYTICS_VISITOR_STORAGE_KEY,
            createAnalyticsId
        );
        const analyticsSessionId = getStoredAnalyticsValue(
            window.sessionStorage,
            ANALYTICS_SESSION_STORAGE_KEY,
            createAnalyticsId
        );
        const analyticsSessionStartedAt = getStoredAnalyticsValue(
            window.sessionStorage,
            ANALYTICS_SESSION_STARTED_STORAGE_KEY,
            () => new Date().toISOString()
        );
        let analyticsEventSequence = (() => {
            try {
                return Math.max(0, Number(window.sessionStorage.getItem(ANALYTICS_SEQUENCE_STORAGE_KEY)) || 0);
            } catch (error) {
                return 0;
            }
        })();

        function analyticsText(value, maximumLength = 255) {
            return String(value || '')
                .replace(/\s+/g, ' ')
                .trim()
                .slice(0, maximumLength);
        }

        function analyticsSlug(value) {
            return analyticsText(value, 120)
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, '-')
                .replace(/^-+|-+$/g, '')
                .slice(0, 100);
        }

        function getAnalyticsDeviceType() {
            if (window.innerWidth <= 640) return 'mobile';
            if (window.innerWidth <= 1024) return 'tablet';
            return 'desktop';
        }

        function consumeAnalyticsActiveSeconds(continueTracking) {
            const now = Date.now();
            if (analyticsActivePeriodStartedAt === null) {
                analyticsActivePeriodStartedAt = continueTracking ? now : null;
                return 0;
            }
            const elapsedSeconds = Math.max(0, Math.round((now - analyticsActivePeriodStartedAt) / 1000));
            analyticsActivePeriodStartedAt = continueTracking ? now : null;
            return Math.min(elapsedSeconds, ANALYTICS_HEARTBEAT_MAX_DELTA_SECONDS);
        }

        function getAnalyticsPageValue() {
            return analyticsText(new URLSearchParams(window.location.search).get('value') || '', 120);
        }

        function getAnalyticsReferrerPath() {
            if (!document.referrer) {
                return '';
            }
            try {
                const referrerUrl = new URL(document.referrer);
                return referrerUrl.origin === window.location.origin
                    ? `${referrerUrl.pathname}${referrerUrl.search}`
                    : referrerUrl.origin;
            } catch (error) {
                return '';
            }
        }

        function getAnalyticsHref(element) {
            if (!(element instanceof HTMLAnchorElement) || !element.href) {
                return '';
            }
            try {
                const url = new URL(element.href, window.location.href);
                return url.origin === window.location.origin
                    ? `${url.pathname}${url.search}`
                    : `${url.origin}${url.pathname}`;
            } catch (error) {
                return '';
            }
        }

        function cleanGa4Parameters(parameters) {
            return Object.fromEntries(Object.entries(parameters).filter(([, value]) => (
                value !== undefined
                && value !== null
                && value !== ''
            )));
        }

        function sendGa4Event(eventName, parameters = {}) {
            if (!GA4_TRACKING_ENABLED) {
                return;
            }
            window.gtag('event', eventName, {
                send_to: GA4_MEASUREMENT_ID,
                ...cleanGa4Parameters(parameters)
            });
        }

        function getGa4PageFile() {
            const pageFile = window.location.pathname.split('/').filter(Boolean).pop();
            return pageFile || 'index';
        }

        function recordGa4VirtualPageView(viewKey) {
            if (!GA4_TRACKING_ENABLED || !overviewTree[viewKey]) {
                return;
            }
            const view = getViewDefinition(viewKey) || overviewTree.root;
            const url = new URL(window.location.href);
            const pageLocation = url.toString();
            if (ga4LastPageLocation === pageLocation) {
                return;
            }
            ga4LastPageLocation = pageLocation;

            sendGa4Event('page_view', {
                page_title: `Test Overview - ${analyticsText(view.title || viewKey, 100)}`,
                page_location: pageLocation,
                page_path: `${url.pathname}${url.search}`,
                testoverview_view: viewKey,
                testoverview_value: getDeepLinkValue(viewKey),
                testoverview_page_file: getGa4PageFile(),
                testoverview_device: getAnalyticsDeviceType()
            });
        }

        function getFieldGuideCtaKey(details) {
            const elementKey = String(details.element_key || '');
            const elementHref = String(details.element_href || '');
            const ctaKey = String(details.metadata?.ga4_cta || '');
            if (ctaKey === 'more_about_me' || ctaKey === 'try_next_level') {
                return ctaKey;
            }
            if (elementKey === 'field-guide:more-about-me' || elementHref.includes('linkedin.com/in/ing-valentijn-p-b696371')) {
                return 'more_about_me';
            }
            if (elementKey === 'field-guide:try-next-level' || elementHref.includes('softwaretestingbreak.com') || elementHref.includes('breaksoftwaretesting.com')) {
                return 'try_next_level';
            }
            return '';
        }

        function recordGa4InteractionEvent(eventType, details = {}) {
            const eventName = GA4_EVENT_NAME_MAP[eventType];
            if (!eventName) {
                return;
            }
            sendGa4Event(eventName, {
                view_key: details.view_key || getCurrentViewKey(),
                previous_view_key: details.previous_view_key,
                target_view_key: details.target_view_key,
                page_value: details.page_value || getAnalyticsPageValue(),
                page_path: details.page_path || window.location.pathname,
                testoverview_page_file: getGa4PageFile(),
                element_kind: details.element_kind,
                element_key: details.element_key,
                element_label: details.element_label,
                element_href: details.element_href,
                pointer_type: details.pointer_type,
                device_type: details.device_type || getAnalyticsDeviceType(),
                audio_source: details.audio_source,
                audio_listened_ms: details.audio_listened_ms,
                audio_autoplay_enabled: details.audio_autoplay_enabled,
                cta_key: details.metadata?.ga4_cta
            });
            const fieldGuideCtaKey = eventType === 'click' ? getFieldGuideCtaKey(details) : '';
            if (fieldGuideCtaKey) {
                sendGa4Event('field_guide_cta_click', {
                    cta_key: fieldGuideCtaKey,
                    cta_label: details.element_label,
                    outbound_url: details.element_href,
                    view_key: details.view_key || getCurrentViewKey(),
                    page_value: details.page_value || getAnalyticsPageValue(),
                    page_path: details.page_path || window.location.pathname,
                    testoverview_page_file: getGa4PageFile(),
                    device_type: details.device_type || getAnalyticsDeviceType()
                });
            }
        }

        function scheduleAnalyticsFlush() {
            if (!analyticsRuntimeEnabled || analyticsFlushTimer || analyticsRequestInFlight) {
                return;
            }
            analyticsFlushTimer = window.setTimeout(() => {
                analyticsFlushTimer = null;
                flushAnalyticsEvents();
            }, Math.max(ANALYTICS_FLUSH_DELAY_MS, analyticsRetryDelayMs));
        }

        async function flushAnalyticsEvents(useBeacon = false) {
            if (!analyticsRuntimeEnabled || (!useBeacon && analyticsRequestInFlight) || analyticsQueue.length === 0) {
                return;
            }

            if (analyticsFlushTimer) {
                window.clearTimeout(analyticsFlushTimer);
                analyticsFlushTimer = null;
            }

            const batch = analyticsQueue.splice(0, ANALYTICS_BATCH_SIZE);
            const body = JSON.stringify({ schema_version: 1, events: batch });
            if (useBeacon && typeof window.navigator.sendBeacon === 'function') {
                const queued = window.navigator.sendBeacon(
                    ANALYTICS_ENDPOINT,
                    new Blob([body], { type: 'application/json' })
                );
                if (!queued) {
                    analyticsQueue.unshift(...batch);
                }
                return;
            }

            analyticsRequestInFlight = true;
            try {
                const response = await window.fetch(ANALYTICS_ENDPOINT, {
                    method: 'POST',
                    credentials: 'same-origin',
                    keepalive: true,
                    headers: { 'Content-Type': 'application/json' },
                    body
                });
                if (!response.ok) {
                    throw new Error(`Analytics endpoint returned HTTP ${response.status}.`);
                }
                analyticsRetryDelayMs = 0;
                analyticsLastError = '';
            } catch (error) {
                analyticsQueue.unshift(...batch);
                analyticsQueue = analyticsQueue.slice(0, 100);
                analyticsLastError = analyticsText(error && error.message, 180)
                    || 'Analytics request failed.';
                analyticsRetryDelayMs = analyticsRetryDelayMs === 0
                    ? 5000
                    : Math.min(analyticsRetryDelayMs * 2, 60000);
            } finally {
                analyticsRequestInFlight = false;
                if (analyticsQueue.length > 0) {
                    scheduleAnalyticsFlush();
                }
            }
        }

        function recordAnalyticsEvent(eventType, details = {}) {
            if (!analyticsRuntimeEnabled) {
                return null;
            }

            analyticsEventSequence += 1;
            try {
                window.sessionStorage.setItem(ANALYTICS_SEQUENCE_STORAGE_KEY, String(analyticsEventSequence));
            } catch (error) {
                // Storage can be unavailable in privacy-focused browser modes.
            }

            const event = {
                session_id: analyticsSessionId,
                visitor_id: analyticsVisitorId,
                session_started_at: analyticsSessionStartedAt,
                event_sequence: analyticsEventSequence,
                application_key: ANALYTICS_APPLICATION_KEY,
                event_type: eventType,
                client_occurred_at: new Date().toISOString(),
                view_key: details.view_key || '',
                previous_view_key: details.previous_view_key || '',
                target_view_key: details.target_view_key || '',
                page_path: window.location.pathname,
                page_value: getAnalyticsPageValue(),
                referrer_path: getAnalyticsReferrerPath(),
                element_kind: details.element_kind || '',
                element_key: details.element_key || '',
                element_id: details.element_id || '',
                element_label: details.element_label || '',
                element_classes: details.element_classes || '',
                element_href: details.element_href || '',
                pointer_type: details.pointer_type || '',
                click_x: details.click_x ?? null,
                click_y: details.click_y ?? null,
                viewport_width: Math.max(0, Math.round(window.innerWidth)),
                viewport_height: Math.max(0, Math.round(window.innerHeight)),
                device_type: getAnalyticsDeviceType(),
                active_seconds_delta: Math.max(0, Math.round(Number(details.active_seconds_delta) || 0)),
                audio_source: details.audio_source || '',
                audio_listened_ms: details.audio_listened_ms ?? null,
                audio_autoplay_enabled: typeof details.audio_autoplay_enabled === 'boolean'
                    ? details.audio_autoplay_enabled
                    : null,
                metadata: details.metadata || {}
            };
            recordGa4InteractionEvent(eventType, event);
            analyticsQueue.push(event);
            if (analyticsQueue.length >= ANALYTICS_BATCH_SIZE && analyticsRetryDelayMs === 0) {
                flushAnalyticsEvents();
            } else {
                scheduleAnalyticsFlush();
            }
            return event;
        }

        function recordAnalyticsView(viewKey) {
            if (!analyticsRuntimeEnabled) {
                return;
            }
            if (analyticsLastRenderedViewKey === null) {
                recordAnalyticsEvent('page_view', {
                    view_key: viewKey,
                    target_view_key: viewKey
                });
            } else if (analyticsLastRenderedViewKey !== viewKey) {
                recordAnalyticsEvent('view_change', {
                    view_key: viewKey,
                    previous_view_key: analyticsLastRenderedViewKey,
                    target_view_key: viewKey
                });
            }
            analyticsLastRenderedViewKey = viewKey;
        }

        function getAnalyticsInteractiveElement(target) {
            if (!(target instanceof Element)) {
                return null;
            }
            return target.closest([
                'button',
                'a',
                'summary',
                'input[type="button"]',
                'input[type="submit"]',
                'input[type="range"]',
                'input[type="checkbox"]',
                'input[type="radio"]',
                'select',
                '[role="button"]',
                '[data-track-id]'
            ].join(','));
        }

        function getAnalyticsElementDetails(element) {
            const label = analyticsText(
                element.dataset.trackLabel
                    || element.getAttribute('aria-label')
                    || element.getAttribute('title')
                    || element.textContent,
                255
            );
            const elementKind = element.tagName.toLowerCase();
            const elementKey = analyticsText(
                element.dataset.trackId
                    || element.id
                    || element.dataset.trackTarget
                    || getAnalyticsHref(element)
                    || `${elementKind}:${analyticsSlug(label)}`,
                160
            );
            return {
                element_kind: elementKind,
                element_key: elementKey,
                element_id: analyticsText(element.id, 120),
                element_label: label,
                element_classes: analyticsText(Array.from(element.classList).join(' '), 255),
                element_href: analyticsText(getAnalyticsHref(element), 512)
            };
        }

        function handleAnalyticsClick(event) {
            const element = getAnalyticsInteractiveElement(event.target);
            if (!element || element.matches(':disabled') || element.getAttribute('aria-disabled') === 'true') {
                return;
            }

            const sourceViewKey = getCurrentViewKey();
            const analyticsEvent = recordAnalyticsEvent('click', {
                ...getAnalyticsElementDetails(element),
                view_key: sourceViewKey,
                target_view_key: analyticsText(element.dataset.trackTarget, 120),
                pointer_type: event.detail === 0 ? 'keyboard' : analyticsText(event.pointerType || 'mouse', 20),
                click_x: Math.max(0, Math.round(event.clientX || 0)),
                click_y: Math.max(0, Math.round(event.clientY || 0)),
                metadata: {
                    ga4_cta: analyticsText(element.dataset.ga4Cta, 60),
                    track_external: analyticsText(element.dataset.trackExternal, 80)
                }
            });

            if (analyticsEvent) {
                window.setTimeout(() => {
                    const resultingViewKey = getCurrentViewKey();
                    if (resultingViewKey !== sourceViewKey) {
                        analyticsEvent.target_view_key = resultingViewKey;
                    }
                    if (element.dataset.trackExternal) {
                        flushAnalyticsEvents();
                    }
                }, 0);
            }
        }

        function handleAnalyticsControlChange(event) {
            const element = event.target;
            if (!(element instanceof HTMLInputElement || element instanceof HTMLSelectElement)) {
                return;
            }
            if (element instanceof HTMLInputElement
                && !['range', 'checkbox', 'radio'].includes(element.type)) {
                return;
            }

            const metadata = {};
            if (element instanceof HTMLInputElement && element.type === 'range') {
                metadata.range_value = Number(element.value);
                metadata.range_min = Number(element.min || 0);
                metadata.range_max = Number(element.max || 100);
            } else if (element instanceof HTMLInputElement) {
                metadata.checked = element.checked;
            } else {
                metadata.selected_index = element.selectedIndex;
            }

            recordAnalyticsEvent('control_change', {
                ...getAnalyticsElementDetails(element),
                view_key: getCurrentViewKey(),
                pointer_type: 'unknown',
                metadata
            });
        }

        function initialiseAnalyticsTracking() {
            if (!analyticsRuntimeEnabled) {
                return;
            }
            document.addEventListener('click', handleAnalyticsClick, true);
            document.addEventListener('change', handleAnalyticsControlChange, true);
            analyticsHeartbeatTimer = window.setInterval(() => {
                if (document.visibilityState === 'visible') {
                    recordAnalyticsEvent('heartbeat', {
                        view_key: getCurrentViewKey(),
                        active_seconds_delta: consumeAnalyticsActiveSeconds(true)
                    });
                }
            }, ANALYTICS_HEARTBEAT_INTERVAL_MS);
            window.addEventListener('pagehide', () => {
                if (analyticsHeartbeatTimer) {
                    window.clearInterval(analyticsHeartbeatTimer);
                    analyticsHeartbeatTimer = null;
                }
                recordAnalyticsEvent('session_end', {
                    view_key: getCurrentViewKey(),
                    active_seconds_delta: consumeAnalyticsActiveSeconds(false)
                });
                flushAnalyticsEvents(true);
            });
            document.addEventListener('visibilitychange', () => {
                if (document.visibilityState === 'hidden') {
                    recordAnalyticsEvent('heartbeat', {
                        view_key: getCurrentViewKey(),
                        active_seconds_delta: consumeAnalyticsActiveSeconds(false)
                    });
                    flushAnalyticsEvents(true);
                } else {
                    analyticsActivePeriodStartedAt = Date.now();
                }
            });
        }

        window.testOverviewAnalytics = Object.freeze({
            isEnabled: () => analyticsRuntimeEnabled,
            setEnabled: (enabled) => {
                analyticsRuntimeEnabled = analyticsCanSend && Boolean(enabled);
                if (!analyticsRuntimeEnabled) {
                    analyticsQueue = [];
                    if (analyticsFlushTimer) {
                        window.clearTimeout(analyticsFlushTimer);
                        analyticsFlushTimer = null;
                    }
                }
                return analyticsRuntimeEnabled;
            },
            getStatus: () => ({
                enabled: analyticsRuntimeEnabled,
                queuedEvents: analyticsQueue.length,
                retryDelayMs: analyticsRetryDelayMs,
                lastError: analyticsLastError,
                applicationKey: ANALYTICS_APPLICATION_KEY,
                endpoint: ANALYTICS_ENDPOINT
            }),
            flush: () => flushAnalyticsEvents()
        });

