        const deepLinkAliases = Object.freeze({
            root: 'requirement',
            'requirement-origin-info': 'requirementdetails',
            'requirement-reason-map': 'knowledgemap',
            'requirement-language-clarity': 'requirementwording',
            dtap: 'dtap',
            'knowledge-root': 'testoverview',
            checking: 'checking',
            'checking-ai': 'ai',
            'checking-test-tool': 'testtool',
            'testing-bridge': 'structuredchaos',
            testing: 'tacitvsexplicit',
            'tacit-knowledge': 'tacitknowledge',
            'explicit-knowledge': 'explicitknowledge',
            'test-techniques': 'testtechniques',
            'test-methods': 'testmethods',
            'testcase-bridge': 'testcase',
            'technique-interaction-table': 'connectedtechniques',
            'integration-testing': 'integrationtesting',
            'knowledge-exchange': 'knowledgeexchange',
            'retest-investigation': 'retestinvestigation'
        });

        const deepLinkNavigatorKeys = Object.freeze([
            'root',
            'requirement-origin-info',
            'requirement-functional',
            'requirement-language-clarity',
            'requirement-reason-map',
            'dtap',
            'knowledge-root',
            'checking',
            'checking-ai',
            'checking-test-tool',
            'checking-test-tool-no-code',
            'checking-test-tool-low-code',
            'checking-test-tool-code',
            'checking-tool-selenium',
            'checking-tool-selenium-proof-not-work',
            'testing-bridge',
            'testing',
            'tacit-knowledge',
            'semantic-tacit',
            'explicit-knowledge',
            'explicit-knowledge-from-techniques',
            'test-techniques',
            'technique-decision-table-testing',
            'technique-decision-table-testing-proof-not-work',
            'testcase-bridge',
            'technique-interaction-table',
            'integration-testing',
            'knowledge-exchange',
            'retest-investigation',
            'test-methods',
            'method-black-box'
        ]);

        function normalizeDeepLinkValue(value = '') {
            return String(value).trim().toLowerCase().replace(/[^a-z0-9]+/g, '');
        }

        function getDeepLinkValue(viewKey) {
            if (deepLinkAliases[viewKey]) {
                return deepLinkAliases[viewKey];
            }

            const view = overviewTree[viewKey];
            if (viewKey.startsWith('requirement-') && view?.type === 'matrix') {
                return normalizeDeepLinkValue(view.title);
            }

            return normalizeDeepLinkValue(viewKey);
        }

        function resolveDeepLinkValue(rawValue) {
            if (!rawValue) return null;
            if (overviewTree[rawValue]) return rawValue;

            const normalizedValue = normalizeDeepLinkValue(rawValue);
            if (!normalizedValue) return null;

            return Object.keys(overviewTree).find((viewKey) => (
                getDeepLinkValue(viewKey) === normalizedValue
                || normalizeDeepLinkValue(viewKey) === normalizedValue
            )) || null;
        }

        function createDeepLinkUrl(viewKey) {
            const url = new URL(window.location.href);
            url.searchParams.set('value', getDeepLinkValue(viewKey));
            return url.toString();
        }

        function syncDeepLinkUrl(viewKey) {
            if (!overviewTree[viewKey]) return;
            const nextValue = getDeepLinkValue(viewKey);
            const url = new URL(window.location.href);
            if (url.searchParams.get('value') === nextValue) return;
            url.searchParams.set('value', nextValue);
            window.history.replaceState({ viewKey }, '', url);
        }

        const requestedDeepLink = new URLSearchParams(window.location.search).get('value');
        const initialViewKey = resolveDeepLinkValue(requestedDeepLink) || 'root';
        const historyStack = initialViewKey === 'root' ? ['root'] : ['root', initialViewKey];

        let lastPraSelection = null;
        let pendingTestcaseBridge = null;
        let overviewAudioContext = null;
        let dashboardCommandAudioStop = null;
        let dashboardCommandIntroToken = 0;
        let dashboardEntrySequenceEndsAt = 0;
        let hasPresentedRootJourneyIntro = false;
        let isEditModeControlPinned = isEditMode || initialViewKey !== 'root';
        let isEditModeControlHidden = false;
        let editModeIntroFadeTimer = null;
        let hasDtapAspectsBeenUsed = false;

        function getCurrentViewKey() {
            return historyStack[historyStack.length - 1] || 'root';
        }

        function getViewDefinition(viewKey) {
            if (overviewTree[viewKey]) {
                return overviewTree[viewKey];
            }

            if (!isEditMode) {
                return null;
            }

            const customView = customOverviewState.views[viewKey];
            if (!customView) {
                return null;
            }

            return {
                title: customView.title,
                breadcrumb: 'Custom page created in Edit modus. Add more custom buttons to keep building this route.',
                type: 'custom',
                frames: [
                    {
                        title: customView.title,
                        copy: 'This custom page lives only in Edit modus. Use the add-button area below to create the next step in your own flow.'
                    }
                ]
            };
        }

        function getPageRatingColor(sentiment, score) {
            const colorSteps = sentiment === 'down'
                ? ['#d9b9bf', '#e49aa6', '#ed7889', '#f35b71', '#ff405e']
                : ['#b5dbce', '#8ed8bb', '#66d5a2', '#45dc8f', '#22e77a'];
            return colorSteps[Math.min(4, Math.max(0, Number(score) - 1))];
        }

        function setPageRatingExpanded(isExpanded, options = {}) {
            const expanded = Boolean(isExpanded);
            pageRatingShell.classList.toggle('is-collapsed', !expanded);
            pageRatingLauncher.setAttribute('aria-expanded', expanded ? 'true' : 'false');
            if (expanded && options.focus !== false) {
                window.setTimeout(() => pageRatingUp.focus(), 350);
            }
        }

        function updatePageRatingUi() {
            const hasSentiment = activePageRatingSentiment === 'up' || activePageRatingSentiment === 'down';
            const score = Math.min(5, Math.max(1, Math.round(Number(activePageRatingScore) || 3)));
            activePageRatingScore = score;

            pageRatingShell.classList.toggle('is-up', activePageRatingSentiment === 'up');
            pageRatingShell.classList.toggle('is-down', activePageRatingSentiment === 'down');
            pageRatingUp.classList.toggle('is-selected', activePageRatingSentiment === 'up');
            pageRatingDown.classList.toggle('is-selected', activePageRatingSentiment === 'down');
            pageRatingUp.setAttribute('aria-pressed', activePageRatingSentiment === 'up' ? 'true' : 'false');
            pageRatingDown.setAttribute('aria-pressed', activePageRatingSentiment === 'down' ? 'true' : 'false');
            pageRatingRange.disabled = !hasSentiment || pageRatingRequestInFlight;
            pageRatingRange.value = String(score);
            pageRatingSubmit.disabled = !hasSentiment || pageRatingRequestInFlight;
            pageRatingShell.style.setProperty(
                '--page-rating-color',
                hasSentiment ? getPageRatingColor(activePageRatingSentiment, score) : 'rgba(167, 239, 255, 0.7)'
            );

            const isDown = activePageRatingSentiment === 'down';
            pageRatingTopLimit.textContent = isDown ? '1' : '5';
            pageRatingBottomLimit.textContent = isDown ? '5' : '1';
            pageRatingRange.setAttribute(
                'aria-label',
                hasSentiment
                    ? `${activePageRatingSentiment === 'up' ? 'Thumbs up' : 'Thumbs down'} strength ${score} of 5`
                    : 'Choose thumbs up or thumbs down before setting rating strength'
            );
            pageRatingReadout.textContent = hasSentiment
                ? `${activePageRatingSentiment === 'up' ? 'Thumbs up' : 'Thumbs down'} - ${score}/5`
                : 'Choose a thumb';
        }

        function renderPageRatingForView(viewKey, view) {
            const savedRating = pageRatingStates[viewKey] || null;
            activePageRatingViewKey = viewKey;
            activePageRatingViewTitle = String(view?.title || viewKey || 'Test overview').slice(0, 255);
            activePageRatingSentiment = savedRating?.sentiment || '';
            activePageRatingScore = savedRating?.score || 3;
            pageRatingPageName.textContent = activePageRatingViewTitle;
            pageRatingStatus.classList.remove('is-error');
            pageRatingStatus.textContent = savedRating
                ? 'Saved for this session. You can still adjust it.'
                : '';
            pageRatingSubmit.textContent = savedRating ? 'Update rating' : 'Save rating';
            pageRatingShell.classList.remove('is-saving', 'is-saved');
            updatePageRatingUi();
            setPageRatingExpanded(false, { focus: false });
        }

        function choosePageRatingSentiment(sentiment) {
            if (pageRatingRequestInFlight || (sentiment !== 'up' && sentiment !== 'down')) {
                return;
            }
            activePageRatingSentiment = sentiment;
            pageRatingStatus.classList.remove('is-error');
            pageRatingStatus.textContent = pageRatingStates[activePageRatingViewKey]
                ? 'Ready to update this page rating.'
                : 'Choose a strength, then save.';
            updatePageRatingUi();
            playOverviewButtonSound(`${activePageRatingViewKey}-rating-${sentiment}`, sentiment === 'up' ? 'forward' : 'back');
        }

        async function submitPageRating() {
            if (pageRatingRequestInFlight
                || (activePageRatingSentiment !== 'up' && activePageRatingSentiment !== 'down')) {
                return;
            }

            const submittingViewKey = activePageRatingViewKey;
            const submittingViewTitle = activePageRatingViewTitle;
            const submittingSentiment = activePageRatingSentiment;
            const submittingScore = activePageRatingScore;
            const signedScore = submittingSentiment === 'up' ? submittingScore : -submittingScore;
            pageRatingRequestInFlight = true;
            pageRatingShell.classList.add('is-saving');
            pageRatingStatus.classList.remove('is-error');
            pageRatingStatus.textContent = 'Saving your signal...';
            updatePageRatingUi();

            recordAnalyticsEvent('control_change', {
                view_key: submittingViewKey,
                element_kind: 'page_rating',
                element_key: 'page-rating:submit',
                element_label: `${submittingSentiment} ${submittingScore}/5`,
                metadata: {
                    rating_dimension: 'overall',
                    rating_sentiment: submittingSentiment,
                    rating_score: submittingScore,
                    signed_score: signedScore
                }
            });

            try {
                let savedAt = new Date().toISOString();
                if (analyticsCanSend) {
                    const response = await window.fetch(PAGE_RATING_ENDPOINT, {
                        method: 'POST',
                        credentials: 'same-origin',
                        keepalive: true,
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            schema_version: 1,
                            rating: {
                                session_id: analyticsSessionId,
                                visitor_id: analyticsVisitorId,
                                session_started_at: analyticsSessionStartedAt,
                                application_key: ANALYTICS_APPLICATION_KEY,
                                rating_dimension: 'overall',
                                view_key: submittingViewKey,
                                view_title: submittingViewTitle,
                                page_path: window.location.pathname,
                                page_value: getAnalyticsPageValue(),
                                sentiment: submittingSentiment,
                                score: submittingScore,
                                device_type: getAnalyticsDeviceType(),
                                viewport_width: Math.max(0, Math.round(window.innerWidth)),
                                viewport_height: Math.max(0, Math.round(window.innerHeight)),
                                client_occurred_at: new Date().toISOString(),
                                metadata: {
                                    page_file: getGa4PageFile(),
                                    source: 'page_widget'
                                }
                            }
                        })
                    });
                    const result = await response.json().catch(() => ({}));
                    if (!response.ok || !result.ok) {
                        throw new Error(result.error || `Rating endpoint returned HTTP ${response.status}.`);
                    }
                    savedAt = result.saved_at || savedAt;
                }

                pageRatingStates[submittingViewKey] = {
                    sentiment: submittingSentiment,
                    score: submittingScore,
                    savedAt
                };
                savePageRatingStates();
                sendGa4Event('page_rating_submit', {
                    view_key: submittingViewKey,
                    page_title: submittingViewTitle,
                    page_value: getAnalyticsPageValue(),
                    page_path: window.location.pathname,
                    testoverview_page_file: getGa4PageFile(),
                    rating_dimension: 'overall',
                    rating_sentiment: submittingSentiment,
                    rating_score: submittingScore,
                    signed_score: signedScore,
                    device_type: getAnalyticsDeviceType()
                });

                if (activePageRatingViewKey === submittingViewKey) {
                    pageRatingStatus.textContent = analyticsCanSend
                        ? 'Saved. You can still adjust it.'
                        : 'Preview saved locally. The live PHP page stores it in MySQL.';
                    pageRatingSubmit.textContent = 'Update rating';
                    pageRatingShell.classList.remove('is-saved');
                    void pageRatingShell.offsetWidth;
                    pageRatingShell.classList.add('is-saved');
                }
            } catch (error) {
                if (activePageRatingViewKey === submittingViewKey) {
                    pageRatingStatus.classList.add('is-error');
                    pageRatingStatus.textContent = analyticsText(error?.message, 180) || 'The rating could not be saved.';
                }
            } finally {
                pageRatingRequestInFlight = false;
                pageRatingShell.classList.remove('is-saving');
                updatePageRatingUi();
            }
        }

        function sanitizeHistoryForMode() {
            if (isEditMode) {
                return;
            }

            for (let index = historyStack.length - 1; index >= 0; index -= 1) {
                if (!overviewTree[historyStack[index]]) {
                    historyStack.splice(index, 1);
                }
            }

            if (!historyStack.length) {
                historyStack.push('root');
            }

            if (!overviewTree[getCurrentViewKey()]) {
                historyStack.length = 1;
                historyStack[0] = 'root';
            }
        }

        function updateEditModeControlVisibility() {
            const shouldHide = isEditModeControlHidden && !isEditModeControlPinned;
            document.documentElement.classList.toggle('is-edit-mode-control-hidden', shouldHide);
            editModeToggle.setAttribute('aria-hidden', shouldHide ? 'true' : 'false');
            editModeToggle.tabIndex = shouldHide ? -1 : 0;
        }

        function pinEditModeControl() {
            isEditModeControlPinned = true;
            isEditModeControlHidden = false;
            if (editModeIntroFadeTimer) {
                window.clearTimeout(editModeIntroFadeTimer);
                editModeIntroFadeTimer = null;
            }
            updateEditModeControlVisibility();
        }

        function scheduleEditModeControlIntroFade() {
            updateEditModeControlVisibility();
            if (initialViewKey !== 'root' || isEditModeControlPinned || editModeIntroFadeTimer) {
                return;
            }

            editModeIntroFadeTimer = window.setTimeout(() => {
                editModeIntroFadeTimer = null;
                if (isEditModeControlPinned) {
                    return;
                }
                isEditModeControlHidden = true;
                updateEditModeControlVisibility();
            }, EDIT_MODE_INTRO_FADE_DELAY_MS);
        }

        function updateEditModeToggleUi() {
            editModeToggle.classList.toggle('is-active', isEditMode);
            editModeToggle.setAttribute('aria-pressed', isEditMode ? 'true' : 'false');
            editModeToggleLabel.textContent = isEditMode ? 'Edit modus' : 'View modus';
            updateEditModeControlVisibility();
        }

        function updateAutoplayToggleUi() {
            autoplayToggle.classList.toggle('is-active', isNarrationAutoplayEnabled);
            autoplayToggle.setAttribute('aria-pressed', isNarrationAutoplayEnabled ? 'true' : 'false');
            autoplayToggle.setAttribute(
                'aria-label',
                isNarrationAutoplayEnabled ? 'Autoplay narration on' : 'Autoplay narration off'
            );
        }

        function applyNarrationButtonState() {
            const isEnabled = supportsSpeechSynthesis && activeNarrationText.length > 0;
            narrationButton.disabled = !isEnabled;
            narrationButton.classList.toggle('is-playing', isEnabled && narrationState === 'playing');
            narrationButton.classList.toggle('is-paused', isEnabled && narrationState === 'paused');
            narrationButton.setAttribute(
                'aria-pressed',
                isEnabled && narrationState !== 'idle' ? 'true' : 'false'
            );

            if (!isEnabled) {
                narrationButton.setAttribute('aria-label', 'Page narration unavailable');
                return;
            }

            if (narrationState === 'playing') {
                narrationButton.setAttribute('aria-label', 'Pause page narration');
                return;
            }

            if (narrationState === 'paused') {
                narrationButton.setAttribute('aria-label', 'Resume page narration');
                return;
            }

            narrationButton.setAttribute('aria-label', 'Play page narration');
        }

        function accumulateNarrationListenedTime() {
            if (!narrationAnalyticsPlayback || narrationAnalyticsPlayback.activeStartedAt === null) {
                return;
            }
            narrationAnalyticsPlayback.listenedMs += Math.max(
                0,
                window.performance.now() - narrationAnalyticsPlayback.activeStartedAt
            );
            narrationAnalyticsPlayback.activeStartedAt = null;
        }

        function beginNarrationAnalytics(source, text) {
            narrationAnalyticsPlayback = {
                source: source === 'autoplay' ? 'autoplay' : 'manual',
                viewKey: getCurrentViewKey(),
                listenedMs: 0,
                activeStartedAt: window.performance.now()
            };
            recordAnalyticsEvent('audio_start', {
                view_key: narrationAnalyticsPlayback.viewKey,
                audio_source: narrationAnalyticsPlayback.source,
                audio_listened_ms: 0,
                audio_autoplay_enabled: isNarrationAutoplayEnabled,
                metadata: {
                    character_count: String(text || '').length,
                    word_count: String(text || '').trim().split(/\s+/).filter(Boolean).length
                }
            });
        }

        function recordNarrationProgress(eventType, reason = '') {
            if (!narrationAnalyticsPlayback) {
                return;
            }
            accumulateNarrationListenedTime();
            recordAnalyticsEvent(eventType, {
                view_key: narrationAnalyticsPlayback.viewKey,
                audio_source: narrationAnalyticsPlayback.source,
                audio_listened_ms: Math.max(0, Math.round(narrationAnalyticsPlayback.listenedMs)),
                audio_autoplay_enabled: isNarrationAutoplayEnabled,
                metadata: reason ? { reason } : {}
            });
        }

        function finishNarrationAnalytics(eventType, reason) {
            if (!narrationAnalyticsPlayback) {
                return;
            }
            recordNarrationProgress(eventType, reason);
            narrationAnalyticsPlayback = null;
        }

        function stopNarration(reason = 'interrupted') {
            finishNarrationAnalytics('audio_stop', reason);
            continueNarrationPlayback = null;
            narrationState = 'idle';

            if (supportsSpeechSynthesis) {
                narrationPlaybackToken += 1;
                window.speechSynthesis.cancel();
            }

            applyNarrationButtonState();
        }

        function pauseNarration() {
            if (!supportsSpeechSynthesis || narrationState !== 'playing') return;
            recordNarrationProgress('audio_pause', 'user');
            narrationState = 'paused';

            if (window.speechSynthesis.speaking && !window.speechSynthesis.paused) {
                window.speechSynthesis.pause();
            }

            applyNarrationButtonState();
        }

        function resumeNarration() {
            if (!supportsSpeechSynthesis || narrationState !== 'paused') return;
            narrationState = 'playing';
            if (narrationAnalyticsPlayback) {
                narrationAnalyticsPlayback.activeStartedAt = window.performance.now();
                recordAnalyticsEvent('audio_resume', {
                    view_key: narrationAnalyticsPlayback.viewKey,
                    audio_source: narrationAnalyticsPlayback.source,
                    audio_listened_ms: Math.max(0, Math.round(narrationAnalyticsPlayback.listenedMs)),
                    audio_autoplay_enabled: isNarrationAutoplayEnabled
                });
            }
            applyNarrationButtonState();

            if (window.speechSynthesis.paused) {
                window.speechSynthesis.resume();
                return;
            }

            if (typeof continueNarrationPlayback === 'function') {
                window.setTimeout(() => {
                    if (narrationState === 'playing' && typeof continueNarrationPlayback === 'function') {
                        continueNarrationPlayback();
                    }
                }, 0);
            }
        }

        function waitForNarrationVoices(timeoutMs = 5000) {
            if (!supportsSpeechSynthesis) {
                return Promise.resolve([]);
            }

            if (typeof window.speechSynthesis.getVoices !== 'function') {
                return Promise.resolve([]);
            }

            const existingVoices = window.speechSynthesis.getVoices();
            if (existingVoices.length) {
                return Promise.resolve(existingVoices);
            }

            if (narrationVoicesPromise) {
                return narrationVoicesPromise;
            }

            narrationVoicesPromise = new Promise((resolve) => {
                let pollTimer = null;
                let timeoutTimer = null;
                let isFinished = false;

                const finish = (voices) => {
                    if (isFinished) return;
                    isFinished = true;
                    if (pollTimer) window.clearTimeout(pollTimer);
                    if (timeoutTimer) window.clearTimeout(timeoutTimer);
                    window.speechSynthesis.removeEventListener?.('voiceschanged', checkForVoices);
                    narrationVoicesPromise = null;
                    resolve(voices);
                };

                const checkForVoices = () => {
                    const voices = window.speechSynthesis.getVoices();
                    if (voices.length) {
                        finish(voices);
                        return;
                    }
                    if (!pollTimer) {
                        pollTimer = window.setTimeout(() => {
                            pollTimer = null;
                            checkForVoices();
                        }, 120);
                    }
                };

                timeoutTimer = window.setTimeout(() => {
                    finish(window.speechSynthesis.getVoices());
                }, timeoutMs);
                if (typeof window.speechSynthesis.addEventListener === 'function') {
                    window.speechSynthesis.addEventListener('voiceschanged', checkForVoices);
                }

                window.speechSynthesis.getVoices();
                window.setTimeout(checkForVoices, 0);
            });

            return narrationVoicesPromise;
        }

        function getEnglishNarrationVoice(voices = []) {
            if (!supportsSpeechSynthesis) return null;
            if (!voices.length) return null;

            const preferredVoiceNames = [
                'Microsoft Aria Online (Natural)',
                'Microsoft Ava Online (Natural)',
                'Microsoft Jenny Online (Natural)',
                'Microsoft Libby Online (Natural)',
                'Microsoft Sonia Online (Natural)',
                'Aria Online',
                'Ava Online',
                'Jenny Online',
                'Libby Online',
                'Aria',
                'Ava',
                'Jenny',
                'Emma',
                'Libby',
                'Sonia',
                'Michelle',
                'Zira',
                'Hazel',
                'Susan',
                'Google UK English Female',
                'Google US English',
                'Female'
            ];
            const femaleVoiceNames = [
                'aria', 'ava', 'jenny', 'emma', 'libby', 'sonia', 'michelle', 'zira',
                'hazel', 'susan', 'samantha', 'karen', 'moira', 'tessa', 'veena',
                'fiona', 'victoria', 'female'
            ];
            const maleVoiceNames = [
                'david', 'guy', 'mark', 'george', 'daniel', 'james', 'ryan',
                'christopher', 'eric', 'male'
            ];

            const englishVoices = voices.filter((voice) => typeof voice.lang === 'string' && voice.lang.toLowerCase().startsWith('en'));
            if (!englishVoices.length) {
                return null;
            }

            const scoreVoice = (voice) => {
                const name = (voice.name || '').toLowerCase();
                let score = 0;

                const preferredIndex = preferredVoiceNames.findIndex((preferredName) => (
                    name.includes(preferredName.toLowerCase())
                ));
                if (preferredIndex >= 0) score += 620 - (preferredIndex * 14);

                if (voice.lang.toLowerCase() === 'en-us') score += 60;
                if (voice.lang.toLowerCase() === 'en-gb') score += 55;
                if (voice.default) score += 20;
                if (name.includes('natural')) score += 140;
                if (name.includes('online')) score += 100;
                if (name.includes('neural')) score += 120;
                if (name.includes('premium')) score += 60;
                if (femaleVoiceNames.some((femaleName) => name.includes(femaleName))) score += 220;
                if (maleVoiceNames.some((maleName) => name.includes(maleName))) score -= 280;

                return score;
            };

            return englishVoices
                .slice()
                .sort((left, right) => scoreVoice(right) - scoreVoice(left))[0] || null;
        }

        function cacheEnglishNarrationVoice(voices = []) {
            const selectedVoice = getEnglishNarrationVoice(voices);
            if (selectedVoice) {
                cachedNarrationVoice = selectedVoice;
            }
            return selectedVoice || cachedNarrationVoice;
        }

        function primeNarrationVoice() {
            if (!supportsSpeechSynthesis) return;
            waitForNarrationVoices().then((voices) => {
                cacheEnglishNarrationVoice(voices);
            }).catch(() => {});
        }

        function updateNarrationButton(view) {
            activeNarrationText = typeof view.speechText === 'string' ? view.speechText.trim() : '';
            narrationState = 'idle';
            continueNarrationPlayback = null;
            applyNarrationButtonState();
        }

        function splitNarrationText(text) {
            return String(text || '')
                .split(/(?<=[.!?])\s+/)
                .map((segment) => segment.trim())
                .filter(Boolean);
        }

        async function playNarration(text, source = 'manual') {
            if (!supportsSpeechSynthesis || !text) return;

            stopNarration('restarted');
            const playbackToken = narrationPlaybackToken + 1;
            narrationPlaybackToken = playbackToken;

            narrationState = 'playing';
            applyNarrationButtonState();

            const voices = await waitForNarrationVoices();
            if (playbackToken !== narrationPlaybackToken) {
                return;
            }

            const voice = cacheEnglishNarrationVoice(voices);
            narrationLastVoiceName = voice?.name || 'Browser default voice';
            const segments = splitNarrationText(text);
            if (!segments.length) {
                continueNarrationPlayback = null;
                narrationState = 'idle';
                applyNarrationButtonState();
                return;
            }

            const voiceName = voice?.name || '';
            const isNaturalVoice = /natural|online|neural/i.test(voiceName);
            const isPreferredFemaleVoice = /aria|ava|jenny|emma|libby|sonia|michelle|zira|hazel|susan|samantha|female/i.test(voiceName);
            const playbackRate = isNaturalVoice ? 0.98 : (isPreferredFemaleVoice ? 0.96 : 0.94);
            const playbackPitch = isNaturalVoice ? 1.02 : (isPreferredFemaleVoice ? 1.04 : 1.06);

            let segmentIndex = 0;
            beginNarrationAnalytics(source, text);

            const speakNextSegment = () => {
                if (playbackToken !== narrationPlaybackToken) {
                    return;
                }

                continueNarrationPlayback = speakNextSegment;

                if (narrationState === 'paused') {
                    return;
                }

                if (segmentIndex >= segments.length) {
                    finishNarrationAnalytics('audio_complete', 'completed');
                    continueNarrationPlayback = null;
                    narrationState = 'idle';
                    applyNarrationButtonState();
                    return;
                }

                const utterance = new SpeechSynthesisUtterance(segments[segmentIndex]);
                utterance.lang = voice?.lang || 'en-US';
                utterance.rate = playbackRate;
                utterance.pitch = playbackPitch;
                utterance.volume = 1;

                if (voice) {
                    utterance.voice = voice;
                }

                utterance.onend = () => {
                    if (playbackToken !== narrationPlaybackToken) {
                        return;
                    }
                    segmentIndex += 1;
                    window.setTimeout(() => {
                        if (playbackToken !== narrationPlaybackToken) {
                            return;
                        }
                        if (narrationState === 'paused') {
                            continueNarrationPlayback = speakNextSegment;
                            return;
                        }
                        speakNextSegment();
                    }, 110);
                };

                utterance.onerror = () => {
                    if (playbackToken !== narrationPlaybackToken) {
                        return;
                    }
                    continueNarrationPlayback = null;
                    finishNarrationAnalytics('audio_error', 'speech_synthesis_error');
                    narrationState = 'idle';
                    applyNarrationButtonState();
                };

                window.speechSynthesis.speak(utterance);
            };

            speakNextSegment();
        }

        function maybeAutoplayNarration(view, viewKey) {
            if (!isNarrationAutoplayEnabled || !supportsSpeechSynthesis || !activeNarrationText || narrationButton.disabled) {
                return;
            }

            const expectedText = typeof view.speechText === 'string' ? view.speechText.trim() : '';
            window.setTimeout(() => {
                if (!isNarrationAutoplayEnabled) {
                    return;
                }
                if (getCurrentViewKey() !== viewKey) {
                    return;
                }
                if (!expectedText || activeNarrationText !== expectedText) {
                    return;
                }
                if (narrationState !== 'idle') {
                    return;
                }
                playNarration(expectedText, 'autoplay');
            }, 140);
        }

        function getOverviewAudioContext() {
            try {
                if (!overviewAudioContext) {
                    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
                    if (!AudioContextClass) return null;
                    overviewAudioContext = new AudioContextClass();
                }
                if (overviewAudioContext.state === 'suspended') {
                    overviewAudioContext.resume().catch(() => {});
                }
                return overviewAudioContext;
            } catch (error) {
                return null;
            }
        }

        function playDashboardBootLaserSequence() {
            const audioContext = getOverviewAudioContext();
            if (!audioContext) return;

            const now = audioContext.currentTime + 0.01;
            const masterGain = audioContext.createGain();
            const compressor = audioContext.createDynamicsCompressor();
            dashboardEntrySequenceEndsAt = Date.now() + 6200;

            compressor.threshold.setValueAtTime(-20, now);
            compressor.knee.setValueAtTime(16, now);
            compressor.ratio.setValueAtTime(5, now);
            compressor.attack.setValueAtTime(0.004, now);
            compressor.release.setValueAtTime(0.3, now);
            masterGain.gain.setValueAtTime(0.0001, now);
            masterGain.gain.exponentialRampToValueAtTime(0.28, now + 0.045);
            masterGain.gain.setValueAtTime(0.28, now + 5.15);
            masterGain.gain.exponentialRampToValueAtTime(0.0001, now + 6.05);
            masterGain.connect(compressor);
            compressor.connect(audioContext.destination);

            const connectWithPan = (source, gain, panValue = 0) => {
                source.connect(gain);
                if (typeof audioContext.createStereoPanner === 'function') {
                    const panner = audioContext.createStereoPanner();
                    panner.pan.setValueAtTime(panValue, now);
                    gain.connect(panner);
                    panner.connect(masterGain);
                    return panner;
                }
                gain.connect(masterGain);
                return null;
            };

            // Sub pressure makes the entry feel physical before the brighter effects arrive.
            const pressure = audioContext.createOscillator();
            const pressureGain = audioContext.createGain();
            const pressureFilter = audioContext.createBiquadFilter();
            pressure.type = 'sawtooth';
            pressure.frequency.setValueAtTime(31, now);
            pressure.frequency.exponentialRampToValueAtTime(48, now + 2.4);
            pressure.frequency.exponentialRampToValueAtTime(27, now + 5.8);
            pressureFilter.type = 'lowpass';
            pressureFilter.frequency.setValueAtTime(130, now);
            pressureFilter.frequency.exponentialRampToValueAtTime(260, now + 3.8);
            pressureGain.gain.setValueAtTime(0.0001, now);
            pressureGain.gain.exponentialRampToValueAtTime(0.34, now + 0.22);
            pressureGain.gain.setValueAtTime(0.34, now + 4.8);
            pressureGain.gain.exponentialRampToValueAtTime(0.0001, now + 6);
            pressure.connect(pressureFilter);
            pressureFilter.connect(pressureGain);
            pressureGain.connect(masterGain);
            pressure.start(now);
            pressure.stop(now + 6.08);

            // Filtered noise and metal harmonics create two heavy doors sliding apart.
            const doorBuffer = audioContext.createBuffer(1, Math.floor(audioContext.sampleRate * 2.8), audioContext.sampleRate);
            const doorData = doorBuffer.getChannelData(0);
            for (let index = 0; index < doorData.length; index += 1) {
                const progress = index / doorData.length;
                doorData[index] = ((Math.random() * 2) - 1) * Math.sin(Math.PI * progress);
            }
            const doorNoise = audioContext.createBufferSource();
            const doorFilter = audioContext.createBiquadFilter();
            const doorGain = audioContext.createGain();
            doorNoise.buffer = doorBuffer;
            doorNoise.playbackRate.setValueAtTime(0.72, now + 0.28);
            doorFilter.type = 'bandpass';
            doorFilter.frequency.setValueAtTime(180, now + 0.28);
            doorFilter.frequency.exponentialRampToValueAtTime(620, now + 2.7);
            doorFilter.Q.setValueAtTime(1.7, now + 0.28);
            doorGain.gain.setValueAtTime(0.0001, now + 0.24);
            doorGain.gain.exponentialRampToValueAtTime(0.22, now + 0.55);
            doorGain.gain.exponentialRampToValueAtTime(0.0001, now + 3.2);
            doorNoise.connect(doorFilter);
            doorFilter.connect(doorGain);
            const doorPanner = connectWithPan(doorGain, audioContext.createGain(), -0.72);
            if (doorPanner) {
                doorPanner.pan.setValueAtTime(-0.72, now + 0.28);
                doorPanner.pan.linearRampToValueAtTime(0.72, now + 2.9);
            }
            doorNoise.start(now + 0.28);
            doorNoise.stop(now + 3.35);

            [
                { at: 0.18, frequency: 96, end: 38, pan: -0.82, gain: 0.34 },
                { at: 0.56, frequency: 132, end: 46, pan: 0.82, gain: 0.28 },
                { at: 2.72, frequency: 170, end: 52, pan: -0.55, gain: 0.3 },
                { at: 3.02, frequency: 210, end: 58, pan: 0.55, gain: 0.26 }
            ].forEach((impact) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const startAt = now + impact.at;
                oscillator.type = 'triangle';
                oscillator.frequency.setValueAtTime(impact.frequency, startAt);
                oscillator.frequency.exponentialRampToValueAtTime(impact.end, startAt + 0.32);
                gain.gain.setValueAtTime(0.0001, startAt);
                gain.gain.exponentialRampToValueAtTime(impact.gain, startAt + 0.008);
                gain.gain.exponentialRampToValueAtTime(0.0001, startAt + 0.38);
                connectWithPan(oscillator, gain, impact.pan);
                oscillator.start(startAt);
                oscillator.stop(startAt + 0.42);
            });

            [
                { at: 0.04, from: 3600, to: 280, duration: 0.28, type: 'sawtooth', gain: 0.24, pan: -0.9 },
                { at: 0.34, from: 520, to: 4200, duration: 0.22, type: 'square', gain: 0.16, pan: 0.9 },
                { at: 0.78, from: 4800, to: 430, duration: 0.38, type: 'sawtooth', gain: 0.22, pan: 0.65 },
                { at: 1.22, from: 740, to: 5100, duration: 0.28, type: 'triangle', gain: 0.17, pan: -0.7 },
                { at: 1.68, from: 3200, to: 190, duration: 0.5, type: 'square', gain: 0.14, pan: 0.35 },
                { at: 2.36, from: 900, to: 6200, duration: 0.34, type: 'sawtooth', gain: 0.13, pan: -0.25 }
            ].forEach((tone) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const startAt = now + tone.at;
                oscillator.type = tone.type;
                oscillator.frequency.setValueAtTime(tone.from, startAt);
                oscillator.frequency.exponentialRampToValueAtTime(tone.to, startAt + tone.duration);
                gain.gain.setValueAtTime(0.0001, startAt);
                gain.gain.exponentialRampToValueAtTime(tone.gain, startAt + 0.012);
                gain.gain.exponentialRampToValueAtTime(0.0001, startAt + tone.duration);
                connectWithPan(oscillator, gain, tone.pan);
                oscillator.start(startAt);
                oscillator.stop(startAt + tone.duration + 0.03);
            });

            [0.12, 0.26, 0.48, 0.7, 1.08, 1.48, 2.08].forEach((offset, index) => {
                const bleep = audioContext.createOscillator();
                const bleepGain = audioContext.createGain();
                const startAt = now + offset;
                bleep.type = index % 2 ? 'square' : 'sine';
                bleep.frequency.setValueAtTime(880 + ((index % 4) * 420), startAt);
                bleepGain.gain.setValueAtTime(0.0001, startAt);
                bleepGain.gain.exponentialRampToValueAtTime(0.1, startAt + 0.008);
                bleepGain.gain.exponentialRampToValueAtTime(0.0001, startAt + 0.09);
                connectWithPan(bleep, bleepGain, index % 2 ? 0.52 : -0.52);
                bleep.start(startAt);
                bleep.stop(startAt + 0.11);
            });

            // A layered engine rises out of the opened bay and locks into game mode.
            [
                { frequency: 28, end: 96, type: 'sawtooth', gain: 0.2, detune: -8 },
                { frequency: 55, end: 138, type: 'square', gain: 0.1, detune: 7 },
                { frequency: 82.41, end: 196, type: 'triangle', gain: 0.08, detune: 0 }
            ].forEach((engine) => {
                const oscillator = audioContext.createOscillator();
                const filter = audioContext.createBiquadFilter();
                const gain = audioContext.createGain();
                oscillator.type = engine.type;
                oscillator.frequency.setValueAtTime(engine.frequency, now + 2.18);
                oscillator.frequency.exponentialRampToValueAtTime(engine.end, now + 4.7);
                oscillator.detune.setValueAtTime(engine.detune, now + 2.18);
                filter.type = 'lowpass';
                filter.frequency.setValueAtTime(180, now + 2.18);
                filter.frequency.exponentialRampToValueAtTime(1900, now + 4.72);
                filter.Q.setValueAtTime(3.2, now + 2.18);
                gain.gain.setValueAtTime(0.0001, now + 2.12);
                gain.gain.exponentialRampToValueAtTime(engine.gain, now + 2.65);
                gain.gain.setValueAtTime(engine.gain, now + 4.72);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + 5.78);
                oscillator.connect(filter);
                filter.connect(gain);
                gain.connect(masterGain);
                oscillator.start(now + 2.12);
                oscillator.stop(now + 5.85);
            });

            const gameImpact = audioContext.createOscillator();
            const gameImpactGain = audioContext.createGain();
            gameImpact.type = 'sine';
            gameImpact.frequency.setValueAtTime(108, now + 3.72);
            gameImpact.frequency.exponentialRampToValueAtTime(24, now + 4.62);
            gameImpactGain.gain.setValueAtTime(0.0001, now + 3.68);
            gameImpactGain.gain.exponentialRampToValueAtTime(0.46, now + 3.74);
            gameImpactGain.gain.exponentialRampToValueAtTime(0.0001, now + 4.66);
            gameImpact.connect(gameImpactGain);
            gameImpactGain.connect(masterGain);
            gameImpact.start(now + 3.68);
            gameImpact.stop(now + 4.72);

            [55, 82.41, 110, 146.83, 220, 293.66].forEach((frequency, index) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const startAt = now + 3.92 + (index * 0.055);
                oscillator.type = index < 2 ? 'sawtooth' : 'triangle';
                oscillator.frequency.setValueAtTime(frequency, startAt);
                oscillator.frequency.exponentialRampToValueAtTime(frequency * 1.012, startAt + 1.42);
                gain.gain.setValueAtTime(0.0001, startAt);
                gain.gain.exponentialRampToValueAtTime(index < 2 ? 0.13 : 0.075, startAt + 0.08);
                gain.gain.exponentialRampToValueAtTime(0.0001, startAt + 1.65);
                connectWithPan(oscillator, gain, (index - 2.5) / 3.2);
                oscillator.start(startAt);
                oscillator.stop(startAt + 1.72);
            });

            [440, 659.25, 880, 1174.66, 1318.51].forEach((frequency, index) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const startAt = now + 4.18 + (index * 0.16);
                oscillator.type = 'sine';
                oscillator.frequency.setValueAtTime(frequency, startAt);
                gain.gain.setValueAtTime(0.0001, startAt);
                gain.gain.exponentialRampToValueAtTime(0.09, startAt + 0.018);
                gain.gain.exponentialRampToValueAtTime(0.0001, startAt + 0.34);
                connectWithPan(oscillator, gain, index % 2 ? 0.6 : -0.6);
                oscillator.start(startAt);
                oscillator.stop(startAt + 0.38);
            });
        }

        function playDashboardCommandCentreScore() {
            const audioContext = getOverviewAudioContext();
            if (!audioContext) return;

            const now = audioContext.currentTime + 0.01;
            const masterGain = audioContext.createGain();
            const compressor = audioContext.createDynamicsCompressor();
            masterGain.gain.setValueAtTime(0.0001, now);
            masterGain.gain.exponentialRampToValueAtTime(0.2, now + 0.5);
            masterGain.gain.setValueAtTime(0.2, now + 11.7);
            masterGain.gain.exponentialRampToValueAtTime(0.0001, now + 13.1);
            masterGain.connect(compressor);
            compressor.connect(audioContext.destination);

            [55, 82.41].forEach((frequency, index) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const filter = audioContext.createBiquadFilter();
                oscillator.type = index ? 'triangle' : 'sawtooth';
                oscillator.frequency.setValueAtTime(frequency, now);
                oscillator.detune.setValueAtTime(index ? 5 : -7, now);
                filter.type = 'lowpass';
                filter.frequency.setValueAtTime(260, now);
                filter.frequency.exponentialRampToValueAtTime(720, now + 8.8);
                gain.gain.setValueAtTime(0.0001, now);
                gain.gain.exponentialRampToValueAtTime(index ? 0.11 : 0.075, now + 0.85);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + 12.8);
                oscillator.connect(filter);
                filter.connect(gain);
                gain.connect(masterGain);
                oscillator.start(now);
                oscillator.stop(now + 12.95);
            });

            const commandNotes = [110, 146.83, 174.61, 220, 196, 146.83, 174.61, 261.63];
            commandNotes.forEach((frequency, index) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const filter = audioContext.createBiquadFilter();
                const startAt = now + 0.35 + (index * 0.58);
                oscillator.type = index % 3 === 0 ? 'square' : 'triangle';
                oscillator.frequency.setValueAtTime(frequency, startAt);
                oscillator.frequency.exponentialRampToValueAtTime(frequency * 1.01, startAt + 0.38);
                filter.type = 'lowpass';
                filter.frequency.setValueAtTime(860, startAt);
                filter.Q.setValueAtTime(5, startAt);
                gain.gain.setValueAtTime(0.0001, startAt);
                gain.gain.exponentialRampToValueAtTime(0.085, startAt + 0.025);
                gain.gain.exponentialRampToValueAtTime(0.0001, startAt + 0.48);
                oscillator.connect(filter);
                filter.connect(gain);
                gain.connect(masterGain);
                oscillator.start(startAt);
                oscillator.stop(startAt + 0.52);
            });

            const rise = audioContext.createOscillator();
            const riseGain = audioContext.createGain();
            rise.type = 'sine';
            rise.frequency.setValueAtTime(72, now + 0.2);
            rise.frequency.exponentialRampToValueAtTime(880, now + 3.4);
            riseGain.gain.setValueAtTime(0.0001, now + 0.2);
            riseGain.gain.exponentialRampToValueAtTime(0.045, now + 1.2);
            riseGain.gain.exponentialRampToValueAtTime(0.0001, now + 3.5);
            rise.connect(riseGain);
            riseGain.connect(masterGain);
            rise.start(now + 0.2);
            rise.stop(now + 3.6);

            // An original double-tracked power riff gives the command-centre voice a game-intro backbone.
            const guitarDrive = audioContext.createWaveShaper();
            const guitarCabinet = audioContext.createBiquadFilter();
            const guitarHighPass = audioContext.createBiquadFilter();
            const guitarBus = audioContext.createGain();
            const distortionCurve = new Float32Array(4096);
            for (let index = 0; index < distortionCurve.length; index += 1) {
                const input = ((index * 2) / distortionCurve.length) - 1;
                distortionCurve[index] = ((3 + 85) * input * 20 * (Math.PI / 180))
                    / (Math.PI + (85 * Math.abs(input)));
            }
            guitarDrive.curve = distortionCurve;
            guitarDrive.oversample = '4x';
            guitarHighPass.type = 'highpass';
            guitarHighPass.frequency.setValueAtTime(72, now);
            guitarCabinet.type = 'lowpass';
            guitarCabinet.frequency.setValueAtTime(3100, now);
            guitarCabinet.Q.setValueAtTime(1.4, now);
            guitarBus.gain.setValueAtTime(0.0001, now);
            guitarBus.gain.exponentialRampToValueAtTime(0.62, now + 0.72);
            guitarBus.gain.setValueAtTime(0.62, now + 10.8);
            guitarBus.gain.exponentialRampToValueAtTime(0.0001, now + 12.7);
            guitarBus.connect(guitarDrive);
            guitarDrive.connect(guitarHighPass);
            guitarHighPass.connect(guitarCabinet);
            guitarCabinet.connect(masterGain);

            const guitarTracks = [-0.72, 0.72].map((panValue) => {
                if (typeof audioContext.createStereoPanner !== 'function') return guitarBus;
                const panner = audioContext.createStereoPanner();
                panner.pan.setValueAtTime(panValue, now);
                panner.connect(guitarBus);
                return panner;
            });
            const riffPattern = [82.41, 82.41, 98, 82.41, 110, 82.41, 123.47, 110];
            const riffStep = 0.285;
            for (let cycle = 0; cycle < 5; cycle += 1) {
                riffPattern.forEach((rootFrequency, stepIndex) => {
                    const noteIndex = (cycle * riffPattern.length) + stepIndex;
                    const startAt = now + 0.66 + (noteIndex * riffStep);
                    const isAccent = stepIndex === 0 || stepIndex === 4;
                    guitarTracks.forEach((track, trackIndex) => {
                        [1, 1.5, 2].forEach((ratio, harmonicIndex) => {
                            const oscillator = audioContext.createOscillator();
                            const noteGain = audioContext.createGain();
                            oscillator.type = harmonicIndex === 2 ? 'square' : 'sawtooth';
                            oscillator.frequency.setValueAtTime(rootFrequency * ratio, startAt);
                            oscillator.detune.setValueAtTime(trackIndex ? 7 : -7, startAt);
                            noteGain.gain.setValueAtTime(0.0001, startAt);
                            noteGain.gain.exponentialRampToValueAtTime(
                                (isAccent ? 0.045 : 0.03) / (harmonicIndex + 1),
                                startAt + 0.012
                            );
                            noteGain.gain.exponentialRampToValueAtTime(
                                0.0001,
                                startAt + (isAccent ? riffStep * 1.45 : riffStep * 0.76)
                            );
                            oscillator.connect(noteGain);
                            noteGain.connect(track);
                            oscillator.start(startAt);
                            oscillator.stop(startAt + (isAccent ? riffStep * 1.52 : riffStep * 0.84));
                        });
                    });
                });
            }

            const cymbalBuffer = audioContext.createBuffer(1, Math.floor(audioContext.sampleRate * 0.34), audioContext.sampleRate);
            const cymbalData = cymbalBuffer.getChannelData(0);
            for (let index = 0; index < cymbalData.length; index += 1) {
                cymbalData[index] = ((Math.random() * 2) - 1) * (1 - (index / cymbalData.length));
            }
            for (let beat = 0; beat < 20; beat += 1) {
                const beatAt = now + 0.66 + (beat * riffStep * 2);
                const kick = audioContext.createOscillator();
                const kickGain = audioContext.createGain();
                kick.type = 'sine';
                kick.frequency.setValueAtTime(118, beatAt);
                kick.frequency.exponentialRampToValueAtTime(43, beatAt + 0.13);
                kickGain.gain.setValueAtTime(0.0001, beatAt);
                kickGain.gain.exponentialRampToValueAtTime(beat % 4 === 0 ? 0.24 : 0.14, beatAt + 0.008);
                kickGain.gain.exponentialRampToValueAtTime(0.0001, beatAt + 0.19);
                kick.connect(kickGain);
                kickGain.connect(masterGain);
                kick.start(beatAt);
                kick.stop(beatAt + 0.22);

                if (beat % 2 === 0) {
                    const cymbal = audioContext.createBufferSource();
                    const cymbalFilter = audioContext.createBiquadFilter();
                    const cymbalGain = audioContext.createGain();
                    cymbal.buffer = cymbalBuffer;
                    cymbalFilter.type = 'highpass';
                    cymbalFilter.frequency.setValueAtTime(4300, beatAt);
                    cymbalGain.gain.setValueAtTime(0.0001, beatAt);
                    cymbalGain.gain.exponentialRampToValueAtTime(0.055, beatAt + 0.006);
                    cymbalGain.gain.exponentialRampToValueAtTime(0.0001, beatAt + 0.28);
                    cymbal.connect(cymbalFilter);
                    cymbalFilter.connect(cymbalGain);
                    cymbalGain.connect(masterGain);
                    cymbal.start(beatAt);
                    cymbal.stop(beatAt + 0.32);
                }
            }

            return () => {
                const stopAt = audioContext.currentTime;
                masterGain.gain.cancelScheduledValues(stopAt);
                masterGain.gain.setValueAtTime(Math.max(0.0001, masterGain.gain.value), stopAt);
                masterGain.gain.exponentialRampToValueAtTime(0.0001, stopAt + 0.16);
            };
        }

        function getDashboardCommandVoice(voices = []) {
            const englishVoices = voices.filter((voice) => String(voice.lang || '').toLowerCase().startsWith('en'));
            if (!englishVoices.length) return null;

            const preferredNames = ['guy', 'ryan', 'christopher', 'eric', 'roger', 'steffan', 'david', 'mark', 'george', 'daniel', 'male'];
            return englishVoices.slice().sort((left, right) => {
                const score = (voice) => {
                    const name = String(voice.name || '').toLowerCase();
                    let value = voice.default ? 10 : 0;
                    preferredNames.forEach((preferred, index) => {
                        if (name.includes(preferred)) value += 260 - (index * 15);
                    });
                    if (/natural|online|neural/.test(name)) value += 170;
                    if (/male/.test(name)) value += 120;
                    if (/female|aria|jenny|libby|zira|hazel|sonia|ava|emma/.test(name)) value -= 240;
                    if (voice.lang === 'en-GB') value += 35;
                    if (voice.lang === 'en-US') value += 25;
                    return value;
                };
                return score(right) - score(left);
            })[0] || null;
        }

        function stopDashboardCommandCentreIntro() {
            dashboardCommandIntroToken += 1;
            if (typeof dashboardCommandAudioStop === 'function') {
                dashboardCommandAudioStop();
                dashboardCommandAudioStop = null;
            }
            if (supportsSpeechSynthesis) {
                window.speechSynthesis.cancel();
            }
        }

        async function playDashboardCommandCentreIntro(dashboardWindow, options = {}) {
            stopDashboardCommandCentreIntro();
            const introToken = dashboardCommandIntroToken;
            if (typeof options.onStart === 'function') {
                options.onStart();
            }
            stopNarration('dashboard_command_centre');
            const entryDelayMs = Math.max(0, dashboardEntrySequenceEndsAt - Date.now() + 180);
            if (entryDelayMs > 0) {
                await new Promise((resolve) => window.setTimeout(resolve, entryDelayMs));
            }
            if (introToken !== dashboardCommandIntroToken || !dashboardWindow.isConnected) return;
            dashboardCommandAudioStop = playDashboardCommandCentreScore() || null;
            dashboardWindow.classList.remove('is-command-centre-booting');
            dashboardWindow.classList.remove('is-command-centre-ready');
            void dashboardWindow.offsetWidth;
            dashboardWindow.classList.add('is-command-centre-booting');
            window.setTimeout(() => {
                if (introToken !== dashboardCommandIntroToken || !dashboardWindow.isConnected) return;
                dashboardWindow.classList.remove('is-command-centre-booting');
                dashboardWindow.classList.add('is-command-centre-ready');
                playOverviewVictorySound('analytics-dashboard-interface-ready');
                if (typeof options.onFinish === 'function') {
                    options.onFinish();
                }
                window.setTimeout(() => dashboardWindow.classList.remove('is-command-centre-ready'), 1800);
            }, 10900);

            if (!supportsSpeechSynthesis) return;
            const voices = await waitForNarrationVoices();
            if (introToken !== dashboardCommandIntroToken || !dashboardWindow.isConnected) return;
            const voice = getDashboardCommandVoice(voices);
            const utterance = new SpeechSynthesisUtterance(
                'Welcome back, sir. All systems for command centre will be prepared in a few moments. For now, feel free to grab a cup of coffee and have a good day.'
            );
            const isNaturalVoice = Boolean(voice && /natural|online|neural/i.test(voice.name || ''));
            utterance.lang = voice?.lang || 'en-GB';
            utterance.rate = isNaturalVoice ? 1.16 : 1.07;
            utterance.pitch = isNaturalVoice ? 0.72 : 0.58;
            utterance.volume = 1;
            if (voice) utterance.voice = voice;
            window.setTimeout(() => {
                if (introToken !== dashboardCommandIntroToken || !dashboardWindow.isConnected) return;
                window.speechSynthesis.cancel();
                window.speechSynthesis.speak(utterance);
            }, 720);
        }

        function hashOverviewViewKey(value) {
            let hash = 2166136261;
            for (let index = 0; index < value.length; index += 1) {
                hash ^= value.charCodeAt(index);
                hash = Math.imul(hash, 16777619);
            }
            return hash >>> 0;
        }

        function playOverviewButtonSound(viewKey, direction = 'forward') {
            const audioContext = getOverviewAudioContext();
            if (!audioContext) return;

            const hash = hashOverviewViewKey(viewKey || 'root');
            const now = audioContext.currentTime + 0.005;
            const duration = direction === 'back' ? 0.24 : 0.32;
            const types = ['triangle', 'sawtooth', 'square', 'sine'];
            const baseFrequency = 150 + (hash % 210);
            const colorFrequency = 520 + ((hash >>> 4) % 780);
            const glowFrequency = 920 + ((hash >>> 9) % 920);
            const startFrequency = direction === 'back'
                ? baseFrequency * (1.52 + ((hash >>> 2) % 12) / 100)
                : baseFrequency * (0.7 + ((hash >>> 2) % 14) / 100);
            const endFrequency = direction === 'back'
                ? baseFrequency * (0.74 + ((hash >>> 6) % 9) / 100)
                : baseFrequency * (1.48 + ((hash >>> 6) % 16) / 100);

            const masterGain = audioContext.createGain();
            masterGain.gain.setValueAtTime(0.0001, now);
            masterGain.gain.exponentialRampToValueAtTime(0.18, now + 0.018);
            masterGain.gain.exponentialRampToValueAtTime(0.0001, now + duration + 0.06);
            masterGain.connect(audioContext.destination);

            const mainOscillator = audioContext.createOscillator();
            const mainGain = audioContext.createGain();
            mainOscillator.type = types[hash % types.length];
            mainOscillator.frequency.setValueAtTime(startFrequency, now);
            mainOscillator.frequency.exponentialRampToValueAtTime(endFrequency, now + duration);
            mainGain.gain.setValueAtTime(0.0001, now);
            mainGain.gain.exponentialRampToValueAtTime(0.19, now + 0.02);
            mainGain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
            mainOscillator.connect(mainGain);
            mainGain.connect(masterGain);
            mainOscillator.start(now);
            mainOscillator.stop(now + duration + 0.03);

            const colorOscillator = audioContext.createOscillator();
            const colorGain = audioContext.createGain();
            colorOscillator.type = types[(hash >>> 3) % types.length];
            colorOscillator.frequency.setValueAtTime(colorFrequency, now + 0.02);
            colorOscillator.frequency.exponentialRampToValueAtTime(
                direction === 'back' ? colorFrequency * 0.82 : colorFrequency * 1.12,
                now + duration * 0.8
            );
            colorGain.gain.setValueAtTime(0.0001, now + 0.01);
            colorGain.gain.exponentialRampToValueAtTime(0.085, now + 0.045);
            colorGain.gain.exponentialRampToValueAtTime(0.0001, now + duration * 0.85);
            colorOscillator.connect(colorGain);
            colorGain.connect(masterGain);
            colorOscillator.start(now + 0.01);
            colorOscillator.stop(now + duration + 0.02);

            const glowOscillator = audioContext.createOscillator();
            const glowGain = audioContext.createGain();
            glowOscillator.type = 'triangle';
            glowOscillator.frequency.setValueAtTime(glowFrequency, now + 0.03);
            glowOscillator.frequency.exponentialRampToValueAtTime(
                direction === 'back' ? glowFrequency * 0.9 : glowFrequency * 1.18,
                now + duration * 0.62
            );
            glowGain.gain.setValueAtTime(0.0001, now + 0.025);
            glowGain.gain.exponentialRampToValueAtTime(0.042, now + 0.055);
            glowGain.gain.exponentialRampToValueAtTime(0.0001, now + duration * 0.58);
            glowOscillator.connect(glowGain);
            glowGain.connect(masterGain);
            glowOscillator.start(now + 0.025);
            glowOscillator.stop(now + duration * 0.64);

            const clickOscillator = audioContext.createOscillator();
            const clickGain = audioContext.createGain();
            clickOscillator.type = 'square';
            clickOscillator.frequency.setValueAtTime(direction === 'back' ? 1380 : 1180, now);
            clickOscillator.frequency.exponentialRampToValueAtTime(direction === 'back' ? 560 : 740, now + 0.06);
            clickGain.gain.setValueAtTime(0.0001, now);
            clickGain.gain.exponentialRampToValueAtTime(0.03, now + 0.008);
            clickGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.07);
            clickOscillator.connect(clickGain);
            clickGain.connect(masterGain);
            clickOscillator.start(now);
            clickOscillator.stop(now + 0.08);
        }

        function playOverviewVictorySound(viewKey) {
            const audioContext = getOverviewAudioContext();
            if (!audioContext) return;

            const hash = hashOverviewViewKey(viewKey || 'victory');
            const now = audioContext.currentTime + 0.005;
            const masterGain = audioContext.createGain();
            masterGain.gain.setValueAtTime(0.0001, now);
            masterGain.gain.exponentialRampToValueAtTime(0.2, now + 0.02);
            masterGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.62);
            masterGain.connect(audioContext.destination);

            [1, 1.26, 1.6].forEach((ratio, index) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const baseFrequency = 320 + ((hash >>> (index * 3)) % 120);
                oscillator.type = index === 1 ? 'triangle' : 'sine';
                oscillator.frequency.setValueAtTime(baseFrequency * ratio, now + index * 0.055);
                oscillator.frequency.exponentialRampToValueAtTime(baseFrequency * ratio * 1.26, now + 0.22 + index * 0.05);
                gain.gain.setValueAtTime(0.0001, now + index * 0.05);
                gain.gain.exponentialRampToValueAtTime(0.11 - index * 0.02, now + 0.045 + index * 0.05);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.34 + index * 0.07);
                oscillator.connect(gain);
                gain.connect(masterGain);
                oscillator.start(now + index * 0.05);
                oscillator.stop(now + 0.38 + index * 0.08);
            });

            const sparkleOscillator = audioContext.createOscillator();
            const sparkleGain = audioContext.createGain();
            sparkleOscillator.type = 'square';
            sparkleOscillator.frequency.setValueAtTime(1240 + (hash % 200), now + 0.08);
            sparkleOscillator.frequency.exponentialRampToValueAtTime(1880 + (hash % 220), now + 0.18);
            sparkleGain.gain.setValueAtTime(0.0001, now + 0.075);
            sparkleGain.gain.exponentialRampToValueAtTime(0.04, now + 0.1);
            sparkleGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.24);
            sparkleOscillator.connect(sparkleGain);
            sparkleGain.connect(masterGain);
            sparkleOscillator.start(now + 0.075);
            sparkleOscillator.stop(now + 0.25);
        }

        function playRequirementReasonOutcomeSound(outcomeType) {
            const audioContext = getOverviewAudioContext();
            if (!audioContext) return;

            const now = audioContext.currentTime + 0.005;
            const masterGain = audioContext.createGain();
            masterGain.gain.setValueAtTime(0.0001, now);
            masterGain.gain.exponentialRampToValueAtTime(outcomeType === 'nothing' ? 0.16 : 0.14, now + 0.018);
            masterGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.78);
            masterGain.connect(audioContext.destination);

            const notes = outcomeType === 'nothing'
                ? [392, 523.25, 659.25, 783.99]
                : [392, 311.13, 246.94];

            notes.forEach((frequency, index) => {
                const oscillator = audioContext.createOscillator();
                const gain = audioContext.createGain();
                const startAt = now + index * (outcomeType === 'nothing' ? 0.07 : 0.11);
                oscillator.type = outcomeType === 'nothing' ? (index % 2 ? 'triangle' : 'sine') : 'sawtooth';
                oscillator.frequency.setValueAtTime(frequency, startAt);
                oscillator.frequency.exponentialRampToValueAtTime(
                    outcomeType === 'nothing' ? frequency * 1.08 : frequency * 0.78,
                    startAt + 0.18
                );
                gain.gain.setValueAtTime(0.0001, startAt);
                gain.gain.exponentialRampToValueAtTime(outcomeType === 'nothing' ? 0.075 : 0.06, startAt + 0.028);
                gain.gain.exponentialRampToValueAtTime(0.0001, startAt + (outcomeType === 'nothing' ? 0.25 : 0.32));
                oscillator.connect(gain);
                gain.connect(masterGain);
                oscillator.start(startAt);
                oscillator.stop(startAt + 0.36);
            });

            if (outcomeType === 'layer') {
                const thudOscillator = audioContext.createOscillator();
                const thudGain = audioContext.createGain();
                thudOscillator.type = 'triangle';
                thudOscillator.frequency.setValueAtTime(96, now + 0.38);
                thudOscillator.frequency.exponentialRampToValueAtTime(54, now + 0.58);
                thudGain.gain.setValueAtTime(0.0001, now + 0.36);
                thudGain.gain.exponentialRampToValueAtTime(0.075, now + 0.4);
                thudGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.68);
                thudOscillator.connect(thudGain);
                thudGain.connect(masterGain);
                thudOscillator.start(now + 0.36);
                thudOscillator.stop(now + 0.7);
            }
        }

        function playRequirementReasonSlotTick(stepIndex = 0) {
            const audioContext = getOverviewAudioContext();
            if (!audioContext) return;

            const now = audioContext.currentTime + 0.002;
            const masterGain = audioContext.createGain();
            masterGain.gain.setValueAtTime(0.0001, now);
            masterGain.gain.exponentialRampToValueAtTime(0.055, now + 0.006);
            masterGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.07);
            masterGain.connect(audioContext.destination);

            const oscillator = audioContext.createOscillator();
            oscillator.type = stepIndex % 2 ? 'square' : 'triangle';
            oscillator.frequency.setValueAtTime(620 + (stepIndex % 5) * 86, now);
            oscillator.frequency.exponentialRampToValueAtTime(420 + (stepIndex % 3) * 54, now + 0.055);
            oscillator.connect(masterGain);
            oscillator.start(now);
            oscillator.stop(now + 0.075);
        }

        function resetOverviewScrollPosition() {
            const resetScroll = () => {
                const scrollRoot = document.scrollingElement || document.documentElement;
                if (scrollRoot) {
                    scrollRoot.scrollTop = 0;
                    scrollRoot.scrollLeft = 0;
                }
                document.body.scrollTop = 0;
                document.body.scrollLeft = 0;
                window.scrollTo(0, 0);
            };

            resetScroll();
            window.requestAnimationFrame(resetScroll);
        }

        function scheduleSeoAiSummaryFade() {
            if (!seoAiSummary) {
                return;
            }
            if (seoAiSummaryFadeTimer) {
                window.clearTimeout(seoAiSummaryFadeTimer);
            }
            seoAiSummary.classList.remove('is-faded');
            seoAiSummaryFadeTimer = window.setTimeout(() => {
                seoAiSummaryFadeTimer = null;
                seoAiSummary.classList.add('is-faded');
            }, AI_FIELD_NOTE_FADE_DELAY_MS);
        }

        function openTestcaseBridge(item, sourceViewKey = getCurrentViewKey(), soundMode = 'forward') {
            if (!item || !item.target || !getViewDefinition(item.target)) return;
            pendingTestcaseBridge = {
                target: item.target,
                label: item.label || 'Next'
            };
            if (soundMode === 'victory') {
                playOverviewVictorySound(sourceViewKey);
            } else {
                playOverviewButtonSound(sourceViewKey, 'forward');
            }
            historyStack.push('testcase-bridge');
            renderCurrentView({ resetScroll: true });
        }

        function navigateToView(target, sourceViewKey = getCurrentViewKey(), soundMode = 'forward') {
            if (!getViewDefinition(target)) return;
            if (soundMode === 'victory') {
                playOverviewVictorySound(sourceViewKey);
            } else {
                playOverviewButtonSound(sourceViewKey, 'forward');
            }
            historyStack.push(target);
            renderCurrentView({ resetScroll: true });
        }

        function createMenuButton(item) {
            const button = document.createElement('button');
            button.className = 'choice-button';
            button.type = 'button';
            button.dataset.trackId = analyticsText(
                item.trackId || `menu:${item.target || analyticsSlug(item.label)}`,
                160
            );
            button.dataset.trackLabel = analyticsText(item.label, 255);
            if (item.target) {
                button.dataset.trackTarget = analyticsText(item.target, 120);
            }
            if (item.compact) {
                button.classList.add('is-compact');
            }
            if (item.tone === 'green') {
                button.classList.add('is-tone-green');
            } else if (item.tone === 'blue') {
                button.classList.add('is-tone-blue');
            } else if (item.tone === 'slate') {
                button.classList.add('is-tone-slate');
            } else if (item.tone === 'red') {
                button.classList.add('is-tone-red');
            }
            if (item.fullRow) {
                button.classList.add('is-span-full');
            }
            if (item.small) {
                button.classList.add('is-small');
            }
            if (item.centered || String(item.label || '').trim().toLowerCase() === 'next') {
                button.classList.add('is-centered');
            }
            button.innerHTML = `<span class="choice-label">${item.label}</span>`;
            if (item.copy) {
                const copy = document.createElement('span');
                copy.className = 'choice-copy';
                copy.textContent = item.copy;
                button.appendChild(copy);
            }
            button.addEventListener('click', () => {
                const sourceViewKey = getCurrentViewKey();
                const soundMode = item.soundMode || 'forward';
                if (item.url) {
                    if (soundMode === 'victory') {
                        playOverviewVictorySound(sourceViewKey);
                    } else {
                        playOverviewButtonSound(sourceViewKey, 'forward');
                    }
                    window.open(
                        item.url,
                        item.newWindow ? '_blank' : '_self',
                        item.newWindow ? 'noopener,noreferrer' : undefined
                    );
                    return;
                }
                if (item.bridgeBeforeTarget) {
                    openTestcaseBridge(item, sourceViewKey, soundMode);
                    return;
                }
                navigateToView(item.target, sourceViewKey, soundMode);
            });
            return button;
        }

        function createInfoFrame(frame) {
            const element = document.createElement('article');
            element.className = 'info-frame';
            const titleMarkup = `<h2 class="info-title">${frame.title}</h2>`;
            if (Array.isArray(frame.list)) {
                const listMarkup = frame.list.map((entry) => `<li>${entry}</li>`).join('');
                element.innerHTML = `${titleMarkup}<ul class="info-list">${listMarkup}</ul>`;
                return element;
            }
            if (typeof frame.html === 'string' && frame.html.trim()) {
                element.innerHTML = `${titleMarkup}${frame.html}`;
                return element;
            }
            if (frame.table && Array.isArray(frame.table.columns) && Array.isArray(frame.table.rows)) {
                element.innerHTML = titleMarkup;
                if (frame.copy) {
                    const copy = document.createElement('p');
                    copy.className = 'info-copy';
                    copy.textContent = frame.copy;
                    element.appendChild(copy);
                }
                const wrap = document.createElement('div');
                wrap.className = 'info-table-wrap';
                const table = document.createElement('table');
                table.className = 'info-table';
                const thead = document.createElement('thead');
                const headRow = document.createElement('tr');
                frame.table.columns.forEach((column) => {
                    const th = document.createElement('th');
                    th.scope = 'col';
                    th.textContent = column;
                    headRow.appendChild(th);
                });
                thead.appendChild(headRow);
                table.appendChild(thead);
                const tbody = document.createElement('tbody');
                frame.table.rows.forEach((row) => {
                    const rowConfig = Array.isArray(row) ? { cells: row } : row;
                    const tr = document.createElement('tr');
                    if (rowConfig.target && getViewDefinition(rowConfig.target)) {
                        tr.classList.add('is-clickable');
                        tr.tabIndex = 0;
                        tr.setAttribute('role', 'button');
                        tr.setAttribute('aria-label', `Open ${rowConfig.cells[0]}`);
                        const activateRow = () => {
                            navigateToView(
                                rowConfig.target,
                                `${getCurrentViewKey()}-${rowConfig.target}-row`,
                                rowConfig.sound === 'victory' ? 'victory' : 'forward'
                            );
                        };
                        tr.addEventListener('click', activateRow);
                        tr.addEventListener('keydown', (event) => {
                            if (event.key !== 'Enter' && event.key !== ' ') return;
                            event.preventDefault();
                            activateRow();
                        });
                    }
                    (rowConfig.cells || []).forEach((cell) => {
                        const td = document.createElement('td');
                        td.textContent = cell;
                        tr.appendChild(td);
                    });
                    tbody.appendChild(tr);
                });
                table.appendChild(tbody);
                wrap.appendChild(table);
                element.appendChild(wrap);
                return element;
            }
            element.innerHTML = `${titleMarkup}<p class="info-copy">${frame.copy || ''}</p>`;
            return element;
        }

        function renderMenu(view) {
            if (view.layout === 'decision') {
                renderDecisionMenu(view);
                return;
            }

            const grid = document.createElement('div');
            const layoutClass = view.layout === 'triple'
                ? 'choice-grid is-triple'
                : view.layout === 'single'
                    ? 'choice-grid is-single'
                    : view.layout === 'decision'
                        ? 'choice-grid is-decision'
                    : 'choice-grid';
            grid.className = layoutClass;
            (view.items || []).forEach((item) => {
                const nextItem = view.compact ? { ...item, compact: true } : item;
                grid.appendChild(createMenuButton(nextItem));
            });
            overviewContent.appendChild(grid);
        }

        function renderDecisionMenu(view) {
            const layout = document.createElement('div');
            layout.className = 'decision-layout';

            const statusRow = document.createElement('div');
            statusRow.className = 'decision-status-row';

            const intentShell = document.createElement('section');
            intentShell.className = 'decision-intent-shell';

            const intentGrid = document.createElement('div');
            intentGrid.className = 'decision-intent-grid';

            const proofColumn = document.createElement('div');
            proofColumn.className = 'decision-intent-column is-proof';

            const discoveryColumn = document.createElement('div');
            discoveryColumn.className = 'decision-intent-column is-discovery';

            (view.items || []).forEach((item) => {
                const button = createMenuButton(view.compact ? { ...item, compact: true } : item);
                if (item.decisionGroup === 'status') {
                    statusRow.appendChild(button);
                    return;
                }
                if (item.decisionGroup === 'proof') {
                    proofColumn.appendChild(button);
                    return;
                }
                discoveryColumn.appendChild(button);
            });

            if (statusRow.childElementCount) {
                layout.appendChild(statusRow);
                window.setTimeout(() => {
                    if (!statusRow.isConnected) {
                        return;
                    }
                    statusRow.classList.add('is-faded');
                    layout.classList.add('is-status-faded');
                }, 10000);
            }

            if (proofColumn.childElementCount || discoveryColumn.childElementCount) {
                if (proofColumn.childElementCount) {
                    intentGrid.appendChild(proofColumn);
                }
                if (discoveryColumn.childElementCount) {
                    intentGrid.appendChild(discoveryColumn);
                }
                intentShell.appendChild(intentGrid);
                layout.appendChild(intentShell);
            }

            overviewContent.appendChild(layout);
        }

        function renderTestcaseBridge(view) {
            const stage = document.createElement('div');
            stage.className = 'testcase-bridge-stage';

            const frame = document.createElement('section');
            frame.className = 'testcase-bridge-frame';
            frame.setAttribute('aria-label', 'Requirement to testcase to end-goal flow');
            frame.innerHTML = `
                <div class="testcase-bridge-diagram">
                    <div class="testcase-bridge-point">
                        <div class="testcase-bridge-dot" aria-hidden="true"></div>
                        <div class="testcase-bridge-label">requirement</div>
                    </div>
                    <div class="testcase-bridge-arrow" aria-label="testcase">
                        <div class="testcase-bridge-arrow-track" aria-hidden="true"></div>
                        <div class="testcase-bridge-arrow-label">testcase</div>
                        <div class="testcase-bridge-bug-route" aria-hidden="true">
                            <svg class="testcase-bridge-bug-svg" viewBox="0 0 360 138" preserveAspectRatio="none" focusable="false">
                                <path class="testcase-bridge-bug-path" d="M 168 112 C 200 112, 196 30, 304 30"></path>
                            </svg>
                            <span class="testcase-bridge-bug-arrowhead"></span>
                            <div class="testcase-bridge-bug-marker">
                                <span class="testcase-bridge-bug-icon"></span>
                                <span>bug</span>
                            </div>
                        </div>
                    </div>
                    <div class="testcase-bridge-point">
                        <div class="testcase-bridge-dot is-finish" aria-hidden="true"></div>
                        <div class="testcase-bridge-label">end-goal<br>(f.e. verified)</div>
                    </div>
                </div>
            `;

            const actions = document.createElement('div');
            actions.className = 'testcase-bridge-actions';

            const nextButton = document.createElement('button');
            nextButton.className = 'choice-button is-compact is-tone-blue is-centered';
            nextButton.type = 'button';
            nextButton.innerHTML = '<span class="choice-label">Next</span>';
            nextButton.addEventListener('click', () => {
                navigateToView('technique-interaction-table', `${getCurrentViewKey()}-next`, 'forward');
            });

            actions.appendChild(nextButton);
            stage.appendChild(frame);
            stage.appendChild(actions);
            overviewContent.appendChild(stage);
        }

        function createTechniqueLight(isOn) {
            const light = document.createElement('span');
            light.className = `technique-light ${isOn ? 'is-on' : 'is-off'}`;
            light.setAttribute('aria-hidden', 'true');
            return light;
        }

        function renderTechniqueInteractionTable(view) {
            const stage = document.createElement('div');
            stage.className = 'technique-link-stage';

            const legend = document.createElement('section');
            legend.className = 'technique-link-legend';
            legend.setAttribute('aria-label', 'Test techniques connected to the three decision table lights');
            legend.innerHTML = `
                <button class="technique-link-card" type="button" data-light-index="0" data-technique="Boundary Value Analysis" aria-pressed="false" aria-label="Show example for Boundary Value Analysis">
                    <span class="technique-link-card-inner">
                        <span class="technique-link-card-face is-front">
                            <span class="technique-link-code">L1</span>
                            <span class="technique-link-card-title">Boundary Value Analysis</span>
                            <span class="technique-link-card-copy">This light can represent whether a value touches or crosses a critical boundary.</span>
                            <span class="technique-link-card-hint">Click to reveal example</span>
                        </span>
                        <span class="technique-link-card-face is-back">
                            <span class="technique-link-code">L1 example</span>
                            <span class="technique-link-example-title">Age range: 18 to 65</span>
                            <span class="technique-link-example-copy">Test the values 17, 18, 19, 64, 65, and 66 around both boundaries.</span>
                            <span class="technique-link-card-hint">Click to return</span>
                        </span>
                    </span>
                </button>
                <button class="technique-link-card" type="button" data-light-index="1" data-technique="Equivalence Partitioning" aria-pressed="false" aria-label="Show example for Equivalence Partitioning">
                    <span class="technique-link-card-inner">
                        <span class="technique-link-card-face is-front">
                            <span class="technique-link-code">L2</span>
                            <span class="technique-link-card-title">Equivalence Partitioning</span>
                            <span class="technique-link-card-copy">This light can represent whether a value belongs to a selected valid or invalid class.</span>
                            <span class="technique-link-card-hint">Click to reveal example</span>
                        </span>
                        <span class="technique-link-card-face is-back">
                            <span class="technique-link-code">L2 example</span>
                            <span class="technique-link-example-title">Input range: 1 to 100</span>
                            <span class="technique-link-example-copy">Choose one value from each class: 50 is valid, 0 is too low, and 101 is too high.</span>
                            <span class="technique-link-card-hint">Click to return</span>
                        </span>
                    </span>
                </button>
                <button class="technique-link-card" type="button" data-light-index="2" data-technique="State Transition Testing" aria-pressed="false" aria-label="Show example for State Transition Testing">
                    <span class="technique-link-card-inner">
                        <span class="technique-link-card-face is-front">
                            <span class="technique-link-code">L3</span>
                            <span class="technique-link-card-title">State Transition Testing</span>
                            <span class="technique-link-card-copy">This light can represent whether the application has entered the expected state.</span>
                            <span class="technique-link-card-hint">Click to reveal example</span>
                        </span>
                        <span class="technique-link-card-face is-back">
                            <span class="technique-link-code">L3 example</span>
                            <span class="technique-link-example-title">Three failed logins</span>
                            <span class="technique-link-example-copy">Test Active to Warning to Locked, then verify the reset or unlock transition.</span>
                            <span class="technique-link-card-hint">Click to return</span>
                        </span>
                    </span>
                </button>
            `;

            const frame = document.createElement('section');
            frame.className = 'technique-link-frame';
            frame.innerHTML = `
                <h2 class="technique-link-frame-title">Decision table</h2>
                <p class="technique-link-frame-copy">Each row is one combined application state. The result of one test flow can switch one light, while another technique controls the next.</p>
            `;

            const tableWrap = document.createElement('div');
            tableWrap.className = 'technique-link-table-wrap';

            const table = document.createElement('table');
            table.className = 'technique-link-table';
            table.setAttribute('aria-label', 'Eight possible on and off combinations for lights L1, L2, and L3');

            const lightLabels = ['L1', 'L2', 'L3'];
            const head = document.createElement('thead');
            const headRow = document.createElement('tr');
            lightLabels.forEach((label, index) => {
                const th = document.createElement('th');
                th.scope = 'col';
                const content = document.createElement('span');
                content.className = 'technique-link-head';
                const headerLight = createTechniqueLight(true);
                headerLight.classList.add('is-table-header');
                headerLight.dataset.lightIndex = String(index);
                content.appendChild(headerLight);
                content.appendChild(document.createTextNode(label));
                th.appendChild(content);
                headRow.appendChild(th);
            });
            head.appendChild(headRow);
            table.appendChild(head);

            const combinations = [
                [false, false, false],
                [false, false, true],
                [false, true, false],
                [false, true, true],
                [true, false, false],
                [true, false, true],
                [true, true, false],
                [true, true, true]
            ];
            const body = document.createElement('tbody');
            combinations.forEach((combination) => {
                const row = document.createElement('tr');
                row.setAttribute(
                    'aria-label',
                    combination.map((isOn, index) => `${lightLabels[index]} ${isOn ? 'on' : 'off'}`).join(', ')
                );
                combination.forEach((isOn, index) => {
                    const cell = document.createElement('td');
                    cell.setAttribute('aria-label', `${lightLabels[index]} ${isOn ? 'on' : 'off'}`);
                    cell.appendChild(createTechniqueLight(isOn));
                    row.appendChild(cell);
                });
                body.appendChild(row);
            });
            table.appendChild(body);
            tableWrap.appendChild(table);
            frame.appendChild(tableWrap);

            const blinkTimers = new Map();
            const blinkTechniqueLight = (lightIndex) => {
                const normalizedLightIndex = String(lightIndex);
                const headerLight = table.querySelector(
                    `.technique-light.is-table-header[data-light-index="${normalizedLightIndex}"]`
                );
                if (!headerLight) {
                    return;
                }

                const existingTimer = blinkTimers.get(normalizedLightIndex);
                if (existingTimer) {
                    window.clearTimeout(existingTimer);
                }
                headerLight.classList.remove('is-blinking');
                void headerLight.offsetWidth;
                headerLight.classList.add('is-blinking');
                blinkTimers.set(normalizedLightIndex, window.setTimeout(() => {
                    headerLight.classList.remove('is-blinking');
                    blinkTimers.delete(normalizedLightIndex);
                }, 1250));
            };

            legend.querySelectorAll('.technique-link-card').forEach((card) => {
                card.addEventListener('click', () => {
                    const lightIndex = card.dataset.lightIndex || '0';
                    const technique = card.dataset.technique || 'test technique';
                    const isFlipped = card.classList.toggle('is-flipped');
                    card.setAttribute('aria-pressed', isFlipped ? 'true' : 'false');
                    card.setAttribute(
                        'aria-label',
                        isFlipped ? `Return to ${technique} overview` : `Show example for ${technique}`
                    );

                    blinkTechniqueLight(lightIndex);

                    playOverviewButtonSound(`${getCurrentViewKey()}-${lightIndex}-flip`, 'forward');
                });
            });

            const equation = document.createElement('div');
            equation.className = 'technique-link-equation';
            equation.setAttribute('aria-label', 'L1 result plus L2 result plus L3 result determines what to test next');
            equation.innerHTML = `
                <span class="technique-link-equation-part">L1 result</span>
                <span aria-hidden="true">+</span>
                <span class="technique-link-equation-part">L2 result</span>
                <span aria-hidden="true">+</span>
                <span class="technique-link-equation-part">L3 result</span>
                <span aria-hidden="true">=</span>
                <span class="technique-link-equation-result">What to test next</span>
            `;
            frame.appendChild(equation);

            const actions = document.createElement('div');
            actions.className = 'technique-link-actions';
            const nextButton = document.createElement('button');
            nextButton.className = 'choice-button is-compact is-tone-blue is-centered';
            nextButton.type = 'button';
            nextButton.innerHTML = '<span class="choice-label">Next</span>';
            nextButton.addEventListener('click', () => {
                navigateToView('integration-testing', `${getCurrentViewKey()}-next`, 'forward');
            });
            actions.appendChild(nextButton);

            stage.appendChild(legend);
            stage.appendChild(frame);
            stage.appendChild(actions);
            overviewContent.appendChild(stage);

            window.setTimeout(() => {
                const cards = Array.from(legend.querySelectorAll('.technique-link-card'));
                cards.forEach((card, index) => {
                    window.setTimeout(() => {
                        if (!stage.isConnected || card.classList.contains('is-flipped')) {
                            return;
                        }
                        const lightIndex = card.dataset.lightIndex || String(index);
                        card.classList.remove('is-demo-spinning');
                        void card.offsetWidth;
                        card.classList.add('is-demo-spinning');
                        blinkTechniqueLight(lightIndex);
                        window.setTimeout(() => {
                            card.classList.remove('is-demo-spinning');
                        }, 1220);
                    }, index * 420);
                });
            }, 540);
        }

        function renderIntegrationTesting() {
            const stage = document.createElement('div');
            stage.className = 'integration-testing-stage';

            const intro = document.createElement('p');
            intro.className = 'integration-testing-intro';
            intro.textContent = 'Integration testing checks whether features that work on their own still work when they share data, rules, and application flows.';

            const release = document.createElement('section');
            release.className = 'integration-release';
            release.setAttribute('aria-label', 'Release 1.8 integration branch with three switchable features');
            release.innerHTML = `
                <header class="integration-release-head">
