        async function fetchAnalyticsDashboard(token, period, includeIpAddresses = false) {
            if (window.location.pathname.toLowerCase().endsWith('.html')) {
                await new Promise((resolve) => window.setTimeout(resolve, 260));
                return getDashboardPreviewData(period, includeIpAddresses);
            }
            const response = await window.fetch(
                `${ANALYTICS_ENDPOINT}?dashboard=1&period=${encodeURIComponent(period)}${includeIpAddresses ? '&include_ips=1' : ''}`,
                {
                    method: 'GET',
                    credentials: 'same-origin',
                    cache: 'no-store',
                    headers: { 'X-Analytics-Dashboard-Token': token }
                }
            );
            let payload = null;
            try {
                payload = await response.json();
            } catch (error) {
                payload = null;
            }
            if (!response.ok || !payload || !payload.ok) {
                const dashboardError = new Error(payload?.error || `Dashboard request failed (${response.status}).`);
                dashboardError.status = response.status;
                throw dashboardError;
            }
            return payload.data;
        }

        function renderAnalyticsDashboardAccess(stage, statusText, onSubmit) {
            stage.innerHTML = `
                <div class="analytics-dashboard-access">
                    <section class="analytics-dashboard-access-card">
                        <div class="analytics-dashboard-access-icon" aria-hidden="true">&#9670;</div>
                        <h2 class="analytics-dashboard-access-title">Private telemetry</h2>
                        <p class="analytics-dashboard-access-copy">Enter your private dashboard access code. It is kept only for this browser tab.</p>
                        <form class="analytics-dashboard-access-form">
                            <input class="analytics-dashboard-access-input" type="password" autocomplete="current-password" placeholder="Dashboard access code" aria-label="Dashboard access code" required>
                            <button class="analytics-dashboard-access-submit" type="submit">Unlock</button>
                        </form>
                        <p class="analytics-dashboard-access-status" aria-live="polite">${escapeDashboardHtml(statusText || '')}</p>
                    </section>
                </div>
            `;
            const form = stage.querySelector('.analytics-dashboard-access-form');
            const input = stage.querySelector('.analytics-dashboard-access-input');
            form.addEventListener('submit', (event) => {
                event.preventDefault();
                const token = input.value.trim();
                if (token) onSubmit(token);
            });
            input.focus();
        }

        function renderAnalyticsDashboardData(stage, data, period, onPeriodChange) {
            const summary = data.summary || {};
            const counts = data.session_counts || {};
            const showIpAddresses = data.ip_addresses_included === true;
            const deviceTotal = Math.max(0, Number(summary.mobile || 0) + Number(summary.tablet || 0) + Number(summary.desktop || 0));
            const mobileAngle = deviceTotal ? (Number(summary.mobile || 0) / deviceTotal) * 360 : 0;
            const tabletAngle = mobileAngle + (deviceTotal ? (Number(summary.tablet || 0) / deviceTotal) * 360 : 0);
            const timeline = Array.isArray(data.timeline) ? data.timeline : [];
            const timelineMaximum = Math.max(1, ...timeline.flatMap((item) => [Number(item.sessions) || 0, Number(item.clicks) || 0]));
            const audio = data.audio || {};
            const audioStarts = Number(audio.manual_starts || 0) + Number(audio.autoplay_starts || 0);
            const audioCompletionRate = audioStarts > 0 ? (Number(audio.completions || 0) / audioStarts) * 100 : 0;
            const initialAutoplayTotal = Number(audio.initial_autoplay_on || 0) + Number(audio.initial_autoplay_off || 0);
            const initialAutoplayOnRate = initialAutoplayTotal > 0
                ? (Number(audio.initial_autoplay_on || 0) / initialAutoplayTotal) * 100
                : 0;
            const ratings = data.ratings || {};
            const ratingsAvailable = ratings.available === true;
            const ratingSummary = ratings.summary || {};
            const ratingTotal = Math.max(0, Number(ratingSummary.ratings || 0));
            const ratingUpTotal = Math.max(0, Number(ratingSummary.thumbs_up || 0));
            const ratingDownTotal = Math.max(0, Number(ratingSummary.thumbs_down || 0));
            const ratingUpShare = ratingTotal > 0 ? (ratingUpTotal / ratingTotal) * 100 : 0;
            const ratingAverage = Number(ratingSummary.average_signed_score || 0);
            const formatSignedRating = (value) => {
                const number = Number(value) || 0;
                return `${number > 0 ? '+' : ''}${formatDashboardNumber(number, 2)}`;
            };
            const ratingScoreMarkup = (value) => {
                const number = Number(value) || 0;
                const color = number < 0 ? '#ff5872' : (number > 0 ? '#58e29b' : '#b8d7de');
                return `<span class="analytics-dashboard-rating-score" style="--rating-score-color:${color}">${escapeDashboardHtml(formatSignedRating(number))}</span>`;
            };
            const topClicksMarkup = (data.top_clicks || []).length
                ? data.top_clicks.map((item, index) => `
                    <div class="analytics-dashboard-rank">
                        <span class="analytics-dashboard-rank-copy">${index + 1}. ${escapeDashboardHtml(item.element_label)}</span>
                        <span class="analytics-dashboard-rank-count">${formatDashboardNumber(item.clicks)}</span>
                    </div>
                `).join('')
                : '<p class="analytics-dashboard-empty">No clicks recorded in this period yet.</p>';
            const transitionsMarkup = (data.transitions || []).length
                ? data.transitions.map((item) => `
                    <div class="analytics-dashboard-transition">
                        <span class="analytics-dashboard-transition-copy">${escapeDashboardHtml(item.from)} &rarr; ${escapeDashboardHtml(item.to)}</span>
                        <span class="analytics-dashboard-transition-count">${formatDashboardNumber(item.count)}</span>
                    </div>
                `).join('')
                : '<p class="analytics-dashboard-empty">No multi-page paths recorded in this period yet.</p>';
            const sessionRows = (data.recent_sessions || []).length
                ? data.recent_sessions.map((item) => `
                    <tr>
                        <td>${escapeDashboardHtml(item.session)}</td>
                        <td class="analytics-dashboard-journey-when">
                            <strong>Started ${escapeDashboardHtml(formatDashboardTimestamp(item.started_at) || 'unknown')}</strong>
                            <span>Last active ${escapeDashboardHtml(formatDashboardTimestamp(item.last_seen_at) || 'unknown')}</span>
                        </td>
                        ${showIpAddresses ? `<td>${escapeDashboardHtml(item.ip_address || 'unknown')}</td>` : ''}
                        <td>${escapeDashboardHtml(item.device)}</td>
                        <td>${escapeDashboardHtml(item.entry_page)}</td>
                        <td>${escapeDashboardHtml(item.entry_view)}</td>
                        <td>${escapeDashboardHtml(item.last_view)}</td>
                        <td>${formatDashboardDuration(item.duration_seconds)}</td>
                        <td>${formatDashboardNumber(item.clicks)}</td>
                        <td>${formatDashboardNumber(item.path_length)}</td>
                    </tr>
                `).join('')
                : `<tr><td colspan="${showIpAddresses ? 10 : 9}">No sessions recorded in this period yet.</td></tr>`;
            const externalLinkClicks = data.external_link_clicks || {};
            const externalTotals = Array.isArray(externalLinkClicks.totals) ? externalLinkClicks.totals : [];
            const externalTotalLabels = ['More about me', 'Try the next level'];
            const externalTotalsMarkup = externalTotalLabels.map((label) => {
                const item = externalTotals.find((total) => total.cta_label === label) || {};
                return `
                    <article class="analytics-dashboard-external-card">
                        <span class="analytics-dashboard-external-label">${escapeDashboardHtml(label)}</span>
                        <strong class="analytics-dashboard-external-value">${formatDashboardNumber(item.clicks || 0)}</strong>
                        <span class="analytics-dashboard-external-meta">${formatDashboardNumber(item.sessions || 0)} sessions${item.last_clicked_at ? ` &middot; last ${escapeDashboardHtml(formatDashboardTimestamp(item.last_clicked_at))}` : ''}</span>
                    </article>
                `;
            }).join('');
            const externalRecentRows = (externalLinkClicks.recent || []).length
                ? externalLinkClicks.recent.map((item) => `
                    <tr>
                        <td>${escapeDashboardHtml(formatDashboardTimestamp(item.clicked_at || item.server_received_at))}</td>
                        <td>${escapeDashboardHtml(item.cta_label)}</td>
                        <td>${escapeDashboardHtml(item.session || 'unknown')}</td>
                        ${showIpAddresses ? `<td>${escapeDashboardHtml(item.ip_address || 'unknown')}</td>` : ''}
                        <td>${escapeDashboardHtml(item.device || 'unknown')}</td>
                        <td>${escapeDashboardHtml(item.page_path || '')}</td>
                        <td>${escapeDashboardHtml(item.view_key || '')}</td>
                        <td>${item.element_href ? `<a class="analytics-dashboard-outbound-link" href="${escapeDashboardHtml(item.element_href)}" target="_blank" rel="noopener noreferrer">open</a>` : ''}</td>
                    </tr>
                `).join('')
                : `<tr><td colspan="${showIpAddresses ? 8 : 7}">No Field Guide external clicks recorded in this period yet.</td></tr>`;
            const audioPageRows = (audio.pages || []).length
                ? audio.pages.map((item) => `
                    <tr>
                        <td>${escapeDashboardHtml(item.view_key)}</td>
                        <td>${formatDashboardNumber(item.starts)}</td>
                        <td>${formatDashboardNumber(item.autoplay_starts)}</td>
                        <td>${formatDashboardNumber(item.manual_starts)}</td>
                        <td>${formatDashboardNumber(item.completion_rate, 1)}%</td>
                        <td>${formatDashboardNumber(item.stops)}</td>
                        <td>${formatDashboardDuration(item.average_listened_seconds)}</td>
                    </tr>
                `).join('')
                : '<tr><td colspan="7">No page-level audio activity recorded yet.</td></tr>';
            const ratingDistribution = Array.isArray(ratings.distribution) ? ratings.distribution : [];
            const ratingDistributionMaximum = Math.max(1, ...ratingDistribution.map((item) => Number(item.ratings) || 0));
            const ratingDistributionMarkup = [5, 4, 3, 2, 1].map((score) => {
                const up = Number(ratingDistribution.find((item) => item.sentiment === 'up' && Number(item.score) === score)?.ratings || 0);
                const down = Number(ratingDistribution.find((item) => item.sentiment === 'down' && Number(item.score) === score)?.ratings || 0);
                return `
                    <div class="analytics-dashboard-rating-distribution-row">
                        <span>&minus;${score} &middot; ${formatDashboardNumber(down)}</span>
                        <span class="analytics-dashboard-rating-distribution-track" style="--down-width:${(down / ratingDistributionMaximum) * 50}%;--up-width:${(up / ratingDistributionMaximum) * 50}%"><i></i><i></i></span>
                        <span>${formatDashboardNumber(up)} &middot; +${score}</span>
                    </div>
                `;
            }).join('');
            const ratingPageRows = (ratings.pages || []).length
                ? ratings.pages.map((item) => `
                    <tr>
                        <td>${escapeDashboardHtml(item.view_title || item.view_key)}</td>
                        <td>${escapeDashboardHtml(item.view_key)}</td>
                        <td>${formatDashboardNumber(item.ratings)}</td>
                        <td>${formatDashboardNumber(item.thumbs_up)} / ${formatDashboardNumber(item.thumbs_down)}</td>
                        <td>${ratingScoreMarkup(item.average_signed_score)}</td>
                        <td>${formatDashboardNumber(item.average_strength, 2)}/5</td>
                        <td>${escapeDashboardHtml(formatDashboardTimestamp(item.last_rated_at))}</td>
                    </tr>
                `).join('')
                : '<tr><td colspan="7">No page ratings recorded in this period yet.</td></tr>';
            const ratingVisitorRows = (ratings.visitors || []).length
                ? ratings.visitors.map((item) => `
                    <tr>
                        <td>${escapeDashboardHtml(item.visitor || 'unknown')}</td>
                        <td>${formatDashboardNumber(item.ratings)}</td>
                        <td>${formatDashboardNumber(item.rated_pages)}</td>
                        <td>${formatDashboardNumber(item.thumbs_up)} / ${formatDashboardNumber(item.thumbs_down)}</td>
                        <td>${ratingScoreMarkup(item.average_signed_score)}</td>
                        <td>${formatDashboardNumber(item.average_strength, 2)}/5</td>
                        <td>${escapeDashboardHtml(formatDashboardTimestamp(item.last_rated_at))}</td>
                    </tr>
                `).join('')
                : '<tr><td colspan="7">No visitor rating profiles recorded in this period yet.</td></tr>';
            const ratingRecentRows = (ratings.recent || []).length
                ? ratings.recent.map((item) => `
                    <tr>
                        <td>${escapeDashboardHtml(formatDashboardTimestamp(item.rated_at))}</td>
                        <td>${escapeDashboardHtml(item.view_title || item.view_key)}</td>
                        <td>${ratingScoreMarkup(item.signed_score)}</td>
                        <td>${escapeDashboardHtml(item.sentiment)} ${formatDashboardNumber(item.score)}/5</td>
                        <td>${escapeDashboardHtml(item.visitor || 'unknown')}</td>
                        <td>${escapeDashboardHtml(item.session || 'unknown')}</td>
                        ${showIpAddresses ? `<td>${escapeDashboardHtml(item.ip_address || 'unknown')}</td>` : ''}
                        <td>${escapeDashboardHtml(item.device || 'unknown')}</td>
                        <td>${formatDashboardNumber(item.revision_count || 1)}</td>
                    </tr>
                `).join('')
                : `<tr><td colspan="${showIpAddresses ? 9 : 8}">No recent ratings recorded in this period yet.</td></tr>`;
            const timelineMarkup = timeline.map((item) => {
                const sessionsHeight = Math.max(2, ((Number(item.sessions) || 0) / timelineMaximum) * 100);
                const clicksHeight = Math.max(2, ((Number(item.clicks) || 0) / timelineMaximum) * 100);
                const tooltip = `${item.date}: ${item.sessions} sessions, ${item.clicks} clicks`;
                return `
                    <div class="analytics-dashboard-timeline-day" data-tooltip="${escapeDashboardHtml(tooltip)}">
                        <span class="analytics-dashboard-timeline-bar" style="height:${sessionsHeight}%"></span>
                        <span class="analytics-dashboard-timeline-bar is-clicks" style="height:${clicksHeight}%"></span>
                    </div>
                `;
            }).join('');

            stage.innerHTML = `
                <div class="analytics-dashboard-content">
                    <div class="analytics-dashboard-toolbar">
                        <div class="analytics-dashboard-periods" aria-label="Dashboard period">
                            <button class="analytics-dashboard-period ${period === 'day' ? 'is-active' : ''}" type="button" data-period="day">Day</button>
                            <button class="analytics-dashboard-period ${period === 'week' ? 'is-active' : ''}" type="button" data-period="week">Week</button>
                            <button class="analytics-dashboard-period ${period === 'month' ? 'is-active' : ''}" type="button" data-period="month">Month</button>
                        </div>
                        <span class="analytics-dashboard-updated">Updated ${escapeDashboardHtml(new Date(data.generated_at).toLocaleString())}</span>
                    </div>

                    <section class="analytics-dashboard-session-grid" aria-label="Session totals">
                        <article class="analytics-dashboard-session-card"><strong class="analytics-dashboard-value">${formatDashboardNumber(counts.day)}</strong><span class="analytics-dashboard-label">Sessions today</span></article>
                        <article class="analytics-dashboard-session-card"><strong class="analytics-dashboard-value">${formatDashboardNumber(counts.week)}</strong><span class="analytics-dashboard-label">Sessions 7 days</span></article>
                        <article class="analytics-dashboard-session-card"><strong class="analytics-dashboard-value">${formatDashboardNumber(counts.month)}</strong><span class="analytics-dashboard-label">Sessions 30 days</span></article>
                    </section>

                    <section class="analytics-dashboard-metric-grid" aria-label="Selected period metrics">
                        <article class="analytics-dashboard-metric"><strong class="analytics-dashboard-metric-value">${formatDashboardDuration(summary.average_duration_seconds)}</strong><span class="analytics-dashboard-label">Average active visit</span></article>
                        <article class="analytics-dashboard-metric"><strong class="analytics-dashboard-metric-value">${formatDashboardNumber(summary.clicks)}</strong><span class="analytics-dashboard-label">Total clicks</span></article>
                        <article class="analytics-dashboard-metric"><strong class="analytics-dashboard-metric-value">${formatDashboardNumber(summary.average_clicks, 1)}</strong><span class="analytics-dashboard-label">Clicks / session</span></article>
                        <article class="analytics-dashboard-metric"><strong class="analytics-dashboard-metric-value">${formatDashboardNumber(summary.average_path_length, 1)}</strong><span class="analytics-dashboard-label">Average path</span></article>
                    </section>

                    <section class="analytics-dashboard-columns">
                        <article class="analytics-dashboard-panel">
                            <h3 class="analytics-dashboard-panel-title">30-day activity signal</h3>
                            <div class="analytics-dashboard-timeline">${timelineMarkup}</div>
                            <div class="analytics-dashboard-legend"><span>Sessions</span><span>Clicks</span></div>
                        </article>
                        <article class="analytics-dashboard-panel">
                            <h3 class="analytics-dashboard-panel-title">Device field</h3>
                            <div class="analytics-dashboard-device-layout">
                                <div class="analytics-dashboard-device-ring" data-total="${formatDashboardNumber(deviceTotal)}" style="--mobile-angle:${mobileAngle}deg;--tablet-angle:${tabletAngle}deg"></div>
                                <div class="analytics-dashboard-device-list">
                                    <div class="analytics-dashboard-device-item"><span class="analytics-dashboard-device-name">Mobile</span><strong class="analytics-dashboard-device-count">${formatDashboardNumber(summary.mobile)}</strong></div>
                                    <div class="analytics-dashboard-device-item"><span class="analytics-dashboard-device-name">Tablet</span><strong class="analytics-dashboard-device-count">${formatDashboardNumber(summary.tablet)}</strong></div>
                                    <div class="analytics-dashboard-device-item"><span class="analytics-dashboard-device-name">Desktop</span><strong class="analytics-dashboard-device-count">${formatDashboardNumber(summary.desktop)}</strong></div>
                                </div>
                            </div>
                        </article>
                    </section>

                    <section class="analytics-dashboard-columns">
                        <article class="analytics-dashboard-panel"><h3 class="analytics-dashboard-panel-title">Most activated controls</h3><div class="analytics-dashboard-ranking">${topClicksMarkup}</div></article>
                        <article class="analytics-dashboard-panel"><h3 class="analytics-dashboard-panel-title">Strongest transitions</h3><div class="analytics-dashboard-transitions">${transitionsMarkup}</div></article>
                    </section>

                    <section class="analytics-dashboard-panel">
                        <h3 class="analytics-dashboard-panel-title">Field guide exits</h3>
                        <div class="analytics-dashboard-external-grid">${externalTotalsMarkup}</div>
                        <div class="analytics-dashboard-table-scroll">
                            <table class="analytics-dashboard-table ${showIpAddresses ? 'is-ip-visible' : ''}">
                                <thead><tr><th>When</th><th>CTA</th><th>Session</th>${showIpAddresses ? '<th>IP address</th>' : ''}<th>Device</th><th>Page</th><th>View</th><th>URL</th></tr></thead>
                                <tbody>${externalRecentRows}</tbody>
                            </table>
                        </div>
                    </section>

                    <details class="analytics-dashboard-audio">
                        <summary class="analytics-dashboard-audio-summary">
                            <span class="analytics-dashboard-audio-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span>
                            <span><strong class="analytics-dashboard-audio-title">Audio intelligence</strong><span class="analytics-dashboard-audio-copy">Autoplay behaviour, manual listening, completion and time per page</span></span>
                            <span class="analytics-dashboard-audio-preview">${formatDashboardNumber(audioStarts)} plays &middot; ${formatDashboardNumber(audioCompletionRate, 1)}% completed</span>
                            <span class="analytics-dashboard-audio-chevron" aria-hidden="true">&#8964;</span>
                        </summary>
                        <div class="analytics-dashboard-audio-body">
                            <section class="analytics-dashboard-audio-grid">
                                <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(initialAutoplayOnRate, 1)}%</strong><span class="analytics-dashboard-audio-label">Arrived with autoplay on</span></article>
                                <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(audio.autoplay_turned_off)}</strong><span class="analytics-dashboard-audio-label">Turned autoplay off</span></article>
                                <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(audio.manual_starts)}</strong><span class="analytics-dashboard-audio-label">Manual play presses</span></article>
                                <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(audioCompletionRate, 1)}%</strong><span class="analytics-dashboard-audio-label">Completed narration</span></article>
                                <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(audio.pauses)}</strong><span class="analytics-dashboard-audio-label">Paused by listener</span></article>
                                <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardDuration(audio.average_listened_seconds)}</strong><span class="analytics-dashboard-audio-label">Average listened</span></article>
                            </section>
                            <section class="analytics-dashboard-audio-columns">
                                <article class="analytics-dashboard-audio-card">
                                    <h4 class="analytics-dashboard-audio-card-title">Playback behaviour</h4>
                                    <div class="analytics-dashboard-audio-state"><span>Initial autoplay on / off</span><strong>${formatDashboardNumber(audio.initial_autoplay_on)} / ${formatDashboardNumber(audio.initial_autoplay_off)}</strong></div>
                                    <div class="analytics-dashboard-audio-state"><span>Autoplay switched on / off</span><strong>${formatDashboardNumber(audio.autoplay_turned_on)} / ${formatDashboardNumber(audio.autoplay_turned_off)}</strong></div>
                                    <div class="analytics-dashboard-audio-state"><span>Autoplay / manual starts</span><strong>${formatDashboardNumber(audio.autoplay_starts)} / ${formatDashboardNumber(audio.manual_starts)}</strong></div>
                                    <div class="analytics-dashboard-audio-state"><span>Completed / interrupted</span><strong>${formatDashboardNumber(audio.completions)} / ${formatDashboardNumber(audio.stops)}</strong></div>
                                    <div class="analytics-dashboard-audio-state"><span>Sessions that listened</span><strong>${formatDashboardNumber(audio.listening_sessions)}</strong></div>
                                </article>
                                <article class="analytics-dashboard-audio-card">
                                    <h4 class="analytics-dashboard-audio-card-title">Listening per page</h4>
                                    <div class="analytics-dashboard-audio-table-scroll">
                                        <table class="analytics-dashboard-audio-table">
                                            <thead><tr><th>Page</th><th>Starts</th><th>Auto</th><th>Manual</th><th>Completed</th><th>Stopped</th><th>Avg listened</th></tr></thead>
                                            <tbody>${audioPageRows}</tbody>
                                        </table>
                                    </div>
                                </article>
                            </section>
                        </div>
                    </details>

                    <details class="analytics-dashboard-audio analytics-dashboard-ratings">
                        <summary class="analytics-dashboard-audio-summary">
                            <span class="analytics-dashboard-rating-icon" aria-hidden="true">
                                <svg viewBox="0 0 24 24" focusable="false"><path fill="currentColor" d="M2 21h4V9H2v12Zm20-10.8c0-1.1-.9-2-2-2h-6.3l.9-4.4.03-.3c0-.4-.17-.8-.44-1.1L13.1 1.3 6.5 7.9C6.2 8.2 6 8.7 6 9.2V19c0 1.1.9 2 2 2h9c.8 0 1.5-.5 1.8-1.2l3-7c.1-.2.2-.5.2-.8v-1.8Z"/></svg>
                            </span>
                            <span><strong class="analytics-dashboard-audio-title">Page rating intelligence</strong><span class="analytics-dashboard-audio-copy">All-time sentiment, score strength, page averages and anonymous visitor patterns</span></span>
                            <span class="analytics-dashboard-audio-preview">${formatDashboardNumber(ratingTotal)} all-time ratings &middot; average ${escapeDashboardHtml(formatSignedRating(ratingAverage))}</span>
                            <span class="analytics-dashboard-audio-chevron" aria-hidden="true">&#8964;</span>
                        </summary>
                        <div class="analytics-dashboard-audio-body">
                            ${ratingsAvailable ? `
                                <section class="analytics-dashboard-audio-grid">
                                    <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(ratingTotal)}</strong><span class="analytics-dashboard-audio-label">All-time ratings</span></article>
                                    <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(ratingUpShare, 1)}%</strong><span class="analytics-dashboard-audio-label">Thumbs-up share</span></article>
                                    <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${escapeDashboardHtml(formatSignedRating(ratingAverage))}</strong><span class="analytics-dashboard-audio-label">Average signed score</span></article>
                                    <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(ratingSummary.average_strength, 2)}/5</strong><span class="analytics-dashboard-audio-label">Average intensity</span></article>
                                    <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(ratingSummary.rated_pages)}</strong><span class="analytics-dashboard-audio-label">Pages rated</span></article>
                                    <article class="analytics-dashboard-audio-metric"><strong class="analytics-dashboard-audio-value">${formatDashboardNumber(ratingSummary.rating_visitors)}</strong><span class="analytics-dashboard-audio-label">Visitors who rated</span></article>
                                </section>
                                <section class="analytics-dashboard-audio-columns">
                                    <article class="analytics-dashboard-audio-card">
                                        <h4 class="analytics-dashboard-audio-card-title">Sentiment balance</h4>
                                        <div class="analytics-dashboard-rating-balance" style="--rating-up:${ratingUpShare}%"><span></span></div>
                                        <div class="analytics-dashboard-rating-balance-labels"><span>${formatDashboardNumber(ratingDownTotal)} down</span><span>${formatDashboardNumber(ratingUpTotal)} up</span></div>
                                        <div class="analytics-dashboard-audio-state"><span>Ratings updated after saving</span><strong>${formatDashboardNumber(ratingSummary.updates)}</strong></div>
                                    </article>
                                    <article class="analytics-dashboard-audio-card">
                                        <h4 class="analytics-dashboard-audio-card-title">Strength distribution</h4>
                                        <div class="analytics-dashboard-rating-distribution">${ratingDistributionMarkup}</div>
                                    </article>
                                </section>
                                <article class="analytics-dashboard-audio-card">
                                    <h4 class="analytics-dashboard-audio-card-title">Average per page</h4>
                                    <div class="analytics-dashboard-audio-table-scroll">
                                        <table class="analytics-dashboard-audio-table">
                                            <thead><tr><th>Page</th><th>View key</th><th>Ratings</th><th>Up / down</th><th>Average</th><th>Intensity</th><th>Last rating</th></tr></thead>
                                            <tbody>${ratingPageRows}</tbody>
                                        </table>
                                    </div>
                                </article>
                                <article class="analytics-dashboard-audio-card">
                                    <h4 class="analytics-dashboard-audio-card-title">Average per anonymous visitor</h4>
                                    <div class="analytics-dashboard-audio-table-scroll">
                                        <table class="analytics-dashboard-audio-table">
                                            <thead><tr><th>Visitor</th><th>Ratings</th><th>Pages</th><th>Up / down</th><th>Average</th><th>Intensity</th><th>Last rating</th></tr></thead>
                                            <tbody>${ratingVisitorRows}</tbody>
                                        </table>
                                    </div>
                                </article>
                                <article class="analytics-dashboard-audio-card">
                                    <h4 class="analytics-dashboard-audio-card-title">Recent rating audit</h4>
                                    <div class="analytics-dashboard-audio-table-scroll">
                                        <table class="analytics-dashboard-audio-table ${showIpAddresses ? 'is-ip-visible' : ''}">
                                            <thead><tr><th>When</th><th>Page</th><th>Signed</th><th>Rating</th><th>Visitor</th><th>Session</th>${showIpAddresses ? '<th>IP address</th>' : ''}<th>Device</th><th>Revision</th></tr></thead>
                                            <tbody>${ratingRecentRows}</tbody>
                                        </table>
                                    </div>
                                </article>
                            ` : '<p class="analytics-dashboard-rating-unavailable">Page rating analytics are ready, but the database table is not available on this environment yet. Import <strong>create_test_overview_page_ratings.sql</strong> to activate this panel.</p>'}
                        </div>
                    </details>

                    <section class="analytics-dashboard-panel">
                        <h3 class="analytics-dashboard-panel-title">Recent journeys</h3>
                        <div class="analytics-dashboard-table-scroll">
                            <table class="analytics-dashboard-table is-journeys ${showIpAddresses ? 'is-ip-visible' : ''}">
                                <thead><tr><th>Session</th><th>When</th>${showIpAddresses ? '<th>IP address</th>' : ''}<th>Device</th><th>Entry page</th><th>Entry view</th><th>Last view</th><th>Time</th><th>Clicks</th><th>Path</th></tr></thead>
                                <tbody>${sessionRows}</tbody>
                            </table>
                        </div>
                    </section>
                </div>
            `;
            stage.querySelectorAll('.analytics-dashboard-period').forEach((button) => {
                button.addEventListener('click', () => onPeriodChange(button.dataset.period));
            });
        }

        function openAnalyticsDashboard(options = {}) {
            if (document.querySelector('.analytics-dashboard-overlay')) {
                return;
            }
            const playPreviewIntro = Boolean(options.playPreviewIntro);
            const returnFocusTarget = options.returnFocusTarget && typeof options.returnFocusTarget.focus === 'function'
                ? options.returnFocusTarget
                : editModeToggle;
            const previousBodyOverflow = document.body.style.overflow;
            const overlay = document.createElement('div');
            overlay.className = 'analytics-dashboard-overlay';
            overlay.innerHTML = `
                <section class="analytics-dashboard-window" role="dialog" aria-modal="true" aria-labelledby="analyticsDashboardTitle">
                    <span class="analytics-dashboard-holo-rail is-left" aria-hidden="true"></span>
                    <span class="analytics-dashboard-holo-rail is-right" aria-hidden="true"></span>
                    <div class="analytics-dashboard-command-boot" aria-hidden="true">
                        <span class="analytics-dashboard-kaleidoscope"><i></i><i></i><i></i><i></i><i></i><i></i></span>
                        <strong>Command centre</strong>
                        <span class="analytics-dashboard-command-status">All systems preparing</span>
                        <span class="analytics-dashboard-command-release">Interface release in progress</span>
                    </div>
                    <header class="analytics-dashboard-head">
                        <div class="analytics-dashboard-brand">
                            <button class="analytics-dashboard-orbit" type="button" aria-label="Hold for five seconds to reveal IP addresses" aria-pressed="false" title="Hold 5 seconds to reveal IP addresses"></button>
                            <div><p class="analytics-dashboard-kicker">Private telemetry</p><h2 id="analyticsDashboardTitle" class="analytics-dashboard-title"><span class="analytics-dashboard-title-desktop">Test Overview Command Center</span><span class="analytics-dashboard-title-mobile">Command Centre</span></h2></div>
                        </div>
                        <span class="analytics-dashboard-live">Live database</span>
                        <button class="analytics-dashboard-logout" type="button">Log out</button>
                        <button class="analytics-dashboard-close" type="button" aria-label="Close analytics dashboard">&times;</button>
                    </header>
                    <div class="analytics-dashboard-stage"></div>
                    <a class="analytics-dashboard-ga4-link" href="https://analytics.google.com/analytics/web/?utm_campaign=2025-q2-gbl-all-gafree&utm_source=google-growth&utm_medium=email&utm_content=link_to_ads1#/a281009588p401797438/admin/streams/table/5981790415?params=_u..nav%3Dmaui" target="_blank" rel="noopener noreferrer" data-track-id="command-centre:open-ga4" data-track-label="Open GA4 stream" data-track-external="google-analytics" data-ga4-cta="open_ga4_stream">Open analytics</a>
                </section>
            `;
            const stage = overlay.querySelector('.analytics-dashboard-stage');
            const closeButton = overlay.querySelector('.analytics-dashboard-close');
            const logoutButton = overlay.querySelector('.analytics-dashboard-logout');
            const ipRevealButton = overlay.querySelector('.analytics-dashboard-orbit');
            const dashboardWindow = overlay.querySelector('.analytics-dashboard-window');
            let activePeriod = 'week';
            let activeToken = '';
            let playIntroAfterNextSuccessfulLoad = false;
            let commandCentreIntroPlayed = false;
            let revealIpAddresses = false;
            let ipRevealHoldTimer = null;
            let commandCentreIntroActive = false;
            let commandCentreReadyTimer = null;

            const handleDashboardPointerMove = (event) => {
                if (event.pointerType === 'touch' || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
                    return;
                }
                const bounds = dashboardWindow.getBoundingClientRect();
                const x = Math.max(0, Math.min(100, ((event.clientX - bounds.left) / bounds.width) * 100));
                const y = Math.max(0, Math.min(100, ((event.clientY - bounds.top) / bounds.height) * 100));
                overlay.style.setProperty('--holo-pointer-x', `${x}%`);
                overlay.style.setProperty('--holo-pointer-y', `${y}%`);
                dashboardWindow.style.setProperty('--holo-pointer-x', `${x}%`);
                dashboardWindow.style.setProperty('--holo-pointer-y', `${y}%`);
            };

            const clearCommandCentreReadyTimer = () => {
                if (commandCentreReadyTimer) {
                    window.clearTimeout(commandCentreReadyTimer);
                    commandCentreReadyTimer = null;
                }
            };
            const markCommandCentreIntroReady = () => {
                commandCentreIntroActive = false;
                dashboardWindow.classList.remove('is-command-centre-booting');
                dashboardWindow.classList.add('is-command-centre-ready');
                dashboardWindow.classList.add('is-command-centre-intro-complete');
                clearCommandCentreReadyTimer();
                commandCentreReadyTimer = window.setTimeout(() => {
                    commandCentreReadyTimer = null;
                    dashboardWindow.classList.remove('is-command-centre-ready');
                }, 1800);
            };
            const hideCommandCentreGa4Link = () => {
                dashboardWindow.classList.remove('is-command-centre-intro-complete');
            };
            const cancelCommandCentreIntro = () => {
                stopDashboardCommandCentreIntro();
                markCommandCentreIntroReady();
            };
            const handleDashboardIntroClick = (event) => {
                if (event.button !== 0
                    || (!commandCentreIntroActive && !dashboardWindow.classList.contains('is-command-centre-booting'))) {
                    return;
                }
                event.preventDefault();
                event.stopImmediatePropagation();
                cancelCommandCentreIntro();
            };

            const closeDashboard = () => {
                document.removeEventListener('keydown', handleDashboardKeydown);
                overlay.removeEventListener('pointermove', handleDashboardPointerMove);
                overlay.removeEventListener('click', handleDashboardIntroClick, true);
                if (ipRevealHoldTimer) window.clearTimeout(ipRevealHoldTimer);
                clearCommandCentreReadyTimer();
                stopDashboardCommandCentreIntro();
                document.body.style.overflow = previousBodyOverflow;
                overlay.remove();
                if (returnFocusTarget.isConnected) returnFocusTarget.focus();
            };
            const handleDashboardKeydown = (event) => {
                if (event.key !== 'Escape') {
                    return;
                }
                if (commandCentreIntroActive || dashboardWindow.classList.contains('is-command-centre-booting')) {
                    event.preventDefault();
                    cancelCommandCentreIntro();
                }
            };
            const loadDashboard = async (period = activePeriod) => {
                activePeriod = period;
                stage.innerHTML = '<div class="analytics-dashboard-loading"><span>Synchronizing telemetry</span></div>';
                try {
                    const data = await fetchAnalyticsDashboard(activeToken, activePeriod, revealIpAddresses);
                    renderAnalyticsDashboardData(stage, data, activePeriod, loadDashboard);
                    if (playIntroAfterNextSuccessfulLoad && !commandCentreIntroPlayed) {
                        playIntroAfterNextSuccessfulLoad = false;
                        commandCentreIntroPlayed = true;
                        hideCommandCentreGa4Link();
                        playDashboardCommandCentreIntro(dashboardWindow, {
                            onStart: () => {
                                commandCentreIntroActive = true;
                                hideCommandCentreGa4Link();
                            },
                            onFinish: markCommandCentreIntroReady
                        });
                    } else {
                        markCommandCentreIntroReady();
                    }
                } catch (error) {
                    if (error.status === 401) {
                        playIntroAfterNextSuccessfulLoad = false;
                        commandCentreIntroActive = false;
                        hideCommandCentreGa4Link();
                        revealIpAddresses = false;
                        ipRevealButton.classList.remove('is-ip-visible');
                        ipRevealButton.setAttribute('aria-pressed', 'false');
                        try { window.sessionStorage.removeItem(ANALYTICS_DASHBOARD_TOKEN_STORAGE_KEY); } catch (storageError) {}
                        activeToken = '';
                        renderAnalyticsDashboardAccess(stage, 'The access code was not accepted.', submitToken);
                        return;
                    }
                    renderAnalyticsDashboardAccess(stage, error.message || 'Dashboard data could not be loaded.', submitToken);
                }
            };
            const submitToken = (token) => {
                activeToken = token;
                playIntroAfterNextSuccessfulLoad = true;
                try { window.sessionStorage.setItem(ANALYTICS_DASHBOARD_TOKEN_STORAGE_KEY, token); } catch (error) {}
                loadDashboard(activePeriod);
            };

            const beginIpRevealHold = (event) => {
                if ((event.type === 'pointerdown' && event.button !== 0) || !activeToken || revealIpAddresses || ipRevealHoldTimer) {
                    return;
                }
                ipRevealButton.classList.add('is-ip-holding');
                ipRevealHoldTimer = window.setTimeout(() => {
                    ipRevealHoldTimer = null;
                    revealIpAddresses = true;
                    ipRevealButton.classList.remove('is-ip-holding');
                    ipRevealButton.classList.add('is-ip-visible');
                    ipRevealButton.setAttribute('aria-pressed', 'true');
                    playOverviewVictorySound('analytics-dashboard-ip-reveal');
                    loadDashboard(activePeriod);
                }, 5000);
            };
            const endIpRevealHold = () => {
                if (ipRevealHoldTimer) {
                    window.clearTimeout(ipRevealHoldTimer);
                    ipRevealHoldTimer = null;
                }
                ipRevealButton.classList.remove('is-ip-holding');
            };

            closeButton.addEventListener('click', closeDashboard);
            logoutButton.addEventListener('click', () => {
                try { window.sessionStorage.removeItem(ANALYTICS_DASHBOARD_TOKEN_STORAGE_KEY); } catch (error) {}
                activeToken = '';
                revealIpAddresses = false;
                closeDashboard();
            });
            ipRevealButton.addEventListener('pointerdown', beginIpRevealHold);
            ipRevealButton.addEventListener('pointerup', endIpRevealHold);
            ipRevealButton.addEventListener('pointercancel', endIpRevealHold);
            ipRevealButton.addEventListener('pointerleave', endIpRevealHold);
            ipRevealButton.addEventListener('keydown', (event) => {
                if ((event.key === 'Enter' || event.key === ' ') && !event.repeat) beginIpRevealHold(event);
            });
            ipRevealButton.addEventListener('keyup', (event) => {
                if (event.key === 'Enter' || event.key === ' ') endIpRevealHold();
            });
            overlay.addEventListener('pointermove', handleDashboardPointerMove, { passive: true });
            overlay.addEventListener('click', handleDashboardIntroClick, true);
            overlay.addEventListener('click', (event) => {
                if (event.target === overlay) closeDashboard();
            });
            document.addEventListener('keydown', handleDashboardKeydown);
            document.body.style.overflow = 'hidden';
            document.body.appendChild(overlay);

            if (window.location.pathname.toLowerCase().endsWith('.html')) {
                activeToken = 'preview';
                playIntroAfterNextSuccessfulLoad = playPreviewIntro;
                loadDashboard(activePeriod);
                return;
            }
            try { activeToken = window.sessionStorage.getItem(ANALYTICS_DASHBOARD_TOKEN_STORAGE_KEY) || ''; } catch (error) {}
            if (activeToken) {
                playIntroAfterNextSuccessfulLoad = false;
                loadDashboard(activePeriod);
            } else {
                renderAnalyticsDashboardAccess(stage, '', submitToken);
            }
        }

        function renderIntroductionGuide() {
            const launcherRow = document.createElement('div');
            launcherRow.className = 'guide-launcher-row';
            let hasIntroductionGuideBeenUsed = false;
            let introductionGuideFadeTimer = null;
            let commandCentreHoldTimer = null;
            let commandCentreHoldRevealTimer = null;
            let commandCentreLaunchTimer = null;
            let commandCentreLongPressTriggered = false;
            const markIntroductionGuideUsed = () => {
                hasIntroductionGuideBeenUsed = true;
                launcherRow.classList.remove('is-faded');
                if (introductionGuideFadeTimer) {
                    window.clearTimeout(introductionGuideFadeTimer);
                    introductionGuideFadeTimer = null;
                }
            };

            const launcher = document.createElement('button');
            launcher.className = 'guide-launcher';
            launcher.type = 'button';
            launcher.setAttribute('aria-haspopup', 'dialog');
            launcher.innerHTML = `
                <span class="guide-document-icon" aria-hidden="true"></span>
                <span class="guide-launcher-copy">
                    <span class="guide-launcher-kicker">Start here</span>
                    <span class="guide-launcher-title">Open the field guide</span>
                </span>
            `;

            launcherRow.addEventListener('focusin', markIntroductionGuideUsed);
            launcherRow.addEventListener('pointerdown', markIntroductionGuideUsed);
            const openFieldGuide = () => {
                markIntroductionGuideUsed();
                const previousBodyOverflow = document.body.style.overflow;
                const modal = document.createElement('div');
                modal.className = 'guide-modal';
                modal.setAttribute('role', 'presentation');
                modal.innerHTML = `
                    <article class="guide-window" role="dialog" aria-modal="true" aria-labelledby="guideWindowTitle">
                        <header class="guide-window-head">
                            <span class="guide-document-icon" aria-hidden="true"></span>
                            <div>
                                <p class="guide-window-kicker">Interactive field guide</p>
                                <h2 id="guideWindowTitle" class="guide-window-title">Why this test overview exists</h2>
                            </div>
                            <button class="guide-close" type="button" aria-label="Close field guide">&times;</button>
                        </header>
                        <div class="guide-window-body">
                            <p class="guide-lead">Software testing is often drawn as a straight line: a requirement enters, a test case runs, and an answer comes out. Real systems are rarely that polite.</p>

                            <section class="guide-section">
                                <h3 class="guide-section-title">Purpose of this map</h3>
                                <p class="guide-copy">This interactive overview makes the connections around testing visible. It follows one possible journey from requirement categories and risk priorities through development environments, testing mindsets, tacit and explicit knowledge, test techniques, collaboration, and system complexity. The goal is not to give you a checklist. It is to help you notice what changes when one decision affects everything around it.</p>
                            </section>

                            <section class="guide-section">
                                <h3 class="guide-section-title">How to explore</h3>
                                <ul class="guide-list">
                                    <li>Choose a requirement and follow the path that catches your attention.</li>
                                    <li>Click, move, spin, and compare. The interactions are part of the explanation.</li>
                                    <li>Use the narration controls when you want the page to guide the pace.</li>
                                    <li>Return and take a different route. A different path can reveal a different testing question.</li>
                                </ul>
                            </section>

                            <section class="guide-section">
                                <h3 class="guide-section-title">A model, not the model</h3>
                                <p class="guide-copy">The categories and flows in this experiment are intentionally practical rather than official. They are not a certification syllabus, a universal process, or a replacement for professional judgment. Testing changes with the product, the risks, the people, the available knowledge, and the moment in which a decision is made.</p>
                            </section>

                            <section class="guide-section">
                                <h3 class="guide-section-title">The idea underneath it all</h3>
                                <p class="guide-copy">Good testing is not only about executing test cases. It is about asking better questions, recognizing relationships, challenging assumptions, and discussing what one person might miss. Change a requirement and a testcase may change. Change a database and the data may change. Change the domain and the knowledge needed to test it may change. Everything connects to everything else.</p>
                            </section>

                            <section class="guide-section">
                                <h3 class="guide-section-title">About and next step</h3>
                                <p class="guide-copy">This page is a Codex experiment created to make software testing easier to discuss, teach, and explore. If it sparks a useful question or a lively disagreement, it is already doing its job.</p>
                                <div class="guide-link-grid">
                                    <a class="guide-link-card" href="https://www.linkedin.com/in/ing-valentijn-p-b696371/" target="_blank" rel="noopener noreferrer" data-track-id="field-guide:more-about-me" data-track-label="More about me" data-track-external="linkedin" data-ga4-cta="more_about_me">
                                        <span class="guide-link-label">More about me</span>
                                        <span class="guide-link-copy">Meet Valentijn and continue the conversation on LinkedIn.</span>
                                    </a>
                                    <a class="guide-link-card" href="https://softwaretestingbreak.com" target="_blank" rel="noopener noreferrer" data-track-id="field-guide:try-next-level" data-track-label="Try the next level" data-track-external="softwaretestingbreak" data-ga4-cta="try_next_level">
                                        <span class="guide-link-label">Try the next level</span>
                                        <span class="guide-link-copy">Like this experiment? Go deeper at softwaretestingbreak.com.</span>
                                    </a>
                                </div>
                            </section>
                        </div>
                    </article>
                `;

                const closeButton = modal.querySelector('.guide-close');
                const closeGuide = () => {
                    document.removeEventListener('keydown', handleGuideKeydown);
                    document.body.style.overflow = previousBodyOverflow;
                    modal.remove();
                    if (launcher.isConnected) {
                        launcher.focus();
                    }
                };
                const handleGuideKeydown = (event) => {
                    if (event.key === 'Escape') {
                        closeGuide();
                    }
                };

                modal.addEventListener('click', (event) => {
                    if (event.target === modal) {
                        closeGuide();
                    }
                });
                closeButton.addEventListener('click', closeGuide);
                document.addEventListener('keydown', handleGuideKeydown);
                document.body.style.overflow = 'hidden';
                document.body.appendChild(modal);
                closeButton.focus();
            };

            const beginCommandCentreHold = (event) => {
                if (event.type === 'pointerdown' && event.button !== 0) return;
                if (commandCentreHoldTimer || commandCentreHoldRevealTimer || commandCentreLaunchTimer || commandCentreLongPressTriggered) return;
                markIntroductionGuideUsed();
                getOverviewAudioContext();
                commandCentreHoldRevealTimer = window.setTimeout(() => {
                    commandCentreHoldRevealTimer = null;
                    launcher.classList.add('is-command-centre-holding');
                }, ANALYTICS_DASHBOARD_HOLD_REVEAL_MS);
                commandCentreHoldTimer = window.setTimeout(() => {
                    commandCentreHoldTimer = null;
                    commandCentreLongPressTriggered = true;
                    if (commandCentreHoldRevealTimer) {
                        window.clearTimeout(commandCentreHoldRevealTimer);
                        commandCentreHoldRevealTimer = null;
                    }
                    launcher.classList.remove('is-command-centre-holding');
                    launcher.classList.add('is-command-centre-launching');
                    playDashboardBootLaserSequence();
                    const launchDelay = typeof window.matchMedia === 'function'
                        && window.matchMedia('(prefers-reduced-motion: reduce)').matches
                        ? 0
                        : ANALYTICS_DASHBOARD_LAUNCH_SPIN_MS;
                    commandCentreLaunchTimer = window.setTimeout(() => {
                        commandCentreLaunchTimer = null;
                        launcher.classList.remove('is-command-centre-launching');
                        openAnalyticsDashboard({
                            playPreviewIntro: true,
                            returnFocusTarget: launcher
                        });
                    }, launchDelay);
                }, ANALYTICS_DASHBOARD_HOLD_MS);
            };

            const endCommandCentreHold = () => {
                if (commandCentreHoldTimer) {
                    window.clearTimeout(commandCentreHoldTimer);
                    commandCentreHoldTimer = null;
                }
                if (commandCentreHoldRevealTimer) {
                    window.clearTimeout(commandCentreHoldRevealTimer);
                    commandCentreHoldRevealTimer = null;
                }
                launcher.classList.remove('is-command-centre-holding');
                window.setTimeout(() => {
                    commandCentreLongPressTriggered = false;
                }, commandCentreLongPressTriggered ? ANALYTICS_DASHBOARD_LAUNCH_SPIN_MS + 400 : 0);
            };

            launcher.addEventListener('pointerdown', beginCommandCentreHold);
            launcher.addEventListener('pointerup', endCommandCentreHold);
            launcher.addEventListener('pointercancel', endCommandCentreHold);
            launcher.addEventListener('pointerleave', endCommandCentreHold);
            launcher.addEventListener('contextmenu', (event) => event.preventDefault());
            launcher.addEventListener('keydown', (event) => {
                if ((event.key === 'Enter' || event.key === ' ') && !event.repeat) {
                    beginCommandCentreHold(event);
                }
            });
            launcher.addEventListener('keyup', (event) => {
                if (event.key === 'Enter' || event.key === ' ') endCommandCentreHold();
            });
            launcher.addEventListener('click', (event) => {
                if (commandCentreHoldTimer) {
                    event.preventDefault();
                    return;
                }
                if (commandCentreLongPressTriggered) {
                    event.preventDefault();
                    commandCentreLongPressTriggered = false;
                    return;
                }
                openFieldGuide();
            });

            launcherRow.appendChild(launcher);
            overviewContent.appendChild(launcherRow);

            introductionGuideFadeTimer = window.setTimeout(() => {
                if (!hasIntroductionGuideBeenUsed && launcherRow.isConnected) {
                    launcherRow.classList.add('is-faded');
                }
            }, INTRO_GUIDE_FADE_DELAY_MS);
        }

        function renderDeepLinkNavigator() {
            const shell = document.createElement('div');
            shell.className = 'deep-link-shell';
            let hasDeepLinkNavigatorBeenUsed = false;
            let deepLinkNavigatorFadeTimer = null;
            const markDeepLinkNavigatorUsed = () => {
                hasDeepLinkNavigatorBeenUsed = true;
                shell.classList.remove('is-faded');
                if (deepLinkNavigatorFadeTimer) {
                    window.clearTimeout(deepLinkNavigatorFadeTimer);
                    deepLinkNavigatorFadeTimer = null;
                }
            };

            const panel = document.createElement('details');
            panel.className = 'deep-link-panel';
            panel.open = false;
            panel.addEventListener('toggle', () => {
                if (panel.open) {
                    markDeepLinkNavigatorUsed();
                }
            });
            shell.addEventListener('focusin', markDeepLinkNavigatorUsed);
            shell.addEventListener('pointerdown', markDeepLinkNavigatorUsed);

            const summary = document.createElement('summary');
            summary.className = 'deep-link-summary';
            summary.innerHTML = `
                <span class="deep-link-summary-copy">
                    <span class="deep-link-summary-kicker">Direct URL navigation</span>
                    <span class="deep-link-summary-title">Jump to any page</span>
                </span>
                <span class="deep-link-summary-icon" aria-hidden="true">+</span>
            `;
            panel.appendChild(summary);

            const body = document.createElement('div');
            body.className = 'deep-link-body';

            const explainer = document.createElement('p');
            explainer.className = 'deep-link-explainer';
            explainer.appendChild(document.createTextNode('Open a page directly or share its URL, for example:'));
            const example = document.createElement('span');
            example.className = 'deep-link-example';
            example.textContent = '?value=functionalrequirement';
            explainer.appendChild(example);
            body.appendChild(explainer);

            const toolbar = document.createElement('div');
            toolbar.className = 'deep-link-toolbar';
            const search = document.createElement('input');
            search.className = 'deep-link-search';
            search.type = 'search';
            search.placeholder = 'Search page, technique, or URL value...';
            search.setAttribute('aria-label', 'Search direct navigation pages');
            const count = document.createElement('span');
            count.className = 'deep-link-count';
            toolbar.appendChild(search);
            toolbar.appendChild(count);
            body.appendChild(toolbar);

            const groupsContainer = document.createElement('div');
            groupsContainer.className = 'deep-link-groups';
            const status = document.createElement('p');
            status.className = 'deep-link-status';
            status.setAttribute('aria-live', 'polite');

            const groupOrder = [
                'Requirements and risk',
                'Maps and transitions',
                'Knowledge and testing',
                'Techniques and methods',
                'Checking, tools and AI',
                'Other pages'
            ];
            const groupedViews = new Map(groupOrder.map((groupName) => [groupName, []]));
            deepLinkNavigatorKeys.forEach((viewKey) => {
                const view = overviewTree[viewKey];
                if (!view) return;
                const groupName = getDeepLinkGroup(viewKey);
                if (!groupedViews.has(groupName)) {
                    groupedViews.set(groupName, []);
                }
                groupedViews.get(groupName).push({
                    key: viewKey,
                    title: view.title || viewKey,
                    value: getDeepLinkValue(viewKey)
                });
            });

            const itemElements = [];
            const groupElements = [];
            groupedViews.forEach((entries, groupName) => {
                if (!entries.length) return;
                entries.sort((left, right) => left.title.localeCompare(right.title));

                const group = document.createElement('section');
                group.className = 'deep-link-group';
                const title = document.createElement('h3');
                title.className = 'deep-link-group-title';
                title.textContent = groupName;
                group.appendChild(title);

                const grid = document.createElement('div');
                grid.className = 'deep-link-grid';
                entries.forEach((entry) => {
                    const item = document.createElement('div');
                    item.className = 'deep-link-item';
                    item.dataset.search = normalizeDeepLinkValue(
                        `${entry.title} ${entry.key} ${entry.value} ${groupName}`
                    );

                    const jumpButton = document.createElement('button');
                    jumpButton.className = 'deep-link-jump';
                    jumpButton.type = 'button';
                    jumpButton.setAttribute('aria-label', `Open ${entry.title}`);
                    jumpButton.innerHTML = `
                        <span class="deep-link-jump-title"></span>
                        <span class="deep-link-jump-value"></span>
                    `;
                    jumpButton.querySelector('.deep-link-jump-title').textContent = entry.title;
                    jumpButton.querySelector('.deep-link-jump-value').textContent = `?value=${entry.value}`;
                    jumpButton.addEventListener('click', () => {
                        markDeepLinkNavigatorUsed();
                        navigateToView(entry.key, `${getCurrentViewKey()}-deep-link`, 'forward');
                    });

                    const copyButton = document.createElement('button');
                    copyButton.className = 'deep-link-copy';
                    copyButton.type = 'button';
                    copyButton.textContent = 'URL';
                    copyButton.setAttribute('aria-label', `Copy direct URL for ${entry.title}`);
                    copyButton.addEventListener('click', async () => {
                        markDeepLinkNavigatorUsed();
                        try {
                            await copyDeepLinkToClipboard(entry.key);
                            status.textContent = `Copied: ?value=${entry.value}`;
                        } catch (error) {
                            status.textContent = `Could not copy. Use ?value=${entry.value}`;
                        }
                    });

                    item.appendChild(jumpButton);
                    item.appendChild(copyButton);
                    grid.appendChild(item);
                    itemElements.push(item);
                });

                group.appendChild(grid);
                groupsContainer.appendChild(group);
                groupElements.push(group);
            });

            const updateFilter = () => {
                const query = normalizeDeepLinkValue(search.value);
                let visibleCount = 0;
                itemElements.forEach((item) => {
                    const isVisible = !query || item.dataset.search.includes(query);
                    item.hidden = !isVisible;
                    if (isVisible) visibleCount += 1;
                });
                groupElements.forEach((group) => {
                    group.hidden = !Array.from(group.querySelectorAll('.deep-link-item')).some((item) => !item.hidden);
                });
                count.textContent = `${visibleCount} page${visibleCount === 1 ? '' : 's'}`;
            };
            search.addEventListener('input', () => {
                markDeepLinkNavigatorUsed();
                updateFilter();
            });
            updateFilter();

            body.appendChild(groupsContainer);
            body.appendChild(status);
            panel.appendChild(body);
            shell.appendChild(panel);
            overviewContent.appendChild(shell);

            deepLinkNavigatorFadeTimer = window.setTimeout(() => {
                if (!hasDeepLinkNavigatorBeenUsed && shell.isConnected) {
                    shell.classList.add('is-faded');
                }
            }, DEEP_LINK_NAVIGATOR_FADE_DELAY_MS);
        }

        function renderViewAddOns(viewKey, view) {
            renderEditModePanel(viewKey, view);
            renderDiveDeeperPanel(viewKey, view);
        }

        function renderCurrentView(options = {}) {
            if (options.resetScroll === true) {
                resetOverviewScrollPosition();
                scheduleSeoAiSummaryFade();
            }
            resetBackToStartControl();
            sanitizeHistoryForMode();
            updateEditModeToggleUi();
            const currentKey = getCurrentViewKey();
            const view = getViewDefinition(currentKey) || overviewTree.root;
            if (currentKey === 'root') {
                document.body.classList.toggle('has-seen-root-intro', hasPresentedRootJourneyIntro);
                hasPresentedRootJourneyIntro = true;
            }
            document.body.dataset.overviewView = currentKey;
            renderPageRatingForView(currentKey, view);
            syncDeepLinkUrl(currentKey);
            recordGa4VirtualPageView(currentKey);
            recordAnalyticsView(currentKey);
            stopNarration();
            updateNarrationButton(view);

            viewTitle.innerHTML = '';
            if (view.titleButton && view.titleSuffix) {
                const titleButton = document.createElement('button');
                titleButton.className = 'title-inline-button';
                titleButton.type = 'button';
                titleButton.textContent = view.titleButton.label;
                titleButton.setAttribute('aria-label', `${view.titleButton.label} details`);
                titleButton.addEventListener('click', () => {
                    navigateToView(view.titleButton.target, `${currentKey}-title-button`);
                });
                viewTitle.appendChild(titleButton);
                viewTitle.appendChild(document.createTextNode(view.titleSuffix));
            } else {
                viewTitle.textContent = view.title || 'Test overview';
            }
            if (view.breadcrumbHtml) {
                viewBreadcrumb.innerHTML = view.breadcrumbHtml;
            } else {
                viewBreadcrumb.textContent = view.breadcrumb || '';
            }
            backButton.hidden = historyStack.length <= 1;
            backButton.setAttribute(
                'aria-label',
                'Go back one level. Hold for two seconds to return to the first page.'
            );
            overviewContent.innerHTML = '';

            if (currentKey === 'knowledge-root' && lastPraSelection) {
                renderInfoFrames([
                    {
                        title: 'Selected PRA focus',
                        copy: `${lastPraSelection.requirementLabel}, ${lastPraSelection.tone} ${lastPraSelection.score}`
                    }
                ]);
            }

            if (view.type === 'menu') {
                if (currentKey === 'root') {
                    renderIntroductionGuide();
                }
                renderMenu(view);
                if (currentKey === 'root') {
                    renderDeepLinkNavigator();
                }
                renderKnowledgeOverlapSection(view.expandableKnowledgeSection);
                renderExpandableActionSection(view.expandableActionSection);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'menu-with-intro') {
                if (view.intro) {
                    renderInfoFrames([view.intro]);
                }
                renderMenu(view);
                renderKnowledgeOverlapSection(view.expandableKnowledgeSection);
                renderExpandableActionSection(view.expandableActionSection);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'matrix') {
                renderMatrix(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'ai-types') {
                renderAiTypes(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'dtap') {
                renderDtap(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'requirement-reason-map') {
                renderRequirementReasonMap(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'testcase-bridge') {
                renderTestcaseBridge(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'technique-interaction-table') {
                renderTechniqueInteractionTable(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'integration-testing') {
                renderIntegrationTesting(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'knowledge-exchange') {
                renderKnowledgeExchange(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'retest-investigation') {
                renderRetestInvestigation(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'structured-chaos') {
                renderStructuredChaos(view);
                renderViewAddOns(currentKey, view);
                maybeAutoplayNarration(view, currentKey);
                return;
            }

            if (view.type === 'info' || view.type === 'custom') {
                renderInfoFrames(view.frames);
            }

            renderViewAddOns(currentKey, view);
            maybeAutoplayNarration(view, currentKey);
        }

        function resetBackToStartControl() {
            if (backToStartHoldTimer) {
                window.clearTimeout(backToStartHoldTimer);
                backToStartHoldTimer = null;
            }
            if (backToStartLaunchTimer) {
                window.clearTimeout(backToStartLaunchTimer);
                backToStartLaunchTimer = null;
            }
            backToStartLongPressTriggered = false;
            backButton.classList.remove('is-home-holding', 'is-home-launching');
        }

        function beginBackToStartHold(event) {
            if (historyStack.length <= 1 || backToStartHoldTimer || backToStartLaunchTimer) {
                return;
            }
            if (event.type === 'pointerdown' && event.button !== 0) {
                return;
            }

            getOverviewAudioContext();
            backToStartLongPressTriggered = false;
            backButton.classList.add('is-home-holding');
            backButton.setAttribute('aria-label', 'Keep holding to return to the first page');

            if (event.type === 'pointerdown' && typeof backButton.setPointerCapture === 'function') {
                try {
                    backButton.setPointerCapture(event.pointerId);
                } catch (error) {
                    // Pointer capture is optional; the hold still works without it.
                }
            }

            backToStartHoldTimer = window.setTimeout(() => {
                backToStartHoldTimer = null;
                backToStartLongPressTriggered = true;
                backButton.classList.remove('is-home-holding');
                backButton.classList.add('is-home-launching');
                backButton.setAttribute('aria-label', 'Returning to the first page');
                playOverviewVictorySound('back-to-first-page');
                recordAnalyticsEvent('control_change', {
                    view_key: getCurrentViewKey(),
                    element_kind: 'navigation',
                    element_key: 'back:hold-to-start',
                    element_label: 'Return to first page',
                    metadata: { hold_ms: BACK_TO_START_HOLD_MS }
                });

                backToStartLaunchTimer = window.setTimeout(() => {
                    backToStartLaunchTimer = null;
                    hasPresentedRootJourneyIntro = true;
                    historyStack.splice(0, historyStack.length, 'root');
                    renderCurrentView({ resetScroll: true });
                }, BACK_TO_START_LAUNCH_MS);
            }, BACK_TO_START_HOLD_MS);
        }

        function endBackToStartHold() {
            if (backToStartHoldTimer) {
                window.clearTimeout(backToStartHoldTimer);
                backToStartHoldTimer = null;
            }
            backButton.classList.remove('is-home-holding');
            if (!backToStartLaunchTimer) {
                backButton.setAttribute(
                    'aria-label',
                    'Go back one level. Hold for two seconds to return to the first page.'
                );
            }
            if (backToStartLongPressTriggered) {
                window.setTimeout(() => {
                    backToStartLongPressTriggered = false;
                }, 0);
            }
        }

        backButton.addEventListener('pointerdown', beginBackToStartHold);
        backButton.addEventListener('pointerup', endBackToStartHold);
        backButton.addEventListener('pointercancel', endBackToStartHold);
        backButton.addEventListener('lostpointercapture', endBackToStartHold);
        backButton.addEventListener('keydown', (event) => {
            if (event.key !== 'Enter' && event.key !== ' ') return;
            event.preventDefault();
            beginBackToStartHold(event);
        });
        backButton.addEventListener('keyup', (event) => {
            if (event.key !== 'Enter' && event.key !== ' ') return;
            event.preventDefault();
            endBackToStartHold();
            if (!backToStartLongPressTriggered) {
                backButton.click();
            }
        });
        backButton.addEventListener('contextmenu', (event) => {
            if (backToStartHoldTimer || backToStartLaunchTimer) event.preventDefault();
        });

        backButton.addEventListener('click', (event) => {
            if (backToStartLongPressTriggered || backToStartLaunchTimer) {
                event.preventDefault();
                return;
            }
            if (historyStack.length <= 1) return;
            playOverviewButtonSound(getCurrentViewKey(), 'back');
            historyStack.pop();
            renderCurrentView({ resetScroll: true });
        });

        narrationButton.addEventListener('click', () => {
            if (narrationButton.disabled || !activeNarrationText) {
                return;
            }

            if (narrationState === 'playing') {
                pauseNarration();
                return;
            }

            if (narrationState === 'paused') {
                resumeNarration();
                return;
            }

            playOverviewButtonSound(`${getCurrentViewKey()}-narration`, 'forward');
            playNarration(activeNarrationText, 'manual');
        });

        autoplayToggle.addEventListener('click', () => {
            isNarrationAutoplayEnabled = !isNarrationAutoplayEnabled;
            saveNarrationAutoplayState();
            updateAutoplayToggleUi();
            recordAnalyticsEvent('audio_autoplay_toggle', {
                view_key: getCurrentViewKey(),
                audio_autoplay_enabled: isNarrationAutoplayEnabled,
                metadata: { narration_state: narrationState }
            });

            if (isNarrationAutoplayEnabled) {
                playOverviewButtonSound(`${getCurrentViewKey()}-autoplay-on`, 'forward');
                if (!narrationButton.disabled) {
                    if (narrationState === 'paused') {
                        resumeNarration();
                    } else if (narrationState === 'idle' && activeNarrationText) {
                        playNarration(activeNarrationText, 'autoplay');
                    }
                }
                return;
            }

            playOverviewButtonSound(`${getCurrentViewKey()}-autoplay-off`, 'back');
        });

        pageRatingLauncher.addEventListener('click', () => setPageRatingExpanded(true));
        pageRatingCollapse.addEventListener('click', () => {
            setPageRatingExpanded(false, { focus: false });
            pageRatingLauncher.focus();
        });
        pageRatingUp.addEventListener('click', () => choosePageRatingSentiment('up'));
        pageRatingDown.addEventListener('click', () => choosePageRatingSentiment('down'));
        pageRatingRange.addEventListener('input', () => {
            activePageRatingScore = Math.min(5, Math.max(1, Math.round(Number(pageRatingRange.value) || 3)));
            pageRatingStatus.classList.remove('is-error');
            pageRatingStatus.textContent = pageRatingStates[activePageRatingViewKey]
                ? 'Ready to update this page rating.'
                : 'Ready to save.';
            updatePageRatingUi();
        });
        pageRatingSubmit.addEventListener('click', submitPageRating);

        editModeToggle.addEventListener('click', () => {
            pinEditModeControl();
            isEditMode = !isEditMode;
            saveEditModeState();
            if (isEditMode) {
                playOverviewVictorySound(`${getCurrentViewKey()}-edit-mode-on`);
            } else {
                playOverviewButtonSound(`${getCurrentViewKey()}-edit-mode-off`, 'back');
                sanitizeHistoryForMode();
            }
            renderCurrentView();
        });

        window.addEventListener('beforeunload', () => stopNarration('page_exit'));
        if (supportsSpeechSynthesis) {
            window.speechSynthesis.addEventListener?.('voiceschanged', () => {
                cacheEnglishNarrationVoice(window.speechSynthesis.getVoices());
                if (narrationState !== 'idle') {
                    return;
                }
                const currentView = getViewDefinition(getCurrentViewKey()) || overviewTree.root;
                updateNarrationButton(currentView);
            });
        }

        updateAutoplayToggleUi();
        primeNarrationVoice();
        window.testOverviewNarrationDiagnostics = Object.freeze({
            getSelectedVoice: () => {
                const voice = cacheEnglishNarrationVoice(window.speechSynthesis?.getVoices?.() || []);
                return voice ? { name: voice.name, lang: voice.lang } : null;
            },
            getLastVoiceName: () => narrationLastVoiceName,
            getAvailableVoices: () => (window.speechSynthesis?.getVoices?.() || []).map((voice) => ({
                name: voice.name,
                lang: voice.lang,
                default: voice.default
            }))
        });
        if ('scrollRestoration' in window.history) {
            window.history.scrollRestoration = 'manual';
        }
        applyPageTheme(currentDtapThemeKey);
        scheduleEditModeControlIntroFade();
        initialiseAnalyticsTracking();
        recordAnalyticsEvent('audio_autoplay_initial', {
            view_key: getCurrentViewKey(),
            audio_autoplay_enabled: isNarrationAutoplayEnabled
        });
        renderCurrentView({ resetScroll: true });
        const previewSearchParams = new URLSearchParams(window.location.search);
        if (window.location.pathname.toLowerCase().endsWith('.html')
            && previewSearchParams.get('dashboard') === 'preview') {
            window.setTimeout(() => openAnalyticsDashboard({
                playPreviewIntro: previewSearchParams.get('intro') === 'preview'
            }), 0);
        }
    </script>
</body>
</html>
